main :: IO ()
main = do
  arguments <- getArgs
  case arguments of
    ["env", mode]
      | mode == backendStderrFloodMode -> backendStderrFloodHelper
      | backendProcessTreeWrapperPrefix `isPrefixOf` mode ->
          backendProcessTreeWrapperHelper
            $ drop (length backendProcessTreeWrapperPrefix) mode
      | isolatedBackendFakePrefix `isPrefixOf` mode ->
          isolatedBackendFakeHelper
            $ drop (length isolatedBackendFakePrefix) mode
    [mode, heartbeatPath]
      | mode == backendProcessTreeGrandchildMode ->
          backendProcessTreeGrandchildHelper heartbeatPath
    _ -> defaultMain $ testGroup "Leant synthesis boundary"
      [ commandLineTests
      , backendDiscoveryTests
      , backendLifecycleTests
      , isolatedBackendPairTests
      , boundedJsonTests
      , snapshotMetadataTests
      , sessionReplayTests
      , providerCacheTests
      , goalTranslationAcquisitionTests
      , translationPreparationTests
      , providerScheduleTests
      , combinedEngineMergeTests
      , parallelEnginePairTests
      , parallelVerificationSchedulerTests
      , detailedSynthCursorTests
      , typedCandidateRoutingTests
      , lengthCounterexampleBankAdapterTests
      , lengthCounterexampleBankRunnerTests
      , lengthSpinePairBoundaryTests
      , lengthSpinePairRankingTests
      , lengthRankingTests
      , lengthCounterexampleSimplificationTests
      , lengthUsableWorkBudgetTests
      , lengthScopedUsableWorkBudgetTests
      , lengthDescriptorBoundExecutableLaunchTests
      , lengthDescriptorBoundEffectiveIDExecutableAccessTests
      , lengthDescriptorBoundExecveCheckExecutableAccessTests
      , lengthApplicableDomainTests
      , replayPlanTests
      , providerProgramTests
      , candidateVerificationTests
      , verificationObservabilityTests
      , postVerificationTests
      , behavioralSelectionTests
      , lengthSelectionTests
      , providerParserTests
      , instanceImplicitTests
      , providerEngineTests
      , typeApplicationTests
      , parametricFamilyFragmentTests
      , parametricFamilyEngineTests
      , rankNFrontierTests
      , visibleTypeApplicationTests
      ]

commandLineTests :: TestTree
commandLineTests = testGroup "command-line admission"
  [ testCase "keep Length assessment disabled unless a file is explicit" $ do
      options <- expectOptions []
      optLengthRankingConfig options @?= Nothing
      optLengthRankingLoadTimeout options @?= Nothing
      optLengthRankingAllowUnpinned options @?= False
      assertBool "default command line selected Length assessment"
        $ isNothing $ lengthAssessmentSetup options
  , testCase "retain the complete explicit Length assessment request" $ do
      options <- expectOptions
        [ "--length-ranking-config", "/tmp/length-ranking.json"
        , "--length-ranking-config-timeout", "1234"
        , "--length-ranking-allow-unpinned"
        ]
      optLengthRankingConfig options @?=
        Just "/tmp/length-ranking.json"
      optLengthRankingLoadTimeout options @?= Just 1234
      optLengthRankingAllowUnpinned options @?= True
      case lengthAssessmentSetup options of
        Just (PermitUnpinnedExecutable,
            LengthRankingConfigurationFileSource path milliseconds) ->
              (path, milliseconds) @?=
                ("/tmp/length-ranking.json", 1234)
        _ -> assertFailure
          "explicit unpinned Length options acquired the wrong setup"
      maximumOptions <- expectOptions
        [ "--length-ranking-config", "/tmp/length-ranking.json"
        , "--length-ranking-config-timeout", "60000"
        ]
      optLengthRankingLoadTimeout maximumOptions @?= Just 60000
      defaultSetup <- expectOptions
        ["--length-ranking-config", "/tmp/length-ranking.json"]
      case lengthAssessmentSetup defaultSetup of
        Just (RequirePinnedExecutable,
            LengthRankingConfigurationFileSource path milliseconds) ->
              (path, milliseconds) @?=
                ("/tmp/length-ranking.json", 5000)
        _ -> assertFailure
          "config-only Length options did not require a pin by default"
  , testCase "reject Length modifiers without an explicit file" $ do
      assertOptionError
        "--length-ranking-config-timeout requires --length-ranking-config"
        ["--length-ranking-config-timeout", "10"]
      assertOptionError
        "--length-ranking-allow-unpinned requires --length-ranking-config"
        ["--length-ranking-allow-unpinned"]
      assertOptionError
        "--length-ranking-config-timeout expects 1..60000 milliseconds"
        [ "--length-ranking-config", "/tmp/config"
        , "--length-ranking-config-timeout", "x"
        ]
      mapM_ (assertOptionError
          "--length-ranking-config-timeout expects 1..60000 milliseconds")
        [ [ "--length-ranking-config", "/tmp/config"
          , "--length-ranking-config-timeout", invalid
          ]
        | invalid <- ["0", "60001", "18446744073709551617"]
        ]
  ]

expectOptions :: [String] -> IO Options
expectOptions arguments = case parseArgs arguments of
  Left failure -> assertFailure ("option parsing failed: " ++ failure)
    >> error "unreachable"
  Right options -> pure options

assertOptionError :: String -> [String] -> IO ()
assertOptionError expected arguments = case parseArgs arguments of
  Left failure -> failure @?= expected
  Right _ -> assertFailure "invalid command-line options were admitted"

backendDiscoveryTests :: TestTree
backendDiscoveryTests = testGroup "Lean backend discovery"
  [ testCase "find the Lake project above a cached REPL executable" $
      withTemporaryDirectory "leant-backend-project" $ \root -> do
        let project = root </> "cache" </> "owner" </> "repl" </> "revision"
            executable = project </> ".lake" </> "build" </> "bin" </> "repl"
        createDirectoryIfMissing True $ takeDirectory executable
        writeFile (project </> "lakefile.toml") "name = \"repl\"\n"
        writeFile executable ""
        expected <- canonicalizePath project
        found <- findBackendProject executable
        found @?= Just expected
  , testCase "follow a backend symlink to its real Lake project" $
      if os == "mingw32" then pure () else
        withTemporaryDirectory "leant-backend-link" $ \root -> do
          let project = root </> "cache" </> "repl" </> "revision"
              executable = project </> ".lake" </> "build" </> "bin" </> "repl"
              linked = root </> "convenience" </> "repl"
          createDirectoryIfMissing True $ takeDirectory executable
          createDirectoryIfMissing True $ takeDirectory linked
          writeFile (project </> "lakefile.lean") "package repl\n"
          writeFile executable ""
          createFileLink executable linked
          expected <- canonicalizePath project
          found <- findBackendProject linked
          found @?= Just expected
  , testCase "reject a backend executable without an enclosing Lake project" $
      withTemporaryDirectory "leant-backend-orphan" $ \root -> do
        let executable = root </> "bin" </> "repl"
        createDirectoryIfMissing True $ takeDirectory executable
        writeFile executable ""
        found <- findBackendProject executable
        found @?= Nothing
  ]

backendLifecycleTests :: TestTree
backendLifecycleTests = testGroup "Lean backend lifecycle"
  [ testCase "spawn and tear down only an explicitly owned process tree" $ do
      source <- readFile "src/Leant/Backend.hs"
      assertBool "backend spawn did not request a dedicated process group"
        $ "create_group = True" `isInfixOf` source
      assertBool "backend spawn did not request a Windows process Job"
        $ "use_process_jobs = True" `isInfixOf` source
      assertBool "backend spawn did not capture its group leader PID"
        $ "getPid process" `isInfixOf` source
      assertBool "POSIX cleanup did not signal the owned group with SIGTERM"
        $ "signalOwnedProcessGroup sigTERM" `isInfixOf` source
      assertBool "POSIX cleanup did not escalate the owned group to SIGKILL"
        $ "signalOwnedProcessGroup sigKILL" `isInfixOf` source
      assertBool "POSIX cleanup did not wait for post-SIGKILL disappearance"
        $ "processGroupKillWaitMicroseconds" `isInfixOf` source
          && "backend process group remained after SIGKILL" `isInfixOf` source
      assertBool "process-group errors were not restricted to benign ESRCH"
        $ "isDoesNotExistError failure" `isInfixOf` source
          && "otherwise -> ioError failure" `isInfixOf` source
      assertBool "Windows Job cleanup lacked a bounded completion failure"
        $ "timeout microseconds $ waitForProcess process" `isInfixOf` source
          && "backend process Job did not complete after termination"
            `isInfixOf` source
      assertBool "direct wrapper observation still collapsed IO failures"
        $ not $ "tryIOError $ getProcessExitCode" `isInfixOf` source
      assertBool "complete-pipe startup cleanup lacked an unconditional tail"
        $ "cleanupCreatedProcess hIn hOut hErr process processGroupIdentifier = do\n  runCleanupActionsPreservingFirstFailure"
          `isInfixOf` source
      assertBool "partial-pipe startup cleanup lacked an unconditional tail"
        $ "cleanupIncompleteProcess maybeIn maybeOut maybeErr process\n    processGroupIdentifier = do\n  runCleanupActionsPreservingFirstFailure"
          `isInfixOf` source
      assertBool "backend cleanup did not guard every local resource cleanup"
        $ "cleanupBackend backend = mask_ $\n  runCleanupActionsPreservingFirstFailure"
          `isInfixOf` source
          && all (`isInfixOf` source)
            [ "stopBackendStderrCapture backend"
            , "closeQuietly $ beOut backend"
            , "closeQuietly $ beErr backend"
            ]
      assertBool "the cleanup combinator did not preserve the tree failure"
        $ "Left primaryFailure -> throwIO primaryFailure" `isInfixOf` source
      assertBool "failed backend cleanup remained permanently memoized"
        $ "Left _ -> BackendCleanupNotStarted" `isInfixOf` source
  , testCase "terminate backend descendants and stop their heartbeat" $
      withTemporaryDirectory "leant-backend-process-tree" $ \root -> do
        executable <- getExecutablePath
        workingDirectory <- getCurrentDirectory
        let heartbeatPath =
              root </> "grandchild heartbeat path with spaces.log"
            wrapperExitedPath =
              backendProcessTreeWrapperExitedPath heartbeatPath
            wrapperArgument =
              backendProcessTreeWrapperPrefix ++ heartbeatPath
        assertBool "the grandchild path did not exercise argument spaces"
          $ ' ' `elem` heartbeatPath
        backend <- spawnBackend BackendConfig
          { bcLakePath = executable
          , bcReplExe = wrapperArgument
          , bcWorkingDir = workingDirectory
          }
        let cleanup = do
              cleaned <- timeout 4000000 $ killBackend backend
              case cleaned of
                Just () -> pure ()
                Nothing -> assertFailure
                  "backend process-tree cleanup did not return"
        flip finally cleanup $ do
          wrapperExited <- timeout 3000000
            $ waitForHeartbeat wrapperExitedPath
          case wrapperExited of
            Just () -> pure ()
            Nothing -> assertFailure
              "fake Lake wrapper did not exit after launching its child"
          observed <- timeout 3000000 $ waitForHeartbeat heartbeatPath
          case observed of
            Just () -> pure ()
            Nothing -> assertFailure
              "backend grandchild did not establish its heartbeat"
          firstCleanup <- async $ killBackend backend
          threadDelay 20000
          firstState <- poll firstCleanup
          when (os /= "mingw32" && isJust firstState) $ assertFailure
            "POSIX cleanup skipped the bounded SIGTERM grace"
          cancel firstCleanup
          _ <- waitCatch firstCleanup
          concurrentCleanups <- replicateM 4 $ async $ killBackend backend
          completed <- timeout 4000000 $ mapM waitCatch concurrentCleanups
          case completed of
            Nothing -> assertFailure
              "concurrent repeated backend cleanups did not return"
            Just outcomes -> mapM_ (\case
                Left failure -> assertFailure
                  $ "repeated backend cleanup failed: " ++ show failure
                Right () -> pure ()) outcomes
          stabilized <- timeout 2000000
            $ waitForStableHeartbeat heartbeatPath
          case stabilized of
            Just () -> pure ()
            Nothing -> assertFailure
              "backend descendant continued work after killBackend returned"
  , testCase "drain oversized stderr while awaiting a response" $ do
      executable <- getExecutablePath
      workingDirectory <- getCurrentDirectory
      backend <- spawnBackend BackendConfig
        { bcLakePath = executable
        , bcReplExe = backendStderrFloodMode
        , bcWorkingDir = workingDirectory
        }
      let cleanup = do
            cleaned <- timeout 3000000 $ killBackend backend
            case cleaned of
              Just () -> pure ()
              Nothing -> assertFailure
                "backend cleanup blocked after the stderr pump completed"
      flip finally cleanup $ do
        response <- timeout 5000000
          $ Backend.request backend Nothing (Json.JObj [])
        case response of
          Just (Right value) -> value @?=
            Json.JObj [("ok", Json.JBool True)]
          Just other -> assertFailure $ "live backend returned " ++ show other
          Nothing -> assertFailure
            "backend response blocked behind its oversized stderr"
        closed <- timeout 2000000
          $ Backend.request backend Nothing (Json.JObj [])
        case closed of
          Just (Left (ServerClosed diagnostic)) -> diagnostic @?=
            backendStderrTruncationMarker
              ++ replicate backendStderrTailBytes 'T'
          Just other -> assertFailure $ "closed backend returned " ++ show other
          Nothing -> assertFailure
            "closed backend request blocked after stdout reached EOF"
  ]

isolatedBackendPairTests :: TestTree
isolatedBackendPairTests = testGroup "isolated Lean backend pair"
  [ testCase "capture terminal status in the atomic close transition" $ do
      sourceLines <- lines <$> readFile "src/Leant/Backend/Isolated.hs"
      let pairBracket = unlines $ mainSourceSection
            "withIsolatedBackendPair config artifact requestTimeout callback ="
            "-- | Lease one worker" sourceLines
          closeSection = unlines $ mainSourceSection
            "closeIsolatedBackendPair pair = mask"
            "cleanupBackends ::" sourceLines
          atomicClose =
            "terminalStatus <- atomically $ do\n\
            \    state <- readTVar $ isolatedPairState pair\n\
            \    writeTVar (isolatedPairState pair) state\n\
            \      { isolatedPairStatus = IsolatedPairClosedStatus\n\
            \      , isolatedPairAvailable = []\n\
            \      }\n\
            \    pure $ isolatedPairStatus state"
      assertBool "pair bracket still sampled status before closing"
        $ not $ "terminalStatus <- atomically" `isInfixOf` pairBracket
      assertBool "pair bracket did not decide from close's captured status"
        $ "Right (terminalStatus, cleanupFailures)" `isInfixOf` pairBracket
      assertBool "close did not capture status and transition atomically"
        $ atomicClose `isInfixOf` closeSection
  , testCase "restore two distinct workers and retain each leased environment" $
      withTemporaryDirectory "leant isolated backend" $ \root -> do
        let artifact = root </> "snapshot artifact with spaces.olean"
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config artifact (Just 2) $ \pair -> do
          firstReady <- newEmptyMVar
          secondReady <- newEmptyMVar
          release <- newEmptyMVar
          first <- async $ withIsolatedBackendLease pair $ \lease -> do
            putMVar firstReady ()
            readMVar release
            runIsolatedBackendCommand lease "simultaneous-first"
          second <- async $ withIsolatedBackendLease pair $ \lease -> do
            putMVar secondReady ()
            readMVar release
            runIsolatedBackendCommand lease "simultaneous-second"
          ready <- timeout 3000000 $ do
            readMVar firstReady
            readMVar secondReady
          putMVar release ()
          case ready of
            Nothing -> assertFailure
              "two isolated workers could not be leased simultaneously"
            Just () -> pure ()
          completed <- timeout 3000000 $ do
            firstResult <- waitCatch first
            secondResult <- waitCatch second
            pure [firstResult, secondResult]
          identities <- case completed of
            Nothing -> assertFailure
              "simultaneous isolated requests did not complete"
              >> pure []
            Just outcomes -> mapM expectAsyncIsolatedCommand outcomes
          workers <- mapM (requireJsonInteger "worker") identities
          pids <- mapM (requireJsonInteger "pid") identities
          environments <- mapM (requireJsonInteger "seenEnv") identities
          Set.fromList workers @?= Set.fromList [1, 2]
          assertBool "isolated backends reused one operating-system process"
            $ Set.size (Set.fromList pids) == 2
          assertBool "isolated backends reused one process-local environment"
            $ Set.size (Set.fromList environments) == 2
          zipWithM_ (\worker environment ->
              environment @?= isolatedFakeEnvironment worker)
            workers environments
          sequential <- withIsolatedBackendLease pair $ \lease -> do
            firstResponse <- runIsolatedBackendCommand lease "sequence-one"
            secondResponse <- runIsolatedBackendCommand lease "sequence-two"
            pure (firstResponse, secondResponse)
          (firstResponse, secondResponse) <-
            expectSequentialIsolatedCommands sequential
          firstPid <- requireJsonInteger "pid" firstResponse
          secondPid <- requireJsonInteger "pid" secondResponse
          firstEnvironment <- requireJsonInteger "seenEnv" firstResponse
          secondEnvironment <- requireJsonInteger "seenEnv" secondResponse
          firstSequence <- requireJsonInteger "sequence" firstResponse
          secondSequence <- requireJsonInteger "sequence" secondResponse
          secondPid @?= firstPid
          secondEnvironment @?= firstEnvironment
          secondSequence @?= firstSequence + 1
        paired @?= Right ()
        mapM_ (assertFakeWorkerStopped root) [1, 2]
        firstPath <- readFile $ isolatedFakeSetupPath root 1
        secondPath <- readFile $ isolatedFakeSetupPath root 2
        firstPath @?= artifact
        secondPath @?= artifact
        setupOrder <- lines <$> readFile (root </> "setup-order.log")
        setupOrder @?= ["1", "2"]
  , testCase "return fatal, error, and sorry JSON without poisoning" $
      withTemporaryDirectory "leant isolated valid responses" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config
          (root </> "valid response snapshot") (Just 2) $ \pair -> do
            leased <- withIsolatedBackendLease pair $ \lease ->
              forM ["fatal", "error", "sorry", "identity"]
                $ runIsolatedBackendCommand lease
            responses <- case leased of
              Left failure -> assertFailure
                ("valid response lease failed: " ++ show failure)
                >> pure []
              Right results -> mapM expectIsolatedCommand results
            length responses @?= 4
            case responses of
              fatalResponse : errorResponse : sorryResponse : finalResponse : [] -> do
                Json.jLookup "message" fatalResponse @?=
                  Just (Json.JStr "fake command fatal")
                assertBool "error response lost its messages"
                  $ isJust $ Json.jLookup "messages" errorResponse
                assertBool "sorry response lost its sorries"
                  $ isJust $ Json.jLookup "sorries" sorryResponse
                worker <- requireJsonInteger "worker" finalResponse
                seen <- requireJsonInteger "seenEnv" finalResponse
                seen @?= isolatedFakeEnvironment worker
              _ -> assertFailure "valid response batch had the wrong shape"
        paired @?= Right ()
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "reject a lease after its callback releases the worker" $
      withTemporaryDirectory "leant isolated closed lease" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config
          (root </> "closed lease snapshot") (Just 2) $ \pair -> do
            escaped <- withIsolatedBackendLease pair pure
            staleLease <- case escaped of
              Left failure -> assertFailure
                ("could not acquire lease: " ++ show failure)
                >> error "unreachable"
              Right lease -> pure lease
            staleResult <- runIsolatedBackendCommand staleLease "stale"
            staleResult @?= Left IsolatedBackendLeaseClosed
            healthy <- withIsolatedBackendLease pair $ \lease ->
              runIsolatedBackendCommand lease "fresh"
            case healthy of
              Left failure -> assertFailure
                $ "fresh lease failed: " ++ show failure
              Right commandResult -> void $ expectIsolatedCommand commandResult
        paired @?= Right ()
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "keep an idle worker healthy across a lease callback exception" $
      withTemporaryDirectory "leant isolated idle callback exception" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config
          (root </> "idle callback exception snapshot") (Just 2) $ \pair -> do
            attempted <- try $ withIsolatedBackendLease pair $ \_ ->
              ioError $ userError "isolated lease callback sentinel"
            case (attempted :: Either SomeException
                (Either IsolatedBackendFailure ())) of
              Left failure -> assertBool
                "lease callback exception was replaced"
                $ "isolated lease callback sentinel" `isInfixOf` show failure
              Right value -> assertFailure
                $ "lease callback exception became a value: " ++ show value
            healthy <- withIsolatedBackendLease pair $ \lease ->
              runIsolatedBackendCommand lease "after-callback-exception"
            case healthy of
              Left failure -> assertFailure
                $ "idle callback poisoned the pair: " ++ show failure
              Right commandResult -> void $ expectIsolatedCommand commandResult
        paired @?= Right ()
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "serialize concurrent commands sharing one active lease" $
      withTemporaryDirectory "leant isolated lease serialization" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config
          (root </> "lease serialization snapshot") Nothing $ \pair -> do
            leased <- withIsolatedBackendLease pair $ \lease -> do
              first <- async $ runIsolatedBackendCommand lease "gated"
              received <- timeout 3000000 $ waitForHeartbeat
                $ isolatedFakeCommandStartedPath root 1
              received @?= Just ()
              second <- async $ runIsolatedBackendCommand lease
                "serialized-second"
              overlapped <- timeout 200000 $ waitForFakeCommandCount
                (isolatedFakeCommandStartedPath root 1) 2
              overlapped @?= Nothing
              writeFile (isolatedFakeCommandGatePath root 1) "open\n"
              completed <- timeout 5000000 $ do
                firstResult <- waitCatch first
                secondResult <- waitCatch second
                pure (firstResult, secondResult)
              case completed of
                Just (Right firstResult, Right secondResult) -> do
                  firstResponse <- expectIsolatedCommand firstResult
                  secondResponse <- expectIsolatedCommand secondResult
                  firstSequence <- requireJsonInteger
                    "sequence" firstResponse
                  secondSequence <- requireJsonInteger
                    "sequence" secondResponse
                  (firstSequence, secondSequence) @?= (1, 2)
                other -> assertFailure
                  $ "serialized requests did not finish: " ++ show other
            leased @?= Right ()
        paired @?= Right ()
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "wait for an admitted child request before reusing its worker" $
      withTemporaryDirectory "leant isolated inflight release" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config
          (root </> "inflight release snapshot") Nothing $ \pair -> do
            callbackReturned <- newEmptyMVar
            childSlot <- newEmptyMVar
            firstLease <- async $ withIsolatedBackendLease pair $ \lease -> do
              child <- async $ runIsolatedBackendCommand lease "gated"
              received <- timeout 3000000 $ waitForHeartbeat
                $ isolatedFakeCommandStartedPath root 1
              received @?= Just ()
              putMVar childSlot child
              putMVar callbackReturned ()
            returned <- timeout 3000000 $ readMVar callbackReturned
            returned @?= Just ()
            holderReady <- newEmptyMVar
            releaseHolder <- newEmptyMVar
            holder <- async $ withIsolatedBackendLease pair $ \_ -> do
              putMVar holderReady ()
              readMVar releaseHolder
            held <- timeout 3000000 $ readMVar holderReady
            held @?= Just ()
            secondStarted <- newEmptyMVar
            secondLease <- async $ withIsolatedBackendLease pair $ \lease -> do
              putMVar secondStarted ()
              runIsolatedBackendCommand lease "after-gated"
            premature <- timeout 200000 $ readMVar secondStarted
            premature @?= Nothing
            writeFile (isolatedFakeCommandGatePath root 1) "open\n"
            firstOutcome <- timeout 5000000 $ waitCatch firstLease
            case firstOutcome of
              Just (Right (Right ())) -> pure ()
              other -> assertFailure
                $ "first lease did not release cleanly: " ++ show other
            child <- readMVar childSlot
            childOutcome <- timeout 3000000 $ waitCatch child
            childResponse <- case childOutcome of
              Just (Right commandResult) ->
                expectIsolatedCommand commandResult
              other -> assertFailure
                ("gated child did not finish: " ++ show other)
                >> pure Json.JNull
            Json.jLookup "cmd" childResponse @?=
              Just (Json.JStr "gated")
            startedAfterGate <- timeout 3000000 $ readMVar secondStarted
            startedAfterGate @?= Just ()
            secondOutcome <- timeout 3000000 $ waitCatch secondLease
            secondResponse <- case secondOutcome of
              Just outcome -> expectAsyncIsolatedCommand outcome
              Nothing -> assertFailure "second lease did not finish"
                >> pure Json.JNull
            secondWorker <- requireJsonInteger "worker" secondResponse
            secondWorker @?= 1
            putMVar releaseHolder ()
            holderOutcome <- timeout 3000000 $ waitCatch holder
            case holderOutcome of
              Just (Right (Right ())) -> pure ()
              other -> assertFailure
                $ "worker-two holder failed: " ++ show other
        paired @?= Right ()
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "retire a worker when normal release is cancelled" $
      withTemporaryDirectory "leant isolated release cancellation" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config
          (root </> "release cancellation snapshot") Nothing $ \pair -> do
            childSlot <- newEmptyMVar
            callbackReturned <- newEmptyMVar
            releasing <- async $ withIsolatedBackendLease pair $ \lease -> do
              child <- async $ runIsolatedBackendCommand lease "gated"
              received <- timeout 3000000 $ waitForHeartbeat
                $ isolatedFakeCommandStartedPath root 1
              received @?= Just ()
              putMVar childSlot child
              putMVar callbackReturned ()
            returned <- timeout 3000000 $ readMVar callbackReturned
            returned @?= Just ()
            blocked <- timeout 3000000 $ waitForMVarBlock
              $ asyncThreadId releasing
            blocked @?= Just ()
            cancelled <- timeout 5000000 $ cancel releasing
            cancelled @?= Just ()
            releaseOutcome <- waitCatch releasing
            case releaseOutcome of
              Left _ -> pure ()
              Right value -> assertFailure
                $ "cancelled release returned normally: " ++ show value
            child <- readMVar childSlot
            childOutcome <- timeout 5000000 $ waitCatch child
            assertBool "retired worker left its request child blocked"
              $ isJust childOutcome
            reused <- withIsolatedBackendLease pair $ \_ -> pure ()
            reused @?= Left (IsolatedBackendPairPoisoned
              IsolatedBackendRequestInterrupted)
        paired @?= Left (IsolatedBackendPairPoisoned
          IsolatedBackendRequestInterrupted)
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testGroup "reject invalid setup responses"
      [ isolatedSetupFailureTest
          "fatal" "setup-fatal-1" $ \case
            IsolatedBackendSetupFatal 1 "fake setup fatal" -> True
            _ -> False
      , isolatedSetupFailureTest
          "error" "setup-error-1" $ \case
            IsolatedBackendSetupErrors 1 ["fake setup error"] -> True
            _ -> False
      , isolatedSetupFailureTest
          "missing environment" "setup-missing-1" $ \case
            IsolatedBackendSetupMissingEnvironment 1 -> True
            _ -> False
      , isolatedSetupFailureTest
          "timeout" "setup-timeout-1" $ \case
            IsolatedBackendSetupTransportFailure 1
              IsolatedBackendRequestTimeout -> True
            _ -> False
      , isolatedSetupFailureTest
          "timeout while a response line is incomplete"
          "setup-partial-line-1" $ \case
            IsolatedBackendSetupTransportFailure 1
              IsolatedBackendRequestTimeout -> True
            _ -> False
      , isolatedSetupFailureTest
          "missing environment with an unread output tail"
          "setup-output-tail-1" $ \case
            IsolatedBackendSetupMissingEnvironment 1 -> True
            _ -> False
      , isolatedSetupFailureTest
          "EOF" "setup-eof-1" $ \case
            IsolatedBackendSetupTransportFailure 1
              (IsolatedBackendServerClosed _) -> True
            _ -> False
      , isolatedSetupFailureTest
          "malformed JSON" "setup-malformed-1" $ \case
            IsolatedBackendSetupTransportFailure 1
              (IsolatedBackendBadResponse _) -> True
            _ -> False
      ]
  , testCase "clean the first worker after second-worker setup failure" $
      withTemporaryDirectory "leant isolated partial setup" $ \root -> do
        config <- isolatedFakeBackendConfig root "setup-fatal-2" Nothing
        callbackRan <- newIORef False
        paired <- withIsolatedBackendPair config
          (root </> "partial setup snapshot") (Just 1) $ \_ -> do
            modifyIORef' callbackRan $ const True
        case paired of
          Left (IsolatedBackendSetupFatal 2 "fake setup fatal") -> pure ()
          other -> assertFailure $ "wrong second-worker failure: " ++ show other
        callbackWasRun <- readIORef callbackRan
        callbackWasRun @?= False
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "cancel second-worker setup and clean both workers" $
      withTemporaryDirectory "leant isolated setup cancellation" $ \root -> do
        config <- isolatedFakeBackendConfig root "setup-timeout-2" Nothing
        callbackRan <- newIORef False
        running <- async $ withIsolatedBackendPair config
          (root </> "cancelled setup snapshot") Nothing $ \_ ->
            modifyIORef' callbackRan $ const True
        enteredSecondSetup <- timeout 3000000 $ do
          waitForHeartbeat $ isolatedFakeHeartbeatPath root 2
          waitForHeartbeat $ isolatedFakeSetupPath root 2
        enteredSecondSetup @?= Just ()
        cancelled <- timeout 5000000 $ cancel running
        cancelled @?= Just ()
        outcome <- waitCatch running
        case outcome of
          Left _ -> pure ()
          Right value -> assertFailure
            $ "setup cancellation returned normally: " ++ show value
        callbackWasRun <- readIORef callbackRan
        callbackWasRun @?= False
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "clean the first worker after second-worker spawn failure" $
      if os == "mingw32" then pure () else
        withTemporaryDirectory "leant isolated partial spawn" $ \root -> do
          executable <- getExecutablePath
          let launcher = root </> "temporary fake lake launcher"
          createFileLink executable launcher
          config <- isolatedFakeBackendConfig root "healthy" $ Just launcher
          callbackRan <- newIORef False
          paired <- withIsolatedBackendPair config
            (root </> "partial spawn snapshot") (Just 1) $ \_ ->
              modifyIORef' callbackRan $ const True
          case paired of
            Left (IsolatedBackendSpawnFailure 2 _) -> pure ()
            other -> assertFailure $ "wrong second-spawn failure: " ++ show other
          callbackWasRun <- readIORef callbackRan
          callbackWasRun @?= False
          assertFakeWorkerStopped root 1
  , testGroup "retire transport-failed workers without replacement"
      [ isolatedTransportFailureTest
          "timeout" IsolatedBackendRequestTimeout
      , isolatedTransportFailureTest
          "eof" $ IsolatedBackendServerClosed ""
      , isolatedTransportFailureTest
          "malformed" $ IsolatedBackendBadResponse ""
      ]
  , testCase "let a leased sibling finish while retaining the first poison" $
      withTemporaryDirectory "leant isolated sibling finish" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        paired <- withIsolatedBackendPair config
          (root </> "sibling snapshot") (Just 2) $ \pair -> do
            poisonReady <- newEmptyMVar
            siblingReady <- newEmptyMVar
            releasePoisoner <- newEmptyMVar
            releaseSibling <- newEmptyMVar
            poisoner <- async $ withIsolatedBackendLease pair $ \lease -> do
              putMVar poisonReady ()
              readMVar releasePoisoner
              runIsolatedBackendCommand lease "malformed"
            sibling <- async $ withIsolatedBackendLease pair $ \lease -> do
              putMVar siblingReady ()
              readMVar releaseSibling
              first <- runIsolatedBackendCommand lease "post-poison"
              second <- runIsolatedBackendCommand lease "eof"
              pure (first, second)
            ready <- timeout 3000000 $ do
              readMVar poisonReady
              readMVar siblingReady
            ready @?= Just ()
            putMVar releasePoisoner ()
            poisonResult <- waitCatch poisoner
            case poisonResult of
              Right (Right (Left (IsolatedBackendRequestFailure
                  (IsolatedBackendBadResponse _)))) -> pure ()
              other -> assertFailure $ "wrong poison result: " ++ show other
            putMVar releaseSibling ()
            siblingResult <- waitCatch sibling
            case siblingResult of
              Right (Right (firstResult, secondResult)) -> do
                siblingResponse <- expectIsolatedCommand firstResult
                Json.jLookup "cmd" siblingResponse @?=
                  Just (Json.JStr "post-poison")
                case secondResult of
                  Left (IsolatedBackendRequestFailure
                      (IsolatedBackendServerClosed _)) -> pure ()
                  other -> assertFailure
                    $ "wrong sibling transport result: " ++ show other
              other -> assertFailure
                $ "wrong sibling lease result: " ++ show other
        case paired of
          Left (IsolatedBackendPairPoisoned
              (IsolatedBackendBadResponse _)) -> pure ()
          other -> assertFailure $ "pair lost first poison: " ++ show other
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "let close win over a later checked-out request failure" $
      withTemporaryDirectory "leant isolated close ordering" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        lateRequestSlot <- newEmptyMVar
        paired <- withIsolatedBackendPair config
          (root </> "close ordering snapshot") Nothing $ \pair -> do
            lateRequest <- async $ withIsolatedBackendLease pair $ \lease ->
              runIsolatedBackendCommand lease "gated"
            putMVar lateRequestSlot lateRequest
            received <- timeout 3000000 $ waitForHeartbeat
              $ isolatedFakeCommandStartedPath root 1
            received @?= Just ()
            -- Returning closes the pair before cleanup kills the backend and
            -- makes this already-admitted request fail.
            pure ()
        paired @?= Right ()
        lateRequest <- readMVar lateRequestSlot
        lateOutcome <- timeout 5000000 $ waitCatch lateRequest
        assertBool "late checked-out request did not observe pair cleanup"
          $ isJust lateOutcome
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "propagate callback exceptions after killing both workers" $
      withTemporaryDirectory "leant isolated callback exception" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        attempted <- try $ withIsolatedBackendPair config
          (root </> "callback snapshot") (Just 2) $ \_ -> do
            mapM_ (waitForHeartbeat . isolatedFakeHeartbeatPath root) [1, 2]
            ioError $ userError "isolated callback sentinel"
        case (attempted :: Either SomeException
            (Either IsolatedBackendFailure ())) of
          Left failure -> assertBool "callback exception was replaced"
            $ "isolated callback sentinel" `isInfixOf` show failure
          Right result -> assertFailure
            $ "callback exception became a value: " ++ show result
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  , testCase "cancel an in-flight request and still reap checked-out workers" $
      withTemporaryDirectory "leant isolated caller cancellation" $ \root -> do
        config <- isolatedFakeBackendConfig root "healthy" Nothing
        running <- async $ withIsolatedBackendPair config
          (root </> "cancellation snapshot") Nothing $ \pair ->
            withIsolatedBackendLease pair $ \lease -> do
              runIsolatedBackendCommand lease "timeout"
        started <- timeout 3000000 $ waitForHeartbeat
          $ isolatedFakeCommandStartedPath root 1
        started @?= Just ()
        mapM_ (waitForHeartbeat . isolatedFakeHeartbeatPath root) [1, 2]
        cancelled <- timeout 5000000 $ cancel running
        cancelled @?= Just ()
        outcome <- waitCatch running
        case outcome of
          Left _ -> pure ()
          Right value -> assertFailure
            $ "caller cancellation returned normally: " ++ show value
        mapM_ (assertFakeWorkerStopped root) [1, 2]
  ]

isolatedSetupFailureTest
  :: String
  -> String
  -> (IsolatedBackendFailure -> Bool)
  -> TestTree
isolatedSetupFailureTest label scenario expected =
  testCase ("reject " ++ label) $
    withTemporaryDirectory ("leant isolated setup " ++ label) $ \root -> do
      config <- isolatedFakeBackendConfig root scenario Nothing
      callbackRan <- newIORef False
      paired <- withIsolatedBackendPair config
        (root </> "setup artifact with spaces") (Just 1) $ \_ ->
          modifyIORef' callbackRan $ const True
      case paired of
        Left failure | expected failure -> pure ()
        other -> assertFailure $ "wrong setup result: " ++ show other
      callbackWasRun <- readIORef callbackRan
      callbackWasRun @?= False
      assertFakeWorkerStopped root 1

isolatedTransportFailureTest
  :: String
  -> IsolatedBackendTransportFailure
  -> TestTree
isolatedTransportFailureTest command expectedCause =
  testCase command $
    withTemporaryDirectory ("leant isolated transport " ++ command) $ \root -> do
      config <- isolatedFakeBackendConfig root "healthy" Nothing
      paired <- withIsolatedBackendPair config
        (root </> "transport artifact") (Just 1) $ \pair -> do
          failed <- withIsolatedBackendLease pair $ \lease ->
            runIsolatedBackendCommand lease command
          case failed of
            Right (Left (IsolatedBackendRequestFailure actual))
              | sameTransportKind expectedCause actual -> pure ()
            other -> assertFailure $ "wrong request failure: " ++ show other
          reused <- withIsolatedBackendLease pair $ \_ -> pure ()
          case reused of
            Left (IsolatedBackendPairPoisoned actual)
              | sameTransportKind expectedCause actual -> pure ()
            other -> assertFailure $ "poisoned pair was reusable: " ++ show other
      case paired of
        Left (IsolatedBackendPairPoisoned actual)
          | sameTransportKind expectedCause actual -> pure ()
        other -> assertFailure $ "pair did not publish poison: " ++ show other
      third <- doesDirectoryExist $ isolatedFakeClaimPath root 3
      third @?= False
      mapM_ (assertFakeWorkerStopped root) [1, 2]

sameTransportKind
  :: IsolatedBackendTransportFailure
  -> IsolatedBackendTransportFailure
  -> Bool
sameTransportKind IsolatedBackendRequestTimeout
    IsolatedBackendRequestTimeout = True
sameTransportKind (IsolatedBackendServerClosed _)
    (IsolatedBackendServerClosed _) = True
sameTransportKind (IsolatedBackendBadResponse _)
    (IsolatedBackendBadResponse _) = True
sameTransportKind IsolatedBackendRequestInterrupted
    IsolatedBackendRequestInterrupted = True
sameTransportKind _ _ = False

expectAsyncIsolatedCommand
  :: Either SomeException
      (Either IsolatedBackendFailure
        (Either IsolatedBackendFailure Json.JValue))
  -> IO Json.JValue
expectAsyncIsolatedCommand outcome = case outcome of
  Left failure -> assertFailure
    ("isolated lease threw: " ++ show failure) >> pure Json.JNull
  Right (Left failure) -> assertFailure
    ("isolated lease failed: " ++ show failure) >> pure Json.JNull
  Right (Right commandResult) -> expectIsolatedCommand commandResult

expectIsolatedCommand
  :: Either IsolatedBackendFailure Json.JValue
  -> IO Json.JValue
expectIsolatedCommand result = case result of
  Left failure -> assertFailure
    ("isolated command failed: " ++ show failure) >> pure Json.JNull
  Right response -> pure response

expectSequentialIsolatedCommands
  :: Either IsolatedBackendFailure
      ( Either IsolatedBackendFailure Json.JValue
      , Either IsolatedBackendFailure Json.JValue
      )
  -> IO (Json.JValue, Json.JValue)
expectSequentialIsolatedCommands result = case result of
  Left failure -> assertFailure
    ("sequential lease failed: " ++ show failure)
    >> pure (Json.JNull, Json.JNull)
  Right (first, second) -> (,)
    <$> expectIsolatedCommand first
    <*> expectIsolatedCommand second

requireJsonInteger :: String -> Json.JValue -> IO Integer
requireJsonInteger key value = case Json.jLookup key value >>= Json.jInt of
  Just integer -> pure integer
  Nothing -> assertFailure ("missing integer field " ++ show key
    ++ " in " ++ show value) >> pure 0

isolatedBackendFakePrefix :: String
isolatedBackendFakePrefix = "__leant_isolated_backend__:"

isolatedFakeBackendConfig
  :: FilePath
  -> String
  -> Maybe FilePath
  -> IO BackendConfig
isolatedFakeBackendConfig root scenario maybeLauncher = do
  executable <- maybe getExecutablePath pure maybeLauncher
  workingDirectory <- getCurrentDirectory
  let descriptor = Json.JObj $
        [ ("root", Json.JStr root)
        , ("scenario", Json.JStr scenario)
        ] ++ case maybeLauncher of
          Nothing -> []
          Just launcher -> [("removeLauncher", Json.JStr launcher)]
  pure BackendConfig
    { bcLakePath = executable
    , bcReplExe = isolatedBackendFakePrefix
        ++ Json.encodeJson descriptor
    , bcWorkingDir = workingDirectory
    }

isolatedBackendFakeHelper :: String -> IO ()
isolatedBackendFakeHelper encodedDescriptor = do
  descriptor <- case Json.parseJson encodedDescriptor of
    Left failure -> ioError $ userError
      $ "invalid isolated fake-backend descriptor: " ++ failure
    Right value -> pure value
  root <- requireDescriptorString "root" descriptor
  scenario <- requireDescriptorString "scenario" descriptor
  let maybeLauncher = Json.jLookup "removeLauncher" descriptor
        >>= Json.jString
  worker <- claimIsolatedFakeWorker root 1
  pid <- fromIntegral <$> getCurrentPid
  BS.appendFile (isolatedFakeHeartbeatPath root worker)
    $ BS.singleton 'H'
  void $ forkIO $ forever $ do
    threadDelay 10000
    BS.appendFile (isolatedFakeHeartbeatPath root worker)
      $ BS.singleton 'H'
  sequenceNumber <- newIORef 0
  isolatedFakeRequestLoop root scenario maybeLauncher
    worker pid sequenceNumber

requireDescriptorString :: String -> Json.JValue -> IO String
requireDescriptorString key descriptor =
  case Json.jLookup key descriptor >>= Json.jString of
    Just value -> pure value
    Nothing -> ioError $ userError
      $ "isolated fake-backend descriptor lacks " ++ show key

claimIsolatedFakeWorker :: FilePath -> Integer -> IO Integer
claimIsolatedFakeWorker root worker = do
  claimed <- try $ createDirectory $ isolatedFakeClaimPath root worker
  case claimed of
    Right () -> pure worker
    Left failure
      | isAlreadyExistsError failure ->
          claimIsolatedFakeWorker root $ worker + 1
      | otherwise -> ioError failure

isolatedFakeRequestLoop
  :: FilePath
  -> String
  -> Maybe FilePath
  -> Integer
  -> Integer
  -> IORef Integer
  -> IO ()
isolatedFakeRequestLoop root scenario maybeLauncher worker pid sequenceNumber =
  forever $ do
    requestLine <- hGetLine stdin
    unless (null requestLine) $ do
      requestValue <- case Json.parseJson requestLine of
        Left failure -> ioError $ userError
          $ "invalid fake-backend request: " ++ failure
        Right value -> pure value
      case requestValue of
        Json.JObj [("unpickleEnvFrom", Json.JStr artifact)] ->
          isolatedFakeSetupResponse root scenario maybeLauncher
            worker artifact
        Json.JObj
            [("cmd", Json.JStr command), ("env", Json.JInt environment)] ->
          isolatedFakeCommandResponse root scenario worker pid
            sequenceNumber command environment
        _ -> ioError $ userError
          $ "unexpected fake-backend request shape: " ++ show requestValue

isolatedFakeSetupResponse
  :: FilePath
  -> String
  -> Maybe FilePath
  -> Integer
  -> FilePath
  -> IO ()
isolatedFakeSetupResponse root scenario maybeLauncher worker artifact = do
  writeFile (isolatedFakeSetupPath root worker) artifact
  appendFile (root </> "setup-order.log") $ show worker ++ "\n"
  when (worker == 1) $ case maybeLauncher of
    Nothing -> pure ()
    Just launcher -> removeFile launcher
  let targeted prefix = scenario == prefix ++ "-" ++ show worker
      environment = isolatedFakeEnvironment worker
  case () of
    _ | targeted "setup-fatal" ->
          isolatedFakeWriteResponse $ Json.JObj
            [("message", Json.JStr "fake setup fatal")]
      | targeted "setup-error" ->
          isolatedFakeWriteResponse $ Json.JObj
            [ ("env", Json.JInt environment)
            , ("messages", Json.JArr
                [ Json.JObj
                    [ ("severity", Json.JStr "error")
                    , ("data", Json.JStr "fake setup error")
                    ]
                ])
            ]
      | targeted "setup-missing" ->
          isolatedFakeWriteResponse $ Json.JObj
            [("ok", Json.JBool True)]
      | targeted "setup-timeout" -> threadDelay 30000000
      | targeted "setup-partial-line" -> do
          hPutStr stdout "{\"env\":"
          hFlush stdout
          threadDelay 30000000
      | targeted "setup-output-tail" -> do
          isolatedFakeWriteResponse $ Json.JObj [("ok", Json.JBool True)]
          replicateM_ 100 $ hPutStrLn stdout "unread response tail"
          hFlush stdout
          threadDelay 30000000
      | targeted "setup-eof" -> isolatedFakeCloseOutput
      | targeted "setup-malformed" -> isolatedFakeWriteMalformed
      | otherwise -> isolatedFakeWriteResponse $ Json.JObj
          [("env", Json.JInt environment)]

isolatedFakeCommandResponse
  :: FilePath
  -> String
  -> Integer
  -> Integer
  -> IORef Integer
  -> String
  -> Integer
  -> IO ()
isolatedFakeCommandResponse root scenario worker pid sequenceNumber
    command environment = do
  appendFile (isolatedFakeCommandStartedPath root worker)
    $ command ++ "\n"
  sequenceOrdinal <- atomicModifyIORef' sequenceNumber $ \current ->
    let next = current + 1
    in (next, next)
  case command of
    "timeout" -> threadDelay 30000000
    "eof" -> isolatedFakeCloseOutput
    "malformed" -> isolatedFakeWriteMalformed
    "gated" -> waitForHeartbeat
      (isolatedFakeCommandGatePath root worker)
      >> isolatedFakeWriteIdentity sequenceOrdinal
    "fatal" -> isolatedFakeWriteResponse $ Json.JObj
      [("message", Json.JStr "fake command fatal")]
    "error" -> isolatedFakeWriteResponse $ Json.JObj
      [ ("messages", Json.JArr
          [ Json.JObj
              [ ("severity", Json.JStr "error")
              , ("data", Json.JStr "fake command error")
              ]
          ])
      ]
    "sorry" -> isolatedFakeWriteResponse $ Json.JObj
      [("sorries", Json.JArr [Json.JObj []])]
    _ -> isolatedFakeWriteIdentity sequenceOrdinal
 where
  isolatedFakeWriteIdentity sequenceOrdinal =
    isolatedFakeWriteResponse $ Json.JObj
      [ ("pid", Json.JInt pid)
      , ("worker", Json.JInt worker)
      , ("seenEnv", Json.JInt environment)
      , ("env", Json.JInt $ environment + 1000000)
      , ("cmd", Json.JStr command)
      , ("sequence", Json.JInt sequenceOrdinal)
      , ("scenario", Json.JStr scenario)
      ]

isolatedFakeWriteResponse :: Json.JValue -> IO ()
isolatedFakeWriteResponse response = do
  putStr $ Json.encodeJson response ++ "\n\n"
  hFlush stdout

isolatedFakeWriteMalformed :: IO ()
isolatedFakeWriteMalformed = do
  putStr "{malformed fake response\n\n"
  hFlush stdout

-- Closing stderr too lets Backend's bounded diagnostic drain finish before
-- the enclosing request timeout can obscure the intended stdout EOF.
isolatedFakeCloseOutput :: IO ()
isolatedFakeCloseOutput = do
  hClose stdout
  hClose stderr
  threadDelay 30000000

isolatedFakeEnvironment :: Integer -> Integer
isolatedFakeEnvironment worker = 700000 + worker

isolatedFakeSetupPath :: FilePath -> Integer -> FilePath
isolatedFakeSetupPath root worker =
  root </> ("worker-" ++ show worker ++ ".setup")

isolatedFakeHeartbeatPath :: FilePath -> Integer -> FilePath
isolatedFakeHeartbeatPath root worker =
  root </> ("worker-" ++ show worker ++ ".heartbeat")

isolatedFakeClaimPath :: FilePath -> Integer -> FilePath
isolatedFakeClaimPath root worker =
  root </> ("worker-" ++ show worker ++ ".claim")

isolatedFakeCommandStartedPath :: FilePath -> Integer -> FilePath
isolatedFakeCommandStartedPath root worker =
  root </> ("worker-" ++ show worker ++ ".command-started")

isolatedFakeCommandGatePath :: FilePath -> Integer -> FilePath
isolatedFakeCommandGatePath root worker =
  root </> ("worker-" ++ show worker ++ ".command-gate")

waitForFakeCommandCount :: FilePath -> Int -> IO ()
waitForFakeCommandCount path expected = do
  observed <- length . lines <$> readFile path
  if observed >= expected
    then pure ()
    else threadDelay 10000 >> waitForFakeCommandCount path expected

assertFakeWorkerStopped :: FilePath -> Integer -> IO ()
assertFakeWorkerStopped root worker = do
  let heartbeatPath = isolatedFakeHeartbeatPath root worker
  observed <- timeout 3000000 $ waitForHeartbeat heartbeatPath
  case observed of
    Nothing -> assertFailure $ "fake worker " ++ show worker
      ++ " never established its heartbeat"
    Just () -> pure ()
  stabilized <- timeout 3000000 $ waitForStableHeartbeat heartbeatPath
  case stabilized of
    Nothing -> assertFailure $ "fake worker " ++ show worker
      ++ " continued after isolated-pair cleanup"
    Just () -> pure ()

backendStderrFloodMode :: String
backendStderrFloodMode = "__leant_backend_stderr_flood__"

backendProcessTreeWrapperPrefix :: String
backendProcessTreeWrapperPrefix = "__leant_backend_process_tree_wrapper__:"

backendProcessTreeGrandchildMode :: String
backendProcessTreeGrandchildMode = "__leant_backend_process_tree_grandchild__"

backendProcessTreeWrapperExitedPath :: FilePath -> FilePath
backendProcessTreeWrapperExitedPath heartbeatPath =
  heartbeatPath ++ ".wrapper-exited"

backendStderrTailBytes :: Int
backendStderrTailBytes = 64 * 1024

backendStderrTruncationMarker :: String
backendStderrTruncationMarker = "[earlier backend stderr truncated]\n"

backendStderrFloodHelper :: IO ()
backendStderrFloodHelper = do
  hSetBinaryMode stderr True
  ByteString.hPut stderr
    $ ByteString.replicate (2 * backendStderrTailBytes) 80
  ByteString.hPut stderr
    $ ByteString.replicate backendStderrTailBytes 84
  hFlush stderr
  hClose stderr
  putStr "{\"ok\":true}\n\n"
  hFlush stdout
  hClose stdout
  consumeInput
 where
  consumeInput = do
    bytes <- ByteString.hGetSome stdin 4096
    unless (ByteString.null bytes) consumeInput

backendProcessTreeWrapperHelper :: FilePath -> IO ()
backendProcessTreeWrapperHelper heartbeatPath = do
  executable <- getExecutablePath
  let specification
        | os == "mingw32" = proc executable
            [backendProcessTreeGrandchildMode, heartbeatPath]
        | otherwise = proc "/bin/sh"
            [ "-c"
            , "trap '' TERM; exec \"$1\" \"$2\" \"$3\""
            , "leant-backend-grandchild"
            , executable
            , backendProcessTreeGrandchildMode
            , heartbeatPath
            ]
  void $ createProcess specification
  -- Exit the direct wrapper immediately.  The backend must retain the group
  -- address/Job strongly enough to stop this inherited descendant later.
  writeFile (backendProcessTreeWrapperExitedPath heartbeatPath)
    "wrapper launched child and is exiting\n"

backendProcessTreeGrandchildHelper :: FilePath -> IO ()
backendProcessTreeGrandchildHelper heartbeatPath = do
 heartbeat 1500
 where
  -- The finite lifetime is only a final leak guard for a failed cleanup: the
  -- lifecycle test expects the owned process tree to stop within milliseconds.
  heartbeat :: Int -> IO ()
  heartbeat 0 = pure ()
  heartbeat remaining = do
    BS.appendFile heartbeatPath $ BS.singleton 'H'
    threadDelay 10000
    heartbeat $ remaining - 1

waitForMVarBlock :: ThreadId -> IO ()
waitForMVarBlock thread = do
  status <- threadStatus thread
  case status of
    ThreadBlocked BlockedOnMVar -> pure ()
    ThreadFinished -> ioError $ userError
      "thread finished before blocking on its release MVar"
    ThreadDied -> ioError $ userError
      "thread died before blocking on its release MVar"
    _ -> threadDelay 10000 >> waitForMVarBlock thread

waitForHeartbeat :: FilePath -> IO ()
waitForHeartbeat heartbeatPath = do
  exists <- doesFileExist heartbeatPath
  if exists
    then do
      bytes <- ByteString.readFile heartbeatPath
      if ByteString.null bytes
        then pollHeartbeat
        else pure ()
    else pollHeartbeat
 where
  pollHeartbeat = threadDelay 10000 >> waitForHeartbeat heartbeatPath

waitForStableHeartbeat :: FilePath -> IO ()
waitForStableHeartbeat heartbeatPath = do
  initial <- ByteString.length <$> ByteString.readFile heartbeatPath
  observe initial 0
 where
  observe :: Int -> Int -> IO ()
  observe previous stablePolls = do
    threadDelay 20000
    current <- ByteString.length <$> ByteString.readFile heartbeatPath
    if current == previous
      then if stablePolls >= 24
        then pure ()
        else observe current $ stablePolls + 1
      else observe current 0

withTemporaryDirectory :: String -> (FilePath -> IO a) -> IO a
withTemporaryDirectory template action = do
  temporary <- getTemporaryDirectory
  (path, handle) <- openBinaryTempFile temporary template
  hClose handle
  removeFile path
  createDirectory path
  action path `finally` removePathForcibly path

boundedJsonTests :: TestTree
boundedJsonTests = testGroup "strict bounded JSON"
  [ testCase "retain exact values, number spellings, and object order"
      assertBoundedJsonValues
  , testCase "decode UTF-8 scalars and every permitted string escape"
      assertBoundedJsonUnicode
  , testCase "recognize the complete closed syntax-error vocabulary"
      assertBoundedJsonSyntaxErrors
  , testCase "enforce exact JSON number grammar without rounding"
      assertBoundedJsonNumbers
  , testCase "reject decoded duplicate keys, including escaped aliases"
      assertBoundedJsonDuplicateKeys
  , testCase "admit every exact resource boundary and stop at maximum plus one"
      assertBoundedJsonLimits
  , testCase "keep source snippets and duplicate keys out of errors"
      assertBoundedJsonErrorSanitization
  ]

assertBoundedJsonValues :: IO ()
assertBoundedJsonValues = do
  parseBoundedJson generousBoundedJsonLimits
      (BS.pack
        "{\"second\":[null,true,false,-12,1.25,1e+2],\"first\":0}")
    @?= Right (BoundedJsonObject
      [ ( Text.pack "second"
        , BoundedJsonArray
            [ BoundedJsonNull
            , BoundedJsonBool True
            , BoundedJsonBool False
            , BoundedJsonInteger (-12)
            , BoundedJsonNonInteger $ Text.pack "1.25"
            , BoundedJsonNonInteger $ Text.pack "1e+2"
            ]
        )
      , (Text.pack "first", BoundedJsonInteger 0)
      ])
  parseBoundedJson generousBoundedJsonLimits
      (BS.pack " { \"first\" : 0, \"second\" : 1 } \r\n")
    @?= Right (BoundedJsonObject
      [ (Text.pack "first", BoundedJsonInteger 0)
      , (Text.pack "second", BoundedJsonInteger 1)
      ])

assertBoundedJsonUnicode :: IO ()
assertBoundedJsonUnicode = do
  let unicode = Text.pack "\233\x1d11e"
      rawDocument = ByteString.concat
        [BS.pack "\"", TextEncoding.encodeUtf8 unicode, BS.pack "\""]
      escapedDocument = BS.pack
        "\"\\\"\\\\\\/\\b\\f\\n\\r\\t\\u0041\\uD834\\uDD1E\""
      escapedValue = Text.pack
        ['"', '\\', '/', '\b', '\f', '\n', '\r', '\t', 'A', '\x1d11e']
  parseBoundedJson generousBoundedJsonLimits rawDocument @?=
    Right (BoundedJsonString unicode)
  parseBoundedJson generousBoundedJsonLimits escapedDocument @?=
    Right (BoundedJsonString escapedValue)

assertBoundedJsonSyntaxErrors :: IO ()
assertBoundedJsonSyntaxErrors = do
  mapM_ assertCase cases
  parseBoundedJson generousBoundedJsonLimits
      (ByteString.pack [0x6e, 0x75, 0x6c, 0x6c, 0x20, 0xe2, 0x28, 0xa1])
    @?= Left (BoundedJsonSyntaxRejected BoundedJsonInvalidUTF8 6)
 where
  assertCase (label, expected, input) =
    assertBoundedJsonSyntax label expected input

  cases =
    [ ("UTF-8 BOM", BoundedJsonUTF8BOM,
        ByteString.pack [0xef, 0xbb, 0xbf] `ByteString.append`
          BS.pack "null")
    , ("invalid UTF-8", BoundedJsonInvalidUTF8,
        ByteString.pack [0xed, 0xa0, 0x80])
    , ("unexpected end", BoundedJsonUnexpectedEnd, BS.empty)
    , ("unexpected token", BoundedJsonUnexpectedToken, BS.pack "?")
    , ("trailing content", BoundedJsonTrailingContent,
        BS.pack "null null")
    , ("object key", BoundedJsonExpectedObjectKey, BS.pack "{0:0}")
    , ("colon", BoundedJsonExpectedColon, BS.pack "{\"a\" 0}")
    , ("object delimiter", BoundedJsonExpectedObjectDelimiter,
        BS.pack "{\"a\":0 \"b\":1}")
    , ("array delimiter", BoundedJsonExpectedArrayDelimiter,
        BS.pack "[0 1]")
    , ("unterminated string", BoundedJsonUnterminatedString,
        BS.pack "\"unterminated")
    , ("raw control", BoundedJsonRawControlCharacter,
        ByteString.pack [0x22, 0x0a, 0x22])
    , ("escape", BoundedJsonInvalidEscape, BS.pack "\"\\x\"")
    , ("Unicode escape", BoundedJsonInvalidUnicodeEscape,
        BS.pack "\"\\u00xz\"")
    , ("lone high surrogate", BoundedJsonLoneSurrogate,
        BS.pack "\"\\uD800\"")
    , ("number", BoundedJsonInvalidNumber, BS.pack "01")
    , ("duplicate key", BoundedJsonDuplicateObjectKey,
        BS.pack "{\"a\":0,\"\\u0061\":1}")
    ]

assertBoundedJsonNumbers :: IO ()
assertBoundedJsonNumbers = do
  mapM_ assertValid valid
  mapM_ assertInvalid invalid
  assertBoundedJsonSyntax "leading plus" BoundedJsonUnexpectedToken
    $ BS.pack "+1"
 where
  assertValid (source, expected) =
    parseBoundedJson generousBoundedJsonLimits (BS.pack source) @?=
      Right expected

  valid =
    [ ("0", BoundedJsonInteger 0)
    , ("-0", BoundedJsonInteger 0)
    , ("123456789", BoundedJsonInteger 123456789)
    , ("-42", BoundedJsonInteger (-42))
    , ("0.0", BoundedJsonNonInteger $ Text.pack "0.0")
    , ("-0.5", BoundedJsonNonInteger $ Text.pack "-0.5")
    , ("1e9", BoundedJsonNonInteger $ Text.pack "1e9")
    , ("1E+9", BoundedJsonNonInteger $ Text.pack "1E+9")
    , ("1e-9", BoundedJsonNonInteger $ Text.pack "1e-9")
    ]

  assertInvalid source = assertBoundedJsonSyntax source
    BoundedJsonInvalidNumber $ BS.pack source

  invalid = ["01", "-01", "1.", "1e", "1e+", "--1", "1-2"]

assertBoundedJsonDuplicateKeys :: IO ()
assertBoundedJsonDuplicateKeys = do
  mapM_ (assertBoundedJsonSyntax "duplicate object key"
      BoundedJsonDuplicateObjectKey . BS.pack)
    [ "{\"a\":0,\"a\":1}"
    , "{\"a\":0,\"b\":1,\"a\":2}"
    , "{\"a\":0,\"\\u0061\":1}"
    , "{\"\\u00e9\":0,\"\\u00E9\":1}"
    ]

assertBoundedJsonLimits :: IO ()
assertBoundedJsonLimits = do
  mapM_ assertCase boundedJsonLimitCases
  let zeroDepth = generousBoundedJsonLimits
        { boundedJsonMaximumNestingDepth = 0 }
      zeroNodes = generousBoundedJsonLimits
        { boundedJsonMaximumNodes = 0 }
      zeroDepthAndNodes = zeroDepth
        { boundedJsonMaximumNodes = 0 }
  parseBoundedJson zeroDepth (BS.pack "0") @?=
    Right (BoundedJsonInteger 0)
  parseBoundedJson zeroDepth (BS.pack "[]") @?=
    Left (BoundedJsonLimitExceeded BoundedJsonNestingDepth 0 1 0)
  parseBoundedJson zeroNodes (BS.pack "0") @?=
    Left (BoundedJsonLimitExceeded BoundedJsonNodes 0 1 0)
  parseBoundedJson zeroDepthAndNodes (BS.pack "[]") @?=
    Left (BoundedJsonLimitExceeded BoundedJsonNestingDepth 0 1 0)
  parseBoundedJson zeroDepthAndNodes (BS.pack "?") @?=
    Left (BoundedJsonSyntaxRejected BoundedJsonUnexpectedToken 0)
 where
  assertCase
      (label, field, maximumValue, offset, limits, exact, excessive) = do
    case parseBoundedJson limits exact of
      Left failure -> assertFailure $ "exact " ++ label ++
        " boundary was rejected: " ++ show failure
      Right _ -> pure ()
    observed <- timeout 1000000 $ evaluate $
      parseBoundedJson limits excessive
    observed @?= Just (Left $ BoundedJsonLimitExceeded
      field maximumValue (maximumValue + 1) offset)

boundedJsonLimitCases
  :: [( String
      , BoundedJsonLimit
      , Natural
      , Natural
      , BoundedJsonLimits
      , ByteString.ByteString
      , ByteString.ByteString
      )]
boundedJsonLimitCases =
  [ ( "total bytes"
    , BoundedJsonTotalBytes
    , 4
    , 4
    , generousBoundedJsonLimits
        { boundedJsonMaximumTotalBytes = 4 }
    , BS.pack "null"
    , BS.pack "null "
    )
  , ( "nesting depth"
    , BoundedJsonNestingDepth
    , 2
    , 2
    , generousBoundedJsonLimits
        { boundedJsonMaximumNestingDepth = 2 }
    , BS.pack "[[0]]"
    , BS.pack "[[[0]]]"
    )
  , ( "nodes"
    , BoundedJsonNodes
    , 2
    , 3
    , generousBoundedJsonLimits
        { boundedJsonMaximumNodes = 2 }
    , BS.pack "[0]"
    , BS.pack "[0,0]"
    )
  , ( "object members"
    , BoundedJsonObjectMembers
    , 2
    , 13
    , generousBoundedJsonLimits
        { boundedJsonMaximumObjectMembers = 2 }
    , BS.pack "{\"a\":0,\"b\":0}"
    , BS.pack "{\"a\":0,\"b\":0,\"c\":0}"
    )
  , ( "array elements"
    , BoundedJsonArrayElements
    , 2
    , 5
    , generousBoundedJsonLimits
        { boundedJsonMaximumArrayElements = 2 }
    , BS.pack "[0,0]"
    , BS.pack "[0,0,0]"
    )
  , ( "object-key UTF-8 bytes"
    , BoundedJsonObjectKeyUtf8Bytes
    , 2
    , 2
    , generousBoundedJsonLimits
        { boundedJsonMaximumObjectKeyUtf8Bytes = 2 }
    , utf8JsonObject "\233"
    , utf8JsonObject "\8364"
    )
  , ( "string UTF-8 bytes"
    , BoundedJsonStringUtf8Bytes
    , 2
    , 1
    , generousBoundedJsonLimits
        { boundedJsonMaximumStringUtf8Bytes = 2 }
    , utf8JsonString "\233"
    , utf8JsonString "\8364"
    )
  , ( "string Unicode scalars"
    , BoundedJsonStringUnicodeScalars
    , 1
    , 5
    , generousBoundedJsonLimits
        { boundedJsonMaximumStringUnicodeScalars = 1 }
    , utf8JsonString "\x1d11e"
    , utf8JsonString "\x1d11e\&a"
    )
  , ( "number bytes"
    , BoundedJsonNumberBytes
    , 2
    , 2
    , generousBoundedJsonLimits
        { boundedJsonMaximumNumberBytes = 2 }
    , BS.pack "-1"
    , BS.pack "-12"
    )
  ]

assertBoundedJsonErrorSanitization :: IO ()
assertBoundedJsonErrorSanitization = do
  first <- expectBoundedJsonFailure $ BS.pack
    "{\"private-a\":0,\"private-a\":1}"
  second <- expectBoundedJsonFailure $ BS.pack
    "{\"private-b\":0,\"private-b\":1}"
  first @?= second
  let rendered = show first
  assertBool "a duplicate object key leaked through the error"
    $ not $ "private-a" `isInfixOf` rendered
  trailing <- expectBoundedJsonFailure
    $ BS.pack "null PRIVATE_DYNAMIC_TRAILING_BYTES"
  assertBool "trailing source bytes leaked through the error"
    $ not $ "PRIVATE_DYNAMIC_TRAILING_BYTES" `isInfixOf` show trailing

assertBoundedJsonSyntax
  :: String
  -> BoundedJsonErrorKind
  -> ByteString.ByteString
  -> IO ()
assertBoundedJsonSyntax label expected input =
  case parseBoundedJson generousBoundedJsonLimits input of
    Left (BoundedJsonSyntaxRejected observed _) -> observed @?= expected
    Left failure -> assertFailure $ label ++
      " produced a limit failure instead of " ++ show expected ++
      ": " ++ show failure
    Right value -> assertFailure $ label ++ " was accepted as " ++ show value

expectBoundedJsonFailure
  :: ByteString.ByteString
  -> IO BoundedJsonError
expectBoundedJsonFailure input =
  case parseBoundedJson generousBoundedJsonLimits input of
    Left failure -> pure failure
    Right value -> assertFailure ("expected bounded JSON rejection, got " ++
      show value) >> error "unreachable"

generousBoundedJsonLimits :: BoundedJsonLimits
generousBoundedJsonLimits = BoundedJsonLimits
  { boundedJsonMaximumTotalBytes = 1048576
  , boundedJsonMaximumNestingDepth = 1024
  , boundedJsonMaximumNodes = 65536
  , boundedJsonMaximumObjectMembers = 1024
  , boundedJsonMaximumArrayElements = 1024
  , boundedJsonMaximumObjectKeyUtf8Bytes = 65536
  , boundedJsonMaximumStringUtf8Bytes = 65536
  , boundedJsonMaximumStringUnicodeScalars = 65536
  , boundedJsonMaximumNumberBytes = 1024
  }

utf8JsonString :: String -> ByteString.ByteString
utf8JsonString value = ByteString.concat
  [ BS.pack "\""
  , TextEncoding.encodeUtf8 $ Text.pack value
  , BS.pack "\""
  ]

utf8JsonObject :: String -> ByteString.ByteString
utf8JsonObject key = ByteString.concat
  [ BS.pack "{\""
  , TextEncoding.encodeUtf8 $ Text.pack key
  , BS.pack "\":null}"
  ]

sessionReplayTests :: TestTree
sessionReplayTests = testGroup "transactional session replay"
  [ testCase "reconstruct the newest-first undo chain" $ do
      replayed <- replayHistoryWith step (0 :: Int) ["one", "two"]
      replayed @?= Right (2, [1, 0])
  , testCase "report the failing command without a partial result" $ do
      replayed <- replayHistoryWith step (0 :: Int) ["one", "bad", "two"]
      replayed @?= Left "bad"
  , testCase "restore generated-result numbering above a snapshot base" $ do
      itCounterAfterHistory 37
        ["def user := 1", "def \171it!38\187 := (2)", "def \171it!41\187 := (3)"]
        @?= 41
      itCounterAfterHistory 37
        [ "set_option autoImplicit true in def \171it!38\187 : Nat := 2"
        , "set_option autoImplicit true in noncomputable def \171it!40\187"
        ] @?= 40
      itCounterAfterHistory 37 ["def user := 1"] @?= 37
  ]
 where
  step environment command = pure $ case command of
    "one" -> Just (environment + 1)
    "two" -> Just (environment + 1)
    _ -> Nothing

snapshotMetadataTests :: TestTree
snapshotMetadataTests = testGroup "environment snapshot metadata"
  [ testCase "derive stable sibling paths" $ do
      temporary <- getTemporaryDirectory
      let workingDirectory = normalise (temporary </> "project-root")
      snapshotCompanionPath "state.olean"
        @?= "state.leant-synth.olean"
      snapshotMetadataPath "state.olean" @?= "state.leant.json"
      snapshotCompanionPath "state" @?= "state.leant-synth.olean"
      resolveSnapshotPath workingDirectory ("snapshots" </> "state.olean")
        @?= normalise
          (workingDirectory </> "snapshots" </> "state.olean")
  , testCase "round-trip fingerprints, counter, and companion identity" $ do
      let mainFingerprint = SnapshotFingerprint 123 "0123456789abcdef"
          companionFingerprint = SnapshotFingerprint 456 "fedcba9876543210"
          metadata = SnapshotMetadata
            { snapshotItCounter = 37
            , snapshotMainFingerprint = mainFingerprint
            , snapshotSynthesisCompanion = Just SnapshotCompanion
                { snapshotCompanionFile = "state.leant-synth.olean"
                , snapshotCompanionFingerprint = companionFingerprint
                , snapshotCompanionABI = "leant-synth-fnv1a64-abc"
                }
            }
      decodeSnapshotMetadata (encodeSnapshotMetadata metadata)
        @?= Right metadata
      decodeSnapshotMetadata
          (encodeSnapshotMetadata SnapshotMetadata
            { snapshotItCounter = 0
            , snapshotMainFingerprint = mainFingerprint
            , snapshotSynthesisCompanion = Nothing
            })
        @?= Right SnapshotMetadata
          { snapshotItCounter = 0
          , snapshotMainFingerprint = mainFingerprint
          , snapshotSynthesisCompanion = Nothing
          }
  , testCase "fingerprint snapshot contents without loading them whole" $ do
      temporary <- getTemporaryDirectory
      (path, handle) <- openBinaryTempFile temporary "leant-fingerprint.olean"
      BS.hPut handle (BS.pack "hello")
      hClose handle
      fingerprint <- fingerprintSnapshot path `finally` removeFile path
      fingerprint @?= SnapshotFingerprint 5 "a430d84680aabd0b"
  , testCase "reject incompatible or invalid sidecars" $ do
      decodeSnapshotMetadata
          ("{\"format\":\"leant-snapshot\",\"version\":2,"
            ++ "\"itCounter\":0,\"main\":{\"bytes\":0,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"synthesisCompanion\":null}")
        @?= Left "unsupported snapshot metadata version 2"
      decodeSnapshotMetadata
          ("{\"format\":\"leant-snapshot\",\"version\":1,"
            ++ "\"itCounter\":-1,\"main\":{\"bytes\":0,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"synthesisCompanion\":null}")
        @?= Left "snapshot it-counter is out of range"
      decodeSnapshotMetadata
          ("{\"format\":\"leant-snapshot\",\"version\":1,"
            ++ "\"itCounter\":0,\"main\":{\"bytes\":0,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"synthesisCompanion\":{\"file\":\"../stale.olean\","
            ++ "\"fingerprint\":{\"bytes\":0,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"abi\":\"leant-synth-fnv1a64-abc\"}}")
        @?= Left "snapshot companion path must be a sibling filename"
      decodeSnapshotMetadata
          ("{\"format\":\"leant-snapshot\",\"version\":1.4,"
            ++ "\"itCounter\":0,\"main\":{\"bytes\":0,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"synthesisCompanion\":null}")
        @?= Left "missing or invalid snapshot metadata field `version`"
      decodeSnapshotMetadata
          ("{\"format\":\"leant-snapshot\",\"version\":1,"
            ++ "\"itCounter\":0.4,\"main\":{\"bytes\":0,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"synthesisCompanion\":null}")
        @?= Left "missing or invalid snapshot metadata field `itCounter`"
      decodeSnapshotMetadata
          ("{\"format\":\"leant-snapshot\",\"version\":1,"
            ++ "\"itCounter\":0,\"main\":{\"bytes\":1e2,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"synthesisCompanion\":null}")
        @?= Left "missing or invalid snapshot metadata field `bytes`"
      decodeSnapshotMetadata
          ("{\"format\":\"leant-snapshot\",\"version\":1,"
            ++ "\"itCounter\":" ++ show (maxBound :: Int) ++ ","
            ++ "\"main\":{\"bytes\":0,"
            ++ "\"fnv1a64\":\"cbf29ce484222325\"},"
            ++ "\"synthesisCompanion\":null}")
        @?= Left "snapshot it-counter is out of range"
  ]

providerProgramTests :: TestTree
providerProgramTests = testGroup "provider discovery program"
  [ testCase "demote implementation workers but trust session declarations" $ do
      let program = providerProgram ["Demo.listImpl"]
            (ProviderQuery ["Demo"] (Just "List"))
          classifier = unlines
            [ "    let implementationWorker (n : Name) : Bool :="
            , "      match n with"
