verificationObservabilityTests :: TestTree
verificationObservabilityTests = testGroup "verification observability"
  [ testCase "assign unique stable codes to every metric" $ do
      let failures = [minBound .. maxBound]
          metrics =
            [ LegacyCandidateFallback
            , TypedCandidateRendered
            , LeanVariantAttempted
            ]
            ++ map LeanVerificationFailure failures
            ++ [LeanCandidateVerified]
          codes = map leantSynthesisMetricCode metrics
      codes @?=
        [ "legacy-candidate-fallback"
        , "typed-candidate-rendered"
        , "lean-variant-attempted"
        , "lean-verification-failure.backend-request"
        , "lean-verification-failure.backend-fatal-response"
        , "lean-verification-failure.error-diagnostic"
        , "lean-verification-failure.contains-sorry"
        , "lean-candidate-verified"
        ]
      Set.size (Set.fromList codes) @?= length codes
  , testCase "classify rejections exactly once before a success" $ do
      let verdict candidate = pure $ case candidate of
            "request" -> VariantRejected BackendRequestFailure
            "fatal" -> VariantRejected BackendFatalResponse
            "diagnostic" -> VariantRejected LeanErrorDiagnostic
            "sorry" -> VariantRejected LeanContainsSorry
            _ -> VariantAccepted
      batch <- verifyCandidateGroups 1 verdict
        [["request", "fatal", "diagnostic", "sorry", "accepted"]]
      verifiedCandidates batch @?= ["accepted"]
      case verifiedCandidateReceipts batch of
        [receipt] -> verifiedCandidate receipt @?= "accepted"
        receipts -> assertFailure $
          "unexpected verification receipts: " ++ show receipts
      failedCandidateGroups batch @?= 0
      let observations = verificationObservations batch
          failures = sum
            [ observationCount (LeanVerificationFailure failure) observations
            | failure <- [minBound .. maxBound]
            ]
          attempts = observationCount LeanVariantAttempted observations
          verified = observationCount LeanCandidateVerified observations
      attempts @?= 5
      failures @?= 4
      verified @?= 1
      attempts @?= failures + verified
  , testCase "failed groups do not consume the success quota" $ do
      attemptsRef <- newIORef ([] :: [String])
      let verdict candidate = do
            modifyIORef' attemptsRef (++ [candidate])
            pure $ if candidate == "accepted"
              then VariantAccepted
              else VariantRejected LeanErrorDiagnostic
      batch <- verifyCandidateGroups 1 verdict
        [["rejected-1", "rejected-2"], ["accepted"], ["unreached"]]
      attempted <- readIORef attemptsRef
      attempted @?= ["rejected-1", "rejected-2", "accepted"]
      verifiedCandidates batch @?= ["accepted"]
      failedCandidateGroups batch @?= 1
      observationCount LeanVariantAttempted
        (verificationObservations batch) @?= 3
  , testCase
      "separate the bounded spelling frontier from the exact callback trace" $
      do
        attemptsRef <- newIORef ([] :: [String])
        let boundedGroups =
              [ ["first-rejected", "first-accepted", "first-skipped"]
              , ["failed-group"]
              , ["second-accepted", "second-skipped"]
              , ["quota-skipped"]
              ]
            checkedFrontier = concat boundedGroups
            verdict candidate = do
              modifyIORef' attemptsRef (++ [candidate])
              pure $ case candidate of
                "first-rejected" -> VariantRejected LeanErrorDiagnostic
                "failed-group" -> VariantRejected LeanErrorDiagnostic
                _ -> VariantAccepted
        batch <- verifyCandidateGroups 2 verdict boundedGroups
        attempted <- readIORef attemptsRef
        checkedFrontier @?=
          [ "first-rejected"
          , "first-accepted"
          , "first-skipped"
          , "failed-group"
          , "second-accepted"
          , "second-skipped"
          , "quota-skipped"
          ]
        attempted @?=
          [ "first-rejected"
          , "first-accepted"
          , "failed-group"
          , "second-accepted"
          ]
        verifiedCandidates batch @?=
          ["first-accepted", "second-accepted"]
        failedCandidateGroups batch @?= 1
        observationCount LeanVariantAttempted
          (verificationObservations batch) @?= 4
  , testCase "empty groups fail without recording a variant attempt" $ do
      batch <- verifyCandidateGroups 1 (const (pure VariantAccepted))
        [[], ["accepted"]]
      verifiedCandidates batch @?= ["accepted"]
      failedCandidateGroups batch @?= 1
      leantObservationCodeEntries (verificationObservations batch) @?=
        [ ("lean-variant-attempted", 1)
        , ("lean-candidate-verified", 1)
        ]
  , testCase "quota and acceptance leave partial tails untouched" $ do
      zero <- verifyCandidateGroups 0
        (const (assertFailure "zero quota attempted a variant"
          >> pure VariantAccepted))
        (error "zero quota forced the group list")
      verifiedCandidates zero @?= ([] :: [String])
      verificationObservations zero @?= noObservations
      one <- verifyCandidateGroups 1 (const (pure VariantAccepted))
        (("accepted" : error "accepted group forced its variant tail")
          : error "success quota forced the group tail")
      verifiedCandidates one @?= ["accepted"]
      observationCount LeanVariantAttempted
        (verificationObservations one) @?= 1
  , testCase "keep indexed verification provenance lazy at both quotas" $ do
      zero <- verifyCandidateGroups 0
        (\_ -> assertFailure "zero quota attempted an indexed variant"
          >> pure VariantAccepted)
        (map detailedCandidateGroupVerificationVariants
          (error "zero quota forced the detailed group list"))
      verifiedCandidates zero @?= []
      verificationObservations zero @?= noObservations
      let group = detailedCandidateGroup RouteTypedCandidate
            ("accepted" : error "accepted group forced its spelling tail")
          variants = detailedCandidateGroupVerificationVariants group
      one <- verifyCandidateGroups 1
        (\variant -> pure $
          if detailedVerificationVariantText variant == "accepted"
            then VariantAccepted
            else VariantRejected LeanErrorDiagnostic)
        (variants : error "success quota forced the detailed group tail")
      case verifiedCandidates one of
        [accepted] -> do
          detailedVerificationVariantText accepted @?= "accepted"
          detailedVerificationVariantOrdinal accepted @?= 0
          detailedVerificationVariantRoute accepted @?= RouteTypedCandidate
          assertBool "a synthetic group acquired semantic authority"
            (isNothing
              $ detailedVerificationVariantSemanticSidecar accepted)
        accepted -> assertFailure $
          "unexpected indexed verification result: " ++ show accepted
      observationCount LeanVariantAttempted
        (verificationObservations one) @?= 1
  , testCase "stop ranking after exactly five accepted candidates" $ do
      let acceptedGroups =
            [["rank-accepted-" ++ show index]
            | index <- [1 :: Int .. synthMaxShown]
            ]
          groups = acceptedGroups ++ error
            "rank verification forced the group tail after five successes"
      batch <- verifyCandidateGroups synthMaxShown
        (const $ pure VariantAccepted) groups
      verifiedCandidates batch @?= concat acceptedGroups
      observationCount LeanVariantAttempted
        (verificationObservations batch) @?= fromIntegral synthMaxShown
  , testCase "bound an enlarged filter quota before a poison or cyclic tail" $
      do
        let acceptedGroups =
              [["filter-accepted-" ++ show index]
              | index <- [1 :: Int .. synthMaxTried]
              ]
            poisonous = acceptedGroups ++ error
              "filter prefix forced the group tail past its lane bound"
        poisonBatch <- verifyCandidateGroups synthMaxTried
          (const $ pure VariantAccepted)
          (take synthMaxTried poisonous)
        verifiedCandidates poisonBatch @?= concat acceptedGroups
        cyclicBatch <- timeout 1000000 $ verifyCandidateGroups synthMaxTried
          (const $ pure VariantAccepted)
          (take synthMaxTried $ cycle acceptedGroups)
        fmap verifiedCandidates cyclicBatch @?= Just (concat acceptedGroups)
  ]

postVerificationTests :: TestTree
postVerificationTests = testGroup "post-verification ordering boundary"
  [ testCase "keep the disabled stage exact and non-strict" $ do
      verification <- syntheticPostVerificationBatch
        ["post-verification-first", "post-verification-second"]
      skipPostVerificationAssessment verification @?=
        verifiedCandidateReceipts verification
      let poison :: DetailedVerificationVariant
          poison = error "disabled stage forced a verified candidate"
      lazyVerification <- verifyCandidateGroups 1
        (const $ pure VariantAccepted) [[poison]]
      length (skipPostVerificationAssessment lazyVerification) @?= 1
      withPostVerificationInput lazyVerification $ \input -> case
          postVerificationInputCandidates input of
        [candidate] -> do
          batch <- expectRight $ sealPostVerificationBatch 1 input [candidate]
          length (postVerificationBatchCandidates batch) @?= 1
        candidates -> assertFailure $
          "unexpected lazy handle count: " ++ show (length candidates)
  , testCase "seal only a complete exact permutation" $ do
      verification <- syntheticPostVerificationBatch
        [ "post-verification-first"
        , "post-verification-second"
        , "post-verification-third"
        ]
      withPostVerificationInput verification $ \input -> case
          postVerificationInputCandidates input of
        [first, second, third] -> do
          batch <- expectRight $ sealPostVerificationBatch 3 input
            [third, first, second]
          postVerificationBatchCandidates batch @?=
            map postVerificationCandidateVerified [third, first, second]
          assertPostVerificationError
            (PostVerificationProposalLengthMismatch 3 2)
            $ sealPostVerificationBatch 3 input [first, second]
          assertPostVerificationError
            (PostVerificationProposalDuplicateIndex 0)
            $ sealPostVerificationBatch 3 input [first, first, second]
        candidates -> assertFailure $
          "unexpected post-verification handle count: "
            ++ show (length candidates)
  , testCase "keep equal occurrences distinct and bound proposals productively" $ do
      verification <- syntheticPostVerificationBatch
        [ "post-verification-first"
        , "post-verification-second"
        , "post-verification-third"
        ]
      withPostVerificationInput verification $ \input -> case
          postVerificationInputCandidates input of
        [first, second, third] -> do
          assertPostVerificationError
            (PostVerificationCollectionLimitExceeded
              PostVerificationCandidates 2 3)
            $ sealPostVerificationBatch 2 input
                (error "candidate admission forced the proposals")
          bounded <- timeout 1000000 $ evaluate
            $ sealPostVerificationBatch 3 input
                (cycle [first, second, third])
          case bounded of
            Just result -> assertPostVerificationError
              (PostVerificationCollectionLimitExceeded
                PostVerificationProposals 3 4)
              result
            Nothing -> assertFailure
              "cyclic post-verification proposals were not rejected"
        candidates -> assertFailure $
          "unexpected bounded handle count: " ++ show (length candidates)

      duplicates <- syntheticPostVerificationBatch
        ["post-verification-same", "post-verification-same"]
      withPostVerificationInput duplicates $ \input -> case
          postVerificationInputCandidates input of
        [first, second] -> do
          batch <- expectRight $ sealPostVerificationBatch 2 input
            [second, first]
          postVerificationBatchCandidates batch @?=
            map postVerificationCandidateVerified [second, first]
          assertPostVerificationError
            (PostVerificationProposalDuplicateIndex 0)
            $ sealPostVerificationBatch 2 input [first, first]
        candidates -> assertFailure $
          "unexpected duplicate handle count: " ++ show (length candidates)
  ]

syntheticPostVerificationBatch
  :: [String]
  -> IO (VerificationBatch DetailedVerificationVariant)
syntheticPostVerificationBatch spellings =
  verifyCandidateGroups (length spellings) (const $ pure VariantAccepted)
    [ detailedCandidateGroupVerificationVariants
        $ detailedCandidateGroup RouteTypedCandidate [spelling]
    | spelling <- spellings
    ]

assertPostVerificationError
  :: PostVerificationError
  -> Either PostVerificationError batch
  -> IO ()
assertPostVerificationError expected result = case result of
  Left actual -> actual @?= expected
  Right _ -> assertFailure $
    "post-verification proposal was admitted; expected: " ++ show expected

behavioralSelectionTests :: TestTree
behavioralSelectionTests = testGroup "behavioral selection occurrence seal"
  [ testCase "seal an empty batch at the zero limit" $ do
      verification <- syntheticPostVerificationBatch []
      withBehavioralSelectionInput verification $ \input -> do
        batch <- expectRight $ sealBehavioralSelectionBatch 0 input []
        length (behavioralSelectionBatchSelected batch) @?= 0
        length (behavioralSelectionBatchRejected batch) @?= 0
  , testCase
      "partition scrambled decisions in stable original occurrence order" $
      do
        verification <- syntheticPostVerificationBatch
          [ "selection-first"
          , "selection-second"
          , "selection-third"
          , "selection-fourth"
          ]
        withBehavioralSelectionInput verification $ \input -> case
            behavioralSelectionInputCandidates input of
          [first, second, third, fourth] -> do
            batch <- expectRight $ sealBehavioralSelectionBatch 4 input
              [ BehavioralSelectionInternal.rejectBehavioralSelectionCandidate
                  fourth "reject-fourth"
              , BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                  second "retain-second"
              , BehavioralSelectionInternal.rejectBehavioralSelectionCandidate
                  first "reject-first"
              , BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                  third "retain-third"
              ]
            let selected = behavioralSelectionBatchSelected batch
                rejected = behavioralSelectionBatchRejected batch
            map (detailedVerificationVariantText . verifiedCandidate
                . behaviorallySelectedVerified) selected
              @?= ["selection-second", "selection-third"]
            map behaviorallySelectedRetention selected
              @?= ["retain-second", "retain-third"]
            map (detailedVerificationVariantText . verifiedCandidate
                . behaviorallyRejectedVerified) rejected
              @?= ["selection-first", "selection-fourth"]
            map behaviorallyRejectedReason rejected
              @?= ["reject-first", "reject-fourth"]
            length selected + length rejected @?= 4
          candidates -> assertFailure $
            "unexpected behavioral-selection handle count: "
              ++ show (length candidates)
  , testCase "reject missing, extra, and duplicate decisions in precedence" $
      do
        verification <- syntheticPostVerificationBatch
          ["selection-first", "selection-second", "selection-third"]
        withBehavioralSelectionInput verification $ \input -> case
            behavioralSelectionInputCandidates input of
          [first, second, third] -> do
            let retain candidate reason =
                  BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                    candidate reason
                reject candidate reason =
                  BehavioralSelectionInternal.rejectBehavioralSelectionCandidate
                    candidate reason
            assertBehavioralSelectionError
              (BehavioralSelectionDecisionLengthMismatch 3 2)
              $ sealBehavioralSelectionBatch 4 input
                  [ error "length admission forced the first decision"
                  , error "length admission forced the second decision"
                  ]
            assertBehavioralSelectionError
              (BehavioralSelectionDecisionLengthMismatch 3 4)
              $ sealBehavioralSelectionBatch 4 input
                  [ retain first "first"
                  , reject second "second"
                  , retain third "third"
                  , reject first "extra-duplicate"
                  ]
            assertBehavioralSelectionError
              (BehavioralSelectionDecisionDuplicateIndex 0)
              $ sealBehavioralSelectionBatch 3 input
                  [ retain first "first"
                  , reject first "duplicate"
                  , retain third "third"
                  ]
          candidates -> assertFailure $
            "unexpected behavioral-selection handle count: "
              ++ show (length candidates)
  , testCase
      "admit candidates before decisions and bound a cyclic decision spine" $
      do
        oversized <- syntheticPostVerificationBatch
          [ "selection-first"
          , "selection-second"
          , "selection-third"
          , "selection-fourth"
          ]
        withBehavioralSelectionInput oversized $ \input ->
          assertBehavioralSelectionError
            (BehavioralSelectionCollectionLimitExceeded
              BehavioralSelectionCandidates 3 4)
            $ sealBehavioralSelectionBatch 3 input
                (error "candidate admission forced the decision spine")

        verification <- syntheticPostVerificationBatch
          ["selection-first", "selection-second", "selection-third"]
        withBehavioralSelectionInput verification $ \input -> case
            behavioralSelectionInputCandidates input of
          first : _ -> do
            let poisonDecision =
                  BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                    first
                    (error "decision admission forced retention evidence")
            bounded <- timeout 1000000 $ evaluate
              $ sealBehavioralSelectionBatch 3 input
              $ repeat poisonDecision
            case bounded of
              Just result -> assertBehavioralSelectionError
                (BehavioralSelectionCollectionLimitExceeded
                  BehavioralSelectionDecisions 3 4)
                result
              Nothing -> assertFailure
                "cyclic behavioral decisions were not rejected productively"
          [] -> assertFailure "behavioral-selection input was unexpectedly empty"
        -- A cyclic candidate spine cannot be constructed through this safe
        -- boundary: VerificationBatch owns a finite, quota-bounded receipt
        -- list and its constructor is opaque. The finite maximum-plus-one
        -- case above pins the candidate-side admission rule.
  , testCase "keep equal candidate occurrences independently classified" $ do
      verification <- syntheticPostVerificationBatch
        ["selection-same", "selection-same", "selection-same"]
      withBehavioralSelectionInput verification $ \input -> case
          behavioralSelectionInputCandidates input of
        [first, second, third] -> do
          batch <- expectRight $ sealBehavioralSelectionBatch 3 input
            [ BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                third "third-occurrence"
            , BehavioralSelectionInternal.rejectBehavioralSelectionCandidate
                second "second-occurrence"
            , BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                first "first-occurrence"
            ]
          let selected = behavioralSelectionBatchSelected batch
              rejected = behavioralSelectionBatchRejected batch
          map (detailedVerificationVariantText . verifiedCandidate
              . behaviorallySelectedVerified) selected @?=
            ["selection-same", "selection-same"]
          map behaviorallySelectedRetention selected @?=
            ["first-occurrence", "third-occurrence"]
          map (detailedVerificationVariantText . verifiedCandidate
              . behaviorallyRejectedVerified) rejected @?=
            ["selection-same"]
          map behaviorallyRejectedReason rejected @?= ["second-occurrence"]
          assertBehavioralSelectionError
            (BehavioralSelectionDecisionDuplicateIndex 0)
            $ sealBehavioralSelectionBatch 3 input
                [ BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                    first "first"
                , BehavioralSelectionInternal.rejectBehavioralSelectionCandidate
                    first "duplicate"
                , BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                    third "third"
                ]
        candidates -> assertFailure $
          "unexpected equal-occurrence handle count: "
            ++ show (length candidates)
  , testCase "keep candidate and evidence payloads lazy below the seal" $ do
      let poisonCandidate :: DetailedVerificationVariant
          poisonCandidate =
            error "behavioral selection forced a verified candidate payload"
      verification <- verifyCandidateGroups 2
        (const $ pure VariantAccepted)
        [[poisonCandidate], [poisonCandidate]]
      withBehavioralSelectionInput verification $ \input -> case
          behavioralSelectionInputCandidates input of
        [first, second] -> do
          -- Projecting a handle may expose its opaque Verified wrapper without
          -- evaluating the candidate stored beneath that wrapper.
          _ <- evaluate $ behavioralSelectionCandidateVerified first
          batch <- expectRight $ sealBehavioralSelectionBatch 2 input
            [ BehavioralSelectionInternal.rejectBehavioralSelectionCandidate
                second (error "behavioral seal forced rejection evidence")
            , BehavioralSelectionInternal.retainBehavioralSelectionCandidate
                first (error "behavioral seal forced retention evidence")
            ]
          length (behavioralSelectionBatchSelected batch) @?= 1
          length (behavioralSelectionBatchRejected batch) @?= 1
          case behavioralSelectionBatchSelected batch of
            [selected] -> do
              _ <- evaluate $ behaviorallySelectedVerified selected
              pure ()
            selected -> assertFailure $
              "unexpected lazy selected partition: " ++ show (length selected)
          case behavioralSelectionBatchRejected batch of
            [rejected] -> do
              _ <- evaluate $ behaviorallyRejectedVerified rejected
              pure ()
            rejected -> assertFailure $
              "unexpected lazy rejected partition: " ++ show (length rejected)
        candidates -> assertFailure $
          "unexpected poison-candidate handle count: "
            ++ show (length candidates)
  , testCase "keep epoch handles, decisions, and batch constructors opaque" $ do
      publicSource <- readFile "src/Leant/Synth/BehavioralSelection.hs"
      internalSource <- readFile
        "src/Leant/Synth/BehavioralSelection/Internal.hs"
      let exportHeader = unlines
            . takeWhile (not . isInfixOf ") where")
            . lines
          publicExports = exportHeader publicSource
          internalExports = exportHeader internalSource
          opaqueTypes =
            [ "BehavioralSelectionInput"
            , "BehavioralSelectionCandidate"
            , "BehavioralSelectionDecision"
            , "BehaviorallySelected"
            , "BehaviorallyRejected"
            , "BehavioralSelectionBatch"
            ]
          builders =
            [ "retainBehavioralSelectionCandidate"
            , "rejectBehavioralSelectionCandidate"
            ]
      mapM_ (\name -> assertBool
          ("public facade exposed decision builder " ++ name)
          $ not $ name `isInfixOf` publicExports) builders
      mapM_ (\name -> assertBool
          ("internal surface omitted decision builder " ++ name)
          $ name `isInfixOf` internalExports) builders
      mapM_ (\name -> do
          assertBool ("public facade exposed constructor for " ++ name)
            $ not $ (name ++ " (..)") `isInfixOf` publicExports
          assertBool ("internal surface exposed constructor for " ++ name)
            $ not $ (name ++ " (..)") `isInfixOf` internalExports)
        opaqueTypes
      mapM_ (\roleLine -> assertBool
          ("behavioral selection lost nominal role: " ++ roleLine)
          $ roleLine `isInfixOf` internalSource)
        [ "type role BehavioralSelectionInput nominal nominal"
        , "type role BehavioralSelectionCandidate nominal nominal"
        , "type role BehavioralSelectionDecision nominal nominal nominal nominal"
        , "type role BehavioralSelectionBatch nominal nominal nominal"
        ]
  ]

assertBehavioralSelectionError
  :: BehavioralSelectionError
  -> Either BehavioralSelectionError batch
  -> IO ()
assertBehavioralSelectionError expected result = case result of
  Left actual -> actual @?= expected
  Right _ -> assertFailure $
    "behavioral selection was admitted; expected: " ++ show expected

lengthSelectionTests :: TestTree
lengthSelectionTests = testGroup "hard Length behavioral selection"
  [ testCase
      "reject a pure guarded scalar counterexample without opening Z3"
      assertLengthSelectionGuardedPure
  , testCase
      "reuse replay only within one selection and preserve occurrence order"
      assertLengthSelectionLiveMRU
  , testCase
      "retain raw sat, unsat, unknown, and preparation refusals explicitly"
      assertLengthSelectionNeutralStatuses
  , testCase
      "retain bounded positives and reject only their replayed sibling"
      assertLengthSelectionBoundedPositive
  , testCase
      "atomically preserve every candidate on adapter and live failures"
      assertLengthSelectionPreserveAllFailures
  , testCase
      "seal nominal pair evidence and keep both partitions in source order"
      assertLengthSpinePairSelection
  , testCase "preserve pair unknowns and atomically reset pair live failure"
      assertLengthSpinePairSelectionNeutralAndFailure
  , testCase "keep scalar and pair selection evidence opaque and distinct"
      assertLengthSelectionFacadeOpacity
  ]

assertLengthSelectionGuardedPure :: IO ()
assertLengthSelectionGuardedPure = do
  (baseContract, scaled, identity) <- buildScaledProviderReplayFixture
  withTemporaryDirectory "leant-length-selection-guarded" $ \root -> do
    let executable = root </> "missing-z3"
        input = LengthVariable $ LengthInput 0
        guardedDomain = LengthAtMost
          (LengthIf
            (LengthAtMost input $ LengthLiteral 2)
            input
            (LengthLiteral 5))
          (LengthLiteral 3)
        contract = baseContract
          { leanLengthContractSource = LengthContractSource
              { lengthContractPrecondition = guardedDomain
              , lengthContractPostcondition = LengthEqual
                  (LengthVariable LengthResult) input
              }
          }
    (policy, _) <- expectCurrentApplicableDomainPolicy
      $ currentApplicableDomainScalarDocument executable 2000
    verification <- verificationBatchFromReceipts [scaled, identity]
    let original = verifiedCandidateReceipts verification
    result <- expectLengthSelectionWithin "guarded pure scalar"
      $ selectVerifiedLengthCandidatesWithPolicy policy contract verification
    lengthSelectionFailure result @?= Nothing
    selected <- expectLengthSelectionSelected result
    rejected <- expectLengthSelectionRejected result
    case original of
      [verifiedScaled, verifiedIdentity] -> do
        lengthSelectionCandidates result @?= [verifiedIdentity]
        map behaviorallySelectedVerified selected @?= [verifiedIdentity]
        map behaviorallyRejectedVerified rejected @?= [verifiedScaled]
      _ -> assertFailure "guarded scalar verification cardinality changed"
    case selected of
      [retained] -> do
        let evidence = behaviorallySelectedRetention retained
        lengthSelectionRetentionClass evidence @?=
          LengthSelectionApplicableDomainEstablished
        lengthSelectionRetentionPreparationRefusal evidence @?= Nothing
        lengthSelectionRetentionSolverStatus evidence @?= Nothing
        lengthSelectionRetentionInputBox evidence @?= Nothing
        receipt <- case lengthSelectionRetentionApplicableDomain evidence of
          Nothing -> assertFailure
            "guarded scalar survivor lost its applicable-domain receipt"
              >> error "unreachable"
          Just value -> pure value
        Djex.validatedLengthApplicableDomainInclusiveMaximumBoxes receipt @?=
          [[2]]
        Djex.validatedLengthApplicableDomainApplicableAssignmentCount receipt
          @?= 3
      retained -> assertFailure $ "guarded scalar retained "
        ++ show (length retained) ++ " candidates"
    case rejected of
      [removed] -> do
        let evidence = behaviorallyRejectedReason removed
            receipt = lengthSelectionRejectionCounterexample evidence
        Djex.validatedLengthCounterexampleInputs receipt @?= [1]
        Djex.validatedLengthCounterexampleResult receipt @?= 2
        lengthSelectionRejectionCounterexampleSimplification evidence @?=
          Nothing
      removed -> assertFailure $ "guarded scalar rejected "
        ++ show (length removed) ++ " candidates"
    doesFileExist executable >>= (@?= False)
    doesFileExist (executable ++ ".events") >>= (@?= False)

assertLengthSelectionLiveMRU :: IO ()
assertLengthSelectionLiveMRU = do
  identity <- buildOneInputLengthRankingCandidate
  retainedFirst <- syntheticLengthRankingCandidate
    "selection-live-retained-first"
  retainedSecond <- syntheticLengthRankingCandidate
    "selection-live-retained-second"
  let input = LengthVariable $ LengthInput 0
      contract = (lengthRankingContractWithObservedInputs 1 2)
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthAtMost
                (LengthLiteral 1) input
            , lengthContractPostcondition = LengthEqual
                (LengthVariable LengthResult) (LengthLiteral 2)
            }
        }
  withFakeLengthSolver "healthy" $ \executable -> do
    base <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits
          (explicitLengthRankingExecutionSource executable Nothing
            Djex.LengthSMTLibInputValuesAfterSatisfiable)
          Djex.defaultLengthEvaluationLimitSource
    simplificationLimits <- explicitLengthInputBoxLimits 1 4
    let policy = enableLengthRankingCounterexampleSimplification
          simplificationLimits base
    verification <- verificationBatchFromReceipts
      [identity, retainedFirst, identity, retainedSecond]
    let original = verifiedCandidateReceipts verification
    result <- expectLengthSelectionWithin "live scalar MRU"
      $ selectVerifiedLengthCandidatesWithPolicy policy contract verification
    lengthSelectionFailure result @?= Nothing
    selected <- expectLengthSelectionSelected result
    rejected <- expectLengthSelectionRejected result
    case original of
      [verifiedIdentityFirst, verifiedRetainedFirst,
          verifiedIdentitySecond, verifiedRetainedSecond] -> do
        lengthSelectionCandidates result @?=
          [verifiedRetainedFirst, verifiedRetainedSecond]
        map behaviorallySelectedVerified selected @?=
          [verifiedRetainedFirst, verifiedRetainedSecond]
        map behaviorallyRejectedVerified rejected @?=
          [verifiedIdentityFirst, verifiedIdentitySecond]
      _ -> assertFailure "live scalar verification cardinality changed"
    map (lengthSelectionRetentionClass . behaviorallySelectedRetention)
        selected @?=
      replicate 2 LengthSelectionPreparationRefused
    map (lengthSelectionRetentionPreparationRefusal
          . behaviorallySelectedRetention) selected @?=
      replicate 2 (Just LengthPreparationTypedAuthorityUnavailable)
    let evidence = map behaviorallyRejectedReason rejected
        receipts = map lengthSelectionRejectionCounterexample evidence
        simplifications = map
          lengthSelectionRejectionCounterexampleSimplification evidence
    map Djex.validatedLengthCounterexampleInputs receipts @?=
      [[1], [1]]
    map Djex.validatedLengthCounterexampleResult receipts @?= [1, 1]
    case simplifications of
      [Just simplified, Nothing] -> do
        Djex.validatedLengthCounterexampleSimplificationOriginalInputs
            simplified @?= [3]
        Djex.validatedLengthCounterexampleSimplificationInputs simplified @?=
          [1]
        Djex.validatedLengthCounterexampleSimplificationResult simplified @?=
          1
      other -> assertFailure $ "selection reassociated simplification: "
        ++ show other
    firstEvents <- BS.readFile $ executable ++ ".events"
    assertFakeLengthQueryEvents [0] [0] firstEvents

    -- The MRU bank belongs to one ranking invocation.  Reusing the immutable
    -- policy for a fresh verification batch must open a new ordinal-zero
    -- query instead of treating the prior batch's vector as authority.
    freshVerification <- verificationBatchFromReceipts [identity]
    fresh <- expectLengthSelectionWithin "fresh scalar MRU scope"
      $ selectVerifiedLengthCandidatesWithPolicy
          policy contract freshVerification
    lengthSelectionCandidates fresh @?= []
    freshSelected <- expectLengthSelectionSelected fresh
    freshRejected <- expectLengthSelectionRejected fresh
    length freshSelected @?= 0
    case freshRejected of
      [removed] -> case
          lengthSelectionRejectionCounterexampleSimplification
            $ behaviorallyRejectedReason removed of
        Just simplified ->
          Djex.validatedLengthCounterexampleSimplificationOriginalInputs
              simplified @?= [3]
        Nothing -> assertFailure
          "fresh scalar invocation reused earlier simplification metadata"
      removed -> assertFailure $ "fresh scalar selection rejected "
        ++ show (length removed) ++ " candidates"
    secondEvents <- BS.readFile $ executable ++ ".events"
    assertFakeLengthQueryEvents [0] [0] secondEvents

assertLengthSelectionNeutralStatuses :: IO ()
assertLengthSelectionNeutralStatuses = do
  fixture <- buildLengthRankingLiveFixture
  refused <- syntheticLengthRankingCandidate "selection-status-refused"
  let candidates =
        [ lengthRankingFixtureZero fixture
        , refused
        , lengthRankingFixtureOne fixture
        ]
      cases =
        [ ("healthy", Djex.SolverSatisfiable)
        , ("query-unsat", Djex.SolverUnsatisfiable)
        , ("query-unknown", Djex.SolverUnknown)
        ]
  verification <- verificationBatchFromReceipts candidates
  let original = verifiedCandidateReceipts verification
  mapM_ (assertStatusCase verification original) cases
 where
  assertStatusCase verification original (mode, expectedStatus) =
    withFakeLengthSolver mode $ \executable -> do
      policy <- expectRight $ statusOnlyLengthRankingPolicy executable
      result <- expectLengthSelectionWithin ("status-only " ++ mode)
        $ selectVerifiedLengthCandidatesWithPolicy policy
            (lengthRankingContract 0) verification
      lengthSelectionFailure result @?= Nothing
      lengthSelectionCandidates result @?= original
      selected <- expectLengthSelectionSelected result
      rejected <- expectLengthSelectionRejected result
      map behaviorallySelectedVerified selected @?= original
      length rejected @?= 0
      let evidence = map behaviorallySelectedRetention selected
      map lengthSelectionRetentionClass evidence @?=
        [ LengthSelectionHeuristic
        , LengthSelectionPreparationRefused
        , LengthSelectionHeuristic
        ]
      map lengthSelectionRetentionSolverStatus evidence @?=
        [Just expectedStatus, Nothing, Just expectedStatus]
      map lengthSelectionRetentionPreparationRefusal evidence @?=
        [ Nothing
        , Just LengthPreparationTypedAuthorityUnavailable
        , Nothing
        ]
      map lengthSelectionRetentionInputBox evidence @?=
        replicate 3 Nothing
      map lengthSelectionRetentionApplicableDomain evidence @?=
        replicate 3 Nothing
      assertFakeLengthQueryEvents [0, 1] [] =<<
        BS.readFile (executable ++ ".events")

assertLengthSelectionBoundedPositive :: IO ()
assertLengthSelectionBoundedPositive = do
  fixture <- buildLengthRankingLiveFixture
  limits <- explicitLengthInputBoxLimits 0 1
  let one = lengthRankingFixtureOne fixture
      zero = lengthRankingFixtureZero fixture
  verification <- verificationBatchFromReceipts [one, zero]
  let original = verifiedCandidateReceipts verification
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let policy = enableLengthRankingInputBoxValidation limits [] base
    result <- expectLengthSelectionWithin "bounded-positive scalar"
      $ selectVerifiedLengthCandidatesWithPolicy policy
          (lengthRankingContract 0) verification
    selected <- expectLengthSelectionSelected result
    rejected <- expectLengthSelectionRejected result
    case original of
      [verifiedOne, verifiedZero] -> do
        lengthSelectionCandidates result @?= [verifiedZero]
        map behaviorallySelectedVerified selected @?= [verifiedZero]
        map behaviorallyRejectedVerified rejected @?= [verifiedOne]
      _ -> assertFailure "bounded-positive verification cardinality changed"
    case selected of
      [retained] -> do
        let evidence = behaviorallySelectedRetention retained
        lengthSelectionRetentionClass evidence @?=
          LengthSelectionBoundedPositive
        receipt <- case lengthSelectionRetentionInputBox evidence of
          Nothing -> assertFailure
            "bounded-positive selection lost its exact receipt"
              >> error "unreachable"
          Just value -> pure value
        Djex.validatedLengthInputBoxAssignmentCount receipt @?= 1
        Djex.validatedLengthInputBoxApplicableAssignmentCount receipt @?= 1
      retained -> assertFailure $ "bounded-positive selection retained "
        ++ show (length retained) ++ " candidates"
    case rejected of
      [removed] -> do
        let receipt = lengthSelectionRejectionCounterexample
              $ behaviorallyRejectedReason removed
        Djex.validatedLengthCounterexampleInputs receipt @?= []
        Djex.validatedLengthCounterexampleResult receipt @?= 1
      removed -> assertFailure $ "bounded-positive selection rejected "
        ++ show (length removed) ++ " candidates"
    assertFakeLengthQueryEvents [0, 1] [] =<<
      BS.readFile (executable ++ ".events")

assertLengthSelectionPreserveAllFailures :: IO ()
assertLengthSelectionPreserveAllFailures = do
  identity <- buildOneInputLengthRankingCandidate
  let maximumCandidates =
        Djex.defaultLengthSMTLibLiveSessionMaximumQueries
      oversizedCount = fromIntegral maximumCandidates + 1
  oversized <- verificationBatchFromReceipts
    $ replicate oversizedCount identity
  withTemporaryDirectory "leant-length-selection-input-failure" $ \root -> do
    policy <- expectRight $ statusOnlyLengthRankingPolicy
      $ root </> "missing-z3"
    result <- expectLengthSelectionWithin "maximum-plus-one input"
      $ selectVerifiedLengthCandidatesWithPolicy policy
          (error "selection input admission forced its contract") oversized
    case lengthSelectionFailure result of
      Just (LengthSelectionPostVerificationFailed
          (LengthPostVerificationInputRejected
            (LengthRankingInputLimitExceeded maximumValue observed))) ->
        (maximumValue, observed) @?=
          (maximumCandidates, maximumCandidates + 1)
      failure -> assertFailure $ "unexpected selection input failure: "
        ++ show failure
    assertLengthSelectionPreserved
      (verifiedCandidateReceipts oversized) result

  fixture <- buildLengthRankingLiveFixture
  trailing <- syntheticLengthRankingCandidate
    "selection-invalid-replay-trailing"
  invalidReplay <- verificationBatchFromReceipts
    [ lengthRankingFixtureOne fixture
    , lengthRankingFixtureZero fixture
    , trailing
    ]
  withFakeLengthSolver "healthy" $ \executable -> do
    policy <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits
          (explicitLengthRankingExecutionSource executable Nothing
            Djex.LengthSMTLibInputValuesAfterSatisfiable)
          Djex.defaultLengthEvaluationLimitSource
    result <- expectLengthSelectionWithin "invalid satisfiable replay"
      $ selectVerifiedLengthCandidatesWithPolicy policy
          (lengthRankingContract 0) invalidReplay
    assertLengthSelectionRankingPreserved
      (verifiedCandidateReceipts invalidReplay) result

  sessionVerification <- verificationBatchFromReceipts
    [lengthRankingFixtureOne fixture]
  withTemporaryDirectory "leant-length-selection-session-failure" $ \root ->
    do
      let executable = root </> "missing-z3"
      policy <- expectRight $ statusOnlyLengthRankingPolicy executable
      result <- expectLengthSelectionWithin "missing live session"
        $ selectVerifiedLengthCandidatesWithPolicy policy
            (lengthRankingContract 0) sessionVerification
      assertLengthSelectionRankingPreserved
        (verifiedCandidateReceipts sessionVerification) result
      doesFileExist (executable ++ ".events") >>= (@?= False)

  assertLiveFailure fixture "query-hang-status"
    Djex.LengthSMTLibStatusOnly
  assertLiveFailure fixture "query-stale-prewrite"
    Djex.LengthSMTLibInputValuesAfterSatisfiable
 where
  assertLiveFailure fixture mode artifactPolicy =
    withFakeLengthSolver mode $ \executable -> do
      policy <- expectRight $ mkLengthRankingPolicy
        $ explicitLengthRankingPolicySource
            Djex.defaultLengthSMTLibExecutionLimits
            (explicitLengthRankingExecutionSource executable Nothing
              artifactPolicy)
            Djex.defaultLengthEvaluationLimitSource
      verification <- verificationBatchFromReceipts
        [lengthRankingFixtureOne fixture]
      result <- expectLengthSelectionWithin ("live failure " ++ mode)
        $ selectVerifiedLengthCandidatesWithPolicy policy
            (lengthRankingContract 0) verification
      assertLengthSelectionRankingPreserved
        (verifiedCandidateReceipts verification) result

assertLengthSpinePairSelection :: IO ()
assertLengthSpinePairSelection = do
  (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
  refused <- syntheticLengthRankingCandidate "pair-selection-refused"
  withTemporaryDirectory "leant-length-pair-selection" $ \root -> do
    let executable = root </> "missing-z3"
        input = LengthVariable $ Djex.LengthSpinePairInput 0
        guardedDomain = LengthAtMost
          (LengthIf
            (LengthAtMost input $ LengthLiteral 2)
            input
            (LengthLiteral 5))
          (LengthLiteral 3)
        contract = lengthSpinePairRankingContract
          { leanLengthSpinePairContractSource =
              (leanLengthSpinePairContractSource
                lengthSpinePairRankingContract)
                { Djex.lengthSpinePairContractPrecondition = guardedDomain
                }
          }
    (policy, _) <- expectCurrentApplicableDomainPolicy
      $ currentApplicableDomainPairDocument executable 2000
    verification <- verificationBatchFromReceipts
      [duplicatedInput, refused, inputAndZero, duplicatedInput]
    let original = verifiedCandidateReceipts verification
    result <- expectLengthSpinePairSelectionWithin
      $ selectVerifiedLengthSpinePairCandidatesWithPolicy
          policy contract verification
    lengthSpinePairSelectionFailure result @?= Nothing
    selected <- expectLengthSpinePairSelectionSelected result
    rejected <- expectLengthSpinePairSelectionRejected result
    case original of
      [verifiedDuplicateFirst, verifiedRefused,
          verifiedInputAndZero, verifiedDuplicateSecond] -> do
        lengthSpinePairSelectionCandidates result @?=
          [verifiedRefused, verifiedInputAndZero]
        map behaviorallySelectedVerified selected @?=
          [verifiedRefused, verifiedInputAndZero]
        map behaviorallyRejectedVerified rejected @?=
          [verifiedDuplicateFirst, verifiedDuplicateSecond]
      _ -> assertFailure "pair selection verification cardinality changed"
    let retainedEvidence = map behaviorallySelectedRetention selected
    map lengthSpinePairSelectionRetentionClass retainedEvidence @?=
      [ LengthSpinePairSelectionPreparationRefused
      , LengthSpinePairSelectionApplicableDomainEstablished
      ]
    map lengthSpinePairSelectionRetentionPreparationRefusal
        retainedEvidence @?=
      [Just LengthPreparationTypedAuthorityUnavailable, Nothing]
    map lengthSpinePairSelectionRetentionSolverStatus retainedEvidence @?=
      [Nothing, Nothing]
    map lengthSpinePairSelectionRetentionInputBox retainedEvidence @?=
      [Nothing, Nothing]
    case map lengthSpinePairSelectionRetentionApplicableDomain
        retainedEvidence of
      [Nothing, Just receipt] -> do
        Djex.validatedLengthSpinePairApplicableDomainInclusiveMaximumBoxes
            receipt @?= [[2]]
        Djex.validatedLengthSpinePairApplicableDomainApplicableAssignmentCount
            receipt @?= 3
      receipts -> assertFailure $ "pair retention evidence drifted: "
        ++ show receipts
    let rejectionEvidence = map behaviorallyRejectedReason rejected
        receipts = map
          lengthSpinePairSelectionRejectionCounterexample rejectionEvidence
    map Djex.validatedLengthSpinePairCounterexampleInputs receipts @?=
      [[1], [1]]
    map Djex.validatedLengthSpinePairCounterexampleResult receipts @?=
      replicate 2 (Djex.LengthSpinePair 1 1)
    map lengthSpinePairSelectionRejectionCounterexampleSimplification
        rejectionEvidence @?= replicate 2 Nothing
    doesFileExist executable >>= (@?= False)
    doesFileExist (executable ++ ".events") >>= (@?= False)

assertLengthSpinePairSelectionNeutralAndFailure :: IO ()
assertLengthSpinePairSelectionNeutralAndFailure = do
  (duplicatedInput, _) <- buildLengthSpinePairRankingFixture
  refused <- syntheticLengthRankingCandidate "pair-selection-unknown-refused"
  verification <- verificationBatchFromReceipts [duplicatedInput, refused]
  let original = verifiedCandidateReceipts verification
  withFakeLengthSolver "query-unknown" $ \executable -> do
    policy <- expectRight $ statusOnlyLengthRankingPolicy executable
    result <- expectLengthSpinePairSelectionWithin
      $ selectVerifiedLengthSpinePairCandidatesWithPolicy
          policy lengthSpinePairSecondOneContract verification
    lengthSpinePairSelectionFailure result @?= Nothing
    lengthSpinePairSelectionCandidates result @?= original
    selected <- expectLengthSpinePairSelectionSelected result
    rejected <- expectLengthSpinePairSelectionRejected result
    map behaviorallySelectedVerified selected @?= original
    length rejected @?= 0
    let evidence = map behaviorallySelectedRetention selected
    map lengthSpinePairSelectionRetentionClass evidence @?=
      [ LengthSpinePairSelectionHeuristic
      , LengthSpinePairSelectionPreparationRefused
      ]
    map lengthSpinePairSelectionRetentionSolverStatus evidence @?=
      [Just Djex.SolverUnknown, Nothing]
    map lengthSpinePairSelectionRetentionPreparationRefusal evidence @?=
      [Nothing, Just LengthPreparationTypedAuthorityUnavailable]
    assertFakeLengthQueryEvents [0] [] =<<
      BS.readFile (executable ++ ".events")

  failingVerification <- verificationBatchFromReceipts [duplicatedInput]
  let failingOriginal = verifiedCandidateReceipts failingVerification
  withFakeLengthSolver "query-hang-status" $ \executable -> do
    policy <- expectRight $ statusOnlyLengthRankingPolicy executable
    result <- expectLengthSpinePairSelectionWithin
      $ selectVerifiedLengthSpinePairCandidatesWithPolicy
          policy lengthSpinePairSecondOneContract failingVerification
    case lengthSpinePairSelectionFailure result of
      Just LengthSpinePairSelectionRankingFailed{} -> pure ()
      failure -> assertFailure $ "unexpected pair selection failure: "
        ++ show failure
    lengthSpinePairSelectionCandidates result @?= failingOriginal
    assertBool "pair failure exposed selected associations"
      $ isNothing $ lengthSpinePairSelectionSelected result
    assertBool "pair failure exposed rejected associations"
      $ isNothing $ lengthSpinePairSelectionRejected result

assertLengthSelectionFacadeOpacity :: IO ()
assertLengthSelectionFacadeOpacity = do
  scalarSource <- readFile "src/Leant/Synth/Length/Selection.hs"
  pairSource <- readFile
    "src/Leant/Synth/Length/SpinePair/Selection.hs"
  let exportHeader = unlines
        . takeWhile (not . isInfixOf ") where")
        . lines
      scalarExports = exportHeader scalarSource
      pairExports = exportHeader pairSource
      opaqueScalar =
        [ "LengthSelectionRetention"
        , "LengthSelectionRejection"
        , "LengthSelectionResult"
        ]
      opaquePair =
        [ "LengthSpinePairSelectionRetention"
        , "LengthSpinePairSelectionRejection"
        , "LengthSpinePairSelectionResult"
        ]
  mapM_ (assertOpaque "scalar" scalarExports) opaqueScalar
  mapM_ (assertOpaque "pair" pairExports) opaquePair
  assertBool "scalar facade omitted its nominal rejection type"
    $ "LengthSelectionRejection" `isInfixOf` scalarExports
  assertBool "pair facade omitted its nominal rejection type"
    $ "LengthSpinePairSelectionRejection" `isInfixOf` pairExports
  assertBool "scalar facade exposed the pair rejection type"
    $ not $ "LengthSpinePairSelectionRejection" `isInfixOf` scalarExports
  assertBool "pair facade reused the scalar rejection type"
    $ not $ "\n  , LengthSelectionRejection" `isInfixOf` pairExports
 where
  assertOpaque domain exports name = assertBool
    (domain ++ " selection facade exposed constructor for " ++ name)
    $ not $ (name ++ " (..)") `isInfixOf` exports

expectLengthSelectionWithin
  :: String
  -> IO LengthSelectionResult
  -> IO LengthSelectionResult
expectLengthSelectionWithin label action = do
  bounded <- timeout 8000000 action
  case bounded of
    Nothing -> assertFailure
      ("Length selection " ++ label ++ " exceeded its outer bound")
        >> error "unreachable"
    Just result -> pure result

expectLengthSelectionSelected
  :: LengthSelectionResult
  -> IO
      [BehaviorallySelected
        DetailedVerificationVariant LengthSelectionRetention]
expectLengthSelectionSelected result = case lengthSelectionSelected result of
  Nothing -> assertFailure "Length selection discarded its selected seal"
    >> error "unreachable"
  Just selected -> pure selected

expectLengthSelectionRejected
  :: LengthSelectionResult
  -> IO
      [BehaviorallyRejected
        DetailedVerificationVariant LengthSelectionRejection]
expectLengthSelectionRejected result = case lengthSelectionRejected result of
  Nothing -> assertFailure "Length selection discarded its rejected seal"
    >> error "unreachable"
  Just rejected -> pure rejected

assertLengthSelectionPreserved
  :: [Verified DetailedVerificationVariant]
  -> LengthSelectionResult
  -> IO ()
assertLengthSelectionPreserved original result = do
  lengthSelectionCandidates result @?= original
  assertBool "preserved Length selection exposed selected associations"
    $ isNothing $ lengthSelectionSelected result
  assertBool "preserved Length selection exposed rejected associations"
    $ isNothing $ lengthSelectionRejected result

assertLengthSelectionRankingPreserved
  :: [Verified DetailedVerificationVariant]
  -> LengthSelectionResult
  -> IO ()
assertLengthSelectionRankingPreserved original result = do
  case lengthSelectionFailure result of
    Just LengthSelectionRankingFailed{} -> pure ()
    failure -> assertFailure $ "unexpected preserved ranking failure: "
      ++ show failure
  assertLengthSelectionPreserved original result

expectLengthSpinePairSelectionWithin
  :: IO LengthSpinePairSelectionResult
  -> IO LengthSpinePairSelectionResult
expectLengthSpinePairSelectionWithin action = do
  bounded <- timeout 8000000 action
  case bounded of
    Nothing -> assertFailure
      "Length pair selection exceeded its outer bound"
        >> error "unreachable"
    Just result -> pure result

expectLengthSpinePairSelectionSelected
  :: LengthSpinePairSelectionResult
  -> IO
      [BehaviorallySelected
        DetailedVerificationVariant LengthSpinePairSelectionRetention]
expectLengthSpinePairSelectionSelected result = case
    lengthSpinePairSelectionSelected result of
  Nothing -> assertFailure "pair selection discarded its selected seal"
    >> error "unreachable"
  Just selected -> pure selected

expectLengthSpinePairSelectionRejected
  :: LengthSpinePairSelectionResult
  -> IO
      [BehaviorallyRejected
        DetailedVerificationVariant LengthSpinePairSelectionRejection]
expectLengthSpinePairSelectionRejected result = case
    lengthSpinePairSelectionRejected result of
  Nothing -> assertFailure "pair selection discarded its rejected seal"
    >> error "unreachable"
  Just rejected -> pure rejected

replayPlanTests :: TestTree
replayPlanTests = testGroup "synthesis history replay"
  [ testCase "reuse an exact cached history" $
      planReplay ["def a := 1"] ["def a := 1"] @?= Reuse
  , testCase "replay only an appended suffix" $
      planReplay
          ["def a := 1", "def b := a"]
          ["def a := 1", "def b := a", "def «it!1» := b"]
        @?= ReplaySuffix ["def «it!1» := b"]
  , testCase "rebuild after undo shortens the history" $
      planReplay ["def a := 1", "def b := a"] ["def a := 1"]
        @?= ReplayAll ["def a := 1"]
  , testCase "rebuild after an earlier entry is replaced" $
      planReplay ["def a := 1", "def b := a"]
          ["def a := 2", "def b := a"]
        @?= ReplayAll ["def a := 2", "def b := a"]
  , testCase "respect duplicates at the prefix boundary" $
      planReplay ["a", "b"] ["a", "b", "b", "c"]
        @?= ReplaySuffix ["b", "c"]
  ]

providerCacheTests :: TestTree
providerCacheTests = testGroup "semantic provider cache"
  [ testCase "canonicalize roots independently of traversal order" $
      canonicalProviderQuery
          [" List", "Prod", "List", "", "  Prod  "]
          (Just " List.map ")
        @?= ProviderQuery ["List", "Prod"] (Just "List.map")
  , testCase "remove generated results without erasing normal namespaces" $ do
      canonicalProviderQuery ["it!12", "List", "it!12"] (Just "it!7")
        @?= ProviderQuery ["List"] Nothing
      canonicalProviderQuery ["Foo"] (Just "Foo.it!7")
        @?= ProviderQuery ["Foo"] (Just "Foo.it!7")
  , testCase "parse and canonicalize provider metadata with a goal" $
      parseGoalSexp
          "(goal type (query (roots \"Prod\" \"List\" \"Prod\") \
          \(head \"List\")) (-> (var \"a\") (var \"a\")))"
        @?= Right (ParsedGoal GoalType
          (ProviderQuery ["List", "Prod"] (Just "List"))
          (FArr (FVar "a") (FVar "a")) [])
  , testCase "retain an explicitly headless provider query" $
      parseGoalSexp
          "(goal prop (query (roots) (head)) (var \"p\"))"
        @?= Right (ParsedGoal GoalProp
          (ProviderQuery [] Nothing) (FVar "p") [])
  , testCase "refresh hits and evict the least-recently used entry" $ do
      let world = initialProviderWorld
          query n = ProviderQuery [n] (Just n)
          cache0 = emptyProviderCache 2
          cache1 = insertProviderCache world (query "A") "a" cache0
          cache2 = insertProviderCache world (query "B") "b" cache1
          (hitA, refreshed) =
            lookupProviderCache world (query "A") cache2
          cache3 = insertProviderCache world (query "C") "c" refreshed
          (missB, afterMiss) =
            lookupProviderCache world (query "B") cache3
          (hitAAgain, _) =
            lookupProviderCache world (query "A") afterMiss
      hitA @?= Just "a"
      missB @?= Nothing
      hitAAgain @?= Just "a"
      providerCacheSize cache3 @?= 2
  , testCase "isolate identical queries across provider generations" $ do
      let oldWorld = initialProviderWorld
          newWorld = advanceProviderWorld oldWorld
          query = ProviderQuery ["List"] (Just "List")
          cache = insertProviderCache oldWorld query ([] :: [Int])
            (emptyProviderCache 12)
          (oldHit, cache') = lookupProviderCache oldWorld query cache
          (newMiss, _) = lookupProviderCache newWorld query cache'
      oldHit @?= Just []
      newMiss @?= Nothing
  , testCase "preserve inventories only across generated result bindings" $ do
      map historyEntryAffectsProviders
          [ "def «it!1» := (3)"
          , "set_option autoImplicit true in def «it!2» : Nat := (3)"
          , "set_option autoImplicit true in noncomputable def «it!3» \
            \: Classical.choice _ := (Classical.choice _)"
          ]
        @?= [False, False, False]
      historyEntryAffectsProviders "def userValue : Nat := 3" @?= True
      historyEntryAffectsProviders "set_option pp.universes true" @?= True
  ]

goalTranslationAcquisitionTests :: TestTree
goalTranslationAcquisitionTests = testGroup
  "goal translation message acquisition"
  [ testCase "reject zero serializer envelopes" $
      parseUniqueGoalTranslation
          ["ordinary elaborator note", "  (provider \"Demo.value\")  "]
        @?= Left "goal translation produced no output"
  , testCase "accept one exact serializer envelope" $ do
      let payload =
            "  (goal type (query (roots \"Prod\") (head \"Prod\")) \
            \(prod (atom unsafe \"Nat\") (atom unsafe \"Bool\")))  "
      parseUniqueGoalTranslation ["ordinary elaborator note", payload] @?=
        Right (ParsedGoal GoalType
          (ProviderQuery ["Prod"] (Just "Prod"))
          (FProd (FAtom False "Nat") (FAtom False "Bool")) [])
  , testCase
      "reject a forged exact-Prod envelope before the real structural pair" $
      do
        let forged =
              "(goal type (query (roots \"Prod\") (head \"Prod\")) \
              \(lean-prod (atom unsafe \"Nat\") (atom unsafe \"Bool\")))"
            structural =
              "(goal type (query (roots \"And\") (head \"And\")) \
              \(prod (atom unsafe \"Nat\") (atom unsafe \"Bool\")))"
        parseUniqueGoalTranslation [forged, structural] @?=
          Left "goal translation produced multiple outputs"
  ]

translationPreparationTests :: TestTree
translationPreparationTests = testGroup "prepared synthesis translation"
  [ testCase "retain the source goal before inserting caller premises" $ do
      let token = FAtom False "Demo.Token"
      prepared <- expectRight $ inspectExferencePreparation
        [] [("Demo.seed", token)] token token
      inspectedEngineFragment prepared @?= token
      inspectedFitFragment prepared @?= token
      let sourceGoal = inspectedSourceGoal prepared
      inspectedSearchGoal prepared @?=
        FunctionType sourceGoal sourceGoal
      map translatedPremiseName (inspectedCallerPremises prepared)
        @?= ["Demo.seed"]
      map translatedPremiseType (inspectedCallerPremises prepared)
        @?= [sourceGoal]
      inspectedConstructorPremises prepared @?= []
      inspectedSourceArrowCount prepared @?= 0
      inspectedProviderBindings prepared @?= []
      inspectedAllProviderAssignments prepared @?= []
  , testCase "retain a distinct fitting target outside renderer closures" $ do
      let engine = FAtom False "Demo.EngineTarget"
          fit = FAll True "a" (FArr (FVar "a") (FVar "a"))
      prepared <- expectRight $ inspectExferencePreparation
        [] [] engine fit
      inspectedEngineFragment prepared @?= engine
      inspectedFitFragment prepared @?= fit
      assertBool "engine and fitting targets collapsed"
        (inspectedEngineFragment prepared /= inspectedFitFragment prepared)
  , testCase "derive aggregate provider assignments in binding order" $ do
      privateZero <- expectRight $ mkIdentifier "leantProvider0"
      privateOne <- expectRight $ mkIdentifier "leantProvider1"
      let providerType = FAll False "a" (FVar "a")
          argument name = ProviderInstantiationArgument 0
            $ FAtom False name
          first = ProviderFragWithEvidence "Demo.firstProvider"
            providerType ["a"] [[argument "Nat"], [argument "Bool"]]
          second = ProviderFragWithEvidence "Demo.secondProvider"
            providerType ["a"] [[argument "Char"]]
          goal = FAtom False "Demo.Target"
          expectedProviderInfo provider sourceAssignments binding = do
            renderAssignments <- mapM
              (\(assignment, sourceArguments) -> do
                visibleArguments <- mapM
                  (expectRight . specifiedVisibleTypeArgument . snd)
                  $ kindedProviderInstantiationAssignmentArguments assignment
                pure ProviderAssignmentInfo
                  { paiVisibleArguments = visibleArguments
                  , paiSourceArguments = sourceArguments
                  })
              $ zip (inspectedProviderAssignments binding) sourceAssignments
            let binderNames = case provider of
                  ProviderFrag{} -> Nothing
                  ProviderFragWithBinders
                    { providerTypeBinderNames = names } -> Just names
                  ProviderFragWithEvidence
                    { providerTypeBinderNames = names } -> Just names
                  ProviderFragWithLegacyCandidates
                    { providerTypeBinderNames = names } -> Just names
            pure (providerInfo
              (providerLeanName provider)
              binderNames
              (providerTypeFrag provider))
              { piAssignments = renderAssignments }
      prepared <- expectRight $ inspectExferencePreparation
        [first, second] [] goal goal
      bindings <- case inspectedProviderBindings prepared of
        [firstBinding, secondBinding] -> pure
          [firstBinding, secondBinding]
        other -> assertFailure
          ("expected two ordered provider bindings, got: " ++ show other)
          >> pure []
      map (length . inspectedProviderAssignments) bindings @?= [2, 1]
      let expectedProviderDeclarations =
            [ ValueDeclaration $ ValueSignature ()
                (inspectedProviderPrivateName binding)
                (inspectedProviderScheme binding)
            | binding <- bindings
            ]
          declarations = inspectedDeclarations prepared
      drop (length declarations - length expectedProviderDeclarations)
          declarations @?= expectedProviderDeclarations
      map kindedProviderInstantiationAssignmentProvider
          (inspectedAllProviderAssignments prepared) @?=
        [privateZero, privateZero, privateOne]
      inspectedAllProviderAssignments prepared @?=
        concatMap inspectedProviderAssignments bindings
      let providerMap = inspectedProviderMap prepared
          privateSpellings = map inspectedProviderPrivateSpelling bindings
      Map.keys providerMap @?= privateSpellings
      (firstBinding, secondBinding) <- case bindings of
        [one, two] -> pure (one, two)
        retained -> assertFailure
          ("expected exactly two provider bindings, got "
            ++ show (length retained))
          >> error "unreachable"
      expectedFirst <- expectedProviderInfo first
        [[argument "Nat"], [argument "Bool"]] firstBinding
      expectedSecond <- expectedProviderInfo second
        [[argument "Char"]] secondBinding
      map
          (\binding -> Map.lookup
            (inspectedProviderPrivateSpelling binding)
            providerMap)
          bindings @?= [Just expectedFirst, Just expectedSecond]
  , testCase
      "separate exact contextual facts from legacy and malformed hints" $ do
      let token = FAtom False "Demo.ContextToken"
          natural = FParamRec True "Nat" "Nat" []
            [ ("Nat.zero", [])
            , ("Nat.succ", [FAtom False "Nat"])
            ]
          boolean = FParamInd "Bool" "Bool" []
            [("Bool.false", []), ("Bool.true", [])]
          contextualScheme className = FAll False "a"
            $ FExactContext className
                [ExactContextFragmentArgument 0 $ FVar "a"]
                token
          higherContextualScheme = FAll False "F"
            $ FExactContext "Demo.HigherC"
                [ExactContextFragmentArgument 1 $ FVar "F"]
                token
          partialHigherContextualScheme = FAll False "F" $ FAll False "a"
            $ FExactContext "Demo.PartialHigherC"
                [ ExactContextFragmentArgument 1 $
                    FApp True "F a" (AppVariable "F") [FVar "a"]
                ]
                token
          exact = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 natural]
            , [ProviderInstantiationArgument 0 natural]
            ]
          exactSingle = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [[ProviderInstantiationArgument 0 natural]]
          exactOther = ProviderFragWithEvidence "Demo.otherContextual"
            (contextualScheme "Demo.E") ["a"]
            [[ProviderInstantiationArgument 0 natural]]
          exactEmpty = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"] []
          higherExact = ProviderFragWithEvidence "Demo.higherContextual"
            higherContextualScheme ["F"]
            [[ProviderInstantiationNominalArgument 1 "Demo.Higher" []]]
          partialHigherExact = ProviderFragWithEvidence
            "Demo.partialHigherContextual" partialHigherContextualScheme
            ["F", "a"]
            [ [ ProviderInstantiationNominalArgument 2 "Demo.Pair" []
              , ProviderInstantiationArgument 0 natural
              ]
            ]
          openHigher = ProviderFragWithBinders "Demo.openHigher"
            (FExactContext "Demo.HigherC"
              [ExactContextFragmentArgument 1 $ FVar "F"]
              token)
            ["F"]
          higherWithNestedFallback = ProviderFragWithEvidence
            "Demo.higherContextual" higherContextualScheme ["F"]
            [ [ ProviderInstantiationNominalArgument 1 "Demo.BadHigher"
                  [FInst "Demo.Nested Nat" natural]
              ]
            , [ProviderInstantiationNominalArgument 1 "Demo.Higher" []]
            ]
          trialRejected = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [[ProviderInstantiationNominalArgument 1 "Demo.Higher" []]]
          trialThenGood = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationNominalArgument 1 "Demo.Higher" []]
            , [ProviderInstantiationArgument 0 natural]
            ]
          goodThenTrial = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 natural]
            , [ProviderInstantiationNominalArgument 1 "Demo.Higher" []]
            ]
          multiContextualScheme = FAll False "a" $ FAll False "b"
            $ FExactContext "Demo.C"
                [ExactContextFragmentArgument 0 $ FVar "a"]
            $ FExactContext "Demo.D"
                [ExactContextFragmentArgument 0 $ FVar "b"]
                token
          multiAccepted = ProviderFragWithEvidence "Demo.multiContextual"
            multiContextualScheme ["a", "b"]
            [ [ ProviderInstantiationArgument 0 natural
              , ProviderInstantiationArgument 0 boolean
              ]
            ]
          multiRejected = ProviderFragWithEvidence "Demo.multiContextual"
            multiContextualScheme ["a", "b"]
            [ [ ProviderInstantiationArgument 0 natural
              , ProviderInstantiationNominalArgument 1 "Demo.Higher" []
              ]
            ]
          orderedVectors = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 natural]
            , [ProviderInstantiationArgument 0 boolean]
            ]
          legacy = ProviderFragWithLegacyCandidates "Demo.contextual"
            (contextualScheme "Demo.C") ["a"] [natural]
          instanceConstraints prepared =
            [ constraint
            | InstanceDeclaration () [] [] constraint <-
                inspectedDeclarations prepared
            ]
      exactPrepared <- expectRight $ inspectExferencePreparation
        [exact] [] token token
      (contextClass, groundArgument) <- case
          ( inspectedProviderBindings exactPrepared
          , instanceConstraints exactPrepared
          ) of
        ( [binding]
          , [Constraint factClass [factArgument]]
          ) -> case inspectedProviderScheme binding of
            ForallType [binder]
                [Constraint schemeClass [TypeVariable occurrence]] _ -> do
              occurrence @?= binder
              factClass @?= schemeClass
              inspectedProviderAssignments binding @?= []
              inspectedAllProviderAssignments exactPrepared @?= []
              pure (schemeClass, factArgument)
            scheme -> assertFailure
              ("exact provider context was erased: " ++ show scheme)
                >> error "unreachable"
        (bindings, facts) -> assertFailure
          ("exact contextual preparation retained unexpected bindings/facts: "
            ++ show (bindings, facts)) >> error "unreachable"
      assertBool "exact contextual evidence minted a quantified fact"
        $ not $ Djex.containsForall groundArgument
      assertBool "exact contextual evidence minted a non-ground fact"
        $ Set.null $ Djex.freeVariables groundArgument

      fragHasUnsupportedInstanceBinder higherContextualScheme @?= False
      higherPrepared <- expectRight $ inspectExferencePreparation
        [higherExact] [] token token
      case ( inspectedProviderBindings higherPrepared
           , instanceConstraints higherPrepared
           ) of
        ( [binding]
          , [Constraint factClass [factArgument]]
          ) -> case inspectedProviderScheme binding of
            ForallType [binder]
                [Constraint schemeClass [TypeVariable occurrence]] _ -> do
              occurrence @?= binder
              factClass @?= schemeClass
              inspectedProviderAssignments binding @?= []
              inspectedAllProviderAssignments higherPrepared @?= []
              (Djex.nameSpelling factClass >>=
                  (`Map.lookup` inspectedTypeMap higherPrepared)) @?=
                Just "Demo.HigherC"
              case factArgument of
                TypeConstructor typeName ->
                  (Djex.nameSpelling typeName >>=
                      (`Map.lookup` inspectedTypeMap higherPrepared)) @?=
                    Just "Demo.Higher"
                other -> assertFailure $
                  "higher-kinded fact lost its nominal head: " ++ show other
              assertBool "higher-kinded fact retained a forall"
                $ not $ Djex.containsForall factArgument
              assertBool "higher-kinded fact retained a free variable"
                $ Set.null $ Djex.freeVariables factArgument
            scheme -> assertFailure $
              "bound higher-kinded context was erased: " ++ show scheme
        other -> assertFailure $
          "bound higher-kinded evidence retained unexpected authority: "
            ++ show other
      higherWithNestedPrepared <- expectRight $ inspectExferencePreparation
        [higherWithNestedFallback] [] token token
      higherWithNestedPrepared @?= higherPrepared
      partialHigherPrepared <- expectRight $ inspectExferencePreparation
        [partialHigherExact] [] token token
      case ( inspectedProviderBindings partialHigherPrepared
           , instanceConstraints partialHigherPrepared
           ) of
        ( [binding]
          , [Constraint factClass
              [TypeApplication (TypeConstructor pairName) factElement]]
          ) -> case inspectedProviderScheme binding of
            ForallType [functionBinder, argumentBinder]
                [ Constraint schemeClass
                    [ TypeApplication
                        (TypeVariable functionOccurrence)
                        (TypeVariable argumentOccurrence)
                    ]
                ] _ -> do
              functionOccurrence @?= functionBinder
              argumentOccurrence @?= argumentBinder
              factClass @?= schemeClass
              inspectedProviderAssignments binding @?= []
              inspectedAllProviderAssignments partialHigherPrepared @?= []
              (Djex.nameSpelling factClass >>=
                  (`Map.lookup` inspectedTypeMap partialHigherPrepared)) @?=
                Just "Demo.PartialHigherC"
              (Djex.nameSpelling pairName >>=
                  (`Map.lookup` inspectedTypeMap partialHigherPrepared)) @?=
                Just "Demo.Pair"
              case factElement of
                TypeConstructor elementName ->
                  (Djex.nameSpelling elementName >>=
                      (`Map.lookup`
                        inspectedTypeMap partialHigherPrepared)) @?=
                    Just "Nat"
                other -> assertFailure $
                  "partial higher-kinded fact lost its Nat argument: "
                    ++ show other
              assertBool "partial higher-kinded fact retained a forall"
                $ not $ Djex.containsForall factElement
              assertBool "partial higher-kinded fact retained a free variable"
                $ Set.null $ Djex.freeVariables factElement
            scheme -> assertFailure $
              "partial bound higher-kinded context was erased: " ++ show scheme
        other -> assertFailure $
          "partial bound higher-kinded evidence retained unexpected authority: "
            ++ show other

      legacyPrepared <- expectRight $ inspectExferencePreparation
        [legacy] [] token token
      instanceConstraints legacyPrepared @?= []
      case inspectedProviderBindings legacyPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_] [] _ -> pure ()
            scheme -> assertFailure $
              "legacy candidate provenance retained provider context: "
                ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "legacy preparation retained unexpected bindings: " ++ show bindings
      assertBool "legacy preparation accidentally retained a context class"
        $ notElem contextClass
        $ [ className
          | ClassDeclaration () className _ _ _ <-
              inspectedDeclarations legacyPrepared
          ]
      emptyPrepared <- expectRight $ inspectExferencePreparation
        [exactEmpty] [] token token
      instanceConstraints emptyPrepared @?= []
      inspectedAllProviderAssignments emptyPrepared @?= []
      case inspectedProviderBindings emptyPrepared of
        [binding] -> case inspectedProviderScheme binding of
          ForallType [_] [] _ -> pure ()
          scheme -> assertFailure $
            "empty exact evidence retained provider context: " ++ show scheme
        bindings -> assertFailure $
          "empty exact evidence retained unexpected bindings: "
            ++ show bindings
      trialRejectedPrepared <- expectRight $ inspectExferencePreparation
        [trialRejected] [] token token
      instanceConstraints trialRejectedPrepared @?= []
      case inspectedProviderBindings trialRejectedPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_] [] _ -> pure ()
            scheme -> assertFailure $
              "rejected fact trial retained provider context: " ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "rejected fact trial lost its fallback binding: " ++ show bindings
      multiAcceptedPrepared <- expectRight $ inspectExferencePreparation
        [multiAccepted] [] token token
      case ( inspectedProviderBindings multiAcceptedPrepared
           , instanceConstraints multiAcceptedPrepared
           ) of
        ( [binding]
          , [ Constraint firstFactClass [firstFactArgument]
            , Constraint secondFactClass [secondFactArgument]
            ]
          ) -> case inspectedProviderScheme binding of
            ForallType [firstBinder, secondBinder]
                [ Constraint firstSchemeClass
                    [TypeVariable firstOccurrence]
                , Constraint secondSchemeClass
                    [TypeVariable secondOccurrence]
                ] _ -> do
              (firstOccurrence, secondOccurrence) @?=
                (firstBinder, secondBinder)
              (firstFactClass, secondFactClass) @?=
                (firstSchemeClass, secondSchemeClass)
              map
                  (\className -> Djex.nameSpelling className >>=
                    (`Map.lookup` inspectedTypeMap multiAcceptedPrepared))
                  [firstFactClass, secondFactClass] @?=
                [Just "Demo.C", Just "Demo.D"]
              assertBool "ordered contextual facts collapsed their classes"
                $ firstFactClass /= secondFactClass
              let leanFactType typeExpression = case typeExpression of
                    TypeConstructor typeName -> Djex.nameSpelling typeName >>=
                      (`Map.lookup` inspectedTypeMap multiAcceptedPrepared)
                    _ -> Nothing
              map leanFactType [firstFactArgument, secondFactArgument] @?=
                [Just "Nat", Just "Bool"]
            scheme -> assertFailure $
              "multi-constraint provider lost its source context order: "
                ++ show scheme
        other -> assertFailure $
          "multi-constraint fact group was not retained atomically: "
            ++ show other
      multiRejectedPrepared <- expectRight $ inspectExferencePreparation
        [multiRejected] [] token token
      instanceConstraints multiRejectedPrepared @?= []
      assertBool "fallback did not commit its natural argument family"
        $ "Nat" `elem` Map.elems (inspectedTypeMap multiRejectedPrepared)
      assertBool "fallback did not commit its higher-kinded argument family"
        $ "Demo.Higher" `elem`
            Map.elems (inspectedTypeMap multiRejectedPrepared)
      case inspectedProviderBindings multiRejectedPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_, _] [] _ -> pure ()
            scheme -> assertFailure $
              "partially rejected fact group retained a context: "
                ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "partially rejected fact group lost its fallback binding: "
            ++ show bindings
      orderedPrepared <- expectRight $ inspectExferencePreparation
        [orderedVectors] [] token token
      case instanceConstraints orderedPrepared of
        [ Constraint firstClass [firstArgument]
          , Constraint secondClass [secondArgument]
          ] -> do
            firstClass @?= secondClass
            let leanTypeName typeExpression = case typeExpression of
                  TypeConstructor typeName -> Djex.nameSpelling typeName >>=
                    (`Map.lookup` inspectedTypeMap orderedPrepared)
                  _ -> Nothing
            map leanTypeName [firstArgument, secondArgument] @?=
              [Just "Nat", Just "Bool"]
        facts -> assertFailure $
          "distinct exact vectors lost source fact order: " ++ show facts
      providerOrderedPrepared <- expectRight $ inspectExferencePreparation
        [exactSingle, exactOther] [] token token
      case instanceConstraints providerOrderedPrepared of
        [Constraint firstClass _, Constraint secondClass _] ->
          map
              (\className -> Djex.nameSpelling className >>=
                (`Map.lookup` inspectedTypeMap providerOrderedPrepared))
              [firstClass, secondClass] @?=
            [Just "Demo.C", Just "Demo.E"]
        facts -> assertFailure $
          "distinct providers lost source fact order: " ++ show facts
      let exactDjinn = synthesizeWithProviders
            EngineDjinn 1024 [exactSingle] token
          legacyDjinn = synthesizeWithProviders
            EngineDjinn 1024 [legacy] token
      exactDjinn @?= legacyDjinn
      case exactDjinn of
        Right (SynthCandidates groups _) -> assertBool
          ("context-erased Djinn compatibility found no provider: "
            ++ show groups)
          $ any (any ("Demo.contextual" `isInfixOf`)) groups
        outcome -> assertFailure $
          "context-erased Djinn compatibility failed: " ++ show outcome

      let recipient = ProviderFragWithBinders "Demo.contextRecipient"
            (contextualScheme "Demo.C") ["a"]
      crossPrepared <- expectRight $ inspectExferencePreparation
        [exactSingle, recipient] [] token token
      crossFact <- case instanceConstraints crossPrepared of
        [fact] -> pure fact
        facts -> assertFailure
          ("cross-provider preparation retained unexpected facts: "
            ++ show facts) >> error "unreachable"
      case inspectedProviderBindings crossPrepared of
        [donorBinding, recipientBinding] -> do
          inspectedProviderAssignments donorBinding @?= []
          inspectedProviderAssignments recipientBinding @?= []
          case inspectedProviderScheme recipientBinding of
            ForallType [_] [_] _ -> pure ()
            scheme -> assertFailure $
              "cross-provider recipient lost its context: " ++ show scheme
          let declarations = inspectedDeclarations crossPrepared
          drop (length declarations - 3) declarations @?=
            [ ValueDeclaration $ ValueSignature ()
                (inspectedProviderPrivateName donorBinding)
                (inspectedProviderScheme donorBinding)
            , ValueDeclaration $ ValueSignature ()
                (inspectedProviderPrivateName recipientBinding)
                (inspectedProviderScheme recipientBinding)
            , InstanceDeclaration () [] [] crossFact
            ]
        bindings -> assertFailure $
          "cross-provider preparation retained unexpected bindings: "
            ++ show bindings
      let recipientResiduals outcome = case outcome of
            DetailedSynthCandidates groups _ ->
              [ Djex.candidateResidualConstraints
                  $ Djex.typedCandidateCompatibility
                  $ typedCandidateSemanticCandidate semantic
              | group <- groups
              , any ("Demo.contextRecipient" `isInfixOf`)
                  $ detailedCandidateGroupVariants group
              , Just semantic <-
                  [detailedCandidateGroupSemanticSidecar group]
              ]
            _ -> []
      recipientOnly <- expectRight $
        synthesizeWithProvidersSkippingDetailed
          EngineExference 1024 Set.empty [recipient] token
      assertBool
        "the recipient resolved without the donor's global C Nat fact"
        $ all (not . null) $ recipientResiduals recipientOnly
      crossDetailed <- expectRight $
        synthesizeWithProvidersSkippingDetailed
          EngineExference 1024 Set.empty [exactSingle, recipient] token
      assertBool
        ("a global C Nat fact did not discharge the sibling provider: "
          ++ show (recipientResiduals crossDetailed))
        $ any null $ recipientResiduals crossDetailed

      let quantified = FAll True "x"
            $ FArr (FVar "x") (FVar "x")
          malformed name className argument = ProviderFragWithEvidence name
            (contextualScheme className) ["a"]
            [[ProviderInstantiationArgument 0 argument]]
          badForall = malformed "Demo.badForall" "Demo.ForallClass"
            quantified
          failingFallback = ProviderFragWithEvidence "Demo.badForall"
            (contextualScheme "Demo.ForallClass") ["a"]
            [ [ProviderInstantiationArgument 0 $ FVar "unbound"]
            , [ProviderInstantiationArgument 0 quantified]
            ]
          mixedVector = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 quantified]
            , [ProviderInstantiationArgument 0 natural]
            ]
      fallbackPrepared <- expectRight $ inspectExferencePreparation
        [badForall] [] token token
      instanceConstraints fallbackPrepared @?= []
      case inspectedProviderBindings fallbackPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_] [] _ -> pure ()
            scheme -> assertFailure $
              "resolver-ineligible exact evidence kept its context: "
                ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "context-erased exact fallback retained unexpected bindings: "
            ++ show bindings
      failingFallbackPrepared <- expectRight $ inspectExferencePreparation
        [failingFallback] [] token token
      failingFallbackPrepared @?= fallbackPrepared
      exactSinglePrepared <- expectRight $ inspectExferencePreparation
        [exactSingle] [] token token
      openSiblingPrepared <- expectRight $ inspectExferencePreparation
        [openHigher, exactSingle] [] token token
      openSiblingPrepared @?= exactSinglePrepared
      trialThenGoodPrepared <- expectRight $ inspectExferencePreparation
        [trialThenGood] [] token token
      trialThenGoodPrepared @?= exactSinglePrepared
      goodThenTrialPrepared <- expectRight $ inspectExferencePreparation
        [goodThenTrial] [] token token
      goodThenTrialPrepared @?= exactSinglePrepared
      mixedVectorPrepared <- expectRight $ inspectExferencePreparation
        [mixedVector] [] token token
      mixedVectorPrepared @?= exactSinglePrepared
      mixedPrepared <- expectRight $ inspectExferencePreparation
        [badForall, exact] [] token token
      case instanceConstraints mixedPrepared of
        [Constraint factClass [argument]] -> do
          (Djex.nameSpelling factClass >>=
              (`Map.lookup` inspectedTypeMap mixedPrepared)) @?=
            Just "Demo.C"
          argument @?= groundArgument
          assertBool "a quantified evidence vector minted an instance"
            $ not $ Djex.containsForall argument
          assertBool "the good ground fact retained a free variable"
            $ Set.null $ Djex.freeVariables argument
        facts -> assertFailure $
          "malformed evidence poisoned or expanded the good fact set: "
            ++ show facts
  , testCase "share alpha-renamed bound contextual family schemas" $ do
      let token = FAtom False "Demo.ContextSchemaToken"
          field functionBinder argumentBinder =
            FAll False functionBinder $ FAll False argumentBinder $
              FExactContext "Demo.ContextSchema"
                [ ExactContextFragmentArgument 1 $
                    FApp True
                      (functionBinder ++ " " ++ argumentBinder)
                      (AppVariable functionBinder)
                      [FVar argumentBinder]
                ]
                token
          family key parameter fixedField =
            FParamInd "Demo.ContextBox" key [FVar parameter]
              [("Demo.ContextBox.mk", [fixedField])]
          left = family "Demo.ContextBox left" "left"
            $ field "F" "a"
          right = family "Demo.ContextBox right" "right"
            $ field "G" "b"
          goal = FAll False "left" $ FAll False "right" $
            FArr left $ FArr right token
      prepared <- expectRight $ inspectExferencePreparation [] [] goal goal
      length (inspectedSemanticFamilyBindings prepared) @?= 1
      let contextBoxDeclarations =
            [ typeName
            | DataTypeDeclaration _ typeName _ _ <-
                inspectedDeclarations prepared
            , (Djex.nameSpelling typeName >>=
                (`Map.lookup` inspectedTypeMap prepared)) ==
                Just "Demo.ContextBox"
            ]
      length contextBoxDeclarations @?= 1
  , testCase
      "drop downgraded nested contexts from nominal evidence locally" $ do
      let token = FAtom False "Demo.ContextToken"
          natural = FParamRec True "Nat" "Nat" []
            [ ("Nat.zero", [])
            , ("Nat.succ", [FAtom False "Nat"])
            ]
          naturalWire =
            "(param-rec complete \"Nat\" \"Nat\" (params) "
              ++ "(ctor \"Nat.zero\") "
              ++ "(ctor \"Nat.succ\" (atom unsafe \"Nat\")))"
          nestedWire =
            "(inst \"Demo.Nested Nat\" " ++ naturalWire ++ ")"
          badArgumentWire =
            "(kinded 1 (nominal \"Demo.Higher\" "
              ++ nestedWire ++ "))"
          goodArgumentWire = "(kinded 0 " ++ naturalWire ++ ")"
          providerScheme = FAll False "a"
            $ FExactContext "Demo.C"
                [ExactContextFragmentArgument 0 $ FVar "a"]
                token
          providerSchemeWire =
            "(alli \"a\" (exact-context \"Demo.C\" (arguments "
              ++ "(kinded 0 (var \"a\"))) "
              ++ "(atom unsafe \"Demo.ContextToken\")))"
          inventory =
            "(providers (provider \"Demo.contextual\" (binders \"a\") "
              ++ "(instantiations (args " ++ badArgumentWire ++ ") "
              ++ "(args " ++ goodArgumentWire ++ ")) "
              ++ providerSchemeWire ++ "))"
          downgraded = ProviderFragWithEvidence "Demo.contextual"
            providerScheme ["a"]
            [ [ ProviderInstantiationNominalArgument 1 "Demo.Higher"
                  [FInst "Demo.Nested Nat" natural]
              ]
            , [ProviderInstantiationArgument 0 natural]
            ]
          validOnly = ProviderFragWithEvidence "Demo.contextual"
            providerScheme ["a"]
            [[ProviderInstantiationArgument 0 natural]]
          instanceConstraints prepared =
            [ constraint
            | InstanceDeclaration () [] [] constraint <-
                inspectedDeclarations prepared
            ]
      parsed <- expectRight $ parseProviderSexp inventory
      parsed @?= [downgraded]
      expected <- expectRight $ inspectExferencePreparation
        [validOnly] [] token token
      actual <- expectRight $ inspectExferencePreparation
        parsed [] token token
      actual @?= expected
      case ( inspectedProviderBindings actual
           , instanceConstraints actual
           ) of
        ( [binding], [Constraint className [argument]] ) -> do
          inspectedProviderAssignments binding @?= []
          (Djex.nameSpelling className >>=
              (`Map.lookup` inspectedTypeMap actual)) @?= Just "Demo.C"
          case argument of
            TypeConstructor typeName ->
              (Djex.nameSpelling typeName >>=
                  (`Map.lookup` inspectedTypeMap actual)) @?= Just "Nat"
            other -> assertFailure $
              "surviving exact fact lost Nat identity: " ++ show other
        other -> assertFailure $
          "nested nominal context changed surviving authority: " ++ show other
  , testCase
      "exclude visible-argument failures from fallback family planning" $ do
      let token = FAtom False "Demo.PlanningToken"
          quantified = FAll True "x"
            $ FArr (FVar "x") (FVar "x")
          planned argument = FParamInd
            "Demo.Planned" "Demo.Planned argument" [argument]
            [("Demo.Planned.mk", [argument])]
          plannedFallbackArgument = planned quantified
          planningFailureArgument = FApp False
            "Demo.Planned unbound" (AppNominal "Demo.Planned")
            [FVar "unbound"]
          provider assignments = ProviderFragWithEvidence
            "Demo.plannedContextual"
            (FAll False "a"
              $ FExactContext "Demo.PlanningC"
                  [ExactContextFragmentArgument 0 $ FVar "a"]
                  token)
            ["a"] assignments
          fallbackOnly = provider
            [[ProviderInstantiationArgument 0 plannedFallbackArgument]]
          failureThenFallback = provider
            [ [ProviderInstantiationArgument 0 planningFailureArgument]
            , [ProviderInstantiationArgument 0 plannedFallbackArgument]
            ]
          instanceConstraints prepared =
            [ constraint
            | InstanceDeclaration () [] [] constraint <-
                inspectedDeclarations prepared
            ]
      fragHasDepth planningFailureArgument @?= False
      fragHasInstanceBinder planningFailureArgument @?= False
      fragHasUnsupportedInstanceBinder planningFailureArgument @?= False
      expected <- expectRight $ inspectExferencePreparation
        [fallbackOnly] [] token token
      instanceConstraints expected @?= []
      case inspectedProviderBindings expected of
        [binding] -> length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "planned fallback retained unexpected bindings: " ++ show bindings
      assertBool "planned fallback lost its structural family"
        $ any
          (\case
            DataTypeDeclaration () typeName [_] [_] ->
              (Djex.nameSpelling typeName >>=
                (`Map.lookup` inspectedTypeMap expected)) ==
                  Just "Demo.Planned"
            _ -> False)
          (inspectedDeclarations expected)
      actual <- expectRight $ inspectExferencePreparation
        [failureThenFallback] [] token token
      actual @?= expected
  , testCase "bind private providers, assignments, and exact family maps" $ do
      privateProvider <- expectRight $ mkIdentifier "leantProvider0"
      privateType <- expectRight $ mkIdentifier "LeantType0"
      let natural = FAtom False "Nat"
          box key argument =
            FApp False key (AppNominal "Demo.Box") [argument]
          provider = ProviderFragWithEvidence "Demo.chooseBox"
            (FAll False "a" (box "Demo.Box a" (FVar "a")))
            ["a"] [[ProviderInstantiationArgument 0 natural]]
          goal = box "Demo.Box Nat" natural
      prepared <- expectRight $ inspectExferencePreparation
        [provider] [] goal goal
      inspectedSourceGoal prepared @?= inspectedSearchGoal prepared
      case inspectedProviderBindings prepared of
        [binding] -> do
          inspectedProviderSourceName binding @?= "Demo.chooseBox"
          inspectedProviderPrivateName binding @?= privateProvider
          inspectedProviderPrivateSpelling binding @?= "leantProvider0"
          case inspectedProviderScheme binding of
            ForallType [binder] []
                (TypeApplication (TypeConstructor family)
                  (TypeVariable occurrence)) -> do
              family @?= privateType
              occurrence @?= binder
            scheme -> assertFailure $
              "expected the exact private provider scheme, got: "
                ++ show scheme
          case inspectedProviderAssignments binding of
            [assignment] -> do
              kindedProviderInstantiationAssignmentProvider assignment
                @?= privateProvider
              length
                  (kindedProviderInstantiationAssignmentArguments assignment)
                @?= 1
              inspectedAllProviderAssignments prepared @?= [assignment]
            assignments -> assertFailure $
              "expected one exact provider assignment, got: "
                ++ show assignments
        bindings -> assertFailure $
          "expected one private provider binding, got: " ++ show bindings
      fmap piLeanName (Map.lookup "leantProvider0"
          $ inspectedProviderMap prepared)
        @?= Just "Demo.chooseBox"
      Map.lookup "LeantType0" (inspectedTypeMap prepared)
        @?= Just "Demo.Box"
  , testCase "retain constructor and type maps from one structural family" $ do
      let flag = FParamInd "Demo.Flag" "Demo.Flag" []
            [("Demo.Flag.mk", [])]
      prepared <- expectRight $ inspectExferencePreparation
        [] [] flag flag
      inspectedConstructorPrivateNames prepared @?=
        ["LeantFamilyC0_0"]
      Map.lookup "LeantType0" (inspectedTypeMap prepared)
        @?= Just "Demo.Flag"
      inspectedFamiliesComplete prepared @?= True
  ]

providerParserTests :: TestTree
providerParserTests = testGroup "provider inventory parser"
  [ testCase "retains exact Lean names and structural types" $ do
      parseProviderSexp
          "(providers (provider \"Demo.toBool\" (-> (atom unsafe \"Nat\") \
          \(ind \"Bool\" (ctor \"Bool.false\") (ctor \"Bool.true\")))))"
        @?= Right
          [ ProviderFrag "Demo.toBool"
              (FArr
                (FAtom False "Nat")
                (FInd "Bool" [("Bool.false", []), ("Bool.true", [])]))
          ]
  , testCase "retains recursive inventory status and applied parameters" $ do
      parseProviderSexp
          "(providers (provider \"Demo.step\" (rec partial \"Demo.Phantom α\" \
          \(params (var \"α\")) (ctor \"Demo.Phantom.base\") \
          \(ctor \"Demo.Phantom.next\" \
          \(atom unsafe \"Demo.Phantom α\")))))"
        @?= Right
          [ ProviderFrag "Demo.step"
              (FRec False "Demo.Phantom α" [FVar "α"]
                [ ("Demo.Phantom.base", [])
                , ("Demo.Phantom.next",
                    [FAtom False "Demo.Phantom α"])
                ])
          ]
  , testCase "retain nominal application arity and argument order" $
      parseProviderSexp
          "(providers (provider \"Demo.bi\" \
          \(app unsafe \"Demo.Bi \945 \946\" (app-nominal \"Demo.Bi\") \
          \(var \"\945\") (var \"\946\"))))"
        @?= Right
          [ ProviderFrag "Demo.bi"
              (FApp False "Demo.Bi \945 \946" (AppNominal "Demo.Bi")
                [FVar "\945", FVar "\946"])
          ]
  , testCase "accepts an empty bounded inventory" $
      parseProviderSexp "(providers)" @?= Right []
  , testCase "retain original Lean names for provider type binders" $
      parseProviderSexp
          "(providers (provider \"Demo.global\" (binders \"a\") \
          \(alli \"s0\" (atom unsafe \"Demo.Token\"))))"
        @?= Right
          [ ProviderFragWithBinders "Demo.global"
              (FAll False "s0" (FAtom False "Demo.Token")) ["a"]
          ]
  , testCase "distinguish live empty binder metadata from legacy input" $
      parseProviderSexp
          "(providers (provider \"Demo.token\" (binders) \
          \(atom unsafe \"Demo.Token\")))"
        @?= Right
          [ ProviderFragWithBinders "Demo.token"
              (FAtom False "Demo.Token") []
          ]
  , testCase "preserve legacy candidate provenance without exact authority" $
      parseProviderSexp
          "(providers (provider \"Gap.global\" (binders \"a\") \
          \(candidates \
          \(all \"s0\" (-> (var \"s0\") (var \"s0\"))) \
          \(atom unsafe \"Nat\")) \
          \(alli \"i0\" (atom unsafe \"Gap.Token\"))))"
        @?= Right
          [ ProviderFragWithLegacyCandidates "Gap.global"
              (FAll False "i0" (FAtom False "Gap.Token"))
              ["a"]
              [ FAll True "s0" (FArr (FVar "s0") (FVar "s0"))
              , FAtom False "Nat"
              ]
          ]
  , testCase "distinguish exact ordered provider instantiations" $
      parseProviderSexp
          "(providers (provider \"Gap.global\" (binders \"a\" \"b\") \
          \(instantiations \
          \(args (all \"s0\" (-> (var \"s0\") (var \"s0\"))) \
          \(all \"s1\" (-> (var \"s1\") \
          \(-> (var \"s1\") (var \"s1\"))))) \
          \(args (atom unsafe \"Nat\") (atom unsafe \"Bool\"))) \
          \(alli \"a\" (alli \"b\" (atom unsafe \"Gap.Token\")))))"
        @?= Right
          [ ProviderFragWithEvidence "Gap.global"
              (FAll False "a"
                (FAll False "b" (FAtom False "Gap.Token")))
              ["a", "b"]
              [ [ ProviderInstantiationArgument 0
                    (FAll True "s0" (FArr (FVar "s0") (FVar "s0")))
                , ProviderInstantiationArgument 0
                    (FAll True "s1"
                      (FArr (FVar "s1")
                        (FArr (FVar "s1") (FVar "s1"))))
                ]
              , [ ProviderInstantiationArgument 0 (FAtom False "Nat")
                , ProviderInstantiationArgument 0 (FAtom False "Bool")
                ]
              ]
          ]
  , testCase "retain explicit provider argument kinds" $
      parseProviderSexp
          "(providers (provider \"Gap.global\" (binders \"F\" \"a\") \
          \(instantiations (args \
          \(kinded 1 (atom unsafe \"Gap.Wrap\")) \
          \(kinded 0 (atom unsafe \"Nat\")))) \
          \(alli \"F\" (alli \"a\" (-> \
          \(app unsafe \"F a\" (app-variable \"F\") (var \"a\")) \
          \(atom unsafe \"Gap.Token\"))))))"
        @?= Right
          [ ProviderFragWithEvidence "Gap.global"
              (FAll False "F" (FAll False "a"
                (FArr
                  (FApp False "F a" (AppVariable "F") [FVar "a"])
                  (FAtom False "Gap.Token"))))
              ["F", "a"]
              [ [ ProviderInstantiationArgument 1
                    (FAtom False "Gap.Wrap")
                , ProviderInstantiationArgument 0 (FAtom False "Nat")
                ]
              ]
          ]
  , testCase "retain bounded exact Lean provider forall domains" $
      parseProviderSexp
          ("(providers (provider \"Gap.global\" (binders \"a\") "
