assertLengthSpinePairRankingPolicyBranches :: IO ()
assertLengthSpinePairRankingPolicyBranches = do
  (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
  withFakeLengthSolver "healthy" $ \executable -> do
    let source = explicitLengthRankingExecutionSource executable Nothing
          Djex.LengthSMTLibInputValuesAfterSatisfiable
    base <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits source
          Djex.defaultLengthEvaluationLimitSource
    ranking <- expectRight =<<
      rankVerifiedLengthSpinePairCandidatesWithPolicy
        (enableLengthRankingOriginProbe base)
        lengthSpinePairSecondOneContract [inputAndZero]
    receipt <- expectOnlyLengthSpinePairCounterexample ranking
    Djex.validatedLengthSpinePairCounterexampleInputs receipt @?= [0]
    Djex.validatedLengthSpinePairCounterexampleResult receipt @?=
      Djex.LengthSpinePair 0 0
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

  limits <- explicitLengthInputBoxLimits 1 2
  withFakeLengthSolver "query-unsat" $ \executable -> do
    let source = explicitLengthRankingExecutionSource executable Nothing
          Djex.LengthSMTLibStatusOnly
    base <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits source
          Djex.defaultLengthEvaluationLimitSource
    let combined = enableLengthRankingOriginProbe
          $ enableLengthRankingInputBoxValidation limits [1] base
    ranking <- expectRight =<<
      rankVerifiedLengthSpinePairCandidatesWithPolicy combined
        lengthSpinePairRankingContract [inputAndZero]
    case map rankedLengthSpinePairCandidateAssessment
        $ lengthSpinePairRankingCandidates ranking of
      [LengthSpinePairBoundedPositive positive] -> do
        Djex.validatedLengthSpinePairInputBoxInclusiveMaximums positive @?=
          [1]
        Djex.validatedLengthSpinePairInputBoxAssignmentCount positive @?= 2
      assessments -> assertFailure
        $ "combined product policy changed branch: " ++ show assessments
    assertFakeLengthQueryEvents [0] [] =<<
      BS.readFile (executable ++ ".events")

  refused <- syntheticLengthRankingCandidate "pair-origin-failure-refusal"
  let lowEvaluation = Djex.defaultLengthEvaluationLimitSource
        { Djex.lengthEvaluationLimitSourceIntermediateValueBits = 1 }
      original = [duplicatedInput, refused]
  withFakeLengthSolver "healthy" $ \executable -> do
    let source = explicitLengthRankingExecutionSource executable Nothing
          Djex.LengthSMTLibStatusOnly
    base <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits source lowEvaluation
    ranking <- expectRight =<<
      rankVerifiedLengthSpinePairCandidatesWithPolicy
        (enableLengthRankingOriginProbe base)
        lengthSpinePairSecondTwoContract original
    assertLengthSpinePairAtomicReset original ranking
      [Nothing, Just LengthPreparationTypedAuthorityUnavailable]
    failure <- expectLengthSpinePairRankingFailure ranking
    lengthSpinePairRankingFailureClass failure @?=
      LengthSpinePairRankingOriginProbeEvaluationFailed
        (Djex.LengthSpinePairEvaluationValueBitLimitExceeded
          Djex.LengthSpinePairIntermediateValue 1 2)
    lengthSpinePairRankingFailureOriginalIndex failure @?= Just 0
    lengthSpinePairRankingFailureCleanupIncomplete failure @?= False
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

assertLengthSpinePairRankingInputBox :: IO ()
assertLengthSpinePairRankingInputBox = do
  (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
  limits <- explicitLengthInputBoxLimits 1 2
  let assertNoBox mode expected = do
        (ranking, events) <-
          runLengthSpinePairRankingWithFakeTraceWithInputBox
            mode Djex.LengthSMTLibStatusOnly defaultLengthEvaluationLimits
            limits [] lengthSpinePairRankingContract [inputAndZero]
        lengthSpinePairRankingFailure ranking @?= Nothing
        map rankedLengthSpinePairCandidateAssessment
            (lengthSpinePairRankingCandidates ranking) @?=
          [LengthSpinePairHeuristic expected]
        assertFakeLengthQueryEvents [0] [] events
  -- The deliberately wrong bounds are never inspected for sat or unknown.
  assertNoBox "healthy" Djex.SolverSatisfiable
  assertNoBox "query-unknown" Djex.SolverUnknown

  (ranking, events) <- runLengthSpinePairRankingWithFakeTraceWithInputBox
    "query-unsat" Djex.LengthSMTLibStatusOnly
    defaultLengthEvaluationLimits limits [1]
    lengthSpinePairRankingContract
    [inputAndZero, duplicatedInput, duplicatedInput]
  lengthSpinePairRankingFailure ranking @?= Nothing
  map rankedLengthSpinePairCandidateOriginalIndex
      (lengthSpinePairRankingCandidates ranking) @?= [0, 1, 2]
  case map rankedLengthSpinePairCandidateAssessment
      $ lengthSpinePairRankingCandidates ranking of
    [ LengthSpinePairBoundedPositive positive
      , LengthSpinePairCounterexample first
      , LengthSpinePairCounterexample second
      ] -> do
        Djex.validatedLengthSpinePairInputBoxInclusiveMaximums positive @?=
          [1]
        Djex.validatedLengthSpinePairInputBoxAssignmentCount positive @?= 2
        Djex.validatedLengthSpinePairInputBoxApplicableAssignmentCount
          positive @?= 2
        Djex.validatedLengthSpinePairInputBoxBasis positive @?=
          Djex.FiniteSpineModelUnderAssumedProviderLaws
            (pairRankingUsedProviders inputAndZero
              lengthSpinePairRankingContract)
        map Djex.validatedLengthSpinePairCounterexampleInputs
            [first, second] @?= replicate 2 [1]
        map Djex.validatedLengthSpinePairCounterexampleResult
            [first, second] @?=
          replicate 2 (Djex.LengthSpinePair 1 1)
    assessments -> assertFailure
      ("unexpected product input-box assessments: " ++ show assessments)
  -- The positive does not seed.  The box counterexample does, so the third
  -- occurrence avoids a third solver transaction.
  assertFakeLengthQueryEvents [0, 1] [] events

assertLengthSpinePairApplicableDomain :: IO ()
assertLengthSpinePairApplicableDomain = do
  (counterexampleCandidate, positiveCandidate) <-
    buildLengthSpinePairRankingFixture
  retained <- syntheticLengthRankingCandidate
    "pair-applicable-domain-retained"
  limits <- explicitLengthInputBoxLimits 1 2
  let input = Djex.LengthVariable $ Djex.LengthSpinePairInput 0
      boundedContract = lengthSpinePairRankingContract
        { leanLengthSpinePairContractSource =
            (leanLengthSpinePairContractSource
              lengthSpinePairRankingContract)
              { Djex.lengthSpinePairContractPrecondition =
                  Djex.LengthAtMost input $ Djex.LengthLiteral 1
              }
        }
      original =
        [retained, positiveCandidate, counterexampleCandidate,
          counterexampleCandidate]
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let domainThenPreference =
          enableLengthRankingNonVacuousApplicableDomainPreference
          $ enableLengthRankingOriginProbe
          $ enableLengthRankingApplicableDomainValidation limits
              Djex.defaultLengthBooleanFiniteUnionLimits base
        preferenceThenDomain =
          enableLengthRankingApplicableDomainValidation limits
            Djex.defaultLengthBooleanFiniteUnionLimits
          $ enableLengthRankingOriginProbe
          $ enableLengthRankingNonVacuousApplicableDomainPreference base
        run policy = expectRight =<<
          rankVerifiedLengthSpinePairCandidatesWithPolicy
            policy boundedContract original

    first <- run domainThenPreference
    second <- run preferenceThenDomain
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates first) @?= [1, 0, 2, 3]
    lengthSpinePairRankingSnapshotByOriginalIndex first @?=
      lengthSpinePairRankingSnapshotByOriginalIndex second
    case map rankedLengthSpinePairCandidateAssessment
        $ lengthSpinePairRankingCandidates first of
      [ LengthSpinePairApplicableDomainEstablished positive
        , LengthSpinePairUnassessed
        , LengthSpinePairCounterexample firstCounterexample
        , LengthSpinePairCounterexample secondCounterexample
        ] -> do
          Djex.validatedLengthSpinePairApplicableDomainInclusiveMaximumBoxes
            positive @?= [[1]]
          Djex.validatedLengthSpinePairApplicableDomainAssignmentCount
            positive @?= 2
          Djex.validatedLengthSpinePairApplicableDomainApplicableAssignmentCount
            positive @?= 2
          Djex.validatedLengthSpinePairApplicableDomainBasis positive @?=
            Djex.FiniteSpineModelUnderAssumedProviderLaws
              (pairRankingUsedProviders positiveCandidate boundedContract)
          map Djex.validatedLengthSpinePairCounterexampleInputs
              [firstCounterexample, secondCounterexample] @?=
            replicate 2 [1]
          map Djex.validatedLengthSpinePairCounterexampleResult
              [firstCounterexample, secondCounterexample] @?=
            replicate 2 (Djex.LengthSpinePair 1 1)
      assessments -> assertFailure
        $ "unexpected pair applicable-domain assessments: "
            ++ show assessments
    -- The positive receipt contributes no MRU vector.  The following first
    -- source-ordered violation does, so its duplicate is replayed without a
    -- solver transaction.  The lexical worker may still have been opened.
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

    verification <- verificationBatchFromReceipts original
    associated <- expectLengthSpinePairPostVerificationWithin
      $ assessVerifiedLengthSpinePairCandidatesWithPolicy
          domainThenPreference boundedContract verification
    sealed <- case lengthSpinePairPostVerificationSealedBatch associated of
      Nothing -> assertFailure
        "pair applicable-domain output bypassed its occurrence seal"
          >> error "unreachable"
      Just batch -> pure batch
    lengthSpinePairPostVerificationCandidates associated @?=
      postVerificationBatchCandidates sealed
    associatedRanking <-
      expectLengthSpinePairPostVerificationRanking associated
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates associatedRanking) @?=
      [1, 0, 2, 3]
    positive <- case map rankedLengthSpinePairCandidateAssessment
        $ lengthSpinePairRankingCandidates associatedRanking of
      LengthSpinePairApplicableDomainEstablished receipt : _ -> pure receipt
      assessments -> assertFailure
        ("associated pair domain lost its positive receipt: "
          ++ show assessments) >> error "unreachable"
    let positiveNote =
          renderLengthSpinePairApplicableDomainValidationNote positive
        presentations = presentLengthSpinePairPostVerificationResult associated
    map lengthCandidatePresentationText presentations @?=
      map (detailedVerificationVariantText . verifiedCandidate)
        (lengthSpinePairPostVerificationCandidates associated)
    case map lengthCandidatePresentationNote presentations of
      [Just directNote, Nothing, Just firstNote, Just secondNote] -> do
        directNote @?= positiveNote
        mapM_ (assertBool "pair domain note lost its occurrence" .
            isInfixOf "second result spine length = 1")
          [firstNote, secondNote]
      notes -> assertFailure
        $ "pair domain presentation reassociated notes: " ++ show notes
    mapM_ (\fragment -> assertBool
        ("pair applicable-domain note omitted " ++ show fragment)
        $ fragment `isInfixOf` positiveNote)
      [ "complete binary-product finite-spine Length Boolean finite-union"
      , "conditional on 1 assumed provider law"
      , "boxes = 1"
      , "visits = 2"
      , "unique = 2"
      ]

    let vacuousContract = boundedContract
          { leanLengthSpinePairContractSource =
              (leanLengthSpinePairContractSource boundedContract)
                { Djex.lengthSpinePairContractPrecondition = Djex.LengthAll
                    [ Djex.LengthAtMost input $ Djex.LengthLiteral 1
                    , Djex.LengthAtMost (Djex.LengthLiteral 2) input
                    ]
                , Djex.lengthSpinePairContractPostcondition =
                    Djex.LengthTruth True
                }
          }
        vacuousOriginal =
          [counterexampleCandidate, retained, positiveCandidate]
    vacuous <- expectRight =<<
      rankVerifiedLengthSpinePairCandidatesWithPolicy
        domainThenPreference vacuousContract vacuousOriginal
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates vacuous) @?= [0, 1, 2]
    case map rankedLengthSpinePairCandidateAssessment
        $ lengthSpinePairRankingCandidates vacuous of
      [ LengthSpinePairApplicableDomainEstablished firstVacuous
        , LengthSpinePairUnassessed
        , LengthSpinePairApplicableDomainEstablished secondVacuous
        ] -> map
          Djex.validatedLengthSpinePairApplicableDomainApplicableAssignmentCount
          [firstVacuous, secondVacuous] @?= [0, 0]
      assessments -> assertFailure
        $ "vacuous pair domains left the neutral partition: "
            ++ show assessments
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

assertLengthSpinePairNonVacuousPositivePreference :: IO ()
assertLengthSpinePairNonVacuousPositivePreference = do
  (counterexampleCandidate, positiveCandidate) <-
    buildLengthSpinePairRankingFixture
  retainedFirst <- syntheticLengthRankingCandidate
    "pair-positive-preference-retained-first"
  retainedSecond <- syntheticLengthRankingCandidate
    "pair-positive-preference-retained-second"
  limits <- explicitLengthInputBoxLimits 1 2
  let original =
        [ retainedFirst, counterexampleCandidate, positiveCandidate
        , retainedSecond, positiveCandidate, counterexampleCandidate
        ]
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let bounded = enableLengthRankingInputBoxValidation limits [1] base
        preferred = enableLengthRankingNonVacuousInputBoxPreference bounded
        run label policy = do
          ranking <- expectRight =<< timeoutResult label
            (rankVerifiedLengthSpinePairCandidatesWithPolicy policy
              lengthSpinePairRankingContract original)
          events <- BS.readFile $ executable ++ ".events"
          pure (ranking, events)
    (legacy, legacyEvents) <- run "legacy pair positive ordering" bounded
    (ranked, rankedEvents) <- run
      "preferred pair positive ordering" preferred
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates legacy) @?= [0, 2, 3, 4, 1, 5]
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates ranked) @?= [2, 4, 0, 3, 1, 5]
    case map rankedLengthSpinePairCandidateAssessment
        $ lengthSpinePairRankingCandidates ranked of
      [ LengthSpinePairBoundedPositive first
        , LengthSpinePairBoundedPositive second
        , LengthSpinePairUnassessed, LengthSpinePairUnassessed
        , LengthSpinePairCounterexample firstCounterexample
        , LengthSpinePairCounterexample secondCounterexample
        ] -> do
          map Djex.validatedLengthSpinePairInputBoxApplicableAssignmentCount
            [first, second] @?= [2, 2]
          map Djex.validatedLengthSpinePairCounterexampleInputs
            [firstCounterexample, secondCounterexample] @?= [[1], [1]]
      assessments -> assertFailure
        $ "unexpected pair positive/neutral/counterexample partition: "
            ++ show assessments
    lengthSpinePairRankingSnapshotByOriginalIndex ranked @?=
      lengthSpinePairRankingSnapshotByOriginalIndex legacy
    assertFakeLengthQueryEvents [0, 1, 2] [] legacyEvents
    assertFakeLengthQueryEvents [0, 1, 2] [] rankedEvents
 where
  timeoutResult label action = do
    bounded <- timeout 8000000 action
    case bounded of
      Nothing -> assertFailure (label ++ " exceeded its outer bound")
        >> error "unreachable"
      Just result -> pure result

assertLengthSpinePairPositivePreferenceSafety :: IO ()
assertLengthSpinePairPositivePreferenceSafety = do
  (counterexampleCandidate, positiveCandidate) <-
    buildLengthSpinePairRankingFixture
  retained <- syntheticLengthRankingCandidate
    "pair-vacuous-positive-preference-retained"
  limits <- explicitLengthInputBoxLimits 1 2
  let vacuousContract = lengthSpinePairRankingContract
        { leanLengthSpinePairContractSource =
            Djex.LengthSpinePairContractSource
              { Djex.lengthSpinePairContractPrecondition =
                  Djex.LengthTruth False
              , Djex.lengthSpinePairContractPostcondition =
                  Djex.LengthTruth True
              }
        }
      vacuousInput =
        [positiveCandidate, retained, counterexampleCandidate,
          positiveCandidate]
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let preferred = enableLengthRankingNonVacuousInputBoxPreference
          $ enableLengthRankingInputBoxValidation limits [1] base
    vacuous <- expectRight =<<
      rankVerifiedLengthSpinePairCandidatesWithPolicy
        preferred vacuousContract vacuousInput
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates vacuous) @?= [0, 1, 2, 3]
    case map rankedLengthSpinePairCandidateAssessment
        $ lengthSpinePairRankingCandidates vacuous of
      [ LengthSpinePairBoundedPositive first
        , LengthSpinePairUnassessed
        , LengthSpinePairBoundedPositive second
        , LengthSpinePairBoundedPositive third
        ] -> map
          Djex.validatedLengthSpinePairInputBoxApplicableAssignmentCount
          [first, second, third] @?= [0, 0, 0]
      assessments -> assertFailure
        $ "vacuous pair positives left the neutral partition: "
            ++ show assessments

    verification <- verificationBatchFromReceipts
      [retained, counterexampleCandidate, positiveCandidate,
        positiveCandidate, counterexampleCandidate]
    associated <- expectLengthSpinePairPostVerificationWithin
      $ assessVerifiedLengthSpinePairCandidatesWithPolicy preferred
          lengthSpinePairRankingContract verification
    sealed <- case lengthSpinePairPostVerificationSealedBatch associated of
      Nothing -> assertFailure "preferred pair output bypassed its seal"
        >> error "unreachable"
      Just batch -> pure batch
    lengthSpinePairPostVerificationCandidates associated @?=
      postVerificationBatchCandidates sealed
    associatedRanking <- expectLengthSpinePairPostVerificationRanking associated
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates associatedRanking) @?=
      [2, 3, 0, 1, 4]
    case map lengthCandidatePresentationNote
        $ presentLengthSpinePairPostVerificationResult associated of
      [Just firstPositive, Just secondPositive, Nothing,
          Just firstCounterexample, Just secondCounterexample] -> do
        mapM_ (assertBool "pair positive note followed the wrong occurrence" .
            isInfixOf "applicable assignments = 2")
          [firstPositive, secondPositive]
        mapM_ (assertBool
            "pair counterexample note followed the wrong occurrence" .
            isInfixOf "second result spine length = 1")
          [firstCounterexample, secondCounterexample]
      notes -> assertFailure
        $ "pair positive preference reassociated notes: " ++ show notes

  -- Reuse the fixture's stably selected unary product.  Deliberately empty
  -- bounds make the completed ranking fail before the preference is allowed
  -- to permute it, so the failed value must retain every original occurrence.
  trailing <- syntheticLengthRankingCandidate
    "pair-positive-preference-fallback-trailing"
  let alwaysContract = lengthSpinePairRankingContract
        { leanLengthSpinePairContractSource =
            Djex.LengthSpinePairContractSource
              { Djex.lengthSpinePairContractPrecondition =
                  Djex.LengthTruth True
              , Djex.lengthSpinePairContractPostcondition =
                  Djex.LengthTruth True
              }
        }
      original = [positiveCandidate, counterexampleCandidate, trailing]
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let preferred = enableLengthRankingNonVacuousInputBoxPreference
          $ enableLengthRankingInputBoxValidation limits [] base
    fallback <- expectRight =<<
      rankVerifiedLengthSpinePairCandidatesWithPolicy
        preferred alwaysContract original
    assertLengthSpinePairAtomicReset original fallback
      [Nothing, Nothing, Just LengthPreparationTypedAuthorityUnavailable]
    failure <- expectLengthSpinePairRankingFailure fallback
    lengthSpinePairRankingFailureClass failure @?=
      LengthSpinePairRankingInputBoxValidationFailed
        (Djex.LengthSpinePairInputBoxBoundsArityMismatch 1 0)
    lengthSpinePairRankingFailureOriginalIndex failure @?= Just 0
    assertFakeLengthQueryEvents [0] [] =<<
      BS.readFile (executable ++ ".events")

lengthSpinePairRankingSnapshotByOriginalIndex
  :: LengthSpinePairRanking
  -> [ ( Natural
       , LengthSpinePairRankingAssessment
       , Maybe LengthPreparationRefusalClass
       )
     ]
lengthSpinePairRankingSnapshotByOriginalIndex =
  sortOn (\(index, _, _) -> index)
  . map snapshot
  . lengthSpinePairRankingCandidates
 where
  snapshot ranked =
    ( rankedLengthSpinePairCandidateOriginalIndex ranked
    , rankedLengthSpinePairCandidateAssessment ranked
    , rankedLengthSpinePairCandidatePreparationRefusal ranked
    )

assertLengthSpinePairPostVerificationPresentation :: IO ()
assertLengthSpinePairPostVerificationPresentation = do
  (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
  refused <- syntheticLengthRankingCandidate "pair-presentation-retained"
  let raw = [duplicatedInput, duplicatedInput, refused]
      expected = [refused, duplicatedInput, duplicatedInput]
  verification <- verificationBatchFromReceipts raw
  withFakeLengthSolver "healthy" $ \executable -> do
    let source = explicitLengthRankingExecutionSource executable Nothing
          Djex.LengthSMTLibInputValuesAfterSatisfiable
    policy <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits source
          Djex.defaultLengthEvaluationLimitSource
    result <- expectLengthSpinePairPostVerificationWithin
      $ assessVerifiedLengthSpinePairCandidatesWithPolicy policy
          lengthSpinePairRankingContract verification
    lengthSpinePairPostVerificationAdapterFailure result @?= Nothing
    lengthSpinePairPostVerificationRankingFailure result @?= Nothing
    lengthSpinePairPostVerificationCandidates result @?= expected
    sealed <- case lengthSpinePairPostVerificationSealedBatch result of
      Nothing -> assertFailure
        "product post-verification bypassed its occurrence seal"
          >> error "unreachable"
      Just retained -> pure retained
    postVerificationBatchCandidates sealed @?= expected
    ranking <- expectLengthSpinePairPostVerificationRanking result
    map rankedLengthSpinePairCandidateOriginalIndex
        (lengthSpinePairRankingCandidates ranking) @?= [2, 0, 1]
    let presentations = presentLengthSpinePairPostVerificationResult result
    map lengthCandidatePresentationText presentations @?=
      map (detailedVerificationVariantText . verifiedCandidate) expected
    case map lengthCandidatePresentationNote presentations of
      [Nothing, Just first, Just second] ->
        mapM_ assertLengthSpinePairCounterexampleNote [first, second]
      notes -> assertFailure
        $ "duplicate product occurrence notes were reassociated: "
          ++ show notes
    assertFakeLengthQueryEvents [0] [0] =<<
      BS.readFile (executable ++ ".events")
  assertLengthSpinePairPostVerificationPresentationRemainder inputAndZero

lengthUsableWorkBudgetTests :: TestTree
lengthUsableWorkBudgetTests = testGroup
  "programmatic shared usable-work Length ranking"
  [ testCase
      "compose a persistent last-wins builder and admit before clock capture"
      assertLengthUsableWorkBudgetBuilderAndAdmission
  ]

expectLengthUsableWorkBudget
  :: Int
  -> IO Djex.LengthSMTLibLiveUsableWorkBudget
expectLengthUsableWorkBudget milliseconds = expectRight
  $ Djex.mkLengthSMTLibLiveUsableWorkBudget
  $ Djex.LengthSMTLibLiveUsableWorkBudgetSource milliseconds

usableWorkScalarLiveContract :: LeanLengthContract
usableWorkScalarLiveContract = (lengthRankingContract 0)
  { leanLengthContractTargetArgumentRoles = [LengthObservedSpine]
  , leanLengthContractSource = LengthContractSource
      { lengthContractPrecondition = LengthAtMost
          (LengthLiteral 1) (LengthVariable $ LengthInput 0)
      , lengthContractPostcondition = LengthTruth True
      }
  }

usableWorkPairLiveContract :: LeanLengthSpinePairContract
usableWorkPairLiveContract = lengthSpinePairRankingContract
  { leanLengthSpinePairContractSource =
      (leanLengthSpinePairContractSource lengthSpinePairRankingContract)
        { Djex.lengthSpinePairContractPrecondition = LengthAtMost
            (LengthLiteral 1)
            (LengthVariable $ Djex.LengthSpinePairInput 0)
        , Djex.lengthSpinePairContractPostcondition = LengthTruth True
        }
  }

-- Test-only demand hook.  The owner observes normal callback return, so a
-- delayed lazy field/final transform characterizes its strict boundary
-- without asynchronous interruption or a scheduler-sensitive timeout race.
delayedLengthTestValue :: Int -> value -> value
delayedLengthTestValue microseconds value = unsafePerformIO $ do
  threadDelay microseconds
  pure value
{-# NOINLINE delayedLengthTestValue #-}

-- Tie a delay thunk to a test-owned runtime allocation.  This prevents GHC's
-- full-laziness/CSE from sharing an already-forced static delay with another
-- test which happens to use the same duration and value.
delayedLengthTestValueWithGate :: IORef Int -> Int -> value -> value
delayedLengthTestValueWithGate gate microseconds value = unsafePerformIO $ do
  modifyIORef' gate (+ 1)
  threadDelay microseconds
  pure value
{-# NOINLINE delayedLengthTestValueWithGate #-}

assertScalarUsableWorkExpiry :: String -> LengthRanking -> IO ()
assertScalarUsableWorkExpiry label ranking = do
  map rankedLengthCandidateAssessment
      (lengthRankingCandidates ranking) @?=
    replicate (length $ lengthRankingCandidates ranking) Unassessed
  failure <- case lengthRankingFailure ranking of
    Nothing -> assertFailure (label ++ " retained no usable-work failure")
      >> error "unreachable"
    Just retained -> pure retained
  lengthRankingFailureClass failure @?=
    LengthRankingLiveSessionFailed
      Djex.LengthSMTLibLiveSessionDeadlineExceeded
  lengthRankingFailureOriginalIndex failure @?= Nothing
  lengthRankingFailureCleanupIncomplete failure @?= False

assertPairUsableWorkExpiry :: String -> LengthSpinePairRanking -> IO ()
assertPairUsableWorkExpiry label ranking = do
  map rankedLengthSpinePairCandidateAssessment
      (lengthSpinePairRankingCandidates ranking) @?=
    replicate (length $ lengthSpinePairRankingCandidates ranking)
      LengthSpinePairUnassessed
  failure <- case lengthSpinePairRankingFailure ranking of
    Nothing -> assertFailure (label ++ " retained no usable-work failure")
      >> error "unreachable"
    Just retained -> pure retained
  lengthSpinePairRankingFailureClass failure @?=
    LengthSpinePairRankingLiveSessionFailed
      Djex.LengthSMTLibLiveSessionDeadlineExceeded
  lengthSpinePairRankingFailureOriginalIndex failure @?= Nothing
  lengthSpinePairRankingFailureCleanupIncomplete failure @?= False

assertLengthUsableWorkBudgetBuilderAndAdmission :: IO ()
assertLengthUsableWorkBudgetBuilderAndAdmission = do
  identity <- buildOneInputLengthRankingCandidate
  (_, pairCandidate) <- buildLengthSpinePairRankingFixture
  shortBudget <- expectLengthUsableWorkBudget 80
  -- This fixture tests builder precedence, not process-startup performance.
  -- Two delayed solver queries already spend 600 ms; leave enough margin for
  -- Windows process creation while the 80 ms policy still expires decisively.
  longBudget <- expectLengthUsableWorkBudget 3000
  withFakeLengthSolver "query-delay-300ms" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let shortLast = enableLengthRankingUsableWorkBudget shortBudget
          $ enableLengthRankingUsableWorkBudget longBudget base
        longLast = enableLengthRankingUsableWorkBudget longBudget
          $ enableLengthRankingUsableWorkBudget shortBudget base
        forward = enableLengthRankingUsableWorkBudget longBudget
          $ enableLengthRankingDeferredLiveSessionOpening base
        reverseOrder = enableLengthRankingDeferredLiveSessionOpening
          $ enableLengthRankingUsableWorkBudget longBudget base
        run label policy = expectLengthRankingWithin label
          $ rankVerifiedLengthCandidatesWithPolicy policy
              usableWorkScalarLiveContract [identity]
    run "short last usable-work builder" shortLast >>=
      assertScalarUsableWorkExpiry "short last usable-work builder"
    longRanking <- run "long last usable-work builder" longLast
    lengthRankingFailure longRanking @?= Nothing
    forwardRanking <- run "forward usable-work composition" forward
    reverseRanking <- run "reverse usable-work composition" reverseOrder
    assertLengthRankingsEquivalent forwardRanking reverseRanking
    baseRanking <- run "immutable budget-disabled base" base
    lengthRankingFailure baseRanking @?= Nothing

  -- The delayed 65th list cell proves that productive admission precedes
  -- both preparation and the shared clock capture in both nominal domains.
  withTemporaryDirectory "leant-length-usable-work-admission" $ \root -> do
    let executable = root </> "missing-z3"
        maximumCandidates =
          Djex.defaultLengthSMTLibLiveSessionMaximumQueries
        admittedCount = fromIntegral maximumCandidates
        scalarInput = replicate admittedCount identity
          ++ delayedLengthTestValue 150000 [identity]
        pairInput = replicate admittedCount pairCandidate
          ++ delayedLengthTestValue 150000 [pairCandidate]
        expected = LengthRankingInputLimitExceeded
          maximumCandidates (maximumCandidates + 1)
        assertRejected label result = case result of
          Just (Left failure) -> failure @?= expected
          Just (Right _) -> assertFailure
            $ label ++ " admitted maximum-plus-one input"
          Nothing -> assertFailure $ label ++ " did not reject productively"
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    policy <- enableLengthRankingUsableWorkBudget
      <$> expectLengthUsableWorkBudget 40 <*> pure base
    scalar <- timeout 1000000
      $ rankVerifiedLengthCandidatesWithPolicy policy
          (error "budgeted scalar admission forced preparation") scalarInput
    assertRejected "budgeted scalar admission" scalar
    pair <- timeout 1000000
      $ rankVerifiedLengthSpinePairCandidatesWithPolicy policy
          (error "budgeted pair admission forced preparation") pairInput
    assertRejected "budgeted pair admission" pair
    doesFileExist (executable ++ ".events") >>= (@?= False)

lengthScopedUsableWorkBudgetTests :: TestTree
lengthScopedUsableWorkBudgetTests = testGroup
  "programmatic scoped usable-work Length ranking"
  [ testCase
      "compose a cross-strategy last-wins builder without dropping policies"
      assertLengthScopedUsableWorkBudgetBuilderComposition
  ]

assertLengthScopedUsableWorkBudgetBuilderComposition :: IO ()
assertLengthScopedUsableWorkBudgetBuilderComposition = do
  identity <- buildOneInputLengthRankingCandidate
  limits <- explicitLengthInputBoxLimits 1 2
  shortBudget <- expectLengthUsableWorkBudget 50
  longBudget <- expectLengthUsableWorkBudget 1000
  delayGate <- newIORef 0
  withTemporaryDirectory "leant-length-scoped-budget-builder" $ \root -> do
    let executable = root </> "missing-z3"
        safeContract = relationalPositiveAffineScalarContract
          $ LengthTruth True
        delayedContract microseconds = safeContract
          { leanLengthContractSource =
              delayedLengthTestValueWithGate delayGate microseconds
              $ leanLengthContractSource safeContract
          }
        run label policy contract = expectLengthRankingWithin label
          $ rankVerifiedLengthCandidatesWithPolicy policy contract [identity]
        expectEstablished label ranking = do
          lengthRankingFailure ranking @?= Nothing
          case map rankedLengthCandidateAssessment
              $ lengthRankingCandidates ranking of
            [ApplicableDomainEstablished _] ->
              pure ()
            assessments -> assertFailure
              $ label ++ " lost the current domain policy: "
                  ++ show assessments
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let current = enableLengthRankingApplicableDomainValidation limits
          Djex.defaultLengthBooleanFiniteUnionLimits
        retained = enableLengthRankingNonVacuousApplicableDomainPreference
          $ enableLengthRankingDeferredLiveSessionOpening base
        advanced = current retained
        scopedShortLast = enableLengthRankingScopedUsableWorkBudget shortBudget
          $ enableLengthRankingUsableWorkBudget longBudget advanced
        v1LongLast = enableLengthRankingUsableWorkBudget longBudget
          $ enableLengthRankingScopedUsableWorkBudget shortBudget advanced
        v1ShortLast = enableLengthRankingUsableWorkBudget shortBudget
          $ enableLengthRankingScopedUsableWorkBudget longBudget advanced
        scopedLongLast =
          enableLengthRankingScopedUsableWorkBudget longBudget
          $ enableLengthRankingUsableWorkBudget shortBudget advanced
        budgetThenDomain = current
          $ enableLengthRankingScopedUsableWorkBudget longBudget retained
        domainThenBudget =
          enableLengthRankingScopedUsableWorkBudget longBudget
          $ current retained
    run "scoped short budget last" scopedShortLast
        (delayedContract 150000) >>=
      assertScalarUsableWorkExpiry "scoped short budget last"
    run "v1 short budget last" v1ShortLast (delayedContract 160000) >>=
      assertScalarUsableWorkExpiry "v1 short budget last"
    run "v1 long budget last" v1LongLast (delayedContract 170000) >>=
      expectEstablished "v1 long budget last"
    run "scoped long budget last" scopedLongLast
        (delayedContract 180000) >>=
      expectEstablished "scoped long budget last"
    run "scoped budget then current domain" budgetThenDomain safeContract
      >>= expectEstablished "scoped budget then current domain"
    run "current domain then scoped budget" domainThenBudget safeContract
      >>= expectEstablished "current domain then scoped budget"
    doesFileExist (executable ++ ".events") >>= (@?= False)
  readIORef delayGate >>= (@?= 4)

assertLengthSpinePairPostVerificationPresentationRemainder
  :: Verified DetailedVerificationVariant
  -> IO ()
assertLengthSpinePairPostVerificationPresentationRemainder inputAndZero = do
  unequalVerification <- verificationBatchFromReceipts [inputAndZero]
  withFakeLengthSolver "healthy" $ \executable -> do
    let source = explicitLengthRankingExecutionSource executable Nothing
          Djex.LengthSMTLibInputValuesAfterSatisfiable
    policy <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits source
          Djex.defaultLengthEvaluationLimitSource
    result <- expectLengthSpinePairPostVerificationWithin
      $ assessVerifiedLengthSpinePairCandidatesWithPolicy policy
          lengthSpinePairSecondOneContract unequalVerification
    case map lengthCandidatePresentationNote
        $ presentLengthSpinePairPostVerificationResult result of
      [Just note] -> mapM_ (\fragment -> assertBool
          ("unequal product presentation omitted " ++ show fragment)
          $ fragment `isInfixOf` note)
        [ "conditional on 1 assumed provider law used by this candidate"
        , "observed input spine lengths = [3]"
        , "first result spine length = 3"
        , "second result spine length = 0"
        ]
      notes -> assertFailure
        $ "unequal product presentation changed association: " ++ show notes
    assertFakeLengthQueryEvents [0] [0] =<<
      BS.readFile (executable ++ ".events")

  limits <- explicitLengthInputBoxLimits 1 2
  positiveVerification <- verificationBatchFromReceipts [inputAndZero]
  withFakeLengthSolver "query-unsat" $ \executable -> do
    let source = explicitLengthRankingExecutionSource executable Nothing
          Djex.LengthSMTLibStatusOnly
        policySource = explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits source
          Djex.defaultLengthEvaluationLimitSource
    base <- expectRight $ mkLengthRankingPolicy policySource
    let policy = enableLengthRankingInputBoxValidation limits [1] base
    result <- expectLengthSpinePairPostVerificationWithin
      $ assessVerifiedLengthSpinePairCandidatesWithPolicy policy
          lengthSpinePairRankingContract positiveVerification
    ranking <- expectLengthSpinePairPostVerificationRanking result
    positive <- case map rankedLengthSpinePairCandidateAssessment
        $ lengthSpinePairRankingCandidates ranking of
      [LengthSpinePairBoundedPositive receipt] -> pure receipt
      assessments -> assertFailure
        ("product positive post-verification changed: " ++ show assessments)
          >> error "unreachable"
    let directNote = renderLengthSpinePairInputBoxValidationNote positive
        presentations = presentLengthSpinePairPostVerificationResult result
    map lengthCandidatePresentationNote presentations @?= [Just directNote]
    mapM_ (\fragment -> assertBool
        ("product input-box note omitted " ++ show fragment)
        $ fragment `isInfixOf` directNote)
      [ "independently checked binary-product finite-spine Length input box"
      , "conditional on 1 assumed provider law used by this candidate"
      , "inclusive input maxima = [1]"
      , "checked assignments = 2"
      , "applicable assignments = 2"
      ]
    assertBool "product input-box note exceeded the terminal bound"
      $ length directNote <= maximumLengthCounterexampleNoteCharacters
assertLengthSpinePairCounterexampleNote :: String -> IO ()
assertLengthSpinePairCounterexampleNote note = do
  mapM_ (\fragment -> assertBool
      ("product counterexample note omitted " ++ show fragment)
      $ fragment `isInfixOf` note)
    [ "replayed binary-product finite-spine Length counterexample"
    , "model-relative; provider-independent"
    , "observed input spine lengths = [3]"
    , "first result spine length = 3"
    , "second result spine length = 3"
    ]
  mapM_ (\overclaim -> assertBool
      ("product counterexample note made an unsupported claim: "
        ++ overclaim)
      $ not $ overclaim `isInfixOf` map toLower note)
    ["z3", "proved", "universal", "lean-correct"]
  assertBool "product counterexample note exceeded the terminal bound"
    $ length note <= maximumLengthCounterexampleNoteCharacters

assertLengthSpinePairRankingAtomicFailures :: IO ()
assertLengthSpinePairRankingAtomicFailures = do
  (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
  refused <- syntheticLengthRankingCandidate "pair-atomic-refusal"
  let original = [duplicatedInput, inputAndZero, refused]
  (liveRanking, liveEvents) <- runLengthSpinePairRankingWithFakeTrace
    "healthy" Djex.LengthSMTLibInputValuesAfterSatisfiable
    defaultLengthEvaluationLimits lengthSpinePairRankingContract original
  assertLengthSpinePairAtomicReset original liveRanking
    [Nothing, Nothing, Just LengthPreparationTypedAuthorityUnavailable]
  liveFailure <- expectLengthSpinePairRankingFailure liveRanking
  lengthSpinePairRankingFailureClass liveFailure @?=
    LengthSpinePairRankingLiveQueryFailed
      Djex.LengthSpinePairSMTLibLiveQueryCounterexampleRejected
  lengthSpinePairRankingFailureCleanupIncomplete liveFailure @?= False
  lengthSpinePairRankingFailureOriginalIndex liveFailure @?= Just 1
  assertFakeLengthQueryEvents [0, 1] [0, 1] liveEvents

  (sessionRanking, sessionEvents) <- runLengthSpinePairRankingWithFakeTrace
    "wrong-echo" Djex.LengthSMTLibStatusOnly defaultLengthEvaluationLimits
    lengthSpinePairRankingContract [duplicatedInput, inputAndZero]
  assertLengthSpinePairAtomicReset [duplicatedInput, inputAndZero]
    sessionRanking [Nothing, Nothing]
  sessionFailure <- expectLengthSpinePairRankingFailure sessionRanking
  case lengthSpinePairRankingFailureClass sessionFailure of
    LengthSpinePairRankingLiveSessionFailed _ -> pure ()
    failure -> assertFailure
      $ "unexpected product session failure: " ++ show failure
  lengthSpinePairRankingFailureOriginalIndex sessionFailure @?= Nothing
  assertFakeLengthQueryEvents [] [] sessionEvents

  limits <- explicitLengthInputBoxLimits 1 2
  (boxRanking, boxEvents) <-
    runLengthSpinePairRankingWithFakeTraceWithInputBox
      "query-unsat" Djex.LengthSMTLibStatusOnly
      defaultLengthEvaluationLimits limits []
      lengthSpinePairRankingContract [inputAndZero]
  assertLengthSpinePairAtomicReset [inputAndZero] boxRanking [Nothing]
  boxFailure <- expectLengthSpinePairRankingFailure boxRanking
  lengthSpinePairRankingFailureClass boxFailure @?=
    LengthSpinePairRankingInputBoxValidationFailed
      (Djex.LengthSpinePairInputBoxBoundsArityMismatch 1 0)
  lengthSpinePairRankingFailureOriginalIndex boxFailure @?= Just 0
  assertFakeLengthQueryEvents [0] [] boxEvents

assertLengthSpinePairScalarRegression :: IO ()
assertLengthSpinePairScalarRegression = do
  scalarFixture <- buildLengthRankingLiveFixture
  (duplicatedInput, _) <- buildLengthSpinePairRankingFixture
  let scalarCandidate = lengthRankingFixtureZero scalarFixture
      scalarContract = lengthRankingContract 2
      prepareScalar = expectRight
          (prepareCheckedLengthQuery scalarContract scalarCandidate)
        >>= expectRight
  before <- prepareScalar
  _ <- expectRight
      (prepareCheckedLengthSpinePairQuery
        lengthSpinePairRankingContract duplicatedInput)
    >>= expectRight
  after <- prepareScalar
  fingerprintCanonicalBytes (lengthSMTLibQueryFingerprint before) @?=
    fingerprintCanonicalBytes (lengthSMTLibQueryFingerprint after)
  lengthSMTLibQueryCheckBytes before @?= lengthSMTLibQueryCheckBytes after
  lengthSMTLibQueryInputSymbols before @?=
    lengthSMTLibQueryInputSymbols after
  lengthSMTLibQueryInputValueRequestBytes before @?=
    lengthSMTLibQueryInputValueRequestBytes after
  lengthSMTLibQuerySchemaTag @?=
    spinePairBytes "djex-length-z3-qf-lia-smtlib2/v2"

  scalarRanking <- runLengthRankingWithFake "healthy"
    Djex.LengthSMTLibInputValuesAfterSatisfiable scalarContract
    [scalarCandidate]
  scalarReceipt <- case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates scalarRanking of
    [Counterexample receipt] -> pure receipt
    assessments -> assertFailure
      ("scalar regression lost its counterexample: " ++ show assessments)
        >> error "unreachable"
  renderLengthCounterexampleNote scalarReceipt @?=
    "replayed finite-list-spine Length counterexample (model-relative; "
      ++ "conditional on 1 assumed provider law used by this candidate): "
      ++ "observed input spine lengths = []; result spine length = 0"

buildLengthSpinePairRankingFixture
  :: IO
      ( Verified DetailedVerificationVariant
      , Verified DetailedVerificationVariant
      )
buildLengthSpinePairRankingFixture = do
  detailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      False EngineExference 512 Set.empty
        [ProviderFrag "Demo.zeroList" lengthSpinePairFixtureList]
        lengthSpinePairFixtureGoal
  groups <- case detailed of
    DetailedSynthCandidates retained _ -> pure retained
    other -> assertFailure
      ("product ranking fixture synthesis failed: " ++ show other)
        >> error "unreachable"
  batch <- verifyCandidateGroups 512 (const $ pure VariantAccepted)
    $ map detailedCandidateGroupVerificationVariants groups
  let receipts = verifiedCandidateReceipts batch
      prepared =
        [ (verified, result)
        | verified <- receipts
        , Right problem <-
            [prepareCheckedLengthSpinePairProblem
              lengthSpinePairRankingContract verified]
        , let result = Djex.checkedLengthSpinePairCandidateResult
                $ Djex.checkedLengthSpinePairProblemCandidate problem
        ]
      input = LengthVariable $ LengthInput 0
      duplicatedResult = Djex.LengthSpinePair input input
      inputAndZeroResult = Djex.LengthSpinePair input $ LengthLiteral 0
  duplicated <- chooseResult "(input,input)" duplicatedResult prepared
  inputAndZero <- chooseResult "(input,zero)" inputAndZeroResult prepared
  pure (duplicated, inputAndZero)
 where
  chooseResult label expected prepared = case
      [verified | (verified, actual) <- prepared, actual == expected] of
    verified : _ -> pure verified
    [] -> assertFailure
      ("product ranking fixture lacked " ++ label ++ ": "
        ++ show (map snd prepared)) >> error "unreachable"

lengthSpinePairRankingContract :: LeanLengthSpinePairContract
lengthSpinePairRankingContract = lengthSpinePairFixtureContract
  { leanLengthSpinePairContractProviderLaws =
      [ LeanLengthProviderLaw
          { leanLengthProviderLawName = "Demo.zeroList"
          , leanLengthProviderLawArgumentRoles = []
          , leanLengthProviderLawTransfer = LengthLiteral 0
          }
      ]
  }

pairRankingUsedProviders
  :: Verified DetailedVerificationVariant
  -> LeanLengthSpinePairContract
  -> [Djex.Name]
pairRankingUsedProviders verified contract = case
    prepareCheckedLengthSpinePairProblem contract verified of
  Left failure -> error
    $ "product ranking provider fixture stopped preparing: " ++ show failure
  Right problem -> Djex.checkedLengthSpinePairCandidateUsedProviders
    $ Djex.checkedLengthSpinePairProblemCandidate problem

lengthSpinePairSecondOneContract :: LeanLengthSpinePairContract
lengthSpinePairSecondOneContract = lengthSpinePairSecondLiteralContract 1

lengthSpinePairSecondTwoContract :: LeanLengthSpinePairContract
lengthSpinePairSecondTwoContract = lengthSpinePairSecondLiteralContract 2

lengthSpinePairSecondLiteralContract
  :: Natural
  -> LeanLengthSpinePairContract
lengthSpinePairSecondLiteralContract expected = lengthSpinePairRankingContract
  { leanLengthSpinePairContractSource = Djex.LengthSpinePairContractSource
      { Djex.lengthSpinePairContractPrecondition = Djex.LengthTruth True
      , Djex.lengthSpinePairContractPostcondition = Djex.LengthAll
          [ Djex.LengthEqual
              (Djex.LengthVariable $ Djex.LengthSpinePairResult
                Djex.LengthSpinePairFirst)
              (Djex.LengthVariable $ Djex.LengthSpinePairInput 0)
          , Djex.LengthEqual
              (Djex.LengthVariable $ Djex.LengthSpinePairResult
                Djex.LengthSpinePairSecond)
              (Djex.LengthLiteral expected)
          ]
      }
  }

rankedLengthSpinePairVerifiedCandidates
