scalarBooleanFiniteUnionOneInputPrecondition
  :: LengthFormula LengthContractVariable
scalarBooleanFiniteUnionOneInputPrecondition = LengthNot $ LengthAll
  [ LengthNot $ LengthAtMost scalarInput $ LengthLiteral 1
  , LengthNot $ LengthAtMost scalarInput $ LengthLiteral 3
  ]
 where
  scalarInput = LengthVariable $ LengthInput 0

buildTwoInputBooleanFiniteUnionScalarFixture
  :: IO (LeanLengthContract, Verified DetailedVerificationVariant)
buildTwoInputBooleanFiniteUnionScalarFixture = do
  (contract, candidates) <- buildLengthSeedBankArityFixture
  case drop 2 candidates of
    candidate : _ -> pure
      ( contract
          { leanLengthContractTargetArgumentRoles =
              replicate 2 LengthObservedSpine
          }
      , candidate
      )
    [] -> assertFailure "seed-bank fixture lost its two-input candidate"
      >> error "unreachable"

buildTwoInputBooleanFiniteUnionPairFixture
  :: IO
      ( LeanLengthSpinePairContract
      , Verified DetailedVerificationVariant
      )
buildTwoInputBooleanFiniteUnionPairFixture = do
  let goal = FArr lengthSpinePairFixtureList
        $ FArr lengthSpinePairFixtureList
        $ FLeanProd lengthSpinePairFixtureList lengthSpinePairFixtureList
      contract =
        (strictRelationalPositiveAffineQuotientPairContract
          (LengthTruth True) (LengthTruth True))
          { leanLengthSpinePairContractTargetArgumentRoles =
              replicate 2 LengthObservedSpine
          }
  detailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      False EngineExference 1024 Set.empty
        [ProviderFrag "Demo.zeroList" lengthSpinePairFixtureList]
        goal
  groups <- case detailed of
    DetailedSynthCandidates retained _ -> pure retained
    other -> assertFailure
      ("two-input product union synthesis failed: " ++ show other)
        >> error "unreachable"
  batch <- verifyCandidateGroups 1024 (const $ pure VariantAccepted)
    $ map detailedCandidateGroupVerificationVariants groups
  let prepared =
        [ verified
        | verified <- verifiedCandidateReceipts batch
        , Right problem <-
            [prepareCheckedLengthSpinePairProblem contract verified]
        , Djex.checkedLengthSpinePairProblemInputCount problem == 2
        ]
  case prepared of
    candidate : _ -> pure (contract, candidate)
    [] -> assertFailure
      ("two-input product union fixture had no checked candidate: "
        ++ show (map detailedCandidateGroupVariants groups))
        >> error "unreachable"

scalarBooleanFiniteUnionEvaluationFailurePrecondition
  :: LengthFormula LengthContractVariable
scalarBooleanFiniteUnionEvaluationFailurePrecondition = LengthAll
  [ LengthAtMost scalarInput $ LengthLiteral 1
  , LengthAtMost (LengthScale 2 scalarInput) $ LengthLiteral 2
  ]
 where
  scalarInput = LengthVariable $ LengthInput 0

pairBooleanFiniteUnionEvaluationFailurePrecondition
  :: LengthFormula Djex.LengthSpinePairContractVariable
pairBooleanFiniteUnionEvaluationFailurePrecondition = LengthAll
  [ LengthAtMost pairInput $ LengthLiteral 1
  , LengthAtMost (LengthScale 2 pairInput) $ LengthLiteral 2
  ]
 where
  pairInput = LengthVariable $ Djex.LengthSpinePairInput 0

lengthApplicableDomainTests
  :: TestTree
lengthApplicableDomainTests =
  testGroup "current applicable-domain startup Length ranking"
    [ testCase
        "close exact current scalar and product roots, objects, and caps"
        assertCurrentLengthApplicableDomainSchema
    , testCase
        "select current domains explicitly and reject historical root shapes"
        assertCurrentLengthApplicableDomainDecoderIsolation
    , testCase
        "compose the current domain builder without dropping other policy"
        assertCurrentLengthApplicableDomainBuilderComposition
    , testCase
        "establish fixed current scalar and product domain receipts"
        assertCurrentLengthApplicableDomainPureRanking
    , testCase
        "decode guarded conditionals into nominal pure domain receipts"
        assertCurrentLengthApplicableDomainGuardedConditional
    , testCase
        "retain counterexample simplification and only its final MRU vector"
        assertCurrentLengthApplicableDomainSimplificationMRU
    , testCase
        "prefer, seal, force, and present nominal recursive receipts exactly"
        assertCurrentLengthApplicableDomainPreferencePresentation
    , testCase
        "retain scoped and live routes, failures, deadlines, and cap misses"
        assertCurrentLengthApplicableDomainScopedRoutes
    ]

historicalRecursiveApplicableDomainStrategyLiteral
  :: String
historicalRecursiveApplicableDomainStrategyLiteral =
  "strict-relational-positive-affine-quotient-root-extrema-monus-boolean-finite-union-atomic-branching-recursive-piecewise-affine-v1"

currentApplicableDomainObject :: Json.JValue
currentApplicableDomainObject = Json.JObj
  [ ("maximumInputs", Json.JInt 8)
  , ("maximumGeneratedBranches", Json.JInt 256)
  , ("maximumRulesPerBranch", Json.JInt 64)
  , ("maximumClosureInspectionsPerBranch", Json.JInt 4096)
  , ("maximumRetainedBoxes", Json.JInt 256)
  , ("maximumAssignmentVisits", Json.JInt 262144)
  , ("maximumAssignments", Json.JInt 65536)
  ]

currentApplicableDomainScalarDocument
  :: FilePath
  -> Integer
  -> Json.JValue
currentApplicableDomainScalarDocument
    executable milliseconds =
  setJsonField ["usableWorkBudget", "milliseconds"]
      (Json.JInt milliseconds)
  $ setJsonField ["contract"] positiveAffineScalarContractValue
  $ lengthRankingConfigurationFileFixture executable Nothing

currentApplicableDomainPairDocument
  :: FilePath
  -> Integer
  -> Json.JValue
currentApplicableDomainPairDocument
    executable milliseconds =
  setJsonField ["usableWorkBudget", "milliseconds"]
      (Json.JInt milliseconds)
  $ lengthAssessmentConfigurationFileSpinePairFixture
      executable Nothing [1] 2 positiveAffinePairContractValue

expectCurrentApplicableDomainPolicy
  :: Json.JValue
  -> IO (LengthRankingPolicy, LeanLengthContractSelection)
expectCurrentApplicableDomainPolicy
    document = do
  disabled <- expectLengthAssessmentConfigurationFile document
  activated <- expectLengthAssessmentConfigurationActivation
    PermitUnpinnedExecutable disabled
  lengthRankingPolicyExecutableLaunchStrategy (fst activated) @?=
    Djex.LengthSMTLibDescriptorBoundExecveCheckExecutableAccessLaunch
  pure activated

assertCurrentLengthApplicableDomainSchema :: IO ()
assertCurrentLengthApplicableDomainSchema =
  withTemporaryDirectory "leant-length-recursive-piecewise-schema"
    $ \root -> do
      let executable = root </> "missing-z3"
          scalar =
            currentApplicableDomainScalarDocument
              executable 65000
          pair =
            currentApplicableDomainPairDocument
              executable 65000
          documents = [scalar, pair]
          missing = assertConfigurationFieldMissing
          unexpected = assertConfigurationFieldUnexpected
          rootShape = lengthRankingConfigurationRootShape
          applicableShape =
            [ ( LengthRankingConfigurationApplicableDomainMaximumInputsField
              , "maximumInputs"
              )
            , ( LengthRankingConfigurationApplicableDomainMaximumGeneratedBranchesField
              , "maximumGeneratedBranches"
              )
            , ( LengthRankingConfigurationApplicableDomainMaximumRulesPerBranchField
              , "maximumRulesPerBranch"
              )
            , ( LengthRankingConfigurationApplicableDomainMaximumClosureInspectionsPerBranchField
              , "maximumClosureInspectionsPerBranch"
              )
            , ( LengthRankingConfigurationApplicableDomainMaximumRetainedBoxesField
              , "maximumRetainedBoxes"
              )
            , ( LengthRankingConfigurationApplicableDomainMaximumAssignmentVisitsField
              , "maximumAssignmentVisits"
              )
            , ( LengthRankingConfigurationApplicableDomainMaximumAssignmentsField
              , "maximumAssignments"
              )
            ]
          simplificationShape =
            [ ( LengthRankingConfigurationCounterexampleSimplificationMaximumInputsField
              , "maximumInputs"
              )
            , ( LengthRankingConfigurationCounterexampleSimplificationMaximumAssignmentsField
              , "maximumAssignments"
              )
            ]
          budgetShape =
            [ ( LengthRankingConfigurationUsableWorkBudgetMillisecondsField
              , "milliseconds"
              )
            ]
      mapM_ (\document -> do
          _ <- expectLengthAssessmentConfigurationFile document
          _ <- expectLengthAssessmentConfigurationFile
            $ reverseJsonObjectFields document
          mapM_ (\(field, name) -> missing
              LengthRankingConfigurationRootObject field [name] document)
            rootShape
          unexpected LengthRankingConfigurationRootObject [] document
          assertLengthAssessmentConfigurationFileError
            (LengthRankingConfigurationExpectedObject
              LengthRankingConfigurationApplicableDomainValidationObject)
            $ setJsonField ["applicableDomainValidation"] Json.JNull document
          mapM_ (\(field, name) -> missing
              LengthRankingConfigurationApplicableDomainValidationObject field
              ["applicableDomainValidation", name] document)
            applicableShape
          unexpected
            LengthRankingConfigurationApplicableDomainValidationObject
            ["applicableDomainValidation"] document
          assertLengthAssessmentConfigurationFileError
            (LengthRankingConfigurationExpectedObject
              LengthRankingConfigurationCounterexampleSimplificationObject)
            $ setJsonField ["counterexampleSimplification"] Json.JNull
                document
          mapM_ (\(field, name) -> missing
              LengthRankingConfigurationCounterexampleSimplificationObject
              field ["counterexampleSimplification", name] document)
            simplificationShape
          unexpected
            LengthRankingConfigurationCounterexampleSimplificationObject
            ["counterexampleSimplification"] document
          assertLengthAssessmentConfigurationFileError
            (LengthRankingConfigurationExpectedObject
              LengthRankingConfigurationUsableWorkBudgetObject)
            $ setJsonField ["usableWorkBudget"] Json.JNull document
          mapM_ (\(field, name) -> missing
              LengthRankingConfigurationUsableWorkBudgetObject field
              ["usableWorkBudget", name] document)
            budgetShape
          unexpected LengthRankingConfigurationUsableWorkBudgetObject
            ["usableWorkBudget"] document
          assertLengthAssessmentConfigurationFileError
            (LengthRankingConfigurationUnexpectedField
              LengthRankingConfigurationExecutionObject)
            $ addJsonField ["execution"]
                ("executableLaunch", Json.JStr "obsolete") document
          assertLengthAssessmentConfigurationFileError
            (LengthRankingConfigurationUnexpectedField
              LengthRankingConfigurationApplicableDomainValidationObject)
            $ addJsonField ["applicableDomainValidation"]
                ("strategy", Json.JStr "obsolete") document
          assertLengthAssessmentConfigurationFileError
            (LengthRankingConfigurationUnexpectedField
              LengthRankingConfigurationCounterexampleSimplificationObject)
            $ addJsonField ["counterexampleSimplification"]
                ("strategy", Json.JStr "obsolete") document
          assertLengthAssessmentConfigurationFileError
            (LengthRankingConfigurationUnexpectedField
              LengthRankingConfigurationUsableWorkBudgetObject)
            $ addJsonField ["usableWorkBudget"]
                ("strategy", Json.JStr "obsolete") document)
        documents
      (_, scalarSelection) <-
        expectCurrentApplicableDomainPolicy
          scalar
      case scalarSelection of
        LeanLengthScalarContractSelection _ -> pure ()
        LeanLengthSpinePairContractSelection _ -> assertFailure
          "the scalar startup selected the product Length contract"
      (_, pairSelection) <-
        expectCurrentApplicableDomainPolicy
          pair
      case pairSelection of
        LeanLengthSpinePairContractSelection _ -> pure ()
        LeanLengthScalarContractSelection _ -> assertFailure
          "the product startup selected the scalar Length contract"
      assertDescriptorBoundExecutableLaunchCaps scalar
      assertCurrentApplicableDomainCaps scalar

assertCurrentLengthApplicableDomainDecoderIsolation :: IO ()
assertCurrentLengthApplicableDomainDecoderIsolation =
  withTemporaryDirectory "leant-length-current-domain-and-legacy-roots"
    $ \root -> do
      let executable = root </> "missing-z3"
          scalar =
            currentApplicableDomainScalarDocument
              executable 1000
          pair =
            currentApplicableDomainPairDocument
              executable 1000
          legacyV1 = addJsonField [] ("version", Json.JInt 1)
            $ deleteJsonField ["rankingDomain"]
            $ deleteJsonField ["inputBoxValidation"]
            $ deleteJsonField ["applicableDomainValidation"]
            $ deleteJsonField ["counterexampleSimplification"]
            $ deleteJsonField ["usableWorkBudget"]
            $ deleteJsonField ["contract", "targetArgumentRoles"]
            $ deleteJsonField ["contract", "candidateCasePolicy"] scalar
          legacyV34 = addJsonField []
              ("liveSessionOpening", Json.JStr "defer-until-live-query")
            $ addJsonField []
                ("applicableDomainOrdering", Json.JStr "prefer-non-vacuous")
            $ addJsonField []
                ("boundedPositiveOrdering", Json.JStr "prefer-non-vacuous")
            $ addJsonField []
                ("counterexampleProbe", Json.JStr "origin-before-live")
            $ addJsonField [] ("version", Json.JInt 34)
            $ addJsonField ["execution"]
                ("executableLaunch", Json.JStr
                  "descriptor-bound-execve-check-executable-access-v1")
            $ addJsonField ["applicableDomainValidation"]
                ("strategy", Json.JStr
                  historicalRecursiveApplicableDomainStrategyLiteral)
            $ addJsonField ["counterexampleSimplification"]
                ("strategy", Json.JStr "componentwise-lexicographic-v1")
            $ addJsonField ["usableWorkBudget"]
                ("strategy", Json.JStr
                  "scoped-checkpointed-shared-usable-work-deadline-v2")
            $ deleteJsonField ["rankingDomain"] pair
          missingDomain = LengthRankingConfigurationMissingField
            LengthRankingConfigurationRootObject
            LengthRankingConfigurationRankingDomainField
          unexpectedRoot = LengthRankingConfigurationUnexpectedField
            LengthRankingConfigurationRootObject
      assertLengthAssessmentConfigurationFileError
        (LengthRankingConfigurationFieldTypeMismatch
          LengthRankingConfigurationRankingDomainField
          LengthRankingConfigurationStringValue)
        $ setJsonField ["rankingDomain"] (Json.JBool False) scalar
      assertLengthAssessmentConfigurationFileError
        (LengthRankingConfigurationFieldValueRejected
          LengthRankingConfigurationRankingDomainField)
        $ addJsonField [] ("version", Json.JInt 35)
        $ setJsonField ["rankingDomain"] (Json.JStr "private-domain") scalar
      mapM_ (assertLengthAssessmentConfigurationFileError missingDomain)
        [legacyV1, legacyV34]
      mapM_ (assertLengthAssessmentConfigurationFileError unexpectedRoot)
        [ addJsonField []
            ("rankingDomain", Json.JStr "scalar") legacyV1
        , addJsonField []
            ("rankingDomain", Json.JStr "binary-product") legacyV34
        , addJsonField [] ("version", Json.JInt 35) scalar
        ]

assertCurrentLengthApplicableDomainBuilderComposition :: IO ()
assertCurrentLengthApplicableDomainBuilderComposition = do
  identity <- buildOneInputLengthRankingCandidate
  neutral <- syntheticLengthRankingCandidate
    "recursive-piecewise-builder-neutral"
  inputBoxLimits <- explicitLengthInputBoxLimits 1 15
  shortBudget <- expectLengthUsableWorkBudget 50
  longBudget <- expectLengthUsableWorkBudget 2000
  delayGate <- newIORef 0
  withTemporaryDirectory "leant-length-recursive-piecewise-builder"
    $ \root -> do
      let executable = root </> "missing-z3"
          contract = strictRelationalPositiveAffineQuotientScalarContract
            currentApplicableDomainBuilderPrecondition
            $ LengthTruth True
          delayedContract microseconds = contract
            { leanLengthContractSource =
                delayedLengthTestValueWithGate delayGate microseconds
                $ leanLengthContractSource contract
            }
          run label policy selectedContract candidates =
            expectLengthRankingWithin label
              $ rankVerifiedLengthCandidatesWithPolicy policy
                  selectedContract candidates
      base <- expectRight
        $ mkLengthRankingPolicyWithDescriptorBoundExecveCheckExecutableAccessLaunch
        $ explicitLengthRankingPolicySource
            Djex.defaultLengthSMTLibExecutionLimits
            (explicitLengthRankingExecutionSource executable Nothing
              Djex.LengthSMTLibStatusOnly)
            Djex.defaultLengthEvaluationLimitSource
      let retained = enableLengthRankingScopedUsableWorkBudget longBudget
            $ enableLengthRankingNonVacuousApplicableDomainPreference
            $ enableLengthRankingNonVacuousInputBoxPreference
            $ enableLengthRankingCounterexampleSimplification inputBoxLimits
            $ enableLengthRankingOriginProbe
            $ enableLengthRankingInputBoxValidation inputBoxLimits [14]
            $ enableLengthRankingDeferredLiveSessionOpening base
          current = enableLengthRankingApplicableDomainValidation
            inputBoxLimits Djex.defaultLengthBooleanFiniteUnionLimits
          currentPolicy = current retained
          budgetThenCurrent = current
            $ enableLengthRankingScopedUsableWorkBudget shortBudget
            $ enableLengthRankingDeferredLiveSessionOpening base
          currentThenBudget =
            enableLengthRankingScopedUsableWorkBudget shortBudget
            $ current $ enableLengthRankingDeferredLiveSessionOpening base
          policies = [currentPolicy, budgetThenCurrent, currentThenBudget]
      mapM_ (\policy ->
          lengthRankingPolicyExecutableLaunchStrategy policy @?=
            Djex.LengthSMTLibDescriptorBoundExecveCheckExecutableAccessLaunch)
        policies
      established <- run "current applicable-domain builder"
        currentPolicy
        contract [neutral, identity]
      map rankedLengthCandidateOriginalIndex
          (lengthRankingCandidates established) @?= [1, 0]
      builderReceipt <- case map rankedLengthCandidateAssessment
          $ lengthRankingCandidates established of
        [ ApplicableDomainEstablished receipt
          , Unassessed
          ] -> pure receipt
        assessments -> assertFailure
          ("current applicable-domain builder lost authority: "
            ++ show assessments) >> error "unreachable"
      Djex.validatedLengthApplicableDomainInclusiveMaximumBoxes
          builderReceipt @?= [[2]]
      origin <- run "current applicable-domain origin retention"
        currentPolicy
        ((lengthRankingContract 2)
          { leanLengthContractTargetArgumentRoles = [LengthObservedSpine] })
        [identity]
      lengthRankingFailure origin @?= Nothing
      case lengthRankingCandidates origin of
        [ranked] -> case rankedLengthCandidateAssessment ranked of
          Counterexample receipt -> do
            Djex.validatedLengthCounterexampleInputs receipt @?= [0]
            Djex.validatedLengthCounterexampleResult receipt @?= 0
            rankedLengthCandidateCounterexampleSimplification ranked @?=
              Nothing
          assessment -> assertFailure
            $ "current applicable-domain builder dropped origin probing: "
              ++ show assessment
        ranked -> assertFailure
          $ "current applicable-domain origin cardinality changed: "
            ++ show (length ranked)
      run "budget then current applicable domain" budgetThenCurrent
          (delayedContract 150000) [identity] >>=
        assertScalarUsableWorkExpiry "budget then current applicable domain"
      run "current applicable domain then budget" currentThenBudget
          (delayedContract 160000) [identity] >>=
        assertScalarUsableWorkExpiry "current applicable domain then budget"
      doesFileExist (executable ++ ".events") >>= (@?= False)
  readIORef delayGate >>= (@?= 2)

currentApplicableDomainBuilderPrecondition
  :: LengthFormula LengthContractVariable
currentApplicableDomainBuilderPrecondition = LengthAtMost
  (LengthMaximum scalarInput $ LengthLiteral 1)
  (LengthMonus (LengthLiteral 3)
    $ LengthMinimum scalarInput $ LengthLiteral 1)
 where
  scalarInput = LengthVariable $ LengthInput 0

currentApplicableDomainMinimumPrecondition
  :: LengthFormula LengthContractVariable
currentApplicableDomainMinimumPrecondition = LengthAll
  [ LengthAtMost
      (LengthMaximum scalarFirst scalarSecond)
      (LengthMonus (LengthLiteral 3)
        $ LengthMinimum scalarFirst scalarSecond)
  , LengthAtMost scalarFirst $ LengthLiteral 3
  , LengthAtMost scalarSecond $ LengthLiteral 3
  ]
 where
  scalarFirst = LengthVariable $ LengthInput 0
  scalarSecond = LengthVariable $ LengthInput 1

currentPairApplicableDomainMonusPrecondition
  :: LengthFormula Djex.LengthSpinePairContractVariable
currentPairApplicableDomainMonusPrecondition = LengthAll
  [ LengthAtMost (LengthMaximum firstResult secondResult) $ LengthLiteral 2
  , LengthAtMost pairFirst $ LengthLiteral 3
  , LengthAtMost pairSecond $ LengthLiteral 3
  ]
 where
  pairFirst = LengthVariable $ Djex.LengthSpinePairInput 0
  pairSecond = LengthVariable $ Djex.LengthSpinePairInput 1
  common = LengthMinimum pairFirst pairSecond
  firstResult = LengthSum [common, LengthMonus pairFirst pairSecond]
  secondResult = LengthSum [common, LengthMonus pairSecond pairFirst]

currentPairApplicableDomainVacuousPrecondition
  :: LengthFormula Djex.LengthSpinePairContractVariable
currentPairApplicableDomainVacuousPrecondition = LengthAll
  [ currentPairApplicableDomainMonusPrecondition
  , LengthEqual (LengthModulo 2 pairFirst) $ LengthLiteral 3
  ]
 where
  pairFirst = LengthVariable $ Djex.LengthSpinePairInput 0

currentApplicableDomainRawThirtyTwoPrecondition
  :: LengthFormula LengthContractVariable
currentApplicableDomainRawThirtyTwoPrecondition =
  LengthAll
    [ LengthAtMost firstResult $ LengthLiteral 3
    , LengthAtMost secondResult $ LengthLiteral 3
    , LengthAtMost (LengthLiteral 0)
        $ LengthMaximum scalarFirst scalarSecond
    , LengthAtMost scalarFirst $ LengthLiteral 3
    , LengthAtMost scalarSecond $ LengthLiteral 3
    ]
 where
  scalarFirst = LengthVariable $ LengthInput 0
  scalarSecond = LengthVariable $ LengthInput 1
  common = LengthMinimum scalarFirst scalarSecond
  firstResult = LengthSum
    [common, LengthMonus scalarFirst scalarSecond]
  secondResult = LengthSum
    [common, LengthMonus scalarSecond scalarFirst]

assertCurrentLengthApplicableDomainPureRanking :: IO ()
assertCurrentLengthApplicableDomainPureRanking = do
  (scalarBase, scalarCandidate) <-
    buildTwoInputBooleanFiniteUnionScalarFixture
  (pairBase, pairCandidate) <- buildTwoInputBooleanFiniteUnionPairFixture
  let scalarContract = scalarBase
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition =
                currentApplicableDomainMinimumPrecondition
            , lengthContractPostcondition = LengthTruth True
            }
        }
      pairContract = pairBase
        { leanLengthSpinePairContractSource =
            (leanLengthSpinePairContractSource pairBase)
              { Djex.lengthSpinePairContractPrecondition =
                  currentPairApplicableDomainMonusPrecondition
              , Djex.lengthSpinePairContractPostcondition = LengthTruth True
              }
        }
      rawThirtyTwoContract = scalarBase
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition =
                currentApplicableDomainRawThirtyTwoPrecondition
            , lengthContractPostcondition = LengthTruth True
            }
        }
      configure =
        withCurrentApplicableDomainLimit
            "maximumInputs" 2
        . withCurrentApplicableDomainLimit
            "maximumAssignments" 16
        . withCurrentApplicableDomainLimit
            "maximumAssignmentVisits" 24
  withTemporaryDirectory "leant-length-recursive-piecewise-pure"
    $ \root -> do
      let executable = root </> "missing-z3"
      (scalarPolicy, _) <-
        expectCurrentApplicableDomainPolicy
        $ configure
        $ currentApplicableDomainScalarDocument
            executable 2000
      scalar <- expectLengthRankingWithin
        "current recursive mixed extrema/monus"
        $ rankVerifiedLengthCandidatesWithPolicy scalarPolicy scalarContract
            [scalarCandidate]
      scalarReceipt <- case map rankedLengthCandidateAssessment
          $ lengthRankingCandidates scalar of
        [ ApplicableDomainEstablished
            receipt
          ] -> pure receipt
        assessments -> assertFailure
          ("current recursive mixed extrema/monus produced "
            ++ show assessments)
            >> error "unreachable"
      Djex.validatedLengthApplicableDomainInclusiveMaximumBoxes
          scalarReceipt @?= [[2, 3], [3, 2]]
      Djex.validatedLengthApplicableDomainBoxCount
          scalarReceipt @?= 2
      Djex.validatedLengthApplicableDomainAssignmentVisitCount
          scalarReceipt @?= 24
      Djex.validatedLengthApplicableDomainAssignmentCount
          scalarReceipt @?= 15
      Djex.validatedLengthApplicableDomainApplicableAssignmentCount
          scalarReceipt @?= 10
      _ <- evaluate $ rnf scalarReceipt

      (pairPolicy, _) <-
        expectCurrentApplicableDomainPolicy
        $ configure
        $ currentApplicableDomainPairDocument
            executable 2000
      pair <- expectRight =<<
        rankVerifiedLengthSpinePairCandidatesWithPolicy pairPolicy pairContract
          [pairCandidate]
      pairReceipt <- case map rankedLengthSpinePairCandidateAssessment
          $ lengthSpinePairRankingCandidates pair of
        [ LengthSpinePairApplicableDomainEstablished
            receipt
          ] -> pure receipt
        assessments -> assertFailure
          ("current recursive product identity produced " ++ show assessments)
            >> error "unreachable"
      Djex.validatedLengthSpinePairApplicableDomainInclusiveMaximumBoxes
          pairReceipt @?= [[2, 2]]
      Djex.validatedLengthSpinePairApplicableDomainBoxCount
          pairReceipt @?= 1
      Djex.validatedLengthSpinePairApplicableDomainAssignmentVisitCount
          pairReceipt @?= 9
      Djex.validatedLengthSpinePairApplicableDomainAssignmentCount
          pairReceipt @?= 9
      Djex.validatedLengthSpinePairApplicableDomainApplicableAssignmentCount
          pairReceipt @?= 9
      _ <- evaluate $ rnf pairReceipt

      let rawDocument branchCap =
            withCurrentApplicableDomainLimit
                "maximumInputs" 2
            $ withCurrentApplicableDomainLimit
                "maximumAssignments" 16
            $ withCurrentApplicableDomainLimit
                "maximumAssignmentVisits" 16
            $ withCurrentApplicableDomainLimit
                "maximumGeneratedBranches" branchCap
            $ currentApplicableDomainScalarDocument
                executable 2000
      (rawThirtyOnePolicy, _) <-
        expectCurrentApplicableDomainPolicy
          $ rawDocument 31
      rawThirtyOne <- expectLengthRankingWithin
        "current recursive raw branch cap 31"
        $ rankVerifiedLengthCandidatesWithPolicy rawThirtyOnePolicy
            rawThirtyTwoContract [scalarCandidate]
      map rankedLengthCandidateAssessment
          (lengthRankingCandidates rawThirtyOne) @?= [Unassessed]
      case lengthRankingFailure rawThirtyOne of
        Just failure -> case lengthRankingFailureClass failure of
          LengthRankingLiveSessionFailed _ -> do
            lengthRankingFailureOriginalIndex failure @?= Nothing
            lengthRankingFailureCleanupIncomplete failure @?= False
          failureClass -> assertFailure
            $ "current raw branch cap 31 produced " ++ show failureClass
        Nothing -> assertFailure
          "current raw branch cap 31 unexpectedly retained authority"

      (rawThirtyTwoPolicy, _) <-
        expectCurrentApplicableDomainPolicy
          $ rawDocument 32
      rawThirtyTwo <- expectLengthRankingWithin
        "current recursive raw branch cap 32"
        $ rankVerifiedLengthCandidatesWithPolicy rawThirtyTwoPolicy
            rawThirtyTwoContract [scalarCandidate]
      rawReceipt <- case map rankedLengthCandidateAssessment
          $ lengthRankingCandidates rawThirtyTwo of
        [ ApplicableDomainEstablished
            receipt
          ] -> pure receipt
        assessments -> assertFailure
          ("current raw branch cap 32 produced " ++ show assessments)
            >> error "unreachable"
      Djex.validatedLengthApplicableDomainInclusiveMaximumBoxes
          rawReceipt @?= [[3, 3]]
      Djex.validatedLengthApplicableDomainBoxCount
          rawReceipt @?= 1
      Djex.validatedLengthApplicableDomainAssignmentVisitCount
          rawReceipt @?= 16
      Djex.validatedLengthApplicableDomainAssignmentCount
          rawReceipt @?= 16
      Djex.validatedLengthApplicableDomainApplicableAssignmentCount
          rawReceipt @?= 16
      doesFileExist (executable ++ ".events") >>= (@?= False)

assertCurrentLengthApplicableDomainGuardedConditional :: IO ()
assertCurrentLengthApplicableDomainGuardedConditional = do
  scalarCandidate <- buildOneInputLengthRankingCandidate
  (pairCandidate, _) <- buildLengthSpinePairRankingFixture
  let conditionalPrecondition = jsonLengthAtMost
        (jsonLengthIf
          (jsonLengthAtMost (jsonLengthInput 0) $ jsonLengthLiteral 2)
          (jsonLengthInput 0)
          (jsonLengthLiteral 5))
        (jsonLengthLiteral 3)
      scalarContractValue = addJsonField []
        ("candidateCasePolicy", Json.JStr "cases-rejected")
        $ jsonRoleAwareLengthContract
            ["observed-spine"] conditionalPrecondition
            (jsonLengthTruth True) []
      pairContractValue = jsonLengthSpinePairContract
        ["observed-spine"] "cases-rejected" conditionalPrecondition
        (jsonLengthTruth True) []
      expectedScalarPrecondition = LengthAtMost
        (LengthIf
          (LengthAtMost scalarInput $ LengthLiteral 2)
          scalarInput
          (LengthLiteral 5))
        (LengthLiteral 3)
      expectedPairPrecondition = LengthAtMost
        (LengthIf
          (LengthAtMost pairInput $ LengthLiteral 2)
          pairInput
          (LengthLiteral 5))
        (LengthLiteral 3)
      scalarInput = LengthVariable $ LengthInput 0
      pairInput = LengthVariable $ Djex.LengthSpinePairInput 0
      scalarNote =
        "complete finite-spine Length Boolean finite-union atomic-branching "
          ++ "recursive piecewise-affine domain under strict relational "
          ++ "positive-affine quotient/root-extrema/monus coverage within "
          ++ "admitted bounds (model/provider-relative; provider-independent; "
          ++ "no global proof or solver authority): boxes = 1; visits = 3; "
          ++ "unique = 3; applicable = 3; maxima = [[2]]"
      pairNote =
        "complete binary-product finite-spine Length Boolean finite-union "
          ++ "atomic-branching recursive piecewise-affine domain under strict "
          ++ "relational positive-affine quotient/root-extrema/monus coverage "
          ++ "within admitted bounds (model/provider-relative; "
          ++ "provider-independent; no global proof or solver authority): "
          ++ "boxes = 1; visits = 3; unique = 3; applicable = 3; maxima = [[2]]"
  withTemporaryDirectory "leant-length-guarded-conditional-domain"
    $ \root -> do
      let executable = root </> "missing-z3"
          scalarDocument = setJsonField ["contract"] scalarContractValue
            $ currentApplicableDomainScalarDocument executable 2000
          pairDocument = setJsonField ["contract"] pairContractValue
            $ currentApplicableDomainPairDocument executable 2000
      (scalarPolicy, scalarSelection) <-
        expectCurrentApplicableDomainPolicy scalarDocument
      scalarContract <- case scalarSelection of
        LeanLengthScalarContractSelection contract -> pure contract
        LeanLengthSpinePairContractSelection _ -> assertFailure
          "guarded scalar startup selected the product domain"
            >> error "unreachable"
      lengthContractPrecondition (leanLengthContractSource scalarContract) @?=
        expectedScalarPrecondition
      scalar <- expectLengthRankingWithin "current guarded scalar domain"
        $ rankVerifiedLengthCandidatesWithPolicy scalarPolicy scalarContract
            [scalarCandidate]
      scalarReceipt <- case map rankedLengthCandidateAssessment
          $ lengthRankingCandidates scalar of
        [ApplicableDomainEstablished receipt] -> pure receipt
        assessments -> assertFailure
          ("current guarded scalar domain produced " ++ show assessments)
            >> error "unreachable"
      Djex.validatedLengthApplicableDomainInclusiveMaximumBoxes
          scalarReceipt @?= [[2]]
      Djex.validatedLengthApplicableDomainBoxCount scalarReceipt @?= 1
      Djex.validatedLengthApplicableDomainAssignmentVisitCount
          scalarReceipt @?= 3
      Djex.validatedLengthApplicableDomainAssignmentCount scalarReceipt @?= 3
      Djex.validatedLengthApplicableDomainApplicableAssignmentCount
          scalarReceipt @?= 3
      Djex.validatedLengthApplicableDomainBasis scalarReceipt @?=
        Djex.ProviderIndependentFiniteSpineModel
      renderLengthApplicableDomainValidationNote scalarReceipt @?= scalarNote

      (pairPolicy, pairSelection) <-
        expectCurrentApplicableDomainPolicy pairDocument
      pairContract <- case pairSelection of
        LeanLengthSpinePairContractSelection contract -> pure contract
        LeanLengthScalarContractSelection _ -> assertFailure
          "guarded product startup selected the scalar domain"
            >> error "unreachable"
      Djex.lengthSpinePairContractPrecondition
          (leanLengthSpinePairContractSource pairContract) @?=
        expectedPairPrecondition
      pair <- expectRight =<<
        rankVerifiedLengthSpinePairCandidatesWithPolicy pairPolicy pairContract
          [pairCandidate]
      pairReceipt <- case map rankedLengthSpinePairCandidateAssessment
          $ lengthSpinePairRankingCandidates pair of
        [LengthSpinePairApplicableDomainEstablished receipt] -> pure receipt
        assessments -> assertFailure
          ("current guarded product domain produced " ++ show assessments)
            >> error "unreachable"
      Djex.validatedLengthSpinePairApplicableDomainInclusiveMaximumBoxes
          pairReceipt @?= [[2]]
      Djex.validatedLengthSpinePairApplicableDomainBoxCount pairReceipt @?= 1
      Djex.validatedLengthSpinePairApplicableDomainAssignmentVisitCount
          pairReceipt @?= 3
      Djex.validatedLengthSpinePairApplicableDomainAssignmentCount
          pairReceipt @?= 3
      Djex.validatedLengthSpinePairApplicableDomainApplicableAssignmentCount
          pairReceipt @?= 3
      Djex.validatedLengthSpinePairApplicableDomainBasis pairReceipt @?=
        Djex.ProviderIndependentFiniteSpineModel
      renderLengthSpinePairApplicableDomainValidationNote pairReceipt @?=
        pairNote
      doesFileExist executable >>= (@?= False)
      doesFileExist (executable ++ ".events") >>= (@?= False)

assertCurrentLengthApplicableDomainSimplificationMRU :: IO ()
assertCurrentLengthApplicableDomainSimplificationMRU
  | os /= "linux" = pure ()
  | otherwise =
      whenDescriptorBoundExecveCheckLaunchPubliclyReachable $ do
      identity <- buildOneInputLengthRankingCandidate
      let contract = (lengthRankingContract 2)
            { leanLengthContractTargetArgumentRoles = [LengthObservedSpine]
            , leanLengthContractSource = LengthContractSource
                { lengthContractPrecondition = LengthAtMost
                    (LengthLiteral 1) (LengthVariable $ LengthInput 0)
                , lengthContractPostcondition = LengthEqual
                    (LengthVariable LengthResult) (LengthLiteral 2)
                }
            }
          withInputValues = setJsonField
            ["counterexampleSimplification", "maximumAssignments"]
            (Json.JInt 4)
            . setJsonField ["execution", "artifactPolicy"]
                (Json.JStr "input-values-after-satisfiable")
      withFakeLengthSolver "healthy" $ \executable -> do
        (policy, _) <-
          expectCurrentApplicableDomainPolicy
          $ withInputValues
          $ currentApplicableDomainScalarDocument
              executable 2000
        ranking <- expectLengthRankingWithin
          "current recursive-branching simplification and MRU"
          $ rankVerifiedLengthCandidatesWithPolicy policy contract
              [identity, identity]
        (first, second, firstReceipt, secondReceipt) <- case
            lengthRankingCandidates ranking of
          [firstRanked, secondRanked] -> case
              ( rankedLengthCandidateAssessment firstRanked
              , rankedLengthCandidateAssessment secondRanked
              ) of
            ( Counterexample firstCounterexample
              , Counterexample secondCounterexample
              ) -> pure
                ( firstRanked, secondRanked, firstCounterexample
                , secondCounterexample
                )
            assessments -> assertFailure
              ("current recursive simplification produced "
                ++ show assessments ++ " with failure "
                ++ show (lengthRankingFailure ranking))
                >> error "unreachable"
          ranked -> assertFailure
            ("current recursive simplification cardinality changed: "
              ++ show (length ranked)) >> error "unreachable"
        map Djex.validatedLengthCounterexampleInputs
            [firstReceipt, secondReceipt] @?= [[1], [1]]
        simplification <- case
            rankedLengthCandidateCounterexampleSimplification first of
          Nothing -> assertFailure
            "current recursive path lost simplification metadata"
              >> error "unreachable"
          Just retained -> pure retained
        rankedLengthCandidateCounterexampleSimplification second @?= Nothing
        Djex.validatedLengthCounterexampleSimplificationOriginalInputs
            simplification @?= [3]
        Djex.validatedLengthCounterexampleSimplificationInputs
            simplification @?= [1]
        Djex.validatedLengthCounterexampleSimplificationChanged
            simplification @?= True
        assertFakeLengthQueryEvents [0] [0] =<<
          BS.readFile (executable ++ ".events")

assertCurrentLengthApplicableDomainPreferencePresentation :: IO ()
assertCurrentLengthApplicableDomainPreferencePresentation = do
  maximumLengthCounterexampleNoteCharacters @?= 384
  (scalarBase, scalarCandidate) <-
    buildTwoInputBooleanFiniteUnionScalarFixture
  (pairBase, pairCandidate) <- buildTwoInputBooleanFiniteUnionPairFixture
  scalarNeutral <- syntheticLengthRankingCandidate
    "recursive-piecewise-preference-scalar-neutral"
  pairNeutral <- syntheticLengthRankingCandidate
    "recursive-piecewise-preference-pair-neutral"
  let scalarContract = scalarBase
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition =
                currentApplicableDomainMinimumPrecondition
            , lengthContractPostcondition = LengthTruth True
            }
        }
      pairContract = pairBase
        { leanLengthSpinePairContractSource =
            (leanLengthSpinePairContractSource pairBase)
              { Djex.lengthSpinePairContractPrecondition =
                  currentPairApplicableDomainVacuousPrecondition
              , Djex.lengthSpinePairContractPostcondition = LengthTruth True
              }
        }
      configure =
        withCurrentApplicableDomainLimit
            "maximumInputs" 2
        . withCurrentApplicableDomainLimit
            "maximumAssignments" 16
        . withCurrentApplicableDomainLimit
            "maximumAssignmentVisits" 24
  withTemporaryDirectory "leant-length-recursive-piecewise-presentation"
    $ \root -> do
      let executable = root </> "missing-z3"
      (scalarPolicy, _) <-
        expectCurrentApplicableDomainPolicy
        $ configure
        $ currentApplicableDomainScalarDocument
            executable 2000
      scalar <- expectLengthRankingWithin "current scalar recursive preference"
        $ rankVerifiedLengthCandidatesWithPolicy scalarPolicy scalarContract
            [scalarNeutral, scalarCandidate]
      map rankedLengthCandidateOriginalIndex
          (lengthRankingCandidates scalar) @?= [1, 0]
      scalarReceipt <- case map rankedLengthCandidateAssessment
          $ lengthRankingCandidates scalar of
        [ ApplicableDomainEstablished
            receipt
          , Unassessed
          ] -> pure receipt
        assessments -> assertFailure
          ("current scalar recursive preference changed: "
            ++ show assessments)
            >> error "unreachable"
      _ <- evaluate $ rnf scalarReceipt
      let scalarNote =
            renderLengthApplicableDomainValidationNote
              scalarReceipt
          fullScalarNote =
            "complete finite-spine Length Boolean finite-union atomic-branching recursive piecewise-affine domain under strict relational positive-affine quotient/root-extrema/monus coverage within admitted bounds (model/provider-relative; conditional on 1 assumed provider law used by this candidate; no global proof or solver authority): boxes = 2; visits = 24; unique = 15; applicable = 10; maxima = [[2, 3], [3, 2]]"
      scalarNote @?=
        take maximumLengthCounterexampleNoteCharacters fullScalarNote
      length scalarNote @?= maximumLengthCounterexampleNoteCharacters
      scalarVerification <- verificationBatchFromReceipts
        [scalarNeutral, scalarCandidate]
      scalarAssociated <- expectLengthPostVerificationWithin
        "current scalar recursive occurrence seal"
        $ assessVerifiedLengthCandidatesWithPolicy scalarPolicy
            scalarContract scalarVerification
      assertLengthPostVerificationSealed scalarAssociated
      scalarAssociatedRanking <-
        expectLengthPostVerificationRanking scalarAssociated
      map rankedLengthCandidateOriginalIndex
          (lengthRankingCandidates scalarAssociatedRanking) @?= [1, 0]
      map lengthCandidatePresentationNote
          (presentLengthPostVerificationResult scalarAssociated) @?=
        [Just scalarNote, Nothing]

      (pairPolicy, _) <-
        expectCurrentApplicableDomainPolicy
        $ configure
        $ currentApplicableDomainPairDocument
            executable 2000
      pair <- expectRight =<<
        rankVerifiedLengthSpinePairCandidatesWithPolicy pairPolicy
          pairContract [pairNeutral, pairCandidate]
      map rankedLengthSpinePairCandidateOriginalIndex
          (lengthSpinePairRankingCandidates pair) @?= [0, 1]
      pairReceipt <- case map rankedLengthSpinePairCandidateAssessment
          $ lengthSpinePairRankingCandidates pair of
        [ LengthSpinePairUnassessed
          , LengthSpinePairApplicableDomainEstablished
              receipt
          ] -> pure receipt
        assessments -> assertFailure
          ("current product recursive preference changed: "
            ++ show assessments)
            >> error "unreachable"
      _ <- evaluate $ rnf pairReceipt
      let pairNote =
            renderLengthSpinePairApplicableDomainValidationNote
              pairReceipt
          fullPairNote =
            "complete binary-product finite-spine Length Boolean finite-union atomic-branching recursive piecewise-affine domain under strict relational positive-affine quotient/root-extrema/monus coverage within admitted bounds (model/provider-relative; provider-independent; no global proof or solver authority): boxes = 1; visits = 9; unique = 9; applicable = 0; vacuous (no assignment met the precondition); maxima = [[2, 2]]"
      pairNote @?= take maximumLengthCounterexampleNoteCharacters fullPairNote
      length pairNote @?= maximumLengthCounterexampleNoteCharacters
      pairVerification <- verificationBatchFromReceipts
        [pairNeutral, pairCandidate]
      pairAssociated <- expectLengthSpinePairPostVerificationWithin
        $ assessVerifiedLengthSpinePairCandidatesWithPolicy pairPolicy
            pairContract pairVerification
      sealed <- case lengthSpinePairPostVerificationSealedBatch
          pairAssociated of
        Nothing -> assertFailure
          "current product recursive assessment bypassed occurrence sealing"
            >> error "unreachable"
        Just retained -> pure retained
      postVerificationBatchCandidates sealed @?=
        lengthSpinePairPostVerificationCandidates pairAssociated
      pairAssociatedRanking <-
        expectLengthSpinePairPostVerificationRanking pairAssociated
      map rankedLengthSpinePairCandidateOriginalIndex
          (lengthSpinePairRankingCandidates pairAssociatedRanking) @?= [0, 1]
      map lengthCandidatePresentationNote
          (presentLengthSpinePairPostVerificationResult pairAssociated) @?=
        [Nothing, Just pairNote]
      doesFileExist (executable ++ ".events") >>= (@?= False)




assertCurrentLengthApplicableDomainScopedRoutes :: IO ()
assertCurrentLengthApplicableDomainScopedRoutes = do
  identity <- buildOneInputLengthRankingCandidate
  (pairCandidate, _) <- buildLengthSpinePairRankingFixture
  neutral <- syntheticLengthRankingCandidate
    "recursive-piecewise-branching-neutral"
  pureGate <- newIORef 0
  let pureContract = strictRelationalPositiveAffineQuotientScalarContract
        scalarBooleanFiniteUnionOneInputPrecondition $ LengthTruth True
      delayedPure = pureContract
        { leanLengthContractSource =
            delayedLengthTestValueWithGate pureGate 150000
            $ leanLengthContractSource pureContract
        }
      scalarEvaluationContract =
        strictRelationalPositiveAffineQuotientScalarContract
          scalarBooleanFiniteUnionEvaluationFailurePrecondition
          $ LengthTruth True
      pairEvaluationContract =
        strictRelationalPositiveAffineQuotientPairContract
          pairBooleanFiniteUnionEvaluationFailurePrecondition
          $ LengthTruth True
      scalarCandidates = [identity, identity]
      expectScalarSessionFailure label ranking = do
        map rankedLengthCandidateAssessment
            (lengthRankingCandidates ranking) @?=
          replicate (length $ lengthRankingCandidates ranking) Unassessed
        failure <- case lengthRankingFailure ranking of
          Nothing -> assertFailure
            (label ++ " retained no recursive piecewise-affine failure")
            >> error "unreachable"
          Just retained -> pure retained
        case lengthRankingFailureClass failure of
          LengthRankingLiveSessionFailed _ -> pure ()
          failureClass -> assertFailure
            $ label ++ " produced " ++ show failureClass
        lengthRankingFailureOriginalIndex failure @?= Nothing
        lengthRankingFailureCleanupIncomplete failure @?= False

  withTemporaryDirectory "leant-length-recursive-piecewise-scoped-pure"
    $ \root -> do
      let executable = root </> "missing-z3"
      (policy, _) <-
        expectCurrentApplicableDomainPolicy
        $ currentApplicableDomainScalarDocument
            executable 50
      ranking <- expectLengthRankingWithin
        "current scalar recursive pure scoped deadline"
        $ rankVerifiedLengthCandidatesWithPolicy policy delayedPure [identity]
      assertScalarUsableWorkExpiry
        "current scalar recursive pure scoped deadline" ranking
      doesFileExist (executable ++ ".events") >>= (@?= False)
  readIORef pureGate >>= (@?= 1)

  withTemporaryDirectory "leant-length-recursive-piecewise-failures"
    $ \root -> do
      let executable = root </> "missing-z3"
          scalarFailureDocument = setJsonField
            ["evaluation", "intermediateValueBits"] (Json.JInt 1)
            $ currentApplicableDomainScalarDocument
                executable 2000
      (scalarPolicy, _) <-
        expectCurrentApplicableDomainPolicy
          scalarFailureDocument
      scalar <- expectLengthRankingWithin
        "current scalar recursive admitted evaluation failure"
        $ rankVerifiedLengthCandidatesWithPolicy scalarPolicy
            scalarEvaluationContract [neutral, identity]
      map rankedLengthCandidateAssessment
          (lengthRankingCandidates scalar) @?= [Unassessed, Unassessed]
      scalarFailure <- case lengthRankingFailure scalar of
        Nothing -> assertFailure
          "current scalar recursive discarded admitted evaluation failure"
            >> error "unreachable"
        Just retained -> pure retained
      case lengthRankingFailureClass scalarFailure of
        LengthRankingApplicableDomainValidationFailed
            (Djex.LengthApplicableDomainAssignmentEvaluationRejected 0 _) ->
          pure ()
        failureClass -> assertFailure
          $ "current scalar recursive evaluation route produced "
            ++ show failureClass
      lengthRankingFailureOriginalIndex scalarFailure @?= Just 1
      lengthRankingFailureCleanupIncomplete scalarFailure @?= False

      let pairFailureDocument = setJsonField
            ["evaluation", "intermediateValueBits"] (Json.JInt 1)
            $ currentApplicableDomainPairDocument
                executable 2000
      (pairPolicy, _) <-
        expectCurrentApplicableDomainPolicy
          pairFailureDocument
      pair <- expectRight =<<
        rankVerifiedLengthSpinePairCandidatesWithPolicy pairPolicy
          pairEvaluationContract [pairCandidate, pairCandidate]
      map rankedLengthSpinePairCandidateAssessment
          (lengthSpinePairRankingCandidates pair) @?=
        [LengthSpinePairUnassessed, LengthSpinePairUnassessed]
      pairFailure <- case lengthSpinePairRankingFailure pair of
        Nothing -> assertFailure
          "current product recursive discarded admitted evaluation failure"
            >> error "unreachable"
        Just retained -> pure retained
      case lengthSpinePairRankingFailureClass pairFailure of
        LengthSpinePairRankingApplicableDomainValidationFailed
            (Djex.LengthSpinePairApplicableDomainAssignmentEvaluationRejected
              0 _) -> pure ()
        failureClass -> assertFailure
          $ "current product recursive evaluation route produced "
            ++ show failureClass
      lengthSpinePairRankingFailureOriginalIndex pairFailure @?= Just 0
      lengthSpinePairRankingFailureCleanupIncomplete pairFailure @?= False

      let scalarInvariant =
            LengthRankingApplicableDomainValidationFailed
              Djex.LengthApplicableDomainInternalEnumerationInvariant
          pairInvariant =
            LengthSpinePairRankingApplicableDomainValidationFailed
              Djex.LengthSpinePairApplicableDomainInternalEnumerationInvariant
      scalarInvariant @?=
        LengthRankingApplicableDomainValidationFailed
          Djex.LengthApplicableDomainInternalEnumerationInvariant
      pairInvariant @?=
        LengthSpinePairRankingApplicableDomainValidationFailed
          Djex.LengthSpinePairApplicableDomainInternalEnumerationInvariant
      _ <- evaluate $ length $ show scalarInvariant
      _ <- evaluate $ length $ show pairInvariant
      doesFileExist (executable ++ ".events") >>= (@?= False)

  withTemporaryDirectory "leant-length-recursive-piecewise-cap-misses"
    $ \root -> do
      let executable = root </> "missing-z3"
          base =
            currentApplicableDomainScalarDocument
              executable 2000
          capCases =
            [ ( "input cap"
              , withCurrentApplicableDomainLimit
                  "maximumInputs" 0 base
              )
            , ( "branch cap"
              , withCurrentApplicableDomainLimit
                  "maximumGeneratedBranches" 0 base
              )
            , ( "rule cap"
              , withCurrentApplicableDomainLimit
                  "maximumRulesPerBranch" 0 base
              )
            , ( "closure-inspection cap"
              , withCurrentApplicableDomainLimit
                  "maximumClosureInspectionsPerBranch" 0 base
              )
            , ( "retained-box cap"
              , withCurrentApplicableDomainLimit
                  "maximumRetainedBoxes" 0 base
              )
            , ( "maximum-value admission cap"
              , setJsonField ["evaluation", "assignmentValueBits"]
                  (Json.JInt 0) base
              )
            , ( "assignment-visit cap"
              , withCurrentApplicableDomainLimit
                  "maximumAssignmentVisits" 0 base
              )
            , ( "unique-assignment cap"
              , withCurrentApplicableDomainLimit
                  "maximumAssignments" 0 base
              )
            ]
      mapM_ (\(label, document) -> do
          (policy, _) <-
            expectCurrentApplicableDomainPolicy
              document
          ranking <- expectLengthRankingWithin
            ("current scalar recursive ordinary " ++ label)
            $ rankVerifiedLengthCandidatesWithPolicy policy pureContract
                [identity]
          expectScalarSessionFailure
            ("current scalar recursive ordinary " ++ label) ranking)
        capCases
      doesFileExist (executable ++ ".events") >>= (@?= False)

  supported <- descriptorBoundExecveCheckLaunchPubliclyReachable
  if not supported
    then pure ()
    else do
      withFakeLengthSolver "healthy" $ \executable -> do
        (scalarPolicy, _) <-
          expectCurrentApplicableDomainPolicy
          $ currentApplicableDomainScalarDocument
              executable 2000
        scalar <- expectLengthRankingWithin
          "current scalar recursive live route"
          $ rankVerifiedLengthCandidatesWithPolicy scalarPolicy
              usableWorkScalarLiveContract scalarCandidates
        map rankedLengthCandidateAssessment
            (lengthRankingCandidates scalar) @?=
          [Heuristic Djex.SolverSatisfiable, Heuristic Djex.SolverSatisfiable]
        assertFakeLengthQueryEvents [0, 1] [] =<<
          BS.readFile (executable ++ ".events")

      withFakeLengthSolver "hang" $ \executable -> do
        (policy, _) <-
          expectCurrentApplicableDomainPolicy
          $ currentApplicableDomainScalarDocument
              executable 400
        ranking <- expectLengthRankingWithin
          "current scalar recursive opener timeout"
          $ rankVerifiedLengthCandidatesWithPolicy policy
              usableWorkScalarLiveContract [identity]
        assertScalarUsableWorkExpiry
          "current scalar recursive scoped opener" ranking
        events <- BS.readFile $ executable ++ ".events"
        assertFakeLengthQueryEvents [] [] events
        assertBool "current scalar recursive did not reach the hanging image"
          $ BS.pack "EVENT hang " `BS.isInfixOf` events

      withFakeLengthSolver "query-hang-status" $ \executable -> do
        (policy, _) <-
          expectCurrentApplicableDomainPolicy
          $ currentApplicableDomainPairDocument
              executable 600
        ranking <- expectRight =<<
          rankVerifiedLengthSpinePairCandidatesWithPolicy policy
            usableWorkPairLiveContract [pairCandidate]
        assertPairUsableWorkExpiry
          "current product recursive scoped query" ranking
        events <- BS.readFile $ executable ++ ".events"
        assertFakeLengthQueryEvents [0] [] events
        assertBool
          "current product recursive query did not expire in status phase"
          $ BS.pack "EVENT query-hang " `BS.isInfixOf` events

      withFakeLengthSolver "wrong-echo" $ \executable -> do
        (policy, _) <-
          expectCurrentApplicableDomainPolicy
          $ currentApplicableDomainScalarDocument
              executable 2000
        ranking <- expectLengthRankingWithin
          "current scalar recursive nondeadline session failure"
          $ rankVerifiedLengthCandidatesWithPolicy policy
              usableWorkScalarLiveContract scalarCandidates
        expectScalarSessionFailure
          "current scalar recursive nondeadline session failure" ranking

      withFakeLengthSolver "query-stale-prewrite" $ \executable -> do
        let document = setJsonField ["execution", "artifactPolicy"]
              (Json.JStr "input-values-after-satisfiable")
              $ currentApplicableDomainScalarDocument
                  executable 2000
        (policy, _) <-
          expectCurrentApplicableDomainPolicy
            document
        ranking <- expectLengthRankingWithin
          "current scalar recursive query failure"
          $ rankVerifiedLengthCandidatesWithPolicy policy
              usableWorkScalarLiveContract scalarCandidates
        map rankedLengthCandidateAssessment
            (lengthRankingCandidates ranking) @?= [Unassessed, Unassessed]
        failure <- case lengthRankingFailure ranking of
          Nothing -> assertFailure
            "current scalar recursive discarded its query failure"
            >> error "unreachable"
          Just retained -> pure retained
        lengthRankingFailureClass failure @?=
          LengthRankingLiveQueryFailed
            Djex.LengthSMTLibLiveQueryProtocolRejected
        lengthRankingFailureOriginalIndex failure @?= Just 0
        lengthRankingFailureCleanupIncomplete failure @?= False
        assertFakeLengthQueryEvents [0] [] =<<
          BS.readFile (executable ++ ".events")


lengthRankingTests :: TestTree
lengthRankingTests = testGroup "checked Length behavioral ranking"
  [ testCase "sanitize every pure preparation refusal without forcing payloads"
      assertLengthPreparationRefusalClasses
  , testCase "admit the exact bound and reject a cyclic maximum-plus-one"
      assertLengthRankingInputBound
  , testCase "leave an all-ineligible batch unassessed without opening"
      assertLengthRankingAllIneligible
  , testCase "keep sat, unsat, and unknown heuristic statuses neutral"
      assertLengthRankingNeutralStatuses
  , testCase
      "stably demote replayed counterexamples without pruning or reassociation"
      assertLengthRankingCounterexampleDemotion
  , testCase
      "replay the latest exact counterexample input before another Z3 query"
      assertLengthRankingCounterexampleSeedReplay
  , testCase
      "run Z3 when the latest counterexample input has another arity"
      assertLengthRankingCounterexampleSeedArityMismatch
  , testCase
      "retain four exact counterexample vectors in promoted MRU order"
      assertLengthRankingCounterexampleSeedMRU
  , testCase
      "try equally applicable counterexample seeds newest first"
      assertLengthRankingCounterexampleSeedNewestFirst
  , testCase
      "derive every replay hit from the later query's result and provider basis"
      assertLengthRankingCounterexampleSeedFreshReceipt
  , testCase
      "leave the counterexample seed bank unchanged for heuristic assessments"
      assertLengthRankingCounterexampleSeedHeuristicIsolation
  , testCase
      "apply the caller's evaluation limits to every seed replay attempt"
      assertLengthRankingCounterexampleSeedEvaluationLimits
  , testCase
      "probe query-owned origins after MRU misses and compact live ordinals"
      assertLengthRankingOriginProbeOrdering
  , testCase
      "atomically reset an indexed origin-probe evaluation failure"
      assertLengthRankingOriginProbeAtomicFallback
  , testCase
      "reset earlier live and seed-hit assessments after a later live failure"
      assertLengthRankingAtomicFallback
  , testCase
      "independently validate exact input boxes after unsat only"
      assertLengthRankingInputBoxValidation
  , testCase
      "compose and present directly bounded applicable domains before Z3"
      assertLengthRankingApplicableDomainComposition
  , testCase
      "atomically reset an indexed admitted applicable-domain failure"
      assertLengthRankingApplicableDomainAtomicFailure
  , testCase
      "retain counterexample-only MRU state across bounded positives"
      assertLengthRankingInputBoxSeedIsolation
  , testCase
      "prefer non-vacuous positives after unchanged serial assessment"
      assertLengthRankingNonVacuousPositivePreference
  , testCase
      "keep vacuous positives neutral and preserve fallback associations"
      assertLengthRankingPositivePreferenceSafety
  , testCase
      "atomically reset bounded evidence after an input-box rejection"
      assertLengthRankingInputBoxAtomicFallback
  , testCase
      "adapt ranking only through a validated post-verification permutation"
      assertLengthPostVerificationAdapter
  , lengthRankingConfigurationTests
  ]

lengthRankingConfigurationTests :: TestTree
lengthRankingConfigurationTests = testGroup "explicit ranking policy"
  [ testCase
      "reject a PATH-resolvable relative executable before later poison"
      assertLengthRankingConfigurationRelativePath
  , testCase "reject a malformed explicit SHA-256 pin"
      assertLengthRankingConfigurationDigest
  , testCase "enforce explicit execution admission limits"
      assertLengthRankingConfigurationExecutionLimits
  , testCase "reject explicit evaluation limits after execution validation"
      assertLengthRankingConfigurationEvaluationLimits
  , testCase
      "match the direct runner for all-ineligible input without discovery"
      assertLengthRankingPolicyAllIneligible
  , testCase "match the direct runner for healthy and failing live rankings"
      assertLengthRankingPolicyLiveEquivalence
  , testCase "reuse one sealed solver policy with request-owned contracts"
      assertLengthRankingPolicyContractSeparation
  , testCase
      "compose origin and input-box builders commutatively without mutation"
      assertLengthRankingOriginProbePolicyComposition
  , testCase
      "compose positive ordering independently and leave the base immutable"
      assertLengthRankingPositivePreferencePolicyComposition
  , testCase
      "keep base policy disabled and match explicit input-box policy"
      assertLengthRankingInputBoxPolicyEquivalence
  , lengthRankingConfigurationFileTests
  ]

lengthRankingConfigurationFileTests :: TestTree
lengthRankingConfigurationFileTests = testGroup
  "current bounded ranking configuration file"
  [ testCase "decode and activate order-invariant scalar and product files"
      assertLengthRankingConfigurationFileActivation
  , testCase "apply format, domain, root, decimal, and digest precedence"
      assertLengthRankingConfigurationFileSchemaPrecedence
  , testCase "validate execution before evaluation before contract syntax"
      assertLengthRankingConfigurationFileValidationPrecedence
  , testCase "decode and activate without opening the configured executable"
      assertLengthRankingConfigurationFileNoOpen
  , testCase "reject unknown, missing, and mistyped fields at every object"
      assertLengthRankingConfigurationFileObjectSchema
  , testCase "admit operational caps exactly and reject maximum plus one"
      assertLengthRankingConfigurationFileOperationalCaps
  , testCase "decode every Length syntax constructor and reject bad shapes"
      assertLengthRankingConfigurationFileSyntaxShapes
  , testCase "enforce bounded contract syntax and provider associations"
      assertLengthRankingConfigurationFileSyntaxBounds
  , testCase "match the explicit policy live runner"
      assertLengthRankingConfigurationFileLiveEquivalence
  , testCase "keep paths, digests, fields, tags, and names out of Show errors"
      assertLengthRankingConfigurationFileShowRedaction
  , lengthContractFileTests
  , lengthRankingConfigurationFileAcquisitionTests
  , lengthAssessmentIntegrationTests
  ]

lengthContractFileTests :: TestTree
lengthContractFileTests = testGroup
  "one-shot bounded Length contract file"
  [ lengthSynthInlineWhereTests
  , testCase "parse explicit command paths without opening Lean goal syntax"
      assertLengthSynthCommandParsing
  , testCase "decode the one current scalar and binary-product grammar"
      assertLengthContractFileCurrentGrammar
  , testCase "close the current root, nested grammar, caps, and legacy shapes"
      assertLengthContractFileCurrentSchema
  , testCase "admit and acquire current scalar and product selections"
      assertLengthContractFileAcquisition
  ]

lengthSynthInlineWhereTests :: TestTree
lengthSynthInlineWhereTests = testGroup
  "active inline Length where profiles"
  [ testCase "parse and resolve concise scalar defaults"
      assertLengthSynthNativeScalarForm
  , testCase "parse and resolve concise product defaults"
      assertLengthSynthNativePairForm
  , testCase "observe every translated List argument in source order"
      assertLengthSynthNativeRoleDefaults
  , testCase "fail closed on unsupported concise target shapes"
      assertLengthSynthNativeTargetRefusals
  , testCase "own only the exact concise command envelope"
      assertLengthSynthNativeCommandBoundary
  , testCase "retain bounded parser and result-domain refusals"
      assertLengthSynthNativeClauseRefusals
  , testCase "parse and project the exact scalar form"
      assertLengthSynthInlineScalarForm
  , testCase "parse and project the exact binary-product form"
      assertLengthSynthInlinePairForm
  , testCase "leave every established command result unchanged"
      assertLengthSynthInlineLegacyIsolation
  , testCase "diagnose missing and invalid model fields exactly"
      assertLengthSynthInlineModelErrors
  , testCase "diagnose missing and malformed input fields exactly"
      assertLengthSynthInlineInputErrors
  , testCase "diagnose missing where clauses and delimiters exactly"
      assertLengthSynthInlineWhereErrors
  , testCase "require explicit filter and reject explicit rank"
      assertLengthSynthInlineFilterRequirement
  , testCase "reject every noncanonical option permutation"
      assertLengthSynthInlineOptionPermutations
  , testCase "reject every repeated owned option"
      assertLengthSynthInlineOptionRepetitions
  , testCase "reject file and inline contracts in both apparent orders"
      assertLengthSynthInlineContractExclusion
  , testCase "keep longer lookalikes and opaque-goal options unowned"
      assertLengthSynthInlineExactOwnership
  , testCase "admit arg0, arg1, arg7, and source-ordered gaps"
      assertLeanLengthWhereInputAcceptance
  , testCase "reject empty, malformed, duplicate, and descending inputs"
      assertLeanLengthWhereInputRefusals
  , testCase "bound arg8 and a hostile digit run productively and exactly"
      assertLeanLengthWhereInputBound
  , testCase "slice separator whitespace and retain exact UTF-8 byte offsets"
      assertLeanLengthWhereClauseBytes
  , testCase "expand physical roles and compact arg2 to contract input1"
      assertLeanLengthWhereRoleCompaction
  , testCase "retain an explicitly observed but unused physical input"
      assertLeanLengthWhereUnusedObservedInput
  , testCase "separate omitted, out-of-range, and arity-limit refusals"
      assertLeanLengthWhereResolutionRefusals
  , testCase "reject scalar and pair result namespaces nominally"
      assertLeanLengthWhereResultDomains
  , testCase "keep raw plans and sources positional, opaque, and instance-free"
      assertLeanLengthWhereOpacity
  , testCase "pin Main precedence, arity, and command-context lifetime"
      assertLeanLengthWhereRuntimeArchitecture
  ]

assertLengthSynthNativeScalarForm :: IO ()
assertLengthSynthNativeScalarForm = do
  let source =
        "--where List.length result = List.length arg0 -- " ++
        "List Nat -> List Nat"
  command <- expectLengthSynthNativeInlineCommand source
  lengthSynthNativeInlineCommandGoal command @?= "List Nat -> List Nat"
  resolved <- resolveLengthSynthNativeInlineCommand
    (nativeParsedGoal $ FArr nativeListFragment nativeListFragment)
    command
  resolved @?= inlineScalarSelection [LengthObservedSpine]
    (LengthEqual
      (LengthVariable LengthResult)
      (LengthVariable $ LengthInput 0))

assertLengthSynthNativePairForm :: IO ()
assertLengthSynthNativePairForm = do
  let source =
        "--where List.length result.1 + List.length result.2 = " ++
        "2 * List.length arg0 -- " ++
        "List Nat -> Prod (List Nat) (List Nat)"
  command <- expectLengthSynthNativeInlineCommand source
  lengthSynthNativeInlineCommandGoal command @?=
    "List Nat -> Prod (List Nat) (List Nat)"
  resolved <- resolveLengthSynthNativeInlineCommand
    (nativeParsedGoal $ FArr nativeListFragment
      $ FLeanProd nativeListFragment nativeListFragment)
    command
  resolved @?= inlinePairSelection [LengthObservedSpine]
    (Djex.LengthEqual
      (Djex.LengthSum
        [ Djex.LengthVariable $ Djex.LengthSpinePairResult
            Djex.LengthSpinePairFirst
        , Djex.LengthVariable $ Djex.LengthSpinePairResult
            Djex.LengthSpinePairSecond
        ])
      (Djex.LengthScale 2
        $ Djex.LengthVariable $ Djex.LengthSpinePairInput 0))

assertLengthSynthNativeRoleDefaults :: IO ()
assertLengthSynthNativeRoleDefaults = do
  let target = FAll True "u" $ FInst "inst" $ FArr nativeListFragment
        $ FArr (FAtom False "Nat")
        $ FArr nativeListFragment nativeListFragment
      source =
        "--where List.length result = List.length arg2 + " ++
        "List.length arg0 -- Goal"
  resolved <- expectLengthSynthNativeInlineSelection
