resolveLengthSynthInlineCommand
  :: Natural
  -> LengthSynthInlineCommand
  -> IO LeanLengthContractSelection
resolveLengthSynthInlineCommand arity command = do
  source <- expectLeanLengthWhereSource
    $ lengthSynthInlineCommandWherePlan command
  case resolveLeanLengthWhereSource arity source of
    Left failure -> assertFailure
      ("unexpected inline Length resolution refusal: " ++ show failure)
        >> error "unreachable"
    Right selection -> pure selection

expectLengthSynthInlineSelection
  :: Natural
  -> String
  -> IO LeanLengthContractSelection
expectLengthSynthInlineSelection arity source =
  expectLengthSynthInlineCommand source >>=
    resolveLengthSynthInlineCommand arity

assertLengthSynthInlineResolutionError
  :: LeanLengthWhereSourceError
  -> Natural
  -> String
  -> IO ()
assertLengthSynthInlineResolutionError expected arity source = do
  command <- expectLengthSynthInlineCommand source
  parsed <- expectLeanLengthWhereSource
    $ lengthSynthInlineCommandWherePlan command
  case resolveLeanLengthWhereSource arity parsed of
    Left actual -> actual @?= expected
    Right _ -> assertFailure
      $ "inline Length source resolved; expected " ++ show expected

inlineScalarSelection
  :: [LengthTargetArgumentRole]
  -> LengthFormula LengthContractVariable
  -> LeanLengthContractSelection
inlineScalarSelection roles postcondition =
  LeanLengthScalarContractSelection LeanLengthContract
    { leanLengthContractSpine = inlineLengthListSpine
    , leanLengthContractTargetArgumentRoles = roles
    , leanLengthContractCandidateCasePolicy =
        LeanLengthExactSpineZeroStepV1
    , leanLengthContractSource = LengthContractSource
        { lengthContractPrecondition = LengthTruth True
        , lengthContractPostcondition = postcondition
        }
    , leanLengthContractProviderLaws = []
    }

inlinePairSelection
  :: [LengthTargetArgumentRole]
  -> Djex.LengthFormula Djex.LengthSpinePairContractVariable
  -> LeanLengthContractSelection
inlinePairSelection roles postcondition =
  LeanLengthSpinePairContractSelection LeanLengthSpinePairContract
    { leanLengthSpinePairContractSpine = inlineLengthListSpine
    , leanLengthSpinePairContractTargetArgumentRoles = roles
    , leanLengthSpinePairContractCandidateCasePolicy =
        LeanLengthExactSpineZeroStepV1
    , leanLengthSpinePairContractSource = Djex.LengthSpinePairContractSource
        { Djex.lengthSpinePairContractPrecondition = Djex.LengthTruth True
        , Djex.lengthSpinePairContractPostcondition = postcondition
        }
    , leanLengthSpinePairContractProviderLaws = []
    }

inlineLengthListSpine :: LeanLengthSpineIdentity
inlineLengthListSpine = LeanLengthSpineIdentity
  { leanLengthSpineFamilyName = "List"
  , leanLengthSpineZeroConstructorName = "List.nil"
  , leanLengthSpineStepConstructorName = "List.cons"
  }

assertLengthSynthCommandParsing :: IO ()
assertLengthSynthCommandParsing = do
  let command behavior path goal = Right LengthSynthCommand
        { lengthSynthCommandBehaviorMode = behavior
        , lengthSynthCommandContractPath = path
        , lengthSynthCommandGoal = goal
        }
  parseLengthSynthCommand "List Nat -> List Nat" @?=
    command LengthBehaviorRank Nothing "List Nat -> List Nat"
  parseLengthSynthCommand " --behavior-mode rank -- List Nat " @?=
    command LengthBehaviorRank Nothing "List Nat"
  parseLengthSynthCommand "--behavior-mode filter -- List Nat" @?=
    command LengthBehaviorFilter Nothing "List Nat"
  parseLengthSynthCommand
      " --behavior-mode filter --length-contract /tmp/my contract.json -- \
      \List Nat -- List Nat " @?=
    command LengthBehaviorFilter (Just "/tmp/my contract.json")
      "List Nat -- List Nat"
  -- A contract alone retains the established ranking behavior.
  parseLengthSynthCommand "--length-contract /tmp/request.json --" @?=
    command LengthBehaviorRank (Just "/tmp/request.json") ""

  mapM_ (\source -> parseLengthSynthCommand source @?= Left
      LengthSynthCommandBehaviorModeMissing)
    ["--behavior-mode", "--behavior-mode -- List Nat"]
  parseLengthSynthCommand "--behavior-mode prune -- List Nat" @?= Left
    LengthSynthCommandBehaviorModeInvalid
  parseLengthSynthCommand
      "--behavior-mode --length-contract /tmp/request.json -- List Nat" @?=
    Left LengthSynthCommandBehaviorModeInvalid
  mapM_ (\source -> parseLengthSynthCommand source @?= Left
      LengthSynthCommandDelimiterMissing)
    [ "--behavior-mode filter List Nat"
    , "--behavior-mode rank --- List Nat"
    , "--behavior-mode filter --behavior-mode rank -- List Nat"
    , "--length-contract /tmp/request.json List Nat"
    , "--length-contract /tmp/request.json --behavior-mode filter List Nat"
    ]
  mapM_ (\source -> parseLengthSynthCommand source @?= Left
      LengthSynthCommandContractPathMissing)
    [ "--length-contract -- List Nat"
    , "--length-contract --behavior-mode filter -- List Nat"
    , "--behavior-mode filter --length-contract -- List Nat"
    ]
  parseLengthSynthCommand
      "--length-contract /tmp/request.json --behavior-mode filter -- List Nat"
    @?= Left LengthSynthCommandBehaviorModeMustPrecedeContract
  parseLengthSynthCommand
      "--behavior-mode filter --length-contract /tmp/request.json \
      \--behavior-mode rank -- List Nat" @?=
    Left LengthSynthCommandBehaviorModeMustPrecedeContract

  -- Exact option tokens are recognized only at the start. Longer lookalikes
  -- and option-looking tokens inside an ordinary Lean goal remain opaque.
  mapM_ (\goal -> parseLengthSynthCommand goal @?=
      command LengthBehaviorRank Nothing goal)
    [ "--length-contractual"
    , "--behavior-model filter -- List Nat"
    , "--behavior-mode=filter -- List Nat"
    , "List Nat --behavior-mode filter --length-contract ignored -- Bool"
    ]

  productive <- timeout 1000000 $ evaluate $ parseLengthSynthCommand
    $ "--behavior-mode filter --length-contract /tmp/request.json"
        ++ replicate 131072 ' ' ++ "not-a-delimiter"
  productive @?= Just (Left LengthSynthCommandDelimiterMissing)

assertLengthContractFileCurrentGrammar :: IO ()
assertLengthContractFileCurrentGrammar = do
  assertLengthHandoffUsesUnifiedSealers
  lengthContractFileFormat @?=
    Text.pack "leant-finite-list-spine-length-contract"
  lengthContractFileJsonLimits @?= lengthRankingConfigurationFileJsonLimits
  let scalarRoles = ["unobserved-target", "observed-spine"]
      scalarPrecondition = jsonLengthEqual
        (jsonLengthModulo 2 $ jsonLengthInput 0)
        (jsonLengthLiteral 1)
      scalarPostcondition = jsonLengthEqual jsonLengthResult
        $ jsonLengthQuotient 3
        $ jsonLengthSum
            [ jsonLengthInput 0
            , jsonLengthModulo 2 $ jsonLengthInput 1
            ]
      scalarLaw = jsonLengthProviderLaw "Demo.mapList"
        ["unobserved", "spine"]
        $ jsonLengthQuotient 5 $ jsonLengthArgument 1
      scalarContractValue = addJsonField []
        ("candidateCasePolicy", Json.JStr "cases-rejected")
        $ jsonRoleAwareLengthContract scalarRoles scalarPrecondition
            scalarPostcondition [scalarLaw]
      scalarDocument = lengthContractFileFixture
        "scalar" scalarContractValue
      expectedScalar = LeanLengthContract
        { leanLengthContractSpine = LeanLengthSpineIdentity
            { leanLengthSpineFamilyName = "List"
            , leanLengthSpineZeroConstructorName = "List.nil"
            , leanLengthSpineStepConstructorName = "List.cons"
            }
        , leanLengthContractTargetArgumentRoles =
            [LengthUnobservedTarget, LengthObservedSpine]
        , leanLengthContractCandidateCasePolicy = LeanLengthCasesRejected
        , leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthEqual
                (LengthModulo 2 $ LengthVariable $ LengthInput 0)
                (LengthLiteral 1)
            , lengthContractPostcondition = LengthEqual
                (LengthVariable LengthResult)
                (LengthQuotient 3 $ LengthSum
                  [ LengthVariable $ LengthInput 0
                  , LengthModulo 2 $ LengthVariable $ LengthInput 1
                  ])
            }
        , leanLengthContractProviderLaws =
            [ LeanLengthProviderLaw
                { leanLengthProviderLawName = "Demo.mapList"
                , leanLengthProviderLawArgumentRoles =
                    [LengthUnobservedArgument, LengthSpineArgument]
                , leanLengthProviderLawTransfer = LengthQuotient 5
                    $ LengthVariable $ Djex.LengthProviderArgument 1
                }
            ]
        }
      pairRoles = ["observed-spine", "unobserved-target"]
      pairPrecondition = jsonLengthEqual
        (jsonLengthModulo 2 $ jsonLengthInput 0)
        (jsonLengthLiteral 1)
      pairPostcondition = jsonLengthAll
        [ jsonLengthEqual jsonLengthSpinePairResultFirst
            $ jsonLengthInput 0
        , jsonLengthEqual jsonLengthSpinePairResultSecond
            $ jsonLengthQuotient 3
            $ jsonLengthSum
                [ jsonLengthInput 0
                , jsonLengthModulo 2 $ jsonLengthInput 1
                ]
        ]
      pairLaw = jsonLengthProviderLaw "Demo.mapPair"
        ["unobserved", "spine"]
        $ jsonLengthQuotient 5 $ jsonLengthArgument 1
      pairContractValue = jsonLengthSpinePairContract pairRoles
        "exact-spine-zero-step-v1" pairPrecondition pairPostcondition [pairLaw]
      pairDocument = lengthContractFileFixture
        "binary-product" pairContractValue
      expectedPair = lengthSpinePairFixtureContract
        { leanLengthSpinePairContractTargetArgumentRoles =
            [LengthObservedSpine, LengthUnobservedTarget]
        , leanLengthSpinePairContractCandidateCasePolicy =
            LeanLengthExactSpineZeroStepV1
        , leanLengthSpinePairContractSource =
            Djex.LengthSpinePairContractSource
              { Djex.lengthSpinePairContractPrecondition =
                  Djex.LengthEqual
                    (Djex.LengthModulo 2
                      $ Djex.LengthVariable $ Djex.LengthSpinePairInput 0)
                    (Djex.LengthLiteral 1)
              , Djex.lengthSpinePairContractPostcondition = Djex.LengthAll
                  [ Djex.LengthEqual
                      (Djex.LengthVariable $ Djex.LengthSpinePairResult
                        Djex.LengthSpinePairFirst)
                      (Djex.LengthVariable $ Djex.LengthSpinePairInput 0)
                  , Djex.LengthEqual
                      (Djex.LengthVariable $ Djex.LengthSpinePairResult
                        Djex.LengthSpinePairSecond)
                      (Djex.LengthQuotient 3 $ Djex.LengthSum
                        [ Djex.LengthVariable $ Djex.LengthSpinePairInput 0
                        , Djex.LengthModulo 2
                            $ Djex.LengthVariable
                            $ Djex.LengthSpinePairInput 1
                        ])
                  ]
              }
        , leanLengthSpinePairContractProviderLaws =
            [ LeanLengthProviderLaw
                { leanLengthProviderLawName = "Demo.mapPair"
                , leanLengthProviderLawArgumentRoles =
                    [LengthUnobservedArgument, LengthSpineArgument]
                , leanLengthProviderLawTransfer = Djex.LengthQuotient 5
                    $ Djex.LengthVariable $ Djex.LengthProviderArgument 1
                }
            ]
        }
  expectLengthContractFile scalarDocument >>=
    (@?= LeanLengthScalarContractSelection expectedScalar)
  expectLengthContractFile (reverseJsonObjectFields scalarDocument) >>=
    (@?= LeanLengthScalarContractSelection expectedScalar)
  expectLengthSpinePairContract pairDocument >>= (@?= expectedPair)
  expectLengthSpinePairContract
    (reverseJsonObjectFields pairDocument) >>= (@?= expectedPair)

  scalarStartup <- startupSelection "scalar" scalarContractValue
  pairStartup <- startupSelection "binary-product" pairContractValue
  scalarStartup @?= LeanLengthScalarContractSelection expectedScalar
  pairStartup @?= LeanLengthSpinePairContractSelection expectedPair
 where
  startupSelection domain contract = do
    disabled <- expectLengthAssessmentConfigurationFile
      $ setJsonField ["contract"] contract
      $ setJsonField ["rankingDomain"] (Json.JStr domain)
      $ lengthRankingConfigurationFileFixture
          (fixtureAbsolutePath "/tmp/not-opened-z3") Nothing
    case activateLengthAssessmentConfiguration
        PermitUnpinnedExecutable disabled of
      Left failure -> assertFailure
        ("startup parity activation failed: " ++ show failure)
          >> error "unreachable"
      Right (_, selection) -> pure selection

assertLengthContractFileCurrentSchema :: IO ()
assertLengthContractFileCurrentSchema = do
  let baseContract = jsonCurrentLengthContract
        (jsonLengthTruth True)
        (jsonLengthEqual jsonLengthResult $ jsonLengthLiteral 0)
        []
      base = lengthContractFileFixture "scalar" baseContract
      nested failure = LengthContractFileContractRejected failure
      contractFailure failure = assertLengthContractFileError
        $ nested failure
      missing field = nested $ LengthRankingConfigurationMissingField
        LengthRankingConfigurationContractObject field
      syntax phase failure = nested
        $ LengthRankingConfigurationSyntaxRejected phase failure

  assertLengthContractFileError
    (LengthContractFileMissingRootField LengthContractFileFormatField)
    $ deleteJsonField ["format"] base
  assertLengthContractFileError
    (LengthContractFileFieldTypeMismatch
      LengthContractFileFormatField LengthContractFileStringValue)
    $ setJsonField ["format"] (Json.JBool False) base
  assertLengthContractFileError LengthContractFileUnsupportedFormat
    $ setJsonField ["format"] (Json.JStr "private-format") base
  assertLengthContractFileError
    (LengthContractFileMissingRootField
      LengthContractFileRankingDomainField)
    $ deleteJsonField ["rankingDomain"] base
  assertLengthContractFileError
    (LengthContractFileFieldTypeMismatch
      LengthContractFileRankingDomainField LengthContractFileStringValue)
    $ setJsonField ["rankingDomain"] (Json.JInt 1) base
  assertLengthContractFileError
    (LengthContractFileFieldValueRejected
      LengthContractFileRankingDomainField)
    $ setJsonField ["rankingDomain"] (Json.JStr "private-domain") base
  assertLengthContractFileError LengthContractFileUnexpectedRootField
    $ addJsonField [] ("private-root", Json.JNull)
    $ deleteJsonField ["contract"] base
  assertLengthContractFileError
    (LengthContractFileMissingRootField LengthContractFileContractField)
    $ deleteJsonField ["contract"] base
  assertLengthContractFileError
    (LengthContractFileFieldTypeMismatch
      LengthContractFileContractField LengthContractFileObjectValue)
    $ setJsonField ["contract"] (Json.JStr "private-contract") base

  -- Historical version roots fail through the deterministic current
  -- validation order: the missing domain wins for an untouched v1 root,
  -- while adding a current domain exposes the old version member as
  -- unexpected (including the former product-v6 value).
  let legacyV1 = Json.JObj
        [ ("format", Json.JStr $ Text.unpack lengthContractFileFormat)
        , ("version", Json.JInt 1)
        , ("contract", baseContract)
        ]
  assertLengthContractFileError
    (LengthContractFileMissingRootField
      LengthContractFileRankingDomainField)
    legacyV1
  assertLengthContractFileError LengthContractFileUnexpectedRootField
    $ addJsonField [] ("version", Json.JInt 6) base

  mapM_ (\(field, name) -> assertLengthContractFileError (missing field)
      $ deleteJsonField ["contract", name] base)
    [ (LengthRankingConfigurationSpineField, "spine")
    , ( LengthRankingConfigurationTargetArgumentRolesField
      , "targetArgumentRoles"
      )
    , ( LengthRankingConfigurationCandidateCasePolicyField
      , "candidateCasePolicy"
      )
    , (LengthRankingConfigurationPreconditionField, "precondition")
    , (LengthRankingConfigurationPostconditionField, "postcondition")
    , (LengthRankingConfigurationProviderLawsField, "providerLaws")
    ]
  contractFailure
    (LengthRankingConfigurationFieldTypeMismatch
      LengthRankingConfigurationTargetArgumentRolesField
      LengthRankingConfigurationArrayValue)
    $ setJsonField ["contract", "targetArgumentRoles"]
        (Json.JStr "private-role") base
  contractFailure
    (LengthRankingConfigurationFieldValueRejected
      LengthRankingConfigurationTargetArgumentRolesField)
    $ setJsonField ["contract", "targetArgumentRoles"]
        (Json.JArr [Json.JStr "private-role"]) base
  contractFailure
    (LengthRankingConfigurationFieldValueRejected
      LengthRankingConfigurationCandidateCasePolicyField)
    $ setJsonField ["contract", "candidateCasePolicy"]
        (Json.JStr "private-policy") base

  let withRoles roles = setJsonField ["contract", "targetArgumentRoles"]
        (Json.JArr $ map Json.JStr roles) base
  _ <- expectLengthContractFile $ withRoles
    $ replicate 8 "unobserved-target"
  assertLengthContractFileError
    (nested $ LengthRankingConfigurationPolicyLimitExceeded
      LengthRankingConfigurationTargetArgumentRolesField 8 9)
    $ withRoles $ replicate 9 "unobserved-target"

  let maximumLaws = replicate 256
        $ jsonLengthProviderLaw "Demo.zeroList" [] (jsonLengthLiteral 0)
      withLaws laws = setJsonField ["contract", "providerLaws"]
        (Json.JArr laws) base
  _ <- expectLengthContractFile $ withLaws maximumLaws
  assertLengthContractFileError
    (nested $ LengthRankingConfigurationPolicyLimitExceeded
      LengthRankingConfigurationProviderLawsField 256 257)
    $ withLaws $ maximumLaws ++
        [jsonLengthProviderLaw "extra" [] $ jsonLengthLiteral 0]

  let poisonedChild = Json.JArr [Json.JStr "private-child"]
      withPre expression = setJsonField ["contract", "precondition"]
        (jsonLengthEqual expression $ jsonLengthLiteral 0) base
      withPost expression = setJsonField ["contract", "postcondition"]
        (jsonLengthEqual jsonLengthResult expression) base
      maximumDivisor = 2 ^ (256 :: Int) - 1
  _ <- expectLengthContractFile
    $ withPre $ jsonLengthQuotient maximumDivisor $ jsonLengthLiteral 0
  assertLengthContractFileError
    (syntax LengthRankingConfigurationPreconditionSyntax
      LengthRankingConfigurationQuotientDivisorZero)
    $ withPre $ jsonLengthQuotient 0 poisonedChild
  assertLengthContractFileError
    (syntax LengthRankingConfigurationPreconditionSyntax
      LengthRankingConfigurationModuloDivisorZero)
    $ withPre $ jsonLengthModulo 0 poisonedChild
  assertLengthContractFileError
    (syntax LengthRankingConfigurationPostconditionSyntax
      $ LengthRankingConfigurationSyntaxLimitExceeded
          LengthRankingConfigurationLiteralBits 256 257)
    $ withPost $ jsonLengthModulo (2 ^ (256 :: Int)) poisonedChild

  let pairBase = lengthContractFileFixture "binary-product"
        $ jsonLengthSpinePairContract ["observed-spine"]
            "cases-rejected" (jsonLengthTruth True)
            (jsonLengthEqual jsonLengthSpinePairResultFirst
              $ jsonLengthInput 0) []
  assertLengthContractFileError
    (syntax LengthRankingConfigurationPostconditionSyntax
      $ LengthRankingConfigurationTagArityMismatch 1 0)
    $ setJsonField ["contract", "postcondition"]
        (jsonLengthEqual (Json.JArr [Json.JStr "result"])
          $ jsonLengthLiteral 0) pairBase

  let privateName = "private-Lean-provider-name"
      privateTag = "private-syntax-tag"
      rejected = withLaws
        [jsonLengthProviderLaw privateName []
          $ Json.JArr [Json.JStr privateTag]]
  case decodeLengthContractFile
      $ encodeLengthRankingConfigurationFile rejected of
    Right _ -> assertFailure "private contract fixture unexpectedly decoded"
    Left failure -> do
      assertBool "contract error exposed a private provider name"
        $ not $ privateName `isInfixOf` show failure
      assertBool "contract error exposed a private syntax tag"
        $ not $ privateTag `isInfixOf` show failure
      assertBool "contract error exposed a private domain"
        $ not $ "private-domain" `isInfixOf` show failure

-- | An absolute-by-construction fixture path on the current platform.  The
-- pure admission tests below never open it; POSIX keeps the historical
-- spelling and Windows maps it under a drive so the path-absoluteness gate
-- admits it and the check under test is the one that fires.
fixtureAbsolutePath :: FilePath -> FilePath
fixtureAbsolutePath posix
  | os == "mingw32" = "C:" ++ map (\c -> if c == '/' then '\\' else c) posix
  | otherwise = posix

assertLengthContractFileAcquisition :: IO ()
assertLengthContractFileAcquisition = do
  lengthContractFileDefaultTimeoutMilliseconds @?= 5000
  lengthContractFileMaximumPathCharacters @?= 4096
  lengthContractFileMaximumTimeoutMilliseconds @?= 60000
  lengthContractFileLoadMaximumBytes @?=
    boundedJsonMaximumTotalBytes lengthContractFileJsonLimits
  case mkLengthContractFileRequest $ LengthContractFileSource
      "relative-contract.json" (error "relative path forced timeout") of
    Left LengthContractFilePathNotAbsolute -> pure ()
    Left failure -> assertFailure $ "unexpected relative contract failure: "
      ++ show failure
    Right _ -> assertFailure "relative contract path was admitted"
  case mkLengthContractFileRequest $ LengthContractFileSource
      (fixtureAbsolutePath "/tmp/request.json") 0 of
    Left LengthContractFileTimeoutNotPositive -> pure ()
    Left failure -> assertFailure $ "unexpected contract timeout failure: "
      ++ show failure
    Right _ -> assertFailure "zero contract timeout was admitted"
  case mkLengthContractFileRequest $ LengthContractFileSource
      ('/' : replicate 4096 'x') (error "oversized path forced timeout") of
    Left (LengthContractFilePathCharacterLimitExceeded 4096 4097) -> pure ()
    Left failure -> assertFailure $ "unexpected contract path limit: " ++
      show failure
    Right _ -> assertFailure "oversized contract path was admitted"
  case mkLengthContractFileRequest $ LengthContractFileSource
      (fixtureAbsolutePath "/tmp/request.json") 60001 of
    Left (LengthContractFileTimeoutLimitExceeded 60000 60001) -> pure ()
    Left failure -> assertFailure $ "unexpected contract timeout limit: " ++
      show failure
    Right _ -> assertFailure "oversized contract timeout was admitted"
  if os == "mingw32"
    then pure ()
    else withTemporaryDirectory "leant-one-shot-contract" $ \root -> do
      let path = root </> "request.json"
          malformedPath = root </> "malformed.json"
          missingPath = root </> "missing.json"
          oversizedPath = root </> "oversized.json"
          scalarDocument = lengthContractFileFixture "scalar"
            $ jsonCurrentLengthContract
            (jsonLengthEqual
              (jsonLengthModulo 2 $ jsonLengthLiteral 3)
              $ jsonLengthLiteral 1)
            (jsonLengthEqual jsonLengthResult $ jsonLengthLiteral 0)
            [ jsonLengthProviderLaw "Demo.zeroList" []
                $ jsonLengthLiteral 0
            , jsonLengthProviderLaw "Demo.oneList" []
                $ jsonLengthLiteral 1
            ]
          pairDocument = lengthContractFileFixture "binary-product"
            $ jsonLengthSpinePairContract ["observed-spine"]
                "cases-rejected" (jsonLengthTruth True)
                (jsonLengthAll
                  [ jsonLengthEqual jsonLengthSpinePairResultFirst
                      $ jsonLengthInput 0
                  , jsonLengthEqual jsonLengthSpinePairResultSecond
                      $ jsonLengthQuotient 2 $ jsonLengthInput 0
                  ]) []
      expectedScalar <- expectLengthContractFile scalarDocument
      expectedPair <- expectLengthContractFile pairDocument
      ByteString.writeFile path $ encodeLengthRankingConfigurationFile
        scalarDocument
      request <- expectLengthContractFileRequest path
      loaded <- loadLengthContractFile request
      loaded @?= Right expectedScalar
      ByteString.writeFile path $ encodeLengthRankingConfigurationFile
        pairDocument
      pairLoaded <- loadLengthContractFile request
      pairLoaded @?= Right expectedPair
      ByteString.writeFile malformedPath $ BS.pack "{"
      malformedRequest <- case mkLengthContractFileRequest
          $ LengthContractFileSource malformedPath 1000 of
        Left failure -> assertFailure (show failure) >> error "unreachable"
        Right admitted -> pure admitted
      malformed <- loadLengthContractFile malformedRequest
      case malformed of
        Left failure -> do
          case lengthContractFileLoadErrorClass failure of
            LengthContractFileDecodeRejected _ -> pure ()
            failureClass -> assertFailure $ "unexpected malformed contract " ++
              "failure class: " ++ show failureClass
          lengthContractFileLoadCleanupIncomplete failure @?= False
          assertBool "contract load error exposed its source path"
            $ not $ malformedPath `isInfixOf` show failure
        Right _ -> assertFailure "malformed contract file decoded"
      missingRequest <- expectLengthContractFileRequest missingPath
      missing <- loadLengthContractFile missingRequest
      case missing of
        Left failure -> do
          lengthContractFileLoadErrorClass failure @?=
            LengthContractFileOpenFailed
          lengthContractFileLoadCleanupIncomplete failure @?= False
          assertBool "contract open error exposed its source path"
            $ not $ missingPath `isInfixOf` show failure
        Right _ -> assertFailure "missing contract file loaded"
      ByteString.writeFile oversizedPath $ ByteString.replicate
        (fromIntegral lengthContractFileLoadMaximumBytes + 1) 32
      oversizedRequest <- expectLengthContractFileRequest oversizedPath
      oversized <- loadLengthContractFile oversizedRequest
      case oversized of
        Left failure -> do
          lengthContractFileLoadErrorClass failure @?=
            LengthContractFileByteLimitExceeded
              lengthContractFileLoadMaximumBytes
              (lengthContractFileLoadMaximumBytes + 1)
          lengthContractFileLoadCleanupIncomplete failure @?= False
        Right _ -> assertFailure "oversized contract file loaded"

expectLengthContractFileRequest
  :: FilePath
  -> IO LengthContractFileRequest
expectLengthContractFileRequest path = case mkLengthContractFileRequest
    $ LengthContractFileSource path 1000 of
  Left failure -> assertFailure ("contract request admission failed: " ++
    show failure) >> error "unreachable"
  Right request -> pure request

lengthContractFileFixture
  :: String
  -> Json.JValue
  -> Json.JValue
lengthContractFileFixture domain contract = Json.JObj
  [ ("format", Json.JStr $ Text.unpack lengthContractFileFormat)
  , ("rankingDomain", Json.JStr domain)
  , ("contract", contract)
  ]

expectLengthContractFile
  :: Json.JValue
  -> IO LeanLengthContractSelection
expectLengthContractFile document =
  case decodeLengthContractFile
      $ encodeLengthRankingConfigurationFile document of
    Left failure -> assertFailure ("contract file was rejected: " ++
      show failure) >> error "unreachable"
    Right selection -> pure selection

expectLengthScalarContract :: Json.JValue -> IO LeanLengthContract
expectLengthScalarContract document = do
  selection <- expectLengthContractFile document
  case selection of
    LeanLengthScalarContractSelection contract -> pure contract
    LeanLengthSpinePairContractSelection _ -> assertFailure
      "scalar contract document selected the binary-product domain"
        >> error "unreachable"

expectLengthSpinePairContract
  :: Json.JValue
  -> IO LeanLengthSpinePairContract
expectLengthSpinePairContract document = do
  selection <- expectLengthContractFile document
  case selection of
    LeanLengthSpinePairContractSelection contract -> pure contract
    LeanLengthScalarContractSelection _ -> assertFailure
      "binary-product contract document selected the scalar domain"
        >> error "unreachable"

assertLengthContractFileError
  :: LengthContractFileError
  -> Json.JValue
  -> IO ()
assertLengthContractFileError expected document =
  case decodeLengthContractFile
      $ encodeLengthRankingConfigurationFile document of
    Left failure -> failure @?= expected
    Right _ -> assertFailure $ "expected contract-file failure: " ++
      show expected

lengthRankingConfigurationFileAcquisitionTests :: TestTree
lengthRankingConfigurationFileAcquisitionTests = testGroup
  "bounded explicit file acquisition"
  [ testCase "admit finite paths and timeouts in a productive fixed order"
      assertLengthRankingConfigurationFileRequestAdmission
  , testCase "load and decode one explicitly admitted regular file"
      assertLengthRankingConfigurationFileAcquisition
  , testCase "reject non-regular and final-component symlink sources"
      assertLengthRankingConfigurationFileSourceTypes
  , testCase "probe the exact byte ceiling and cap the excess observation"
      assertLengthRankingConfigurationFileAcquisitionByteLimit
  , testCase "sanitize acquisition failures without losing their phase"
      assertLengthRankingConfigurationFileAcquisitionRedaction
  ]

lengthAssessmentIntegrationTests :: TestTree
lengthAssessmentIntegrationTests = testGroup
  "explicit Length assessment integration"
  [ testCase "keep the disabled mode an exact lazy identity"
      assertLengthAssessmentDisabled
  , testCase "reject one-shot contracts before file IO when disabled"
      assertLengthAssessmentExplicitDisabled
  , testCase
      "dispatch rank and filter through startup and one-shot scalar requests"
      assertLengthAssessmentScalarFilterDispatch
  , testCase
      "dispatch startup and one-shot product filters without sticky state"
      assertLengthAssessmentSpinePairFilterDispatch
  , testCase
      "refill through five rejections to seven ordered survivors in one batch"
      assertLengthAssessmentFilterSurvivorRefill
  , testCase
      "scope one nominal context per established or inline command"
      assertLengthAssessmentMainCommandContext
  , testCase
      "separate bounded lane verification from command accumulation"
      assertLengthAssessmentMainLaneSeam
  , testCase
      "fold continuing lane outcomes in chronological attempt order"
      assertLengthAssessmentMainLaneAccumulation
  , testCase
      "finalize one chronological command accumulation exactly once"
      assertLengthAssessmentMainLaneFinalization
  , testCase
      "continue providers and classical retries after every nonterminal lane"
      assertLengthAssessmentMainLaneScheduling
  , testCase
      "scope parallel work to default structural engine or library pairs"
      assertLengthAssessmentMainParallelBaseline
  , testCase
      "keep progressive cursor policies and run receipts private"
      assertLengthAssessmentMainProgressiveDeclarations
  , testCase
      "advance one synthesis outcome through at most two assessed batches"
      assertLengthAssessmentMainCursorDriver
  , testCase
      "preserve mode-sensitive deadline ownership across classical routes"
      assertLengthAssessmentMainClassicalScheduling
  , testCase
      "gate normal diagnostics after aggregate behavioral handling"
      assertLengthAssessmentMainDiagnosticGates
  , testCase
      "authorize command-local filtering before contract path IO"
      assertLengthAssessmentMainCommandAdmission
  , testCase "admit setup before IO or activation"
      assertLengthAssessmentSetupAdmission
  , testCase "load one fixed contract and assess through the sealed adapter"
      assertLengthAssessmentConfigured
  , testCase "reuse one activated policy with command-local contracts"
      assertLengthAssessmentExplicitContracts
  , testCase
      "rank role-aware map requests including quotient without stickiness"
      assertLengthAssessmentRoleAwareMap
  , testCase
      "rank an exact zero-step case under both current case policies"
      assertLengthAssessmentExactSpineCase
  , testCase "preserve sealed callback order after a live failure"
      assertLengthAssessmentFailureFallback
  , testCase "bound and sanitize counterexample presentation"
      assertLengthCounterexamplePresentation
  , testCase
      "dispatch startup and one-shot products through one sealed policy"
      assertLengthAssessmentSpinePairDispatch
  , testCase
      "keep disabled selection requests lazy and pair projections disjoint"
      assertLengthAssessmentSpinePairDisabled
  ]

assertLengthHandoffUsesUnifiedSealers :: IO ()
assertLengthHandoffUsesUnifiedSealers = do
  source <- readFile "src/Leant/Synth/Length/Handoff.hs"
  let identifiers = words
        [ if isAlphaNum character || character == '_'
            || character == '\''
            then character
            else ' '
        | character <- source
        ]
      required =
        [ "sealLengthSessionWithInterpretationPolicy"
        , "sealLengthContractInSession"
        , "sealLengthTypedCandidateProblemInSession"
        ]
      forbidden =
        [ "sealLengthSession"
        , "sealRoleAwareLengthSession"
        , "sealExactSpineCaseLengthSession"
        , "sealLengthContractInContext"
        , "sealRoleAwareLengthContractInContext"
        , "sealLengthTypedCandidateProblem"
        , "sealRoleAwareLengthTypedCandidateProblem"
        , "sealExactSpineCaseLengthTypedCandidateProblem"
        ]
  mapM_ (\identifier -> assertBool
      ("production Handoff omitted unified sealer " ++ identifier)
      $ identifier `elem` identifiers) required
  mapM_ (\identifier -> assertBool
      ("production Handoff retained compatibility sealer " ++ identifier)
      $ identifier `notElem` identifiers) forbidden

assertLengthAssessmentDisabled :: IO ()
assertLengthAssessmentDisabled = do
  lengthAssessmentModeActivationPolicy disabledLengthAssessmentMode @?=
    Nothing
  verification <- syntheticPostVerificationBatch
    ["integration-disabled-first", "integration-disabled-second"]
  result <- assessLengthVerificationBatch
    disabledLengthAssessmentMode verification
  lengthAssessmentCandidates result @?= verifiedCandidateReceipts verification
  lengthAssessmentFailure result @?= Nothing
  assertBool "disabled Length assessment retained a ranking"
    $ isNothing $ lengthAssessmentRanking result
  map lengthCandidatePresentationText (presentLengthAssessment result) @?=
    ["integration-disabled-first", "integration-disabled-second"]
  map lengthCandidatePresentationNote (presentLengthAssessment result) @?=
    [Nothing, Nothing]
  assertBool "disabled Length assessment retained a configured result"
    $ isNothing $ lengthAssessmentPostVerificationResult result

  lazyResult <- assessLengthVerificationBatch disabledLengthAssessmentMode
    (error "disabled Length integration forced its verification batch")
  lengthAssessmentFailure lazyResult @?= Nothing
  assertBool "lazy disabled Length assessment retained a ranking"
    $ isNothing $ lengthAssessmentRanking lazyResult
  assertBool "lazy disabled Length assessment retained a configured result"
    $ isNothing $ lengthAssessmentPostVerificationResult lazyResult

assertLengthAssessmentExplicitDisabled :: IO ()
assertLengthAssessmentExplicitDisabled = do
  case authorizeExplicitLengthAssessmentRequest LengthBehaviorRank
      disabledLengthAssessmentMode of
    Left failure -> failure @?=
      LengthAssessmentExplicitContractRequiresActivatedPolicy
    Right _ -> assertFailure "disabled mode authorized a one-shot contract"
  case authorizeExplicitLengthAssessmentRequest LengthBehaviorFilter
      disabledLengthAssessmentMode of
    Left failure -> failure @?=
      LengthAssessmentFilteringRequiresActivatedPolicy
    Right _ -> assertFailure "disabled mode authorized a one-shot filter"
  case startupLengthAssessmentRequest LengthBehaviorFilter
      disabledLengthAssessmentMode of
    Left failure -> failure @?=
      LengthAssessmentFilteringRequiresActivatedPolicy
    Right _ -> assertFailure "disabled mode enabled startup filtering"
  disabledRequest <- expectRight $ startupLengthAssessmentRequest
    LengthBehaviorRank disabledLengthAssessmentMode
  lengthAssessmentRequestBehaviorMode disabledRequest @?=
    LengthBehaviorRank
  lazyResult <- assessLengthVerificationRequest disabledRequest
    (error "disabled command request forced its verification batch")
  lengthAssessmentFailure lazyResult @?= Nothing
  assertBool "disabled command request retained a ranking"
    $ isNothing $ lengthAssessmentRanking lazyResult

-- Inline profiles intentionally declare no provider laws.  These fixtures
-- therefore select only checked candidates whose sealed Djex authority is
-- provider-free, so the integration assertions exercise actual filtering
-- rather than preserve-on-preparation-refusal behavior.
buildInlineScalarSelectionFixture
  :: LeanLengthContract
  -> IO
      ( Verified DetailedVerificationVariant
      , Verified DetailedVerificationVariant
      )
buildInlineScalarSelectionFixture contract = do
  let sourceList = lengthSpinePairFixtureList
  candidates <- verifiedInlineLengthCandidates True []
    $ FArr sourceList sourceList
  let prepared =
        [ (verified, checkedLengthCandidateResult checked)
        | verified <- candidates
        , Right problem <- [prepareCheckedLengthProblem contract verified]
        , let checked = checkedLengthProblemCandidate problem
        , null $ checkedLengthCandidateUsedProviders checked
        ]
      input = LengthVariable $ LengthInput 0
      zero = LengthLiteral 0
      predecessor = LengthMonus input $ LengthLiteral 1
      exactResult offset = LengthIf (LengthEqual input zero) input
        $ LengthSum [LengthLiteral offset, predecessor]
  identity <- choose "exact identity" (exactResult 1) prepared
  incremented <- choose "exact positive-spine increment" (exactResult 2)
    prepared
  pure (identity, incremented)
 where
  choose label expected prepared = case
      [verified | (verified, actual) <- prepared, actual == expected] of
    verified : _ -> pure verified
    [] -> assertFailure
      ("provider-free inline scalar fixture lacked " ++ label ++ ": " ++
       show (map snd prepared)) >> error "unreachable"

buildInlineSpinePairSelectionFixture
  :: LeanLengthSpinePairContract
  -> IO
      ( Verified DetailedVerificationVariant
      , Verified DetailedVerificationVariant
      )
buildInlineSpinePairSelectionFixture contract = do
  candidates <- verifiedInlineLengthCandidates False []
    lengthSpinePairFixtureGoal
  let prepared =
        [ (verified, Djex.checkedLengthSpinePairCandidateResult checked)
        | verified <- candidates
        , Right problem <-
            [prepareCheckedLengthSpinePairProblem contract verified]
        , let checked = Djex.checkedLengthSpinePairProblemCandidate problem
        , null $ Djex.checkedLengthSpinePairCandidateUsedProviders checked
        ]
      input :: LengthExpression LengthContractVariable
      input = LengthVariable $ LengthInput 0
  duplicated <- choose "duplicated input"
    (Djex.LengthSpinePair input input) prepared
  inputAndZero <- choose "input and zero"
    (Djex.LengthSpinePair input $ LengthLiteral 0) prepared
  pure (duplicated, inputAndZero)
 where
  choose label expected prepared = case
      [verified | (verified, actual) <- prepared, actual == expected] of
    verified : _ -> pure verified
    [] -> assertFailure
      ("provider-free inline product fixture lacked " ++ label ++ ": " ++
       show (map snd prepared)) >> error "unreachable"

verifiedInlineLengthCandidates
  :: Bool
  -> [ProviderFrag]
  -> Frag
  -> IO [Verified DetailedVerificationVariant]
verifiedInlineLengthCandidates multiConstructorPatterns providers goal = do
  detailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      multiConstructorPatterns EngineExference 512 Set.empty providers goal
  groups <- case detailed of
    DetailedSynthCandidates retained _ -> pure retained
    other -> assertFailure
      ("provider-free inline fixture synthesis failed: " ++ show other)
        >> error "unreachable"
  batch <- verifyCandidateGroups 512 (const $ pure VariantAccepted)
    $ map detailedCandidateGroupVerificationVariants groups
  pure $ verifiedCandidateReceipts batch

assertLengthAssessmentScalarFilterDispatch :: IO ()
assertLengthAssessmentScalarFilterDispatch
  | os == "mingw32" = pure ()
  | otherwise = do
      (baseContract, scaled, identity) <- buildScaledProviderReplayFixture
      withTemporaryDirectory "leant-filter-command-scalar" $ \root -> do
        let executable = root </> "missing-z3"
            configurationPath = root </> "filter-command-scalar-config.json"
            contractPath = root </> "filter-command-scalar-contract.json"
            input = jsonLengthInput 0
            guardedDomain = jsonLengthAtMost
              (jsonLengthIf
                (jsonLengthAtMost input $ jsonLengthLiteral 2)
                input
                (jsonLengthLiteral 5))
              (jsonLengthLiteral 3)
            scalarContractValue expected = addJsonField []
              ("candidateCasePolicy", Json.JStr "cases-rejected")
              $ jsonRoleAwareLengthContract ["observed-spine"]
                  guardedDomain
                  (jsonLengthEqual jsonLengthResult expected)
              [ jsonLengthProviderLaw "Demo.scaleList" ["spine"]
                  $ jsonLengthScale 2 $ jsonLengthArgument 0
              ]
            inlineScalarContractValue expected = setJsonField
              ["candidateCasePolicy"]
              (Json.JStr "exact-spine-zero-step-v1")
              $ scalarContractValue expected
            configuration = setJsonField ["contract"]
              (scalarContractValue input)
              $ currentApplicableDomainScalarDocument executable 2000
            renderVerified = detailedVerificationVariantText
              . verifiedCandidate
            original = [scaled, identity]
        ByteString.writeFile configurationPath
          $ encodeLengthRankingConfigurationFile configuration
        loaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource configurationPath 1000
        mode <- case loaded of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right configured -> pure configured
        verification <- verificationBatchFromReceipts original

        rankRequest <- expectRight $ startupLengthAssessmentRequest
          LengthBehaviorRank mode
        lengthAssessmentRequestBehaviorMode rankRequest @?=
          LengthBehaviorRank
        ranked <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest rankRequest verification
        length (lengthAssessmentCandidates ranked) @?= length original
        sortOn id (map renderVerified $ lengthAssessmentCandidates ranked) @?=
          sortOn id (map renderVerified original)
        assertBool "rank request acquired scalar selection authority"
          $ isNothing $ lengthAssessmentSelectionResult ranked
        assertBool "rank request emitted rejection rows"
          $ null $ presentLengthAssessmentRejections ranked

        filterRequest <- expectRight $ startupLengthAssessmentRequest
          LengthBehaviorFilter mode
        lengthAssessmentRequestBehaviorMode filterRequest @?=
          LengthBehaviorFilter
        filtered <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest filterRequest verification
        lengthAssessmentFailure filtered @?= Nothing
        lengthAssessmentCandidates filtered @?= [identity]
        assertBool "scalar filter retained a ranking projection"
          $ isNothing $ lengthAssessmentRanking filtered
        assertBool "scalar filter retained a post-verification projection"
          $ isNothing $ lengthAssessmentPostVerificationResult filtered
        scalarResult <- case lengthAssessmentSelectionResult filtered of
          Nothing -> assertFailure "scalar filter lost its selection result"
            >> error "unreachable"
          Just selected -> pure selected
        lengthSelectionCandidates scalarResult @?= [identity]
        selected <- expectLengthSelectionSelected scalarResult
        rejected <- expectLengthSelectionRejected scalarResult
        map behaviorallySelectedVerified selected @?= [identity]
        map behaviorallyRejectedVerified rejected @?= [scaled]
        map lengthCandidatePresentationText
            (presentLengthAssessment filtered) @?=
          [renderVerified identity]
        case (rejected, presentLengthAssessmentRejections filtered) of
          ([removed], [presentation]) -> do
            lengthCandidateRejectionPresentationText presentation @?=
              renderVerified scaled
            lengthCandidateRejectionPresentationNote presentation @?=
              renderLengthSelectionRejectionNote
                (behaviorallyRejectedReason removed)
            assertBool "scalar rejection note lost its result association"
              $ "result spine length = 2" `isInfixOf`
                lengthCandidateRejectionPresentationNote presentation
          pair -> assertFailure $ "unexpected scalar rejection presentation: "
            ++ show (length $ fst pair, length $ snd pair)

        permission <- case authorizeExplicitLengthAssessmentRequest
            LengthBehaviorFilter mode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right authorized -> pure authorized
        let bottomContractRequest = explicitLengthAssessmentRequest permission
              (error "behavior projection forced its one-shot contract")
        lengthAssessmentRequestBehaviorMode bottomContractRequest @?=
          LengthBehaviorFilter
        ByteString.writeFile contractPath
          $ encodeLengthRankingConfigurationFile
          $ lengthContractFileFixture "scalar"
          $ scalarContractValue $ jsonLengthScale 2 input
        contractRequest <- expectLengthContractFileRequest contractPath
        loadedContract <- loadLengthContractFile contractRequest >>= either
          (\failure -> assertFailure (show failure) >> error "unreachable")
          pure
        let oneShotRequest = explicitLengthAssessmentRequest
              permission loadedContract
        lengthAssessmentRequestBehaviorMode oneShotRequest @?=
          LengthBehaviorFilter
        ByteString.writeFile contractPath $ BS.pack "{"
        oneShot <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest oneShotRequest verification
        lengthAssessmentCandidates oneShot @?= [scaled]
        assertBool "one-shot scalar filter used the pair projection"
          $ isNothing $ lengthAssessmentSpinePairSelectionResult oneShot

        inlineSelection <- expectLengthSynthInlineSelection 1
          $ scalarInlineLengthCommand "arg0"
              "len(result)=len(arg0)+min(len(arg0),1)"
              "List Nat -> List Nat"
        inlineContract <- case inlineSelection of
          LeanLengthScalarContractSelection contract -> pure contract
          LeanLengthSpinePairContractSelection _ -> assertFailure
            "scalar inline command resolved to a product contract"
              >> error "unreachable"
        (inlineIdentity, inlineIncremented) <-
          buildInlineScalarSelectionFixture inlineContract
        inlineVerification <- verificationBatchFromReceipts
          [inlineIdentity, inlineIncremented]
        whenDescriptorBoundExecveCheckLaunchPubliclyReachable $
          withFakeLengthSolver "healthy" $ \inlineExecutable -> do
            let inlineConfigurationPath = takeDirectory inlineExecutable </>
                  "filter-command-scalar-inline-config.json"
                inlineConfiguration = setJsonField ["contract"]
                  (inlineScalarContractValue input)
                  $ currentApplicableDomainScalarDocument
                      inlineExecutable 2000
            ByteString.writeFile inlineConfigurationPath
              $ encodeLengthRankingConfigurationFile inlineConfiguration
            inlineLoaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
              $ LengthRankingConfigurationFileSource
                  inlineConfigurationPath 1000
            inlineMode <- case inlineLoaded of
              Left failure -> assertFailure (show failure)
                >> error "unreachable"
              Right configured -> pure configured
            inlineStartupRequest <- expectRight $
              startupLengthAssessmentRequest LengthBehaviorFilter inlineMode
            inlineStartup <- expectLengthAssessmentWithin
              $ assessLengthVerificationRequest
                  inlineStartupRequest inlineVerification
            lengthAssessmentCandidates inlineStartup @?= [inlineIdentity]
            inlinePermission <- case authorizeExplicitLengthAssessmentRequest
                LengthBehaviorFilter inlineMode of
              Left failure -> assertFailure (show failure)
                >> error "unreachable"
              Right authorized -> pure authorized
            inline <- expectLengthAssessmentWithin
              $ assessLengthVerificationRequest
                  (explicitLengthAssessmentRequest
                    inlinePermission inlineSelection)
                  inlineVerification
            lengthAssessmentFailure inline @?= Nothing
            lengthAssessmentCandidates inline @?= [inlineIncremented]
            inlineResult <- case lengthAssessmentSelectionResult inline of
              Nothing -> assertFailure
                "inline scalar filter lost its selection result"
                  >> error "unreachable"
              Just selectedResult -> pure selectedResult
            inlineSelected <- expectLengthSelectionSelected inlineResult
            inlineRejected <- expectLengthSelectionRejected inlineResult
            map behaviorallySelectedVerified inlineSelected @?=
              [inlineIncremented]
            map behaviorallyRejectedVerified inlineRejected @?=
              [inlineIdentity]
            assertBool "inline scalar filter used the pair projection"
              $ isNothing $ lengthAssessmentSpinePairSelectionResult inline
            inlineRepeated <- expectLengthAssessmentWithin
              $ assessLengthVerificationRequest
                  inlineStartupRequest inlineVerification
            lengthAssessmentCandidates inlineRepeated @?= [inlineIdentity]

        -- The mode, contract, and replay bank are request-local: returning to
        -- the startup request must reproduce its original partition after a
        -- file-backed and inline command-local filter have run.
        repeated <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest filterRequest verification
        lengthAssessmentCandidates repeated @?= [identity]

        let maximumCandidates =
              Djex.defaultLengthSMTLibLiveSessionMaximumQueries
            oversizedCount = fromIntegral maximumCandidates + 1
        oversizedVerification <- verificationBatchFromReceipts
          $ replicate oversizedCount scaled
        preserved <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest filterRequest oversizedVerification
        case lengthAssessmentFailure preserved of
          Just (LengthAssessmentSelectionFailed
              (LengthSelectionPostVerificationFailed
                (LengthPostVerificationInputRejected
                  (LengthRankingInputLimitExceeded maximumValue observed)))) ->
                    (maximumValue, observed) @?=
                      (maximumCandidates, maximumCandidates + 1)
          failure -> assertFailure $ "unexpected filter admission failure: "
            ++ show failure
        lengthAssessmentCandidates preserved @?=
          verifiedCandidateReceipts oversizedVerification
        preservedResult <- case lengthAssessmentSelectionResult preserved of
          Nothing -> assertFailure
            "filter admission failure discarded its preserve-all result"
              >> error "unreachable"
          Just result -> pure result
        assertBool "filter admission failure exposed selected associations"
          $ isNothing $ lengthSelectionSelected preservedResult
        assertBool "filter admission failure exposed rejected associations"
          $ isNothing $ lengthSelectionRejected preservedResult
        length (presentLengthAssessment preserved) @?= oversizedCount
        length (take synthMaxShown $ presentLengthAssessment preserved) @?=
          synthMaxShown
        assertBool "filter admission failure emitted rejection rows"
          $ null $ presentLengthAssessmentRejections preserved

        allRejectedVerification <- verificationBatchFromReceipts original
        let guardedFormula = LengthAtMost
              (LengthIf
                (LengthAtMost
                  (LengthVariable $ LengthInput 0)
                  (LengthLiteral 2))
                (LengthVariable $ LengthInput 0)
                (LengthLiteral 5))
              (LengthLiteral 3)
            allRejectedContract = baseContract
              { leanLengthContractSource = LengthContractSource
                  { lengthContractPrecondition = guardedFormula
                  , lengthContractPostcondition = LengthEqual
                      (LengthVariable LengthResult) (LengthLiteral 99)
                  }
              }
        let allRejectedRequest = explicitLengthAssessmentRequest permission
              $ LeanLengthScalarContractSelection allRejectedContract
        allRejected <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest allRejectedRequest
              allRejectedVerification
        lengthAssessmentFailure allRejected @?= Nothing
        lengthAssessmentCandidates allRejected @?= []
        assertBool "all-rejected scalar filter exposed survivor rows"
          $ null $ presentLengthAssessment allRejected
        let rejectionRows = presentLengthAssessmentRejections allRejected
        map lengthCandidateRejectionPresentationText rejectionRows @?=
          map renderVerified original
        length rejectionRows @?= 2
        doesFileExist executable >>= (@?= False)
        doesFileExist (executable ++ ".events") >>= (@?= False)

assertLengthAssessmentFilterSurvivorRefill :: IO ()
assertLengthAssessmentFilterSurvivorRefill = do
  identity <- buildOneInputLengthRankingCandidate
  retained <- mapM
    (syntheticLengthRankingCandidate . ("refill-survivor-" ++) . show)
    [1 :: Int .. 7]
  let input = LengthVariable $ LengthInput 0
      contract = (lengthRankingContractWithObservedInputs 1 2)
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthAtMost
                (LengthLiteral 1) input
            , lengthContractPostcondition = LengthEqual
                (LengthVariable LengthResult) (LengthLiteral 2)
            }
        }
      candidatePrefix = replicate synthMaxShown identity ++ retained
      renderVerified = detailedVerificationVariantText . verifiedCandidate
  length candidatePrefix @?= synthMaxTried
  withFakeLengthSolver "healthy" $ \executable -> do
    base <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits
          (explicitLengthRankingExecutionSource executable Nothing
            Djex.LengthSMTLibInputValuesAfterSatisfiable)
          Djex.defaultLengthEvaluationLimitSource
    simplificationLimits <- explicitLengthInputBoxLimits 1 4
    let policy = enableLengthRankingCounterexampleSimplification
          simplificationLimits base
    verification <- verificationBatchFromReceipts candidatePrefix
    let original = verifiedCandidateReceipts verification
        (expectedRejected, expectedSelected) = splitAt synthMaxShown original
    result <- expectLengthSelectionWithin "survivor refill batch"
      $ selectVerifiedLengthCandidatesWithPolicy policy contract verification
    lengthSelectionFailure result @?= Nothing
    selected <- expectLengthSelectionSelected result
    rejected <- expectLengthSelectionRejected result
    lengthSelectionCandidates result @?= expectedSelected
    map behaviorallySelectedVerified selected @?= expectedSelected
    map behaviorallyRejectedVerified rejected @?= expectedRejected
    map (renderVerified . behaviorallySelectedVerified) selected @?=
      ["refill-survivor-" ++ show index | index <- [1 :: Int .. 7]]
    map (lengthSelectionRetentionClass . behaviorallySelectedRetention)
        selected @?=
      replicate 7 LengthSelectionPreparationRefused
    let rejectionEvidence = map behaviorallyRejectedReason rejected
        receipts = map lengthSelectionRejectionCounterexample
          rejectionEvidence
        simplifications = map
          lengthSelectionRejectionCounterexampleSimplification
          rejectionEvidence
    map Djex.validatedLengthCounterexampleInputs receipts @?=
      replicate synthMaxShown [1]
    map Djex.validatedLengthCounterexampleResult receipts @?=
      replicate synthMaxShown 1
    case simplifications of
      Just first : replayed -> do
        Djex.validatedLengthCounterexampleSimplificationOriginalInputs first
          @?= [3]
        Djex.validatedLengthCounterexampleSimplificationInputs first @?= [1]
        assertBool "later refill rejections did not reuse the MRU seed"
          $ all isNothing replayed
      other -> assertFailure $ "unexpected refill simplifications: "
        ++ show other
    assertFakeLengthQueryEvents [0] [0] =<<
      BS.readFile (executable ++ ".events")

assertLengthAssessmentSpinePairFilterDispatch :: IO ()
assertLengthAssessmentSpinePairFilterDispatch
  | os == "mingw32" = pure ()
  | otherwise = do
      (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
      withTemporaryDirectory "leant-filter-command-pair" $ \root -> do
        let executable = root </> "missing-z3"
            configurationPath = root </> "filter-command-pair-config.json"
            contractPath = root </> "filter-command-pair-contract.json"
            input = jsonLengthInput 0
            guardedDomain = jsonLengthAtMost
              (jsonLengthIf
                (jsonLengthAtMost input $ jsonLengthLiteral 2)
                input
                (jsonLengthLiteral 5))
              (jsonLengthLiteral 3)
            pairContract expected = jsonLengthSpinePairContract
              ["observed-spine"] "cases-rejected"
              guardedDomain
              (jsonLengthAll
                [ jsonLengthEqual jsonLengthSpinePairResultFirst
                    input
                , jsonLengthEqual jsonLengthSpinePairResultSecond
                    expected
                ])
              [ jsonLengthProviderLaw "Demo.zeroList" []
                  $ jsonLengthLiteral 0
              ]
            inlinePairContract expected = setJsonField
              ["candidateCasePolicy"]
              (Json.JStr "exact-spine-zero-step-v1")
              $ pairContract expected
            configuration = setJsonField ["contract"]
              (pairContract $ jsonLengthLiteral 0)
              $ currentApplicableDomainPairDocument executable 2000
            renderVerified = detailedVerificationVariantText
              . verifiedCandidate
            original = [duplicatedInput, inputAndZero]
        ByteString.writeFile configurationPath
          $ encodeLengthRankingConfigurationFile configuration
        loaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource configurationPath 1000
        mode <- case loaded of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right configured -> pure configured
        verification <- verificationBatchFromReceipts original
        startupRequest <- expectRight $ startupLengthAssessmentRequest
          LengthBehaviorFilter mode
        startup <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest startupRequest verification
        lengthAssessmentFailure startup @?= Nothing
        lengthAssessmentCandidates startup @?= [inputAndZero]
        assertBool "pair filter used the scalar selection projection"
          $ isNothing $ lengthAssessmentSelectionResult startup
        pairResult <- case lengthAssessmentSpinePairSelectionResult startup of
          Nothing -> assertFailure "pair filter lost its selection result"
            >> error "unreachable"
          Just selected -> pure selected
        pairRejected <- expectLengthSpinePairSelectionRejected pairResult
        map behaviorallyRejectedVerified pairRejected @?= [duplicatedInput]
        case (pairRejected, presentLengthAssessmentRejections startup) of
          ([removed], [presentation]) -> do
            lengthCandidateRejectionPresentationText presentation @?=
              renderVerified duplicatedInput
            lengthCandidateRejectionPresentationNote presentation @?=
              renderLengthSpinePairSelectionRejectionNote
                (behaviorallyRejectedReason removed)
          pair -> assertFailure $ "unexpected pair rejection presentation: "
            ++ show (length $ fst pair, length $ snd pair)

        permission <- case authorizeExplicitLengthAssessmentRequest
            LengthBehaviorFilter mode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right authorized -> pure authorized
        ByteString.writeFile contractPath
          $ encodeLengthRankingConfigurationFile
          $ lengthContractFileFixture "binary-product" $ pairContract input
        contractRequest <- expectLengthContractFileRequest contractPath
        loadedContract <- loadLengthContractFile contractRequest >>= either
          (\failure -> assertFailure (show failure) >> error "unreachable")
          pure
        ByteString.writeFile contractPath $ BS.pack "{"
        oneShot <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission loadedContract)
              verification
        lengthAssessmentCandidates oneShot @?= [duplicatedInput]
        assertBool "one-shot pair filter used the scalar projection"
          $ isNothing $ lengthAssessmentSelectionResult oneShot
        assertBool "one-shot pair filter lost the pair projection"
          $ isJust (lengthAssessmentSpinePairSelectionResult oneShot)

        inlineSelection <- expectLengthSynthInlineSelection 1
          $ pairInlineLengthCommand "arg0"
              ("len(result.first)+len(result.second)=" ++
               "2*len(arg0)")
              "List Nat -> Prod (List Nat) (List Nat)"
        inlineContract <- case inlineSelection of
          LeanLengthSpinePairContractSelection contract -> pure contract
          LeanLengthScalarContractSelection _ -> assertFailure
            "product inline command resolved to a scalar contract"
              >> error "unreachable"
        (inlineDuplicated, inlineInputAndZero) <-
          buildInlineSpinePairSelectionFixture inlineContract
        inlineVerification <- verificationBatchFromReceipts
          [inlineDuplicated, inlineInputAndZero]
        whenDescriptorBoundExecveCheckLaunchPubliclyReachable $
          withFakeLengthSolver "healthy" $ \inlineExecutable -> do
            let inlineConfigurationPath = takeDirectory inlineExecutable </>
                  "filter-command-pair-inline-config.json"
                inlineConfiguration = setJsonField ["contract"]
                  (inlinePairContract $ jsonLengthLiteral 0)
                  $ currentApplicableDomainPairDocument
                      inlineExecutable 2000
            ByteString.writeFile inlineConfigurationPath
              $ encodeLengthRankingConfigurationFile inlineConfiguration
            inlineLoaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
              $ LengthRankingConfigurationFileSource
                  inlineConfigurationPath 1000
            inlineMode <- case inlineLoaded of
              Left failure -> assertFailure (show failure)
                >> error "unreachable"
              Right configured -> pure configured
            inlineStartupRequest <- expectRight $
              startupLengthAssessmentRequest LengthBehaviorFilter inlineMode
            inlineStartup <- expectLengthAssessmentWithin
              $ assessLengthVerificationRequest
                  inlineStartupRequest inlineVerification
            lengthAssessmentCandidates inlineStartup @?=
              [inlineInputAndZero]
            inlinePermission <- case authorizeExplicitLengthAssessmentRequest
                LengthBehaviorFilter inlineMode of
              Left failure -> assertFailure (show failure)
                >> error "unreachable"
              Right authorized -> pure authorized
            inline <- expectLengthAssessmentWithin
              $ assessLengthVerificationRequest
                  (explicitLengthAssessmentRequest
                    inlinePermission inlineSelection)
                  inlineVerification
            lengthAssessmentFailure inline @?= Nothing
            lengthAssessmentCandidates inline @?= [inlineDuplicated]
            assertBool "inline pair filter used the scalar projection"
              $ isNothing $ lengthAssessmentSelectionResult inline
            inlineResult <- case
                lengthAssessmentSpinePairSelectionResult inline of
              Nothing -> assertFailure
                "inline pair filter lost its selection result"
                  >> error "unreachable"
              Just selectedResult -> pure selectedResult
            inlineSelected <-
              expectLengthSpinePairSelectionSelected inlineResult
            inlineRejected <-
              expectLengthSpinePairSelectionRejected inlineResult
            map behaviorallySelectedVerified inlineSelected @?=
              [inlineDuplicated]
            map behaviorallyRejectedVerified inlineRejected @?=
              [inlineInputAndZero]
            inlineRepeated <- expectLengthAssessmentWithin
              $ assessLengthVerificationRequest
                  inlineStartupRequest inlineVerification
            lengthAssessmentCandidates inlineRepeated @?=
              [inlineInputAndZero]

        repeated <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest startupRequest verification
        lengthAssessmentCandidates repeated @?= [inputAndZero]
        doesFileExist executable >>= (@?= False)
        doesFileExist (executable ++ ".events") >>= (@?= False)

mainSourceSection :: String -> String -> [String] -> [String]
mainSourceSection start end =
  takeWhile (not . isInfixOf end) . dropWhile (not . isInfixOf start)

mainSourcePositions :: String -> [String] -> [Int]
mainSourcePositions fragment section =
  [ index
  | (index, line) <- zip [0 :: Int ..] section
  , fragment `isInfixOf` line
  ]

expectMainSourcePosition :: String -> String -> [String] -> IO Int
expectMainSourcePosition boundary fragment section =
  case mainSourcePositions fragment section of
    index : _ -> pure index
    [] -> assertFailure
      ("Main " ++ boundary ++ " omitted " ++ show fragment)
        >> error "unreachable"

assertMainSourceContains :: String -> [String] -> String -> IO ()
assertMainSourceContains boundary section fragment =
  assertBool ("Main " ++ boundary ++ " omitted " ++ show fragment)
    $ fragment `isInfixOf` unwords (words $ unlines section)

assertLengthAssessmentMainCommandContext :: IO ()
assertLengthAssessmentMainCommandContext = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let sourceText = unlines sourceLines
      importSection = mainSourceSection
        "import Leant.Synth.Length.Integration"
        "import Leant.Synth.Length.Command" sourceLines
      stateSection = mainSourceSection
        "data ReplState = ReplState"
        "-- | Backend-local identifiers" sourceLines
      commandSection = mainSourceSection
        "cmdSynth :: St -> String -> IO ()"
        "-- | Select one command-local assessment authority" sourceLines
      runSection = mainSourceSection
        "synthRun :: LengthAssessmentRequest"
        "-- | Activate one already authorized" sourceLines
      explicitInlineSection = mainSourceSection
        "-- | Activate one already authorized"
        "-- | Activate the concise source" sourceLines
      nativeInlineSection = mainSourceSection
        "-- | Activate the concise source"
        "-- | Translate once and preserve" sourceLines
      translationSection = mainSourceSection
        "-- | Translate once and preserve"
        "-- | Count only source arrows" sourceLines
      retrySection = mainSourceSection
        "-- | Auto-bound variables get"
        "-- | Whether an error text names this marker universe" sourceLines
      goSection = mainSourceSection
        "synthGo assessmentContext st args retriedVars goal parsed = do"
        "synthGo' assessmentContext st args retriedVars goal parsed = do"
        sourceLines
      schedulerSection = mainSourceSection
        "synthGo' assessmentContext st args retriedVars goal parsed = do"
        "loadSynthProviders ::" sourceLines
      classicalSection = mainSourceSection
        "synthClassical assessmentContext commandDeadline st goal parsed accumulation ="
        "verifySynthLane assessmentContext groupLimit st goal notes groups ="
        sourceLines
  mapM_ (assertMainSourceContains "Length Integration import" importSection)
    [ "LengthAssessmentContext"
    , "assessLengthVerificationContext"
    , "lengthAssessmentContextBehaviorMode"
    , "withLengthAssessmentRequestContext"
    ]
  mapM_ (assertMainSourceContains "detailed cursor import" sourceLines)
    [ "DetailedSynthCursor"
    , "DetailedSynthCursorError (..)"
    , "DetailedSynthCursorStep (..)"
    , "advanceDetailedSynthCursor"
    , "forceDetailedSynthCursorStep"
    , "startDetailedSynthCursor"
    ]
  mapM_ (\fragment -> assertBool
      ("Main retained the request-only Integration surface " ++ show fragment)
      $ not $ fragment `isInfixOf` sourceText)
    [ "assessLengthVerificationRequest"
    , "lengthAssessmentRequestBehaviorMode"
    ]
  assertMainSourceContains "rank-2 command context" sourceLines
    "{-# LANGUAGE RankNTypes #-}"
  length (mainSourcePositions
      "withLengthAssessmentRequestContext assessmentRequest" sourceLines)
    @?= 1
  length (mainSourcePositions
      "withLengthAssessmentRequestContext"
      $ dropWhile (not . isInfixOf "synthRun ::") sourceLines) @?= 3
  length (mainSourcePositions
      ":: LengthAssessmentContext command" sourceLines)
    @?= 7

  assertMainSourceContains "command entrance" commandSection
    "synthRun assessmentRequest st args goal"
  assertBool "cmdSynth created a second assessment context"
    $ not ("withLengthAssessmentRequestContext" `isInfixOf`
      unlines commandSection)
  contextOpen <- expectMainSourcePosition "synthRun context"
    "withLengthAssessmentRequestContext assessmentRequest"
      runSection
  translation <- expectMainSourcePosition "synthRun context"
    "translateSynthGoalWithRetry st goal" runSection
  direct <- expectMainSourcePosition "synthRun context"
    "$ synthGo assessmentContext st args" runSection
  assertBool "the established context did not enclose translation and retry"
    $ contextOpen < translation && translation < direct

  inlineTranslation <- expectMainSourcePosition "explicit inline context"
    "translateSynthGoalWithRetry st goal" explicitInlineSection
  inlineResolution <- expectMainSourcePosition "explicit inline context"
    "case resolveLeanLengthWhereSource" explicitInlineSection
  inlineContext <- expectMainSourcePosition "explicit inline context"
    "withLengthAssessmentRequestContext" explicitInlineSection
  inlineScheduler <- expectMainSourcePosition "explicit inline context"
    "synthGo assessmentContext st args retriedVars" explicitInlineSection
  length (mainSourcePositions
      "withLengthAssessmentRequestContext" explicitInlineSection) @?= 1
  assertBool "the explicit inline context opened before translation or resolution"
    $ inlineTranslation < inlineResolution
      && inlineResolution < inlineContext
      && inlineContext < inlineScheduler

  nativeTranslation <- expectMainSourcePosition "concise inline context"
    "translateSynthGoalWithRetry st goal" nativeInlineSection
  nativeResolution <- expectMainSourcePosition "concise inline context"
    "case resolveLeanNativeLengthWhereSource" nativeInlineSection
  nativeContext <- expectMainSourcePosition "concise inline context"
    "withLengthAssessmentRequestContext" nativeInlineSection
  nativeScheduler <- expectMainSourcePosition "concise inline context"
    "synthGo assessmentContext st args retriedVars" nativeInlineSection
  length (mainSourcePositions
      "withLengthAssessmentRequestContext" nativeInlineSection) @?= 1
  assertBool "the concise inline context opened before translation or resolution"
    $ nativeTranslation < nativeResolution
      && nativeResolution < nativeContext
      && nativeContext < nativeScheduler

  assertMainSourceContains "generalized translation retry" translationSection
    "synthUniverseRetry st goal errors continuation"

  retryTranslation <- expectMainSourcePosition "universe retry context"
    "outcome <- translateGoal st wrapped" retrySection
  retryScheduler <- expectMainSourcePosition "universe retry context"
    "continuation (Just wrapVars) wrapped parsed"
      retrySection
  assertBool "the universe retry stopped forwarding its continuation"
    $ retryTranslation < retryScheduler
  assertBool "the universe retry reacquired a nominal command context"
    $ not $ "assessmentContext" `isInfixOf` unlines retrySection
  assertMainSourceContains "synthGo context forwarding" goSection
    "synthGo' assessmentContext st args retriedVars goal parsed"
  mapM_ (assertMainSourceContains "constructive context" schedulerSection)
    [ "runSynthLaneCursor assessmentContext"
    , "ordinarySynthLaneCursorPolicy assessmentContext laneEngine limits"
    , "synthClassical assessmentContext runDeadline st goal parsed"
    ]
  length (mainSourcePositions
      "runSynthLaneCursor assessmentContext" classicalSection) @?= 2
  mapM_ (assertMainSourceContains "classical context" classicalSection)
    [ "emDeadline <- classicalSynthLaneDeadline assessmentContext commandDeadline st"
    , "emRun <- runSynthLaneCursor assessmentContext"
    , "nnDeadline <- classicalSynthLaneDeadline assessmentContext commandDeadline st"
    , "nnRun <- runSynthLaneCursor assessmentContext nnPolicy nnDeadline st goal"
    ]

  assertMainSourceContains "ReplState Length configuration" stateSection
    "rsLengthAssessmentMode :: LengthAssessmentMode"
  mapM_ (\fragment -> assertBool
      ("Main persisted command-local synthesis state in ReplState: "
        ++ fragment)
      $ not $ fragment `isInfixOf` unlines stateSection)
    [ "LengthAssessmentContext"
    , "SynthLaneAccumulation"
    , "CounterexampleBankContext"
    ]

assertLengthAssessmentMainLaneSeam :: IO ()
assertLengthAssessmentMainLaneSeam = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let declarationSection = mainSourceSection
        "data SynthLaneOutcome =" "-- Output (" sourceLines
      verificationSection = mainSourceSection
        "verifySynthLane assessmentContext groupLimit st goal notes groups ="
        "synthLaneDispositionWith ::" sourceLines
      dispositionSection = mainSourceSection
        "synthLaneDispositionWith shown outcome ="
        "synthLaneAccumulationDisposition" sourceLines
      callbackSection = mainSourceSection
        "synthVerify successQuota st goal groups ="
        "completionCandidates ::" sourceLines
      verificationText = unlines verificationSection
      dispositionText = unlines dispositionSection
  mapM_ (assertMainSourceContains "lane outcome declaration"
      declarationSection)
    [ "synthLaneCheckedFrontierSpellings :: [String]"
    , "synthLaneCallbackAttemptVariants :: [DetailedVerificationVariant]"
    , "synthLaneOutcomeObservations :: LeantObservations"
    , "synthLaneOutcomeNotes :: [String]"
    , "synthLaneAssessed :: Maybe AssessedSynthLane"
    , "assessedSynthLaneVerification :: VerificationBatch DetailedVerificationVariant"
    , "assessedSynthLaneLengthAssessment :: LengthAssessmentResult"
    , "SynthLaneNoVerified"
    , "SynthLaneSurvivors [LengthCandidatePresentation] [LengthCandidateRejectionPresentation]"
    , "SynthLaneAllBehaviorallyRejected [LengthCandidateRejectionPresentation]"
    , "SynthLaneAssessmentPreserved [LengthCandidatePresentation] [LengthCandidateRejectionPresentation]"
    ]
  assertBool "Main made a private lane-outcome field strict"
    $ not ("!" `isInfixOf` unlines declarationSection)

  boundedPrefix <- expectMainSourcePosition "lane verifier"
    "case take groupLimit groups of" verificationSection
  projectedMode <- expectMainSourcePosition "lane verifier"
    "lengthAssessmentContextBehaviorMode assessmentContext"
      verificationSection
  rankQuota <- expectMainSourcePosition "lane verifier"
    "LengthBehaviorRank -> shown" verificationSection
  filterQuota <- expectMainSourcePosition "lane verifier"
    "LengthBehaviorFilter -> groupLimit" verificationSection
  callback <- expectMainSourcePosition "lane verifier"
    "(verification, callbackAttempts) <- synthVerify successQuota st goal"
      verificationSection
  assessment <- expectMainSourcePosition "lane verifier"
    "assessLengthVerificationContext assessmentContext verification"
      verificationSection
  assertBool "Main projected behavior mode before bounding the lane"
    $ boundedPrefix < projectedMode
  assertBool "Main changed the five-success ranking frontier"
    $ projectedMode < rankQuota && rankQuota < callback
  assertBool "Main did not give filtering the complete bounded lane quota"
    $ projectedMode < filterQuota && filterQuota < callback
  assertBool "Main assessed candidates before callback verification"
    $ callback < assessment
  mapM_ (assertMainSourceContains "lane verifier" verificationSection)
    [ "synthLaneCheckedFrontierSpellings = []"
    , "synthLaneCallbackAttemptVariants = []"
    , "synthLaneAssessed = Nothing"
    , "concatMap detailedCandidateGroupVariants boundedGroups"
    , "synthLaneCallbackAttemptVariants = callbackAttempts"
    , "map detailedCandidateGroupVerificationVariants boundedGroups"
    , "synthLaneAssessed = Just AssessedSynthLane"
    ]
  mapM_ (\fragment -> assertBool
      ("verification-only lane seam retained side effect " ++ show fragment)
      $ not $ fragment `isInfixOf` verificationText)
    [ "emitLn st"
    , "synthBind st"
    , "rsSynthIts"
    , "modifyIORef' st"
    , "reportLengthAssessmentRejections"
    , "reportSynthLaneNotes"
    , "finalizeSynthLaneOutcome"
    , "finalizeSynthLaneAccumulation"
    , "accumulateSynthLaneOutcome"
    ]

  mapM_ (assertMainSourceContains "callback trace" callbackSection)
    [ "reverseAttempts <- newIORef []"
    , "verification <- verifyCandidateGroups successQuota (verifyVariant reverseAttempts) groups"
    , "attempts <- reverse <$> readIORef reverseAttempts"
    , "pure (verification, attempts)"
    , "modifyIORef' reverseAttempts (variant :)"
    , "result <- runCurrentCmd st (candidateVerificationProgram goal term)"
    ]
  traceAppend <- expectMainSourcePosition "callback trace"
    "modifyIORef' reverseAttempts (variant :)" callbackSection
  backendAttempt <- expectMainSourcePosition "callback trace"
    "result <- runCurrentCmd st" callbackSection
  assertBool "Main moved the callback trace after the backend attempt"
    $ traceAppend < backendAttempt
  assertBool "Main substituted the full checked frontier for callback attempts"
    $ not ("concatMap detailedCandidateGroupVariants"
      `isInfixOf` unlines callbackSection)

  mapM_ (assertMainSourceContains "lane disposition" dispositionSection)
    [ "Nothing -> SynthLaneNoVerified"
    , "null $ verifiedCandidateReceipts $ assessedSynthLaneVerification assessed -> SynthLaneNoVerified"
    , "take shown $ presentLengthAssessment assessment"
    , "rejections = presentLengthAssessmentRejections assessment"
    , "Just _ -> SynthLaneAssessmentPreserved presentations rejections"
    , "SynthLaneSurvivors presentations rejections"
    , "SynthLaneAllBehaviorallyRejected rejections"
    , "SynthLaneSurvivors [] []"
    ]
  assertBool "an assessed lane can become NoVerified without an empty receipt batch"
    $ length (mainSourcePositions "SynthLaneNoVerified" dispositionSection)
      == 2
  assertBool "Main capped behavioral rejection rows with survivor output"
    $ not ("take synthMaxShown $ presentLengthAssessmentRejections"
      `isInfixOf` dispositionText)
  receiptGate <- expectMainSourcePosition "lane disposition"
    "verifiedCandidateReceipts" dispositionSection
  failureGate <- expectMainSourcePosition "lane disposition"
    "case lengthAssessmentFailure assessment of" dispositionSection
  assertBool "Main classified behavioral outcomes before proving verification"
    $ receiptGate < failureGate

  synthMaxShown @?= 5
  synthMaxTried @?= 12
  synthVerificationWindow EngineDjinn @?= 12
  synthVerificationWindow EngineExference @?= 12
  synthVerificationWindow EngineBoth @?= 24
  synthMaxTried `div` 2 @?= 6
  2 * synthVerificationWindow EngineBoth @?= 48
  2 * synthVerificationWindow EngineDjinn @?= 24
  2 * synthVerificationWindow EngineExference @?= 24
  assertBool "two combined filter batches exceed the cursor hard cap"
    $ 2 * synthVerificationWindow EngineBoth <= candidateWindow

assertLengthAssessmentMainLaneAccumulation :: IO ()
assertLengthAssessmentMainLaneAccumulation = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let declarationSection = mainSourceSection
        "newtype SynthLaneAccumulation ="
        "-- | Pure scheduling meaning of a lane" sourceLines
      foldSection = mainSourceSection
        "synthLaneAccumulationDisposition"
        "-- | Finalize one command's already verified/assessed lanes"
        sourceLines
      declarationText = unlines declarationSection
      foldText = unlines foldSection
  mapM_ (assertMainSourceContains "lane accumulation declaration"
      declarationSection)
    [ "newtype SynthLaneAccumulation = SynthLaneAccumulation [SynthLaneOutcome]"
    , "emptySynthLaneAccumulation :: SynthLaneAccumulation"
    , "emptySynthLaneAccumulation = SynthLaneAccumulation []"
    , "accumulateSynthLaneOutcome :: SynthLaneOutcome -> SynthLaneAccumulation -> SynthLaneAccumulation"
    , "accumulateSynthLaneOutcome outcome (SynthLaneAccumulation reverseOutcomes) = SynthLaneAccumulation (outcome : reverseOutcomes)"
    ]
  assertBool "Main made the reverse lane accumulation strict"
    $ not ("!" `isInfixOf` declarationText)
  assertBool "Main replaced the positional private accumulation with a record"
    $ not ("{" `isInfixOf` declarationText)
  mapM_ (\fragment -> assertBool
      ("Main derived a frozen accumulation instance: " ++ fragment)
      $ not $ fragment `isInfixOf` declarationText)
    [ "deriving"
    , "Eq"
    , "Show"
    ]

  chronologicalFold <- expectMainSourcePosition "lane accumulation fold"
    "foldl accumulateDisposition SynthLaneNoVerified" foldSection
  chronologicalInput <- expectMainSourcePosition "lane accumulation fold"
    "map (synthLaneDispositionWith shown) $ reverse reverseOutcomes" foldSection
  assertBool "Main stopped folding the reverse history chronologically"
    $ chronologicalFold < chronologicalInput
  mapM_ (assertMainSourceContains "lane accumulation fold" foldSection)
    [ "accumulateDisposition accumulated disposition = case accumulated of"
    , "SynthLaneSurvivors _ _ -> accumulated"
    , "SynthLaneAssessmentPreserved _ _ -> accumulated"
    , "SynthLaneNoVerified -> accumulated"
    , "SynthLaneAllBehaviorallyRejected rejections -> appendRejections accumulated rejections"
    , "SynthLaneSurvivors presentations rejections -> SynthLaneSurvivors presentations (dispositionRejections accumulated ++ rejections)"
    , "SynthLaneAssessmentPreserved presentations rejections -> SynthLaneAssessmentPreserved presentations (dispositionRejections accumulated ++ rejections)"
    , "SynthLaneNoVerified -> SynthLaneAllBehaviorallyRejected rejections"
    , "SynthLaneAllBehaviorallyRejected prior -> SynthLaneAllBehaviorallyRejected (prior ++ rejections)"
    , "SynthLaneNoVerified -> []"
    ]
  survivorGuard <- expectMainSourcePosition "lane accumulation fold"
    "SynthLaneSurvivors _ _ -> accumulated" foldSection
  preservedGuard <- expectMainSourcePosition "lane accumulation fold"
    "SynthLaneAssessmentPreserved _ _ -> accumulated" foldSection
  newLane <- expectMainSourcePosition "lane accumulation fold"
    "_ -> case disposition of" foldSection
  assertBool "the accumulated-terminal guard no longer precedes the new lane"
    $ survivorGuard < newLane && preservedGuard < newLane
  length (mainSourcePositions
      "SynthLaneSurvivors _ _ -> accumulated" foldSection) @?= 2
  length (mainSourcePositions
      "SynthLaneAssessmentPreserved _ _ -> accumulated" foldSection) @?= 2
  mapM_ (\fragment -> assertBool
      ("pure lane accumulation retained effect " ++ show fragment)
      $ not $ fragment `isInfixOf` foldText)
    [ "emitLn st"
    , "synthBind st"
    , "modifyIORef'"
    , "finalizeSynthLaneAccumulation"
    , "reportLengthAssessmentRejections"
    , "reportSynthLaneNotes"
    ]

assertLengthAssessmentMainLaneFinalization :: IO ()
assertLengthAssessmentMainLaneFinalization = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let sourceText = unlines sourceLines
      verificationSection = mainSourceSection
        "verifySynthLane assessmentContext groupLimit st goal notes groups ="
        "synthLaneDispositionWith ::" sourceLines
      dispositionSection = mainSourceSection
        "synthLaneDispositionWith shown outcome ="
        "synthLaneAccumulationDisposition" sourceLines
      finalizerSection = mainSourceSection
        "accumulation@(SynthLaneAccumulation reverseOutcomes) = do"
        "finalizeSynthLanePresentations st args goal presentations rejections = do"
        sourceLines
      presentationSection = mainSourceSection
        "finalizeSynthLanePresentations st args goal presentations rejections = do"
        "reportSynthLaneNotes ::" sourceLines
      noVerifiedBranch = takeWhile
          (not . isInfixOf "SynthLaneSurvivors presentations rejections ->")
        $ dropWhile (not . isInfixOf "SynthLaneNoVerified -> pure ()")
          finalizerSection
      allRejectedBranch = takeWhile
          (not . isInfixOf
            "SynthLaneAssessmentPreserved presentations rejections ->")
        $ dropWhile (not . isInfixOf
            "SynthLaneAllBehaviorallyRejected rejections -> do")
          finalizerSection
      finalizerText = unlines finalizerSection
      presentationText = unlines presentationSection
  mapM_ (assertMainSourceContains "lane finalizer" finalizerSection)
    [ "let outcomes = reverse reverseOutcomes"
    , "dispositions = map (synthLaneDispositionWith shown) outcomes"
    , "effectiveLanes = throughFirstTerminal $ zip outcomes dispositions"
    , "forM_ outcomes $ \\outcome -> forM_ (leantObservationCodeEntries $ synthLaneOutcomeObservations outcome)"
    , "forM_ (map fst effectiveLanes) $ \\outcome -> case synthLaneAssessed outcome of"
    , "lengthAssessmentFailure $ assessedSynthLaneLengthAssessment assessed"
    , "let disposition = synthLaneAccumulationDisposition shown accumulation"
    , "SynthLaneNoVerified -> pure ()"
    , "SynthLaneSurvivors presentations rejections -> finalizeSynthLanePresentations st args goal presentations rejections"
    , "SynthLaneAllBehaviorallyRejected rejections -> do"
    , "rsSynthIts = [], rsSynthItsProve = False"
    , "SynthLaneAssessmentPreserved presentations rejections -> finalizeSynthLanePresentations st args goal presentations rejections"
    , "forM_ effectiveLanes $ \\(outcome, laneDisposition) -> case laneDisposition of"
    , "SynthLaneNoVerified -> pure () SynthLaneSurvivors _ _ -> reportSynthLaneNotes st (synthLaneOutcomeNotes outcome)"
    , "throughFirstTerminal lanes = case lanes of"
    , "SynthLaneSurvivors _ _ -> []"
    , "SynthLaneAssessmentPreserved _ _ -> []"
    , "SynthLaneNoVerified -> throughFirstTerminal remaining"
    , "SynthLaneAllBehaviorallyRejected _ -> throughFirstTerminal remaining"
    ]
  assertBool "the singular eager lane finalizer survived"
    $ not ("finalizeSynthLaneOutcome" `isInfixOf` sourceText)
  assertBool "the command finalizer collapsed per-lane forensic metrics"
    $ not ("mconcat" `isInfixOf` finalizerText)
  assertBool "NoVerified cleared or replaced stale synthesis splices"
    $ not ("rsSynthIts" `isInfixOf` unlines noVerifiedBranch)
  mapM_ (assertMainSourceContains "all-rejected finalizer"
      allRejectedBranch)
    [ "rsSynthIts = []"
    , "rsSynthItsProve = False"
    , "reportLengthAssessmentRejections st rejections"
    ]
  assertBool "all-rejected behavioral output attempted to bind a candidate"
    $ not ("synthBind" `isInfixOf` unlines allRejectedBranch)
  length (mainSourcePositions "rsSynthIts = []" finalizerSection) @?= 1
  length (mainSourcePositions "rsSynthItsProve = False" finalizerSection)
    @?= 1
  length (mainSourcePositions "reportSynthLaneNotes st" finalizerSection)
    @?= 3

  mapM_ (assertMainSourceContains "survivor finalizer"
      presentationSection)
    [ "shown = map lengthCandidatePresentationText presentations"
    , "counters <- mapM (synthBind st goal) (reverse shown)"
    , "zip shown (reverse counters)"
    , "rsSynthIts = splices, rsSynthItsProve = proving"
    , "forM_ (zip [1 :: Int ..] presentations)"
    , "reportLengthAssessmentRejections st rejections"
    ]
  reverseBinding <- expectMainSourcePosition "survivor finalizer"
    "counters <- mapM (synthBind st goal) (reverse shown)"
      presentationSection
  cacheMutation <- expectMainSourcePosition "survivor finalizer"
    "rsSynthIts = splices" presentationSection
  survivorRows <- expectMainSourcePosition "survivor finalizer"
    "forM_ (zip [1 :: Int ..] presentations)" presentationSection
  rejectionRows <- expectMainSourcePosition "survivor finalizer"
    "reportLengthAssessmentRejections st rejections" presentationSection
  assertBool "Main changed reverse binding or output ordering"
    $ reverseBinding < cacheMutation
      && cacheMutation < survivorRows
      && survivorRows < rejectionRows
  assertBool "survivor finalization projected text from rejection rows"
    $ not ("lengthCandidateRejectionPresentationText"
      `isInfixOf` presentationText)
  length (mainSourcePositions
      "counters <- mapM (synthBind st goal)" presentationSection) @?= 1
  length (mainSourcePositions
      "modifyIORef' st" presentationSection) @?= 1

  chronology <- expectMainSourcePosition "lane finalizer"
    "let outcomes = reverse reverseOutcomes" finalizerSection
  metrics <- expectMainSourcePosition "lane finalizer"
    "forM_ outcomes" finalizerSection
  warnings <- expectMainSourcePosition "lane finalizer"
    "forM_ (map fst effectiveLanes)" finalizerSection
  disposition <- expectMainSourcePosition "lane finalizer"
    "let disposition = synthLaneAccumulationDisposition shown accumulation"
      finalizerSection
  stateAndRows <- expectMainSourcePosition "lane finalizer"
    "case disposition of" finalizerSection
  handledNotes <- expectMainSourcePosition "lane finalizer"
    "forM_ effectiveLanes" finalizerSection
  assertBool "Main changed chronological finalizer effect ordering"
    $ chronology < metrics
      && metrics < warnings
      && warnings < disposition
      && disposition < stateAndRows
      && stateAndRows < handledNotes
  mapM_ (\fragment -> assertBool
      ("verification/disposition seam retained finalizer effect "
        ++ show fragment)
      $ not $ fragment `isInfixOf`
          (unlines verificationSection ++ unlines dispositionSection))
    [ "emitLn st"
    , "synthBind st"
    , "rsSynthIts"
    , "modifyIORef' st"
    , "reportLengthAssessmentRejections"
    , "reportSynthLaneNotes"
    ]
  assertBool "the finalizer re-capped already sealed survivor presentations"
    $ not ("take synthMaxShown" `isInfixOf` finalizerText)

assertLengthAssessmentMainLaneScheduling :: IO ()
assertLengthAssessmentMainLaneScheduling = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let schedulerSection = mainSourceSection
        "synthGo' assessmentContext st args retriedVars goal parsed = do"
        "loadSynthProviders ::" sourceLines
      constructiveSection = mainSourceSection
        "limit <- synthTimeoutSeconds st"
        "if structuralFirst" schedulerSection
      baselineSection = mainSourceSection
        "if structuralFirst"
        "where" schedulerSection
      continuationSection = mainSourceSection
        "continueAfterBaseline runDeadline runLane discover laneEngine baseline = do"
        "runProviderLanes runDeadline fallback runLane checked accumulation lanes ="
        schedulerSection
      providerSection = mainSourceSection
        "runProviderLanes runDeadline fallback runLane checked accumulation lanes ="
        "finalize accumulation = do"
        schedulerSection
      schedulerText = unlines schedulerSection
  mapM_ (assertMainSourceContains "constructive cursor lane"
      constructiveSection)
    [ "let deadline"
    , "runSynthesis includeLibrary checked laneEngine providers accumulation ="
    , "base = synthesizeWithProvidersSkippingDetailedWith limits laneEngine (rsSynthSteps state) checked providers fragment"
    , "in runSynthLaneCursor assessmentContext"
    , "ordinarySynthLaneCursorPolicy assessmentContext laneEngine limits"
    , "deadline st goal id outcome accumulation"
    ]
  assertBool
      "constructive scheduling lost its serial or two parallel cursors"
    $ length (mainSourcePositions
        "runSynthLaneCursor assessmentContext" constructiveSection) == 3

  mapM_ (assertMainSourceContains "baseline run routing" baselineSection)
    [ "baseline <- case initialBaselineSchedule of"
    , "Nothing ->"
    , "runSynthesis True Set.empty engine [] emptySynthLaneAccumulation"
    , "Just runParallelBaseline -> do"
    , "capabilities <- getNumCapabilities"
    , "if capabilities >= 2"
    , "then runParallelBaseline emptySynthLaneAccumulation"
    , "case synthLaneRunEnd baseline of"
    , "SynthLaneRunTimedOut -> report deadline baseline"
    , "SynthLaneRunCursorAdmissionFailed _ -> report deadline baseline"
    , "SynthLaneRunEngineFailed _ -> report deadline baseline"
    , "SynthLaneRunRefuted True -> do"
    , "then report deadline baseline"
    , "else runProviderLanes deadline (Just baseline)"
    , "SynthLaneRunStoppedByDisposition -> finalize (synthLaneRunAccumulation baseline)"
    , "_ -> continueAfterBaseline deadline runSynthesis discoverProviders engine baseline"
    ]
  mapM_ (assertMainSourceContains "baseline continuation"
      continuationSection)
    [ "accumulation = synthLaneRunAccumulation baseline"
    , "checked = Set.fromList (synthLaneRunCheckedFrontierSpellings baseline)"
    , "then report runDeadline baseline"
    , "else runProviderLanes runDeadline Nothing (runLane False) checked accumulation"
    ]

  mapM_ (assertMainSourceContains "provider run routing" providerSection)
    [ "fresh <- runLane checked laneEngine providers accumulation"
    , "case synthLaneRunEnd fresh of"
    , "SynthLaneRunTimedOut -> finish fresh"
    , "SynthLaneRunCursorAdmissionFailed _ -> finish fresh"
    , "SynthLaneRunEngineFailed _ -> finish fresh"
    , "SynthLaneRunStoppedByDisposition -> finalize (synthLaneRunAccumulation fresh)"
    , "if null remaining then finish fresh else runProviderLanes runDeadline fallback runLane"
    , "Set.union checked $ Set.fromList $ synthLaneRunCheckedFrontierSpellings fresh"
    , "synthLaneRunAccumulation fresh"
    , "finish fresh = case fallback of"
    , "Just fallbackRun -> report runDeadline (fallbackRun { synthLaneRunAccumulation = synthLaneRunAccumulation fresh })"
    , "Nothing -> report runDeadline fresh"
    ]
  assertBool "provider dedup substituted callback attempts for the full frontier"
    $ not ("synthLaneCallbackAttemptVariants"
      `isInfixOf` schedulerText)
  assertBool "the old Bool handled boundary survived the lane outcome refactor"
    $ not ("verifyAndDisplay" `isInfixOf` schedulerText)
  mapM_ (\fragment -> assertBool
      ("lane scheduler retained quota-fill arithmetic " ++ show fragment)
      $ not $ fragment `isInfixOf` schedulerText)
    [ "remainingQuota"
    , "successesNeeded"
    , "synthMaxShown -"
    , "groupLimit -"
    , "reassess"
    , "reverify"
    ]

  assertBool "provider fallback replaced its proof-backed run taxonomy"
    $ not ("synthLaneRunEnd = synthLaneRunEnd fresh"
      `isInfixOf` unlines providerSection)
  assertBool "the scheduler reran an engine to obtain a cursor successor"
    $ not ("startDetailedSynthCursor" `isInfixOf` schedulerText)

assertLengthAssessmentMainParallelBaseline :: IO ()
assertLengthAssessmentMainParallelBaseline = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  engineLines <- lines <$> readFile "src/Leant/Synth/Engine.hs"
  let schedulerSection = mainSourceSection
        "synthGo' assessmentContext st args retriedVars goal parsed = do"
        "loadSynthProviders ::" sourceLines
      constructiveSection = mainSourceSection
        "limit <- synthTimeoutSeconds st"
        "if structuralFirst" schedulerSection
      serialSection = mainSourceSection
        "runSynthesis includeLibrary checked laneEngine providers accumulation ="
        "-- Scoped parallel work remains limited" constructiveSection
      parallelSection = mainSourceSection
        "-- Scoped parallel work remains limited"
        "if structuralFirst" constructiveSection
      structuralParallelSection = mainSourceSection
        "runParallelStructuralBaseline accumulation = do"
        "runParallelLibraryBaseline accumulation = do" parallelSection
      libraryParallelSection = mainSourceSection
        "runParallelLibraryBaseline accumulation = do"
        "if structuralFirst" parallelSection
      scheduleSelectionSection = mainSourceSection
        "initialBaselineSchedule"
        "runParallelStructuralBaseline accumulation = do" parallelSection
      routingSection = mainSourceSection
        "if structuralFirst"
        "case synthLaneRunEnd baseline of" schedulerSection
      structuralTimeoutReceiptSection = mainSourceSection
        "Nothing -> pure SynthLaneRun"
        "Just branches ->" structuralParallelSection
      libraryTimeoutReceiptSection = mainSourceSection
        "Nothing -> pure SynthLaneRun"
        "Just branches ->" libraryParallelSection
      pairForceSection = mainSourceSection
        "forceDetailedSynthPairBefore leftRequested rightRequested deadline left right ="
        "-- | Filtering owns one command-wide deadline" sourceLines
      providerSection = mainSourceSection
        "runProviderLanes runDeadline fallback runLane checked accumulation lanes ="
        "finalize accumulation = do" schedulerSection
      classicalSection = mainSourceSection
        "synthClassical assessmentContext commandDeadline st goal parsed accumulation ="
        "verifySynthLane assessmentContext groupLimit st goal notes groups ="
        sourceLines
      engineBothSection = mainSourceSection
        "EngineBoth -> do"
        "-- | Prepare one engine-specific translation" engineLines
      excludedSerialSections =
        [ ("ordinary/library/provider callback", serialSection)
        , ("provider widening", providerSection)
        , ("classical retries", classicalSection)
        ]

  length (mainSourcePositions
      "runSynthLaneCursor assessmentContext" constructiveSection) @?= 3
  length (mainSourcePositions
      "runSynthLaneCursor assessmentContext" serialSection) @?= 1
  length (mainSourcePositions
      "runSynthLaneCursor assessmentContext" structuralParallelSection) @?= 1
  length (mainSourcePositions
      "runSynthLaneCursor assessmentContext" libraryParallelSection) @?= 1

  mapM_ (assertMainSourceContains "parallel baseline eligibility"
      parallelSection)
    [ "baselinePolicy = ordinarySynthLaneCursorPolicy assessmentContext engine limits"
    , "parallelStructuralBaselineStaticallyEligible = engine == EngineBoth"
    , "&& limits == defaultSynthLimits"
    , "&& null libraryPremises"
    , "&& not (synthLaneCursorAllowsFilterSuccessor baselinePolicy)"
    , "parallelLibraryBaselineStaticallyEligible = structuralFirst"
    , "&& limits == defaultSynthLimits"
    , "&& not (null libraryPremises)"
    , "initialBaselineSchedule"
    , "| parallelLibraryBaselineStaticallyEligible = Just runParallelLibraryBaseline"
    , "| parallelStructuralBaselineStaticallyEligible = Just runParallelStructuralBaseline"
    , "| otherwise = Nothing"
    ]
  mapM_ (\effect -> assertBool
      ("pure initial baseline schedule performed " ++ effect)
      $ not $ effect `isInfixOf` unlines scheduleSelectionSection)
    [ "getNumCapabilities"
    , "runSynthesis"
    , "forceDetailedSynthPairBefore"
    ]
  let libraryEligibilitySection = mainSourceSection
        "parallelLibraryBaselineStaticallyEligible ="
        "initialBaselineSchedule" parallelSection
  assertBool "library-pair admission was restricted to one engine"
    $ not ("engine ==" `isInfixOf` unlines libraryEligibilitySection)

  scheduleSelection <- expectMainSourcePosition "parallel baseline routing"
    "case initialBaselineSchedule of" routingSection
  serialSchedule <- expectMainSourcePosition "parallel baseline routing"
    "Nothing ->" routingSection
  serialScheduleRoute <- expectMainSourcePosition "parallel baseline routing"
    "runSynthesis True Set.empty engine [] emptySynthLaneAccumulation"
      routingSection
  selectedParallelSchedule <- expectMainSourcePosition
    "parallel baseline routing" "Just runParallelBaseline -> do"
      routingSection
  capabilityRead <- expectMainSourcePosition "parallel baseline routing"
    "capabilities <- getNumCapabilities" routingSection
  capabilityGate <- expectMainSourcePosition "parallel baseline routing"
    "if capabilities >= 2" routingSection
  parallelScheduleDispatch <- expectMainSourcePosition
    "parallel baseline routing"
      "then runParallelBaseline emptySynthLaneAccumulation"
      routingSection
  n1SerialRoute <- case mainSourcePositions
      "runSynthesis True Set.empty engine [] emptySynthLaneAccumulation"
      routingSection
    of
      _ : route : _ -> pure route
      _ -> assertFailure "parallel baseline routing omitted its N1 serial route"
        >> error "unreachable"
  assertBool "RTS capabilities were inspected before concrete static selection"
    $ scheduleSelection < serialSchedule
      && serialSchedule < serialScheduleRoute
      && serialScheduleRoute < selectedParallelSchedule
      && selectedParallelSchedule < capabilityRead
      && capabilityRead < capabilityGate
      && capabilityGate < parallelScheduleDispatch
      && parallelScheduleDispatch < n1SerialRoute
  length (mainSourcePositions "getNumCapabilities" schedulerSection) @?= 1
  length (mainSourcePositions
      "runParallelStructuralBaseline emptySynthLaneAccumulation"
      routingSection) @?= 0
  length (mainSourcePositions
      "runParallelLibraryBaseline emptySynthLaneAccumulation"
      routingSection) @?= 0
  length (mainSourcePositions
      "then runParallelBaseline emptySynthLaneAccumulation"
      routingSection) @?= 1
  length (mainSourcePositions
      "runSynthesis True Set.empty engine []" routingSection) @?= 2

  mapM_ (assertMainSourceContains "parallel structural branches"
      structuralParallelSection)
    [ "runBranch laneEngine = synthesizeWithProvidersSkippingDetailedWith limits laneEngine (rsSynthSteps state) Set.empty [] fragment"
    , "prepared <- forceDetailedSynthPairBefore (synthLimitTried limits) (synthLimitTried limits) deadline"
    , "(runBranch EngineDjinn) (runBranch EngineExference)"
    , "let outcome = fmap (uncurry $ mergeDetailedOutcomesSkipping Set.empty) branches"
    , "in runSynthLaneCursor assessmentContext baselinePolicy deadline st goal id outcome accumulation"
    ]
  synthLimitTried defaultSynthLimits @?= 12
  synthLimitTried defaultSynthLimits @?= synthMaxTried
  synthVerificationWindow EngineBoth @?= 24
  assertBool "parallel workers forced a combined rather than per-engine prefix"
    $ synthLimitTried defaultSynthLimits
      < synthVerificationWindow EngineBoth
  branchDefinition <- expectMainSourcePosition "parallel structural branches"
    "let runBranch laneEngine" structuralParallelSection
  djinnBranch <- expectMainSourcePosition "parallel structural branches"
    "(runBranch EngineDjinn)" structuralParallelSection
  exferenceBranch <- expectMainSourcePosition "parallel structural branches"
    "(runBranch EngineExference)" structuralParallelSection
  defaultMerge <- expectMainSourcePosition "parallel structural branches"
    "mergeDetailedOutcomesSkipping Set.empty" structuralParallelSection
  mergedCursor <- expectMainSourcePosition "parallel structural branches"
    "in runSynthLaneCursor assessmentContext baselinePolicy deadline"
      structuralParallelSection
  assertBool "parallel branches or their default merge changed order"
    $ branchDefinition < djinnBranch
      && djinnBranch <= exferenceBranch
      && exferenceBranch < defaultMerge
      && defaultMerge < mergedCursor

  mapM_ (assertMainSourceContains "parallel library branches"
      libraryParallelSection)
    [ "base = synthesizeWithProvidersSkippingDetailedWith limits engine (rsSynthSteps state) Set.empty [] fragment"
    , "library = synthesizeTunedDetailedWith limits engine (rsSynthSteps state) (synthLimitWindow limits, Just 100000)"
    , "[ (name, stripRecCtors premise) | (name, premise) <- libraryPremises ]"
    , "(stripRecCtors fragment) fragment"
    , "prepared <- forceDetailedSynthPairBefore 0 (synthVerificationWindowWith limits engine) deadline base library"
    , "let outcome = branches >>= \\(baseOutcome, libraryOutcome) -> mergeLibraryDetailedOutcomes (Right baseOutcome) (Right libraryOutcome)"
    , "in runSynthLaneCursor assessmentContext baselinePolicy deadline st goal id outcome accumulation"
    ]
  mapM_ (\forbidden -> assertBool
      ("outer library pair nested through " ++ forbidden)
      $ not $ forbidden `isInfixOf` unlines libraryParallelSection)
    [ "runParallelStructuralBaseline"
    , "getNumCapabilities"
    , "EngineDjinn"
    , "EngineExference"
    ]
  libraryBase <- expectMainSourcePosition "parallel library branches"
    "let base = synthesizeWithProvidersSkippingDetailedWith limits"
      libraryParallelSection
  librarySearch <- expectMainSourcePosition "parallel library branches"
    "library = synthesizeTunedDetailedWith limits engine"
      libraryParallelSection
  libraryPair <- expectMainSourcePosition "parallel library branches"
    "prepared <- forceDetailedSynthPairBefore" libraryParallelSection
  libraryMerge <- expectMainSourcePosition "parallel library branches"
    "mergeLibraryDetailedOutcomes" libraryParallelSection
  libraryCursor <- expectMainSourcePosition "parallel library branches"
    "in runSynthLaneCursor assessmentContext baselinePolicy deadline"
      libraryParallelSection
  assertBool "parallel library pair changed base-first merge/cursor order"
    $ libraryBase < librarySearch
      && librarySearch < libraryPair
      && libraryPair < libraryMerge
      && libraryMerge < libraryCursor

  mapM_ (\(label, timeoutReceiptSection) -> do
      mapM_ (assertMainSourceContains
          ("empty " ++ label ++ " timeout receipt") timeoutReceiptSection)
        [ "synthLaneRunAccumulation = accumulation"
        , "synthLaneRunCheckedFrontierSpellings = []"
        , "synthLaneRunCandidateGroupCount = 0"
        , "synthLaneRunNotes = []"
        , "synthLaneRunEnd = SynthLaneRunTimedOut"
        ]
      mapM_ (\forbidden -> assertBool
          (label ++ " timeout receipt probed unavailable work " ++ forbidden)
          $ not $ forbidden `isInfixOf` unlines timeoutReceiptSection)
        [ "branches"
        , "outcome"
        , "mergeDetailedOutcomesSkipping"
        , "mergeLibraryDetailedOutcomes"
        , "runSynthLaneCursor"
        ])
    [ ("structural pair", structuralTimeoutReceiptSection)
    , ("library pair", libraryTimeoutReceiptSection)
    ]

  mapM_ (assertMainSourceContains "bounded parallel prefix ownership"
      pairForceSection)
    [ "beforeDeadline $ runParallelEitherPairOrdered (strictPrefix leftRequested left) (strictPrefix rightRequested right)"
    , "strictPrefix requested outcome = outcome <$ evaluate (forceDetailedOutcome requested outcome)"
    , "beforeDeadline action = case deadline of"
    , "Nothing -> Just <$> action"
    , "Just absoluteDeadline -> do"
    , "now <- getCurrentTime"
    , "diffUTCTime absoluteDeadline now"
    , "if remainingMicros <= 0 then pure Nothing else timeout remainingMicros action"
    ]
  length (mainSourcePositions "forceDetailedOutcome" sourceLines) @?= 2
  length (mainSourcePositions
      "forceDetailedOutcome requested outcome" pairForceSection) @?= 1
  length (mainSourcePositions
      "runParallelEitherPairOrdered" sourceLines) @?= 2
  length (mainSourcePositions
      "runParallelEitherPairOrdered" pairForceSection) @?= 1
  mapM_ (\deferredOwner -> assertBool
      ("bounded pair helper eagerly acquired merged demand via "
        ++ deferredOwner)
      $ not $ deferredOwner `isInfixOf` unlines pairForceSection)
    [ "mergeDetailedOutcomesSkipping"
    , "startDetailedSynthCursor"
    , "forceDetailedSynthCursorStep"
    , "candidateWindow"
    ]
  pairForce <- expectMainSourcePosition "parallel structural branches"
    "prepared <- forceDetailedSynthPairBefore" structuralParallelSection
  pairDeadline <- expectMainSourcePosition "parallel structural branches"
    "(synthLimitTried limits) (synthLimitTried limits) deadline"
      structuralParallelSection
  assertBool "bounded pair work escaped the command deadline"
    $ pairForce <= pairDeadline && pairDeadline < mergedCursor

  mapM_ (\(label, section) -> mapM_ (\parallelToken -> assertBool
      (label ++ " unexpectedly entered parallel scheduling via "
        ++ parallelToken)
      $ not $ parallelToken `isInfixOf` unlines section)
      [ "runParallelStructuralBaseline"
      , "runParallelLibraryBaseline"
      , "forceDetailedSynthPairBefore"
      , "runParallelEitherPairOrdered"
      , "getNumCapabilities"
      ]) excludedSerialSections
  mapM_ (assertMainSourceContains "serial ordinary/library lane"
      serialSection)
    [ "base = synthesizeWithProvidersSkippingDetailedWith limits laneEngine (rsSynthSteps state) checked providers fragment"
    , "includeLibrary && not (null libraryPremises)"
    , "mergeLibraryDetailedOutcomes base"
    , "synthesizeTunedDetailedWith limits laneEngine"
    ]
  mapM_ (\parallelToken -> assertBool
      ("structural engine pair unexpectedly nested through " ++ parallelToken)
      $ not $ parallelToken `isInfixOf` unlines structuralParallelSection)
    [ "runParallelLibraryBaseline"
    , "getNumCapabilities"
    ]
  mapM_ (assertMainSourceContains "serial EngineBoth implementation"
      engineBothSection)
    [ "djinnPrepared <- prepareSynthesis djinnRecursiveProjection"
    , "djinnCompatibility <- djinnRun"
    , "exferencePrepared <- prepareSynthesis exferenceRecursiveProjection"
    , "exference <- exferenceRun"
    , "mergeDetailedOutcomesSkippingWith limits checked djinn exference"
    ]
  mapM_ (\parallelToken -> assertBool
      ("pure EngineBoth unexpectedly owns concurrency via " ++ parallelToken)
      $ not $ parallelToken `isInfixOf` unlines engineBothSection)
    [ "runParallelEitherPairOrdered"
    , "withAsync"
    , "async"
    , "getNumCapabilities"
    ]

assertLengthAssessmentMainProgressiveDeclarations :: IO ()
assertLengthAssessmentMainProgressiveDeclarations = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let sourceText = unlines sourceLines
      stateSection = mainSourceSection
        "data ReplState = ReplState"
        "-- | Backend-local identifiers" sourceLines
      policySection = mainSourceSection
        "data SynthLaneCursorPolicy ="
        "-- | Why observation" sourceLines
      endSection = mainSourceSection
        "data SynthLaneRunEnd"
        "-- | Complete command-local receipt" sourceLines
      runSection = mainSourceSection
        "data SynthLaneRun ="
        "-- Output (" sourceLines
      engineTokens = words $ map normalizeMainInstancePunctuation sourceText
      privateTypes =
        [ "SynthLaneCursorPolicy"
        , "SynthLaneRunEnd"
        , "SynthLaneRun"
        ]
      forbiddenInstanceHeads =
        [ words $ "instance " ++ className ++ " " ++ typeName
        | className <- ["Eq", "Show"]
        , typeName <- privateTypes
        ]
  assertMainSourceContains "private Main export" sourceLines
    "module Main (main) where"
  mapM_ (assertMainSourceContains "cursor policy declaration" policySection)
    [ "synthLaneCursorBatchSize :: Int"
    , "synthLaneCursorAllowsFilterSuccessor :: Bool"
    , "synthLaneCursorRetainsRunNotes :: Bool"
    ]
  mapM_ (assertMainSourceContains "cursor run-end declaration" endSection)
    [ "SynthLaneRunStoppedByDisposition"
    , "SynthLaneRunBatchPolicyReached"
    , "SynthLaneRunNaturallyExhausted"
    , "SynthLaneRunHardCapReached"
    , "SynthLaneRunTimedOut"
    , "SynthLaneRunCursorAdmissionFailed DetailedSynthCursorError"
    , "SynthLaneRunEngineFailed String"
    , "SynthLaneRunRefuted Bool"
    , "SynthLaneRunNoTerm"
    ]
  mapM_ (assertMainSourceContains "cursor run receipt" runSection)
    [ "synthLaneRunAccumulation :: SynthLaneAccumulation"
    , "synthLaneRunCheckedFrontierSpellings :: [String]"
    , "synthLaneRunCandidateGroupCount :: Int"
    , "synthLaneRunNotes :: [String]"
    , "synthLaneRunEnd :: SynthLaneRunEnd"
    ]
  mapM_ (\(label, section) -> mapM_ (\forbidden -> assertBool
      (label ++ " acquired a frozen representation feature " ++ forbidden)
      $ not $ forbidden `isInfixOf` unlines section)
      ["!", "deriving", "instance Eq", "instance Show"])
    [ ("SynthLaneCursorPolicy", policySection)
    , ("SynthLaneRunEnd", endSection)
    , ("SynthLaneRun", runSection)
    ]
  mapM_ (\instanceHead -> assertBool
      ("Main added a frozen progressive instance head "
        ++ unwords instanceHead)
      $ not $ any (instanceHead `isPrefixOf`) $ tails engineTokens)
    forbiddenInstanceHeads
  mapM_ (\name -> assertBool
      ("Main persisted progressive run state in ReplState: " ++ name)
      $ not $ name `isInfixOf` unlines stateSection)
    privateTypes

assertLengthAssessmentMainCursorDriver :: IO ()
assertLengthAssessmentMainCursorDriver = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let sourceText = unlines sourceLines
      policySection = mainSourceSection
        "ordinarySynthLaneCursorPolicy assessmentContext engine limits ="
        "runDetailedSynthCursorBefore requested window deadline cursor =" sourceLines
      forcingSection = mainSourceSection
        "runDetailedSynthCursorBefore requested window deadline cursor ="
        "forceDetailedSynthPairBefore"
        sourceLines
      driverSection = mainSourceSection
        "runSynthLaneCursor assessmentContext policy deadline st goal transform outcome"
        "debugSynthLaneGroups ::" sourceLines
      debugSection = mainSourceSection
        "debugSynthLaneGroups ::"
        "-- | The Glivenko fallback" sourceLines
      verificationSection = mainSourceSection
        "verifySynthLane assessmentContext groupLimit st goal notes groups ="
        "synthLaneDispositionWith ::" sourceLines
      driverText = unlines driverSection
  mapM_ (assertMainSourceContains "ordinary cursor policy" policySection)
    [ "admissibleCursorBatch limits (synthVerificationWindowWith limits engine)"
    , "LengthBehaviorRank -> False"
    , "LengthBehaviorFilter -> True"
    , "synthLaneCursorRetainsRunNotes = True"
    ]

  admission <- expectMainSourcePosition "cursor deadline helper"
    "case advanceDetailedSynthCursorWith window requested cursor of" forcingSection
  deadlineCase <- expectMainSourcePosition "cursor deadline helper"
    "Right step -> case deadline of" forcingSection
  forceForever <- expectMainSourcePosition "cursor deadline helper"
    "evaluate (forceDetailedSynthCursorStep step)" forcingSection
  currentTime <- expectMainSourcePosition "cursor deadline helper"
    "now <- getCurrentTime" forcingSection
  remaining <- expectMainSourcePosition "cursor deadline helper"
    "diffUTCTime absoluteDeadline now" forcingSection
  boundedForce <- case mainSourcePositions
      "evaluate (forceDetailedSynthCursorStep step)" forcingSection of
    _ : second : _ -> pure second
    _ -> assertFailure "Main omitted one cursor-step force branch"
      >> error "unreachable"
  assertBool "cursor admission moved under or after the timeout boundary"
    $ admission < deadlineCase
      && deadlineCase < forceForever
      && forceForever < currentTime
      && currentTime < remaining
      && remaining < boundedForce
  mapM_ (assertMainSourceContains "cursor deadline helper" forcingSection)
    [ "Left err -> pure (Just (Left err))"
    , "Nothing -> Just (Right step) <$ evaluate (forceDetailedSynthCursorStep step)"
    , "if remainingMicros <= 0 then pure Nothing"
    , "done <- timeout remainingMicros (evaluate (forceDetailedSynthCursorStep step))"
    , "pure (Right step <$ done)"
    ]

  mapM_ (assertMainSourceContains "progressive cursor driver" driverSection)
    [ "observe (1 :: Int) 0 [] [] (startDetailedSynthCursor outcome)"
    , "forced <- runDetailedSynthCursorBefore"
    , "DetailedSynthCursorCandidateBatch batch successor -> do"
    , "groups = map transform (detailedCandidateBatchGroups batch)"
    , "notes = detailedCandidateBatchNotes batch"
    , "nextCount = groupCount + length groups"
    , "debugSynthLaneGroups st groupCount groups"
    , "lane <- verifySynthLane assessmentContext (synthLaneCursorBatchSize policy) st goal [] groups"
    , "let reverseOutcomes' = lane : reverseOutcomes"
    , "SynthLaneSurvivors _ _ -> finish reverseOutcomes' nextCount notes SynthLaneRunStoppedByDisposition"
    , "SynthLaneAssessmentPreserved _ _ -> finish reverseOutcomes' nextCount notes SynthLaneRunStoppedByDisposition"
    , "SynthLaneNoVerified -> continueOrStop batchOrdinal nextCount reverseOutcomes' notes successor"
    , "SynthLaneAllBehaviorallyRejected _ -> continueOrStop batchOrdinal nextCount reverseOutcomes' notes successor"
    , "synthLaneCursorAllowsFilterSuccessor policy && batchOrdinal < 2"
    , "observe (batchOrdinal + 1) groupCount reverseOutcomes notes successor"
    , "SynthLaneRunBatchPolicyReached"
    ]
  mapM_ (assertMainSourceContains "cursor terminal taxonomy" driverSection)
    [ "DetailedSynthCursorNaturallyExhausted notes -> finish reverseOutcomes groupCount notes SynthLaneRunNaturallyExhausted"
    , "DetailedSynthCursorHardCapReached notes -> finish reverseOutcomes groupCount notes SynthLaneRunHardCapReached"
    , "DetailedSynthCursorEngineFailed err -> finish reverseOutcomes groupCount runNotes (SynthLaneRunEngineFailed err)"
    , "DetailedSynthCursorRefuted sound -> finish reverseOutcomes groupCount runNotes (SynthLaneRunRefuted sound)"
    , "DetailedSynthCursorNoTerm notes -> finish reverseOutcomes groupCount notes SynthLaneRunNoTerm"
    , "Nothing -> finish reverseOutcomes groupCount runNotes SynthLaneRunTimedOut"
    , "Just (Left err) -> finish reverseOutcomes groupCount runNotes (SynthLaneRunCursorAdmissionFailed err)"
    ]
  length (mainSourcePositions "startDetailedSynthCursor" sourceLines) @?= 2
  length (mainSourcePositions
      "startDetailedSynthCursor outcome" driverSection) @?= 1
  length (mainSourcePositions
      "advanceDetailedSynthCursor" sourceLines) @?= 2
  length (mainSourcePositions
      "advanceDetailedSynthCursorWith window requested cursor" forcingSection) @?= 1
  length (mainSourcePositions
      "forceDetailedSynthCursorStep" sourceLines) @?= 3
  length (mainSourcePositions
      "runDetailedSynthCursorBefore" driverSection) @?= 1
  length (mainSourcePositions
      "runSynthLaneCursor" sourceLines) @?= 7
  length (mainSourcePositions
      "verifySynthLane assessmentContext" driverSection) @?= 1
  length (mainSourcePositions
      "verifySynthLane assessmentContext" sourceLines) @?= 2
  length (mainSourcePositions
      "assessLengthVerificationContext assessmentContext verification"
      verificationSection) @?= 1
  mapM_ (\forbidden -> assertBool
      ("cursor driver retained rerun/reassessment path " ++ forbidden)
      $ not $ forbidden `isInfixOf` driverText)
    [ "synthesizeWithProviders"
    , "synthesizeTunedDetailed"
    , "assessLengthVerificationContext"
    , "remainingQuota"
    , "successesNeeded"
    , "take synthMaxShown"
    ]

  mapM_ (assertMainSourceContains "progressive run receipt" driverSection)
    [ "attachNotesToRightmostHandled notes reverseOutcomes"
    , "chronologicalOutcomes = reverse noteOwnedReverseOutcomes"
    , "accumulation = foldl (flip accumulateSynthLaneOutcome) initialAccumulation chronologicalOutcomes"
    , "synthLaneRunCheckedFrontierSpellings = concatMap synthLaneCheckedFrontierSpellings chronologicalOutcomes"
    , "synthLaneRunCandidateGroupCount = groupCount"
    , "synthLaneRunNotes = notes"
    , "synthLaneRunEnd = runEnd"
    , "attachNotesToRightmostHandled _ [] = []"
    , "SynthLaneNoVerified -> lane : attachNotesToRightmostHandled notes earlier"
    , "SynthLaneSurvivors _ _ -> lane { synthLaneOutcomeNotes = notes } : earlier"
    , "SynthLaneAllBehaviorallyRejected _ -> lane { synthLaneOutcomeNotes = notes } : earlier"
    , "SynthLaneAssessmentPreserved _ _ -> lane { synthLaneOutcomeNotes = notes } : earlier"
    ]
  length (mainSourcePositions
      "attachNotesToRightmostHandled notes reverseOutcomes"
      driverSection) @?= 1
  length (mainSourcePositions
      "synthLaneOutcomeNotes = notes" driverSection) @?= 3
  let noVerifiedNotesSection = mainSourceSection
        "SynthLaneNoVerified ->"
        "SynthLaneSurvivors _ _ ->" driverSection
  assertBool "all-NoVerified note ownership escaped the final run receipt"
    $ not ("synthLaneOutcomeNotes = notes"
      `isInfixOf` unlines noVerifiedNotesSection)
  assertBool "full-frontier receipt was replaced by callback attempts"
    $ not ("synthLaneCallbackAttemptVariants"
      `isInfixOf` driverText)
  mapM_ (assertMainSourceContains "cumulative debug ordinals" debugSection)
    [ "debugSynthLaneGroups st priorGroupCount groups = do"
    , "zip [priorGroupCount + 1 ..] groups"
    ]
  mapM_ (\oldHelper -> assertBool
      ("Main retained the eager detailed-outcome helper " ++ oldHelper)
      $ not $ oldHelper `isInfixOf` sourceText)
    [ "runEngineBefore"
    , "runEngineBounded"
    ]

assertLengthAssessmentMainClassicalScheduling :: IO ()
assertLengthAssessmentMainClassicalScheduling = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let deadlineSection = mainSourceSection
        "classicalSynthLaneDeadline assessmentContext commandDeadline st ="
        "runSynthLaneCursor assessmentContext policy deadline st goal transform outcome"
        sourceLines
      filterDeadlineSection = mainSourceSection
        "LengthBehaviorFilter -> pure commandDeadline"
        "LengthBehaviorRank -> do" deadlineSection
      rankDeadlineSection = mainSourceSection
        "LengthBehaviorRank -> do"
        "-- | Consume one lazy detailed outcome" deadlineSection
      classicalSection = mainSourceSection
        "synthClassical assessmentContext commandDeadline st goal parsed accumulation ="
        "verifySynthLane assessmentContext groupLimit st goal notes groups ="
        sourceLines
      classicalText = unlines classicalSection
  mapM_ (assertMainSourceContains "classical deadline ownership"
      deadlineSection)
    [ "case lengthAssessmentContextBehaviorMode assessmentContext of"
    , "LengthBehaviorFilter -> pure commandDeadline"
    , "LengthBehaviorRank -> do"
    , "limit <- synthTimeoutSeconds st"
    , "if limit <= 0 then pure Nothing"
    , "started <- getCurrentTime"
    , "Just (addUTCTime (fromIntegral limit) started)"
    ]
  mode <- expectMainSourcePosition "classical deadline ownership"
    "case lengthAssessmentContextBehaviorMode assessmentContext of"
      deadlineSection
  timeoutRead <- expectMainSourcePosition "classical deadline ownership"
    "limit <- synthTimeoutSeconds st" deadlineSection
  zeroGuard <- expectMainSourcePosition "classical deadline ownership"
    "if limit <= 0" deadlineSection
  clock <- expectMainSourcePosition "classical deadline ownership"
    "started <- getCurrentTime" deadlineSection
  assertBool "rank deadline work preceded the mode or zero guard"
    $ mode < timeoutRead && timeoutRead < zeroGuard && zeroGuard < clock
  mapM_ (\forbidden -> assertBool
      ("filter deadline minted fresh route work " ++ forbidden)
      $ not $ forbidden `isInfixOf` unlines filterDeadlineSection)
    [ "synthTimeoutSeconds"
    , "getCurrentTime"
    , "addUTCTime"
    ]
  mapM_ (assertMainSourceContains "fresh rank route deadline"
      rankDeadlineSection)
    [ "limit <- synthTimeoutSeconds st"
    , "if limit <= 0 then pure Nothing"
    , "started <- getCurrentTime"
    , "Just (addUTCTime (fromIntegral limit) started)"
    ]

  mapM_ (assertMainSourceContains "classical cursor schedule"
      classicalSection)
    [ "emDeadline <- classicalSynthLaneDeadline assessmentContext commandDeadline st"
    , "if null atoms || length atoms > 5 then runDoubleNegation engine steps prefix body accumulation"
    , "emRun <- runSynthLaneCursor assessmentContext"
    , "admissibleCursorBatch limits (synthLimitTried limits `div` 2)"
    , "synthLaneCursorAllowsFilterSuccessor = False"
    , "synthLaneCursorRetainsRunNotes = False"
    , "emDeadline st goal id"
    , "synthesizeTunedDetailedWith limits engine steps (synthLimitTried limits, Just 100000)"
    , "SynthLaneRunStoppedByDisposition -> pure (synthLaneRunAccumulation emRun)"
    , "_ -> runDoubleNegation engine steps prefix body (synthLaneRunAccumulation emRun)"
    , "LengthBehaviorRank -> synthLimitTried limits"
    , "LengthBehaviorFilter -> synthLimitWindow limits"
    , "ordinaryPolicy = ordinarySynthLaneCursorPolicy assessmentContext engine limits"
    , "nnPolicy = ordinaryPolicy { synthLaneCursorRetainsRunNotes = False }"
    , "nnDeadline <- classicalSynthLaneDeadline assessmentContext commandDeadline st"
    , "nnRun <- runSynthLaneCursor assessmentContext nnPolicy nnDeadline st goal"
    , "mapDetailedCandidateGroupVariantsDroppingSemanticSidecar wrap"
    , "synthesizeTunedDetailedWith limits engine steps (djinnCandidateCutoff, Nothing)"
    , "pure (synthLaneRunAccumulation nnRun)"
    ]
  length (mainSourcePositions
      "classicalSynthLaneDeadline" classicalSection) @?= 2
  length (mainSourcePositions
      "runSynthLaneCursor assessmentContext" classicalSection) @?= 2
  length (mainSourcePositions
      "synthLaneCursorRetainsRunNotes = False" classicalSection) @?= 2
  emDeadline <- expectMainSourcePosition "classical EM ordering"
    "emDeadline <- classicalSynthLaneDeadline" classicalSection
  skippedEm <- expectMainSourcePosition "classical skipped-EM ordering"
    "if null atoms || length atoms > 5" classicalSection
  emRun <- expectMainSourcePosition "classical EM ordering"
    "emRun <- runSynthLaneCursor" classicalSection
  emStop <- expectMainSourcePosition "classical EM ordering"
    "case synthLaneRunEnd emRun of" classicalSection
  nnBody <- expectMainSourcePosition "classical route ordering"
    "let nnFrag =" classicalSection
  nnDeadline <- expectMainSourcePosition "classical NN ordering"
    "nnDeadline <- classicalSynthLaneDeadline" classicalSection
  nnRun <- expectMainSourcePosition "classical NN ordering"
    "nnRun <- runSynthLaneCursor" classicalSection
  assertBool "classical routes lost separate reached-route deadlines/order"
    $ skippedEm < emDeadline
      && emDeadline < emRun
      && emRun < emStop
      && emStop < nnBody
      && nnBody < nnDeadline
      && nnDeadline < nnRun
  assertBool "classical routes exposed engine notes"
    $ not ("reportSynthLaneNotes" `isInfixOf` classicalText)
  assertBool "classical scheduling finalized before returning to its caller"
    $ not ("finalizeSynthLane" `isInfixOf` classicalText)
  synthMaxTried `div` 2 @?= 6
  synthVerificationWindow EngineDjinn @?= 12
  synthVerificationWindow EngineExference @?= 12
  synthVerificationWindow EngineBoth @?= 24
  candidateWindow @?= 60

normalizeMainInstancePunctuation :: Char -> Char
normalizeMainInstancePunctuation character
  | character == '(' || character == ')' = ' '
  | otherwise = character

assertLengthAssessmentMainDiagnosticGates :: IO ()
assertLengthAssessmentMainDiagnosticGates = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let schedulerSection = mainSourceSection
        "synthGo' assessmentContext st args retriedVars goal parsed = do"
        "loadSynthProviders ::" sourceLines
      reportSection = mainSourceSection
        "report _ laneRun@SynthLaneRun"
        "-- | Ask Lean for the bounded value inventory" schedulerSection
      timeoutSection = mainSourceSection
        "synthLaneRunEnd = SynthLaneRunTimedOut"
        "synthLaneRunEnd = SynthLaneRunCursorAdmissionFailed err"
        reportSection
      admissionSection = mainSourceSection
        "synthLaneRunEnd = SynthLaneRunCursorAdmissionFailed err"
        "synthLaneRunEnd = SynthLaneRunEngineFailed err" reportSection
      errorSection = mainSourceSection
        "synthLaneRunEnd = SynthLaneRunEngineFailed err"
        "report runDeadline laneRun@SynthLaneRun" reportSection
      refutationSection = mainSourceSection
        "report runDeadline laneRun@SynthLaneRun"
        "synthLaneRunEnd = SynthLaneRunNoTerm" reportSection
      soundSection = mainSourceSection
        "| sound = do" "| otherwise = do" refutationSection
      unsoundSection = mainSourceSection
        "| otherwise = do" "synthLaneRunEnd = SynthLaneRunNoTerm"
        refutationSection
      noTermSection = mainSourceSection
        "synthLaneRunEnd = SynthLaneRunNoTerm"
        "synthLaneRunEnd = SynthLaneRunStoppedByDisposition" reportSection
      stoppedSection = mainSourceSection
        "synthLaneRunEnd = SynthLaneRunStoppedByDisposition"
        "report _ laneRun = reportCandidateCompletion laneRun" reportSection
      candidateSection = mainSourceSection
        "report _ laneRun = reportCandidateCompletion laneRun"
        "-- | Ask Lean for the bounded value inventory" reportSection
      providerFinishSection = mainSourceSection
        "finish fresh = case fallback of"
        "finalize accumulation = do"
        schedulerSection
      finalizeSection = mainSourceSection
        "finalize accumulation = do"
        "-- Abnormal engine completion" schedulerSection

  timeoutFinalize <- expectMainSourcePosition "timeout diagnostic"
    "finalizeSynthLaneAccumulation st args goal" timeoutSection
  timeoutDiagnostic <- expectMainSourcePosition "timeout diagnostic"
    "the engine did not finish within" timeoutSection
  assertBool "timeout output preceded completed lane finalization"
    $ timeoutFinalize < timeoutDiagnostic
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" timeoutSection) @?= 1
  admissionFinalize <- expectMainSourcePosition "cursor-admission diagnostic"
    "finalizeSynthLaneAccumulation st args goal" admissionSection
  admissionDiagnostic <- expectMainSourcePosition
    "cursor-admission diagnostic"
    "detailed cursor admission failed" admissionSection
  assertBool "cursor-admission output preceded completed lane finalization"
    $ admissionFinalize < admissionDiagnostic
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" admissionSection) @?= 1
  errorFinalize <- expectMainSourcePosition "engine-error diagnostic"
    "finalizeSynthLaneAccumulation st args goal" errorSection
  engineError <- expectMainSourcePosition "engine-error diagnostic"
    "synthesis engine error:" errorSection
  assertBool "engine-error output preceded completed lane finalization"
    $ errorFinalize < engineError
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" errorSection) @?= 1

  candidateFinalize <- expectMainSourcePosition "candidate diagnostic"
    "disposition <- finalizeSynthLaneAccumulation st args goal"
      candidateSection
  candidateGate <- expectMainSourcePosition "candidate diagnostic"
    "case disposition of" candidateSection
  candidateDiagnostic <- expectMainSourcePosition "candidate diagnostic"
    "the engine proposed " candidateSection
  candidateNotes <- expectMainSourcePosition "candidate diagnostic"
    "reportSynthLaneNotes st (synthLaneRunNotes laneRun)" candidateSection
  assertBool "candidate miss text escaped the aggregate NoVerified gate"
    $ candidateFinalize < candidateGate
      && candidateGate < candidateDiagnostic
      && candidateDiagnostic < candidateNotes
  mapM_ (assertMainSourceContains "candidate diagnostic gate"
      candidateSection)
    [ "SynthLaneSurvivors _ _ -> pure ()"
    , "SynthLaneAllBehaviorallyRejected _ -> pure ()"
    , "SynthLaneAssessmentPreserved _ _ -> pure ()"
    ]
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" candidateSection) @?= 1
  length (mainSourcePositions
      "reportSynthLaneNotes" candidateSection) @?= 1

  unsoundFinalize <- expectMainSourcePosition "unsound-refutation diagnostic"
    "disposition <- finalizeSynthLaneAccumulation" unsoundSection
  unsoundGate <- expectMainSourcePosition "unsound-refutation diagnostic"
    "case disposition of" unsoundSection
  unsoundDiagnostic <- expectMainSourcePosition "unsound-refutation diagnostic"
    "no term found within bounds" unsoundSection
  assertBool "unsound-refutation text escaped the aggregate NoVerified gate"
    $ unsoundFinalize < unsoundGate && unsoundGate < unsoundDiagnostic
  mapM_ (assertMainSourceContains "unsound-refutation diagnostic gate"
      unsoundSection)
    [ "SynthLaneSurvivors _ _ -> pure ()"
    , "SynthLaneAllBehaviorallyRejected _ -> pure ()"
    , "SynthLaneAssessmentPreserved _ _ -> pure ()"
    ]
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" unsoundSection) @?= 1

  noTermFinalize <- expectMainSourcePosition "bounded-miss diagnostic"
    "disposition <- finalizeSynthLaneAccumulation" noTermSection
  noTermGate <- expectMainSourcePosition "bounded-miss diagnostic"
    "case disposition of" noTermSection
  noTermDiagnostic <- expectMainSourcePosition "bounded-miss diagnostic"
    "no term found within the search bounds" noTermSection
  noTermNotes <- expectMainSourcePosition "bounded-miss diagnostic"
    "reportSynthLaneNotes st (synthLaneRunNotes laneRun)" noTermSection
  assertBool "bounded miss text or notes escaped the aggregate NoVerified gate"
    $ noTermFinalize < noTermGate
      && noTermGate < noTermDiagnostic
      && noTermDiagnostic < noTermNotes
  mapM_ (assertMainSourceContains "bounded-miss diagnostic gate"
      noTermSection)
    [ "SynthLaneSurvivors _ _ -> pure ()"
    , "SynthLaneAllBehaviorallyRejected _ -> pure ()"
    , "SynthLaneAssessmentPreserved _ _ -> pure ()"
    ]
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" noTermSection) @?= 1
  length (mainSourcePositions
      "reportSynthLaneNotes" noTermSection) @?= 1

  classicalRetry <- expectMainSourcePosition "sound-refutation diagnostic"
    "then synthClassical assessmentContext runDeadline"
      soundSection
  soundFinalize <- expectMainSourcePosition "sound-refutation diagnostic"
    "classical <- finalizeSynthLaneAccumulation" soundSection
  let classicalGates = mainSourcePositions "case classical of" soundSection
  firstGate <- case classicalGates of
    first : _ -> pure first
    [] -> assertFailure "Main omitted the sound-refutation result gate"
      >> error "unreachable"
  secondGate <- case classicalGates of
    _ : second : _ -> pure second
    _ -> assertFailure "Main omitted the constructive-hint result gate"
      >> error "unreachable"
  uninhabited <- expectMainSourcePosition "sound-refutation diagnostic"
    "provably uninhabited" soundSection
  retryAnnotation <- expectMainSourcePosition "sound-refutation diagnostic"
    "forM_ retriedVars" soundSection
  constructiveHint <- expectMainSourcePosition "sound-refutation diagnostic"
    "constructively" soundSection
  assertBool "sound-refutation gates changed aggregate handling or retry notes"
    $ classicalRetry < soundFinalize
      && soundFinalize < firstGate
      && firstGate < uninhabited
      && uninhabited < retryAnnotation
      && retryAnnotation < secondGate
      && secondGate < constructiveHint
  length (mainSourcePositions
      "SynthLaneAllBehaviorallyRejected _ -> pure ()" soundSection) @?= 2
  length (mainSourcePositions
      "SynthLaneSurvivors _ _ -> pure ()" soundSection) @?= 2
  length (mainSourcePositions
      "SynthLaneAssessmentPreserved _ _ -> pure ()" soundSection) @?= 2
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" soundSection) @?= 1

  mapM_ (assertMainSourceContains "structural fallback" providerFinishSection)
    [ "case fallback of"
    , "Just fallbackRun -> report runDeadline"
    , "fallbackRun { synthLaneRunAccumulation = synthLaneRunAccumulation fresh }"
    , "Nothing -> report runDeadline fresh"
    ]
  assertBool "structural fallback copied a provider-side terminal reason"
    $ not ("synthLaneRunEnd =" `isInfixOf` unlines providerFinishSection)
  mapM_ (assertMainSourceContains "terminal candidate routing" reportSection)
    [ "synthLaneRunEnd = SynthLaneRunTimedOut"
    , "synthLaneRunEnd = SynthLaneRunCursorAdmissionFailed err"
    , "synthLaneRunEnd = SynthLaneRunEngineFailed err"
    , "synthLaneRunEnd = SynthLaneRunRefuted sound"
    , "synthLaneRunEnd = SynthLaneRunNoTerm"
    , "synthLaneRunEnd = SynthLaneRunStoppedByDisposition"
    , "report _ laneRun = reportCandidateCompletion laneRun"
    ]
  mapM_ (\ordinaryEnd -> assertBool
      ("ordinary cursor completion acquired a bespoke report branch "
        ++ ordinaryEnd)
      $ not $ ("synthLaneRunEnd = " ++ ordinaryEnd)
        `isInfixOf` unlines reportSection)
    [ "SynthLaneRunBatchPolicyReached"
    , "SynthLaneRunNaturallyExhausted"
    , "SynthLaneRunHardCapReached"
    ]
  length (mainSourcePositions
      "report _ laneRun = reportCandidateCompletion laneRun"
      reportSection) @?= 1
  assertMainSourceContains "terminal disposition finalization"
    stoppedSection "finalize (synthLaneRunAccumulation laneRun)"
  length (mainSourcePositions
      "finalizeSynthLaneAccumulation" finalizeSection) @?= 1

assertLengthAssessmentMainCommandAdmission :: IO ()
assertLengthAssessmentMainCommandAdmission = do
  sourceLines <- lines <$> readFile "src/Main.hs"
  let requestSection = mainSourceSection
        "lengthAssessmentRequestForCommand state command"
        "synthRun ::" sourceLines
  authorization <- expectMainSourcePosition "request boundary"
    "authorizeExplicitLengthAssessmentRequest behavior mode" requestSection
  admission <- expectMainSourcePosition "request boundary"
    "mkLengthContractFileRequest" requestSection
  acquisition <- expectMainSourcePosition "request boundary"
    "loadLengthContractFile" requestSection
  assertBool "one-shot filtering can touch its path before authorization"
    $ authorization < admission && admission < acquisition

assertLengthAssessmentSetupAdmission :: IO ()
assertLengthAssessmentSetupAdmission = do
  loaded <- loadLengthAssessmentMode
    (error "Length setup admission forced its activation policy")
    $ LengthRankingConfigurationFileSource
        "relative-length-ranking.json"
        (error "Length setup admission forced its timeout")
  case loaded of
    Left failure -> failure @?= LengthAssessmentFileAdmissionRejected
      LengthRankingConfigurationFilePathNotAbsolute
    Right _ -> assertFailure
      "relative Length assessment configuration reached acquisition"
  if os == "mingw32"
    then pure ()
    else withTemporaryDirectory "leant-length-integration-load" $ \root -> do
      missing <- loadLengthAssessmentMode
        (error "Length setup load failure forced its activation policy")
        $ LengthRankingConfigurationFileSource
            (root </> "missing-length-ranking.json") 1000
      case missing of
        Left (LengthAssessmentFileLoadRejected failure) ->
          lengthRankingConfigurationFileLoadErrorClass failure @?=
            LengthRankingConfigurationFileOpenFailed
        Left failure -> assertFailure $ "unexpected setup failure: " ++
          show failure
        Right _ -> assertFailure
          "missing Length assessment configuration reached activation"

assertLengthAssessmentConfigured :: IO ()
assertLengthAssessmentConfigured
  | os == "mingw32" = pure ()
  | otherwise =
      whenDescriptorBoundExecveCheckLaunchPubliclyReachable $ do
      fixture <- buildLengthRankingLiveFixture
      retained <- syntheticLengthRankingCandidate "integration-retained"
      withFakeLengthSolver "healthy" $ \executable -> do
        let sourcePath = takeDirectory executable </>
              "length-assessment-integration.json"
            zero = lengthRankingFixtureZero fixture
            one = lengthRankingFixtureOne fixture
            contract = jsonCurrentLengthContract
              (jsonLengthTruth True)
              (jsonLengthEqual jsonLengthResult $ jsonLengthLiteral 2)
              [ jsonLengthProviderLaw "Demo.zeroList" []
                  $ jsonLengthLiteral 0
              , jsonLengthProviderLaw "Demo.oneList" []
                  $ jsonLengthLiteral 1
              ]
            document = setJsonField ["contract"] contract
              $ setJsonField ["execution", "artifactPolicy"]
                  (Json.JStr "input-values-after-satisfiable")
              $ lengthRankingConfigurationFileFixture executable Nothing
        ByteString.writeFile sourcePath
          $ encodeLengthRankingConfigurationFile document

        requirePinned <- loadLengthAssessmentMode RequirePinnedExecutable
          $ LengthRankingConfigurationFileSource sourcePath 1000
        case requirePinned of
          Left failure -> failure @?= LengthAssessmentActivationRejected
            LengthRankingConfigurationExecutablePinRequired
          Right _ -> assertFailure
            "an unpinned integration configuration was activated implicitly"

        let pinnedDocument = setJsonField
              ["execution", "expectedExecutableSha256"]
              (Json.JStr $ replicate 64 '0') document
        ByteString.writeFile sourcePath
          $ encodeLengthRankingConfigurationFile pinnedDocument
        pinnedRequired <- loadLengthAssessmentMode RequirePinnedExecutable
          $ LengthRankingConfigurationFileSource sourcePath 1000
        requiredMode <- case pinnedRequired of
          Left failure -> assertFailure
            ("pinned Length assessment setup failed: " ++ show failure)
              >> error "unreachable"
          Right configured -> pure configured
        lengthAssessmentModeActivationPolicy requiredMode @?=
          Just RequirePinnedExecutable

        pinnedPermitted <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource sourcePath 1000
        permittedPinnedMode <- case pinnedPermitted of
          Left failure -> assertFailure
            ("relaxed pinned Length assessment setup failed: " ++ show failure)
              >> error "unreachable"
          Right configured -> pure configured
        lengthAssessmentModeActivationPolicy permittedPinnedMode @?=
          Just PermitUnpinnedExecutable

        ByteString.writeFile sourcePath
          $ encodeLengthRankingConfigurationFile document
        loaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource sourcePath 1000
        mode <- case loaded of
          Left failure -> assertFailure
            ("Length assessment setup failed: " ++ show failure)
              >> error "unreachable"
          Right configured -> pure configured
        lengthAssessmentModeActivationPolicy mode @?=
          Just PermitUnpinnedExecutable
        doesFileExist (executable ++ ".events") >>= (@?= False)

        verification <- verificationBatchFromReceipts [zero, retained, one]
        assessed <- expectLengthAssessmentWithin
          $ assessLengthVerificationBatch mode verification
        lengthAssessmentFailure assessed @?= Nothing
        lengthAssessmentCandidates assessed @?= [retained, zero, one]
        _ <- case lengthAssessmentRanking assessed of
          Nothing -> assertFailure
            "enabled Length assessment discarded its compatibility ranking"
              >> error "unreachable"
          Just value -> pure value
        let presentations = presentLengthAssessment assessed
        map lengthCandidatePresentationText presentations @?=
          map (detailedVerificationVariantText . verifiedCandidate)
            [retained, zero, one]
        map (fmap (const True) . lengthCandidatePresentationNote)
            presentations @?=
          [Nothing, Just True, Just True]
        map lengthCandidatePresentationText presentations @?=
          map lengthCandidatePresentationText
            (presentLengthPostVerificationResult
              $ fromMaybe (error "configured presentation lost its result")
              $ lengthAssessmentPostVerificationResult assessed)
        assertLengthPresentationAssociations presentations [Nothing, Just 0,
          Just 1]
        case lengthAssessmentPostVerificationResult assessed of
          Nothing -> assertFailure
            "enabled Length assessment bypassed post-verification sealing"
          Just result -> assertLengthPostVerificationSealed result

        let firstEvents = executable ++ ".events"
            retainedEvents = executable ++ ".events.first"
        doesFileExist firstEvents >>= (@?= True)
        renameFile firstEvents retainedEvents
        ByteString.writeFile sourcePath $ BS.pack "{}"
        repeated <- expectLengthAssessmentWithin
          $ assessLengthVerificationBatch mode verification
        lengthAssessmentFailure repeated @?= Nothing
        lengthAssessmentCandidates repeated @?= [retained, zero, one]
        doesFileExist retainedEvents >>= (@?= True)
        doesFileExist firstEvents >>= (@?= True)

        let maximumCandidates =
              Djex.defaultLengthSMTLibLiveSessionMaximumQueries
            oversizedCount = fromIntegral maximumCandidates + 1
        oversized <- verificationBatchFromReceipts
          $ replicate oversizedCount zero
        rejected <- expectLengthAssessmentWithin
          $ assessLengthVerificationBatch mode oversized
        case lengthAssessmentFailure rejected of
          Just (LengthAssessmentPostVerificationFailed
              (LengthPostVerificationInputRejected
                (LengthRankingInputLimitExceeded maximumValue observed))) ->
                  (maximumValue, observed) @?=
                    (maximumCandidates, maximumCandidates + 1)
          failure -> assertFailure $ "unexpected integration rejection: " ++
            show failure
        lengthAssessmentCandidates rejected @?=
          verifiedCandidateReceipts oversized
        assertBool "rejected integration input retained a ranking"
          $ isNothing $ lengthAssessmentRanking rejected
        assertBool "rejected integration input exposed semantic notes"
          $ all (isNothing . lengthCandidatePresentationNote)
              (presentLengthAssessment rejected)
        case lengthAssessmentPostVerificationResult rejected of
          Nothing -> assertFailure
            "enabled input rejection discarded its adapter result"
          Just result -> do
            assertBool "rejected integration input acquired a sealed batch"
              $ isNothing $ lengthPostVerificationSealedBatch result
            assertBool "rejected integration input acquired a ranking"
              $ isNothing $ lengthPostVerificationRanking result

assertLengthAssessmentExplicitContracts :: IO ()
assertLengthAssessmentExplicitContracts
  | os == "mingw32" = pure ()
  | otherwise =
      whenDescriptorBoundExecveCheckLaunchPubliclyReachable $ do
      fixture <- buildLengthRankingLiveFixture
      retained <- syntheticLengthRankingCandidate
        "one-shot-contract-retained"
      withFakeLengthSolver "healthy" $ \executable -> do
        let configurationPath = takeDirectory executable </>
              "length-request-policy.json"
            contractPath = takeDirectory executable </>
              "length-request-contract.json"
            fixedContract = jsonCurrentLengthContract
              (jsonLengthTruth True)
              (jsonLengthEqual jsonLengthResult $ jsonLengthLiteral 2)
              [ jsonLengthProviderLaw "Demo.zeroList" []
                  $ jsonLengthLiteral 0
              , jsonLengthProviderLaw "Demo.oneList" []
                  $ jsonLengthLiteral 1
              ]
            document = setJsonField ["contract"] fixedContract
              $ setJsonField ["execution", "artifactPolicy"]
                  (Json.JStr "input-values-after-satisfiable")
              $ lengthRankingConfigurationFileFixture executable Nothing
        ByteString.writeFile configurationPath
          $ encodeLengthRankingConfigurationFile document
        loaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource configurationPath 1000
        mode <- case loaded of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right configured -> pure configured
        permission <- case authorizeExplicitLengthAssessmentRequest
            LengthBehaviorRank mode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right authorized -> pure authorized
        let writeContract expected = ByteString.writeFile contractPath
              $ encodeLengthRankingConfigurationFile
              $ lengthContractFileFixture "scalar"
              $ jsonCurrentLengthContract
                  (jsonLengthTruth True)
                  (jsonLengthEqual jsonLengthResult
                    $ jsonLengthLiteral expected)
                  [ jsonLengthProviderLaw "Demo.zeroList" []
                      $ jsonLengthLiteral 0
                  , jsonLengthProviderLaw "Demo.oneList" []
                      $ jsonLengthLiteral 1
                  ]
            loadContract = do
              request <- case mkLengthContractFileRequest
                  $ LengthContractFileSource contractPath 1000 of
                Left failure ->
                  assertFailure (show failure) >> error "unreachable"
                Right admitted -> pure admitted
              loadedContract <- loadLengthContractFile request
              case loadedContract of
                Left failure ->
                  assertFailure (show failure) >> error "unreachable"
                Right contract -> pure contract
            writeModuloContract = ByteString.writeFile contractPath
              $ encodeLengthRankingConfigurationFile
              $ lengthContractFileFixture "scalar"
              $ jsonCurrentLengthContract
                  (jsonLengthTruth True)
                  (jsonLengthEqual jsonLengthResult
                    $ jsonLengthModulo 5 $ jsonLengthLiteral 2)
                  [ jsonLengthProviderLaw "Demo.zeroList" []
                      $ jsonLengthModulo 2 $ jsonLengthLiteral 2
                  , jsonLengthProviderLaw "Demo.oneList" []
                      $ jsonLengthModulo 2 $ jsonLengthLiteral 3
                  ]
        writeContract 0
        firstContract <- loadContract
        writeContract 1
        secondContract <- loadContract
        writeModuloContract
        moduloContract <- loadContract
        -- All request values must remain self-contained after their source
        -- has changed again; no later batch may reopen the command path.
        ByteString.writeFile contractPath $ BS.pack "{"
        let zero = lengthRankingFixtureZero fixture
        verification <- verificationBatchFromReceipts
          [zero, retained]
        first <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission
                firstContract)
              verification
        second <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission
                secondContract)
              verification
        modulo <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission
                moduloContract)
              verification
        startupRequest <- expectRight $ startupLengthAssessmentRequest
          LengthBehaviorRank mode
        startup <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              startupRequest
              verification
        repeatedFirst <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission
                firstContract)
              verification
        lengthAssessmentCandidates first @?= [zero, retained]
        lengthAssessmentCandidates second @?= [retained, zero]
        lengthAssessmentCandidates modulo @?= [retained, zero]
        lengthAssessmentCandidates startup @?= [retained, zero]
        lengthAssessmentCandidates repeatedFirst @?= [zero, retained]
        case lengthAssessmentFailure first of
          Just (LengthAssessmentRankingFailed failure) ->
            lengthRankingFailureClass failure @?=
              LengthRankingLiveQueryFailed
                Djex.LengthSMTLibLiveQueryCounterexampleRejected
          failure -> assertFailure $ "unexpected first one-shot outcome: " ++
            show failure
        lengthAssessmentFailure repeatedFirst @?=
          lengthAssessmentFailure first
        map lengthAssessmentFailure [second, modulo, startup] @?=
          [Nothing, Nothing, Nothing]
        let presentationText = map lengthCandidatePresentationText .
              presentLengthAssessment
            renderReceipt = detailedVerificationVariantText . verifiedCandidate
        presentationText first @?= map renderReceipt [zero, retained]
        presentationText second @?= map renderReceipt [retained, zero]
        presentationText modulo @?= map renderReceipt [retained, zero]
        assertLengthPresentationAssociations
          (presentLengthAssessment modulo) [Nothing, Just 0]
        presentationText startup @?= map renderReceipt [retained, zero]
        presentationText repeatedFirst @?= map renderReceipt [zero, retained]
        mapM_ (\assessed ->
          case lengthAssessmentPostVerificationResult assessed of
            Nothing -> assertFailure
              "enabled command-local assessment bypassed its occurrence seal"
            Just result -> assertLengthPostVerificationSealed result)
          [first, second, modulo, startup, repeatedFirst]
        let maximumCandidates =
              Djex.defaultLengthSMTLibLiveSessionMaximumQueries
            oversizedCount = fromIntegral maximumCandidates + 1
        oversized <- verificationBatchFromReceipts
          $ replicate oversizedCount (lengthRankingFixtureZero fixture)
        rejected <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission
                $ error "maximum-plus-one forced one-shot contract")
              oversized
        case lengthAssessmentFailure rejected of
          Just (LengthAssessmentPostVerificationFailed
              (LengthPostVerificationInputRejected
                (LengthRankingInputLimitExceeded maximumValue observed))) ->
                  (maximumValue, observed) @?=
                    (maximumCandidates, maximumCandidates + 1)
          failure -> assertFailure $ "unexpected one-shot rejection: " ++
            show failure
        lengthAssessmentCandidates rejected @?=
          verifiedCandidateReceipts oversized
        assertBool "one-shot maximum-plus-one retained a ranking"
          $ isNothing $ lengthAssessmentRanking rejected

assertLengthAssessmentRoleAwareMap :: IO ()
assertLengthAssessmentRoleAwareMap
  | os == "mingw32" = pure ()
  | otherwise =
      whenDescriptorBoundExecveCheckLaunchPubliclyReachable $ do
      (contract, verified) <- buildRoleAwareMapFixture
      problem <- expectRight $ prepareCheckedLengthProblem contract verified
      checkedLengthCandidateResult (checkedLengthProblemCandidate problem) @?=
        LengthVariable (LengthInput 0)
      length (checkedLengthCandidateUsedProviders
        $ checkedLengthProblemCandidate problem) @?= 1
      query <- expectRight (prepareCheckedLengthQuery contract verified)
        >>= expectRight
      map (map $ toEnum . fromIntegral)
          (lengthSMTLibQueryInputSymbols query) @?=
        (["djex_length_input_0"] :: [String])
      assertBool "role-aware map query omitted its compact get-value request"
        $ case lengthSMTLibQueryInputValueRequestBytes query of
            Just bytes -> not $ null bytes
            Nothing -> False

      quotientContract <- expectLengthScalarContract
        $ lengthContractFileFixture "scalar"
            roleAwareMapQuotientContractValue
      leanLengthContractCandidateCasePolicy quotientContract @?=
        LeanLengthCasesRejected
      quotientProblem <- expectRight
        $ prepareCheckedLengthProblem quotientContract verified
      checkedLengthCandidateResult
          (checkedLengthProblemCandidate quotientProblem) @?=
        LengthVariable (LengthInput 0)
      quotientQuery <- expectRight
          (prepareCheckedLengthQuery quotientContract verified)
        >>= expectRight
      let quotientCheck = map (toEnum . fromIntegral)
            $ lengthSMTLibQueryCheckBytes quotientQuery
      lengthSMTLibQueryLogic @?= map (fromIntegral . fromEnum) "QF_LIA"
      assertBool "role-aware quotient query did not select QF_LIA"
        $ "(set-logic QF_LIA)\n" `isInfixOf` quotientCheck
      assertBool "role-aware query omitted the quotient witness"
        $ "djex_length_quotient_quotient_0" `isInfixOf` quotientCheck
      assertBool "role-aware query omitted the quotient remainder"
        $ "djex_length_quotient_remainder_0" `isInfixOf` quotientCheck
      assertBool "role-aware query delegated quotient to SMT div"
        $ not $ "(div " `isInfixOf` quotientCheck
      quotientSymbol <- case lengthSMTLibQueryInputSymbols quotientQuery of
        [retained] -> pure retained
        symbols -> assertFailure
          ("role-aware query retained unexpected inputs: " ++ show symbols)
            >> error "unreachable"
      quotientEvidence <- case validateLengthSMTLibCounterexample
          defaultLengthEvaluationLimits quotientQuery
          [Djex.LengthSMTLibIntegerBinding quotientSymbol 3] of
        Left failure -> assertFailure
          ("role-aware quotient replay failed: " ++ show failure)
            >> error "unreachable"
        Right Nothing -> assertFailure
          "the role-aware quotient violation produced no evidence"
            >> error "unreachable"
        Right (Just retained) -> pure retained
      quotientReceipt <- expectRight $ Djex.replayBehavioralEvidence
        (checkedLengthProblemBehavioralProblem quotientProblem)
        quotientEvidence
      Djex.validatedLengthCounterexampleInputs quotientReceipt @?= [3]
      Djex.validatedLengthCounterexampleResult quotientReceipt @?= 3

      let oneRole = contract
            { leanLengthContractTargetArgumentRoles =
                [LengthObservedSpine]
            }
          swapped = contract
            { leanLengthContractTargetArgumentRoles =
                [LengthObservedSpine, LengthUnobservedTarget]
            }
          cyclicRoles = LengthUnobservedTarget : cyclicRoles
          cyclic = contract
            { leanLengthContractTargetArgumentRoles = cyclicRoles }
          badSpine = contract
            { leanLengthContractSpine =
                (leanLengthContractSpine contract)
                  { leanLengthSpineFamilyName = "Unreachable.List" }
            }
          badProvider = contract
            { leanLengthContractProviderLaws =
                [ law { leanLengthProviderLawName = "Demo.missingMap" }
                | law <- leanLengthContractProviderLaws contract
                ]
            }
      case prepareCheckedLengthProblem badSpine verified of
        Left (LengthHandoffFamilyUnavailable "Unreachable.List") -> pure ()
        Left refusal -> assertFailure $ "unexpected bad-spine refusal: "
          ++ show refusal
        Right _ -> assertFailure "unavailable spine family reached sealing"
      case prepareCheckedLengthProblem badProvider verified of
        Left (LengthHandoffProviderUnavailable "Demo.missingMap") -> pure ()
        Left refusal -> assertFailure $ "unexpected bad-provider refusal: "
          ++ show refusal
        Right _ -> assertFailure "unavailable provider reached sealing"
      case prepareCheckedLengthProblem oneRole verified of
        Left (LengthHandoffContractRejected
            (Djex.LengthContractTargetArgumentRoleArityMismatch 2 1)) ->
          pure ()
        Left refusal -> assertFailure $ "unexpected target-role arity refusal: "
          ++ show refusal
        Right _ -> assertFailure "a short target-role vector reached sealing"
      case prepareCheckedLengthProblem swapped verified of
        Left (LengthHandoffContractRejected
            (Djex.LengthContractInputIsNotList 0 _)) -> pure ()
        Left refusal -> assertFailure $ "unexpected swapped-role refusal: "
          ++ show refusal
        Right _ -> assertFailure
          "an observed higher-order target argument became a list spine"
      case prepareCheckedLengthProblem cyclic verified of
        Left (LengthHandoffSessionRejected
            (LengthSessionTargetArgumentRoleLimitExceeded 8 9)) -> pure ()
        Left refusal -> assertFailure $ "unexpected cyclic-role refusal: "
          ++ show refusal
        Right _ -> assertFailure "a cyclic target-role vector reached sealing"

      withFakeLengthSolver "healthy" $ \executable -> do
        let configurationPath = takeDirectory executable </>
              "role-aware-map-policy.json"
            contractPath = takeDirectory executable </>
              "role-aware-map-contract.json"
            fixedContract = jsonCurrentLengthContract
              (jsonLengthTruth True) (jsonLengthTruth True) []
            configuration = setJsonField ["contract"] fixedContract
              $ setJsonField ["execution", "artifactPolicy"]
                  (Json.JStr "input-values-after-satisfiable")
              $ lengthRankingConfigurationFileFixture executable Nothing
            roleAwareDocument = lengthContractFileFixture "scalar"
              roleAwareMapQuotientContractValue
        ByteString.writeFile configurationPath
          $ encodeLengthRankingConfigurationFile configuration
        loadedMode <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource configurationPath 1000
        mode <- case loadedMode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right configured -> pure configured
        permission <- case authorizeExplicitLengthAssessmentRequest
            LengthBehaviorRank mode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right authorized -> pure authorized
        ByteString.writeFile contractPath
          $ encodeLengthRankingConfigurationFile roleAwareDocument
        request <- case mkLengthContractFileRequest
            $ LengthContractFileSource contractPath 1000 of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right admitted -> pure admitted
        loadedContract <- loadLengthContractFile request >>= either
          (\failure -> assertFailure (show failure) >> error "unreachable")
          pure
        loadedContract @?=
          LeanLengthScalarContractSelection quotientContract
        -- The decoded request owns its passive quotient contract. Neither
        -- the first assessment nor a later reuse may reopen the one-shot path,
        -- and the startup request cannot inherit its grammar or
        -- explicit case-rejecting policy.
        ByteString.writeFile contractPath $ BS.pack "{"
        verification <- verificationBatchFromReceipts [verified]
        let explicitRequest = explicitLengthAssessmentRequest
              permission loadedContract
        startupRequest <- expectRight $ startupLengthAssessmentRequest
          LengthBehaviorRank mode
        assessed <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest explicitRequest verification
        startup <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              startupRequest verification
        repeated <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest explicitRequest verification
        map lengthAssessmentFailure [assessed, startup, repeated] @?=
          [Nothing, Nothing, Nothing]
        map lengthAssessmentCandidates [assessed, startup, repeated] @?=
          [[verified], [verified], [verified]]
        map rankedLengthCandidateAssessment
            (maybe (error "role-aware assessment lost its ranking")
              lengthRankingCandidates $ lengthAssessmentRanking assessed) @?=
          [Counterexample $ roleAwareMapReceipt assessed]
        Djex.validatedLengthCounterexampleInputs
            (roleAwareMapReceipt assessed) @?= [3]
        Djex.validatedLengthCounterexampleResult
            (roleAwareMapReceipt assessed) @?= 3
        map rankedLengthCandidateAssessment
            (maybe (error "startup assessment lost its ranking")
              lengthRankingCandidates
              $ lengthAssessmentRanking startup) @?= [Unassessed]
        map lengthCandidatePresentationNote
            (presentLengthAssessment startup) @?= [Nothing]
        let notes = map lengthCandidatePresentationNote
              $ presentLengthAssessment assessed
        case notes of
          [Just note] -> do
            assertBool "role-aware presentation lost the compact input"
              $ "observed input spine lengths = [3]" `isInfixOf` note
            assertBool "role-aware presentation lost model qualification"
              $ "model-relative" `isInfixOf` note
            assertBool "role-aware presentation lost the replayed result"
              $ "result spine length = 3" `isInfixOf` note
            assertBool "role-aware presentation overstated provider trust"
              $ "conditional on 1 assumed provider law" `isInfixOf` note
            assertBool "role-aware presentation exposed the provider name"
              $ not $ "Demo.mapList" `isInfixOf` note
          other -> assertFailure $ "unexpected role-aware presentation: "
            ++ show other
        map rankedLengthCandidateAssessment
            (maybe (error "repeated assessment lost its ranking")
              lengthRankingCandidates $ lengthAssessmentRanking repeated) @?=
          [Counterexample $ roleAwareMapReceipt repeated]
 where
  roleAwareMapReceipt assessed = case lengthAssessmentRanking assessed of
    Just ranking -> case map rankedLengthCandidateAssessment
        $ lengthRankingCandidates ranking of
      [Counterexample receipt] -> receipt
      assessments -> error $ "unexpected role-aware assessments: "
        ++ show assessments
    Nothing -> error "role-aware assessment retained no ranking"

roleAwareMapContractValue :: Json.JValue
roleAwareMapContractValue = addJsonField []
  ("candidateCasePolicy", Json.JStr "cases-rejected")
  $ jsonRoleAwareLengthContract
      ["unobserved-target", "observed-spine"]
      (jsonLengthTruth True)
      (jsonLengthEqual jsonLengthResult $ jsonLengthLiteral 0)
      [ jsonLengthProviderLaw "Demo.mapList" ["unobserved", "spine"]
          $ jsonLengthArgument 1
      ]

roleAwareMapQuotientContractValue :: Json.JValue
roleAwareMapQuotientContractValue = addJsonField []
  ("candidateCasePolicy", Json.JStr "cases-rejected")
  $ jsonRoleAwareLengthContract
      ["unobserved-target", "observed-spine"]
      (jsonLengthTruth True)
      (jsonLengthEqual jsonLengthResult
        $ jsonLengthQuotient 2 $ jsonLengthInput 0)
      [ jsonLengthProviderLaw "Demo.mapList" ["unobserved", "spine"]
          $ jsonLengthArgument 1
      ]

buildRoleAwareMapFixture
  :: IO (LeanLengthContract, Verified DetailedVerificationVariant)
buildRoleAwareMapFixture = do
  let alpha = FVar "alpha"
      beta = FVar "beta"
      source = FVar "source"
      targetElement = FVar "target"
      list key element = FParamRec True "List" key [element]
        [ ("List.nil", [])
        , ("List.cons", [element, FAtom False key])
        ]
      mapType sourceKey resultKey sourceType resultType =
        FArr (FArr sourceType resultType)
          $ FArr (list sourceKey sourceType) (list resultKey resultType)
      target = FAll False "alpha" $ FAll False "beta"
        $ mapType "List alpha" "List beta" alpha beta
      providerScheme = FAll False "source" $ FAll False "target"
        $ mapType "List source" "List target" source targetElement
      provider = ProviderFrag "Demo.mapList" providerScheme
  preparation <- expectRight $ inspectExferencePreparation
    [provider] [] target target
  contract <- expectLengthScalarContract
    $ lengthContractFileFixture "scalar" roleAwareMapContractValue
  production <- expectRight $ synthesizeWithProvidersSkippingDetailed
    EngineExference 512 Set.empty [provider] target
  explicitProduction <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      True EngineExference 512 Set.empty [provider] target
  explicitProduction @?= production
  detailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      False EngineExference 512 Set.empty [provider] target
  (origin, acceptedSpelling) <- case detailed of
    DetailedSynthCandidates groups _ -> case
        [ (group, spelling)
        | group <- groups
        , spelling <- detailedCandidateGroupVariants group
        , "Demo.mapList" `isInfixOf` spelling
        , isJust (detailedCandidateGroupSemanticSidecar group)
        ] of
      match : _ -> pure match
      [] -> assertFailure ("higher-order map provider produced no typed " ++
        "origin: " ++ show
          [ ( detailedCandidateGroupVariants group
            , detailedCandidateGroupRoute group
            , isNothing $ detailedCandidateGroupSemanticSidecar group
            )
          | group <- groups
          ]) >> error "unreachable"
    other -> assertFailure ("higher-order map synthesis failed: " ++
      show other) >> error "unreachable"
  batch <- verifyCandidateGroups 1
    (\variant -> pure $ if detailedVerificationVariantText variant
        == acceptedSpelling
      then VariantAccepted
      else VariantRejected LeanErrorDiagnostic)
    [detailedCandidateGroupVerificationVariants origin]
  case verifiedCandidateReceipts batch of
    [verified] -> do
      problem <- expectRight $ prepareCheckedLengthProblem contract verified
      case inspectedProviderBindings preparation of
        [binding] -> checkedLengthCandidateUsedProviders
            (checkedLengthProblemCandidate problem) @?=
          [inspectedProviderPrivateName binding]
        bindings -> assertFailure ("role-aware map retained unexpected " ++
          "provider bindings: " ++ show bindings)
      pure (contract, verified)
    receipts -> assertFailure ("higher-order map verification produced " ++
      show (length receipts) ++ " receipts") >> error "unreachable"

assertLengthAssessmentExactSpineCase :: IO ()
assertLengthAssessmentExactSpineCase
  | os == "mingw32" = pure ()
  | otherwise =
      whenDescriptorBoundExecveCheckLaunchPubliclyReachable $ do
      (casesRejectedContract, exactContract, verified) <-
        buildExactSpineCaseFixture
      leanLengthContractCandidateCasePolicy casesRejectedContract @?=
        LeanLengthCasesRejected
      leanLengthContractCandidateCasePolicy exactContract @?=
        LeanLengthExactSpineZeroStepV1
      case prepareCheckedLengthProblem casesRejectedContract verified of
        Left (LengthHandoffRendererNotUnique 2) -> pure ()
        Left refusal -> assertFailure $ "unexpected case-policy refusal: "
          ++ show refusal
        Right _ -> assertFailure
          "cases-rejected relaxed the singleton renderer rule"
      let unresolvedFamily = exactContract
            { leanLengthContractSpine =
                (leanLengthContractSpine exactContract)
                  { leanLengthSpineFamilyName = "Unreachable.List" }
            }
          unresolvedProvider = exactContract
            { leanLengthContractProviderLaws =
                [ LeanLengthProviderLaw
                    { leanLengthProviderLawName = "Demo.missingListProvider"
                    , leanLengthProviderLawArgumentRoles = []
                    , leanLengthProviderLawTransfer = LengthLiteral 0
                    }
                ]
            }
      case prepareCheckedLengthProblem unresolvedFamily verified of
        Left (LengthHandoffFamilyUnavailable "Unreachable.List") -> pure ()
        Left refusal -> assertFailure $ "unexpected exact bad-family refusal: "
          ++ show refusal
        Right _ -> assertFailure
          "exact policy admitted an unavailable family"
      case prepareCheckedLengthProblem unresolvedProvider verified of
        Left (LengthHandoffProviderUnavailable
            "Demo.missingListProvider") -> pure ()
        Left refusal -> assertFailure $
          "unexpected exact bad-provider refusal: " ++ show refusal
        Right _ -> assertFailure
          "exact policy admitted an unavailable provider"
      problem <- expectRight
        $ prepareCheckedLengthProblem exactContract verified
      checkedLengthCandidateResult
          (checkedLengthProblemCandidate problem) @?=
        LengthIf
          (LengthEqual (LengthVariable $ LengthInput 0) $ LengthLiteral 0)
          (LengthLiteral 0)
          (LengthSum
            [ LengthLiteral 1
            , LengthMonus (LengthVariable $ LengthInput 0)
                (LengthLiteral 1)
            ])
      query <- expectRight
          (prepareCheckedLengthQuery exactContract verified)
        >>= expectRight
      let quotientCheck = map (toEnum . fromIntegral)
            $ lengthSMTLibQueryCheckBytes query
      lengthSMTLibQueryLogic @?= map (fromIntegral . fromEnum) "QF_LIA"
      assertBool "exact query omitted its quotient witness"
        $ "djex_length_quotient_quotient_0" `isInfixOf` quotientCheck
      assertBool "exact query omitted its quotient remainder"
        $ "djex_length_quotient_remainder_0" `isInfixOf` quotientCheck
      assertBool "exact query delegated quotient to SMT div"
        $ not $ "(div " `isInfixOf` quotientCheck
      symbol <- case lengthSMTLibQueryInputSymbols query of
        [retained] -> pure retained
        symbols -> assertFailure ("exact case query retained unexpected inputs: "
          ++ show symbols) >> error "unreachable"
      let bytes = map $ fromIntegral . fromEnum
      bindings <- expectRight $ Djex.parseLengthSMTLibInputValueResponse
        Djex.defaultLengthSMTLibResponseLimits query
        $ bytes "((" ++ symbol ++ bytes " 3))"
      evidence <- case validateLengthSMTLibCounterexample
          defaultLengthEvaluationLimits query bindings of
        Left failure -> assertFailure ("exact case replay failed: "
          ++ show failure) >> error "unreachable"
        Right Nothing -> assertFailure
          "the exact case's violating input produced no evidence"
            >> error "unreachable"
        Right (Just retained) -> pure retained
      receipt <- expectRight $ Djex.replayBehavioralEvidence
        (checkedLengthProblemBehavioralProblem problem) evidence
      Djex.validatedLengthCounterexampleInputs receipt @?= [3]
      Djex.validatedLengthCounterexampleResult receipt @?= 3

      withFakeLengthSolver "healthy" $ \executable -> do
        let configurationPath = takeDirectory executable </>
              "exact-spine-case-policy.json"
            contractPath = takeDirectory executable </>
              "exact-spine-case-contract.json"
            fixedContract = jsonCurrentLengthContract
              (jsonLengthTruth True) (jsonLengthTruth True) []
            configuration = setJsonField ["contract"] fixedContract
              $ setJsonField ["execution", "artifactPolicy"]
                  (Json.JStr "input-values-after-satisfiable")
              $ lengthRankingConfigurationFileFixture executable Nothing
            exactDocument = lengthContractFileFixture "scalar"
              $ exactSpineCaseQuotientContractValue
                  "exact-spine-zero-step-v1"
        ByteString.writeFile configurationPath
          $ encodeLengthRankingConfigurationFile configuration
        loadedMode <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource configurationPath 1000
        mode <- case loadedMode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right configured -> pure configured
        permission <- case authorizeExplicitLengthAssessmentRequest
            LengthBehaviorRank mode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right authorized -> pure authorized
        ByteString.writeFile contractPath
          $ encodeLengthRankingConfigurationFile exactDocument
        request <- case mkLengthContractFileRequest
            $ LengthContractFileSource contractPath 1000 of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right admitted -> pure admitted
        loadedContract <- loadLengthContractFile request >>= either
          (\failure -> assertFailure (show failure) >> error "unreachable")
          pure
        loadedContract @?=
          LeanLengthScalarContractSelection exactContract
        -- The request owns the decoded quotient grammar and exact case
        -- policy. Reusing it must not reopen the source, and startup or a
        -- cases-rejected request cannot inherit that authority.
        ByteString.writeFile contractPath $ BS.pack "{"
        verification <- verificationBatchFromReceipts [verified]
        let exactRequest = explicitLengthAssessmentRequest
              permission loadedContract
            casesRejectedRequest = explicitLengthAssessmentRequest permission
              $ LeanLengthScalarContractSelection casesRejectedContract
            assessments label assessed = case lengthAssessmentRanking assessed of
              Just ranking -> pure $ map rankedLengthCandidateAssessment
                $ lengthRankingCandidates ranking
              Nothing -> assertFailure (label ++ " lost its ranking")
                >> error "unreachable"
            assertExactCounterexample label assessed = do
              retainedAssessments <- assessments label assessed
              case retainedAssessments of
                [Counterexample liveReceipt] -> do
                  Djex.validatedLengthCounterexampleInputs liveReceipt @?= [3]
                  Djex.validatedLengthCounterexampleResult liveReceipt @?= 3
                unexpected -> assertFailure $ label ++
                  " retained unexpected assessments: " ++ show unexpected
            assertUnassessed label assessed =
              assessments label assessed >>= (@?= [Unassessed])
        startupRequest <- expectRight $ startupLengthAssessmentRequest
          LengthBehaviorRank mode
        assessed <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest exactRequest verification
        startup <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              startupRequest verification
        casesRejected <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              casesRejectedRequest verification
        repeated <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest exactRequest verification
        map lengthAssessmentFailure
            [assessed, startup, casesRejected, repeated] @?=
          replicate 4 Nothing
        map lengthAssessmentCandidates
            [assessed, startup, casesRejected, repeated] @?=
          replicate 4 [verified]
        assertExactCounterexample "loaded exact quotient request" assessed
        assertUnassessed "startup request" startup
        assertUnassessed "cases-rejected request" casesRejected
        assertExactCounterexample "reused exact quotient request" repeated

buildExactSpineCaseFixture
  :: IO
      ( LeanLengthContract
      , LeanLengthContract
      , Verified DetailedVerificationVariant
      )
buildExactSpineCaseFixture = do
  let element = FAtom False "Nat"
      listKey = "List Nat"
      list = FParamRec True "List" listKey [element]
        [ ("List.nil", [])
        , ("List.cons", [element, FAtom False listKey])
        ]
      goal = FArr list list
  casesRejectedContract <- expectLengthScalarContract
    $ lengthContractFileFixture "scalar"
    $ exactSpineCaseQuotientContractValue "cases-rejected"
  exactContract <- expectLengthScalarContract
    $ lengthContractFileFixture "scalar"
    $ exactSpineCaseQuotientContractValue "exact-spine-zero-step-v1"
  detailed <- expectRight $ synthesizeWithProvidersSkippingDetailed
    EngineExference 1024 Set.empty [] goal
  group <- case detailed of
    DetailedSynthCandidates groups _ -> case filter exactRebuildGroup groups of
      retained : _ -> pure retained
      [] -> assertFailure ("production Exference returned no exact rebuild "
        ++ "case: " ++ show (map detailedCandidateGroupVariants groups))
          >> error "unreachable"
    other -> assertFailure ("production exact-case synthesis failed: "
      ++ show other) >> error "unreachable"
  acceptedSpelling <- case detailedCandidateGroupVariants group of
    retained : _ -> pure retained
    [] -> assertFailure "the exact case group contained no renderer variant"
      >> error "unreachable"
  batch <- verifyCandidateGroups 1
    (\variant -> pure $ if detailedVerificationVariantText variant
        == acceptedSpelling
      then VariantAccepted
      else VariantRejected LeanErrorDiagnostic)
    [detailedCandidateGroupVerificationVariants group]
  case verifiedCandidateReceipts batch of
    [verified] -> pure (casesRejectedContract, exactContract, verified)
    receipts -> assertFailure ("exact case verification produced "
      ++ show (length receipts) ++ " receipts") >> error "unreachable"
 where
  exactRebuildGroup group = case detailedCandidateGroupSemanticSidecar group of
    Nothing -> False
    Just semantic -> case typedCandidateTermGraph
        $ typedCandidateSemanticCandidate semantic of
      Left _ -> False
      Right graph -> exactSpineRebuildExpression $ eraseTermGraph graph

exactSpineCaseQuotientContractValue :: String -> Json.JValue
exactSpineCaseQuotientContractValue policy = addJsonField []
  ("candidateCasePolicy", Json.JStr policy)
  $ jsonRoleAwareLengthContract
      ["observed-spine"]
      (jsonLengthTruth True)
      (jsonLengthEqual jsonLengthResult
        $ jsonLengthQuotient 2 $ jsonLengthInput 0)
      []

exactSpineRebuildExpression :: Eq local => Expression local -> Bool
exactSpineRebuildExpression expression = case expression of
  Lambda [Bind argument] (Case (Local scrutinee)
      [ (Constructor zero [], Global returnedZero)
      , ( Constructor step [Bind payload, Bind spineTail]
        , Apply (Apply (Global returnedStep) (Local returnedPayload))
            (Local returnedTail)
        )
      ]) ->
        argument == scrutinee
          && zero == returnedZero
          && step == returnedStep
          && payload == returnedPayload
          && spineTail == returnedTail
  _ -> False

assertLengthAssessmentFailureFallback :: IO ()
assertLengthAssessmentFailureFallback
  | os == "mingw32" = pure ()
  | otherwise =
      whenDescriptorBoundExecveCheckLaunchPubliclyReachable $ do
      fixture <- buildLengthRankingLiveFixture
      retained <- syntheticLengthRankingCandidate "integration-failure-retained"
      withFakeLengthSolver "immediate-eof" $ \executable -> do
        let sourcePath = takeDirectory executable </>
              "length-assessment-failure.json"
            original =
              [ lengthRankingFixtureOne fixture
              , retained
              , lengthRankingFixtureZero fixture
              ]
            contract = jsonCurrentLengthContract
              (jsonLengthTruth True) (jsonLengthTruth True)
              [ jsonLengthProviderLaw "Demo.zeroList" []
                  $ jsonLengthLiteral 0
              , jsonLengthProviderLaw "Demo.oneList" []
                  $ jsonLengthLiteral 1
              ]
            document = setJsonField ["contract"] contract
              $ lengthRankingConfigurationFileFixture executable Nothing
        ByteString.writeFile sourcePath
          $ encodeLengthRankingConfigurationFile document
        loaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource sourcePath 1000
        mode <- case loaded of
          Left failure -> assertFailure
            ("Length failure setup failed: " ++ show failure)
              >> error "unreachable"
          Right configured -> pure configured
        verification <- verificationBatchFromReceipts original
        assessed <- expectLengthAssessmentWithin
          $ assessLengthVerificationBatch mode verification
        lengthAssessmentCandidates assessed @?= original
        case lengthAssessmentRanking assessed of
          Nothing -> assertFailure
            "live integration fallback discarded its ranking report"
          Just ranking -> do
            map rankedLengthCandidateAssessment
                (lengthRankingCandidates ranking) @?=
              replicate (length original) Unassessed
            assertBool "live integration fallback exposed stale evidence"
              $ all (isNothing . lengthCandidatePresentationNote)
                  (presentLengthAssessment assessed)
        case lengthAssessmentFailure assessed of
          Just (LengthAssessmentRankingFailed failure) -> do
            lengthRankingFailureOriginalIndex failure @?= Nothing
            lengthRankingFailureCleanupIncomplete failure @?= False
          failure -> assertFailure $ "unexpected live integration failure: " ++
            show failure
        case lengthAssessmentPostVerificationResult assessed of
          Nothing -> assertFailure
            "live integration fallback discarded its sealed result"
          Just result -> assertLengthPostVerificationSealed result

        filterRequest <- expectRight $ startupLengthAssessmentRequest
          LengthBehaviorFilter mode
        filtered <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest filterRequest verification
        case lengthAssessmentFailure filtered of
          Just (LengthAssessmentSelectionFailed
              LengthSelectionRankingFailed{}) -> pure ()
          failure -> assertFailure $ "unexpected filter fallback failure: "
            ++ show failure
        lengthAssessmentCandidates filtered @?= original
        selection <- case lengthAssessmentSelectionResult filtered of
          Nothing -> assertFailure
            "filter fallback discarded its preserve-all result"
              >> error "unreachable"
          Just result -> pure result
        assertBool "filter fallback exposed partial selected associations"
          $ isNothing $ lengthSelectionSelected selection
        assertBool "filter fallback exposed partial rejected associations"
          $ isNothing $ lengthSelectionRejected selection
        map lengthCandidatePresentationText
            (presentLengthAssessment filtered) @?=
          map (detailedVerificationVariantText . verifiedCandidate) original
        assertBool "filter fallback emitted rejection rows"
          $ null $ presentLengthAssessmentRejections filtered

assertLengthPresentationAssociations
  :: [LengthCandidatePresentation]
  -> [Maybe Natural]
  -> IO ()
assertLengthPresentationAssociations presentations expected = do
  length presentations @?= length expected
  sequence_
    [ case (expectedResult, lengthCandidatePresentationNote presentation) of
        (Nothing, Nothing) -> pure ()
        (Just result, Just note) -> do
          assertBool "counterexample note lost its result association"
            $ ("result spine length = " ++ show result) `isInfixOf` note
          assertBool "counterexample note leaked a private provider name"
            $ not $ "Demo." `isInfixOf` note
        pair -> assertFailure $ "unexpected presentation association: "
          ++ show pair
    | (presentation, expectedResult) <- zip presentations expected
    ]

assertLengthCounterexamplePresentation :: IO ()
assertLengthCounterexamplePresentation = do
  fixture <- buildLengthRankingLiveFixture
  retained <- syntheticLengthRankingCandidate "presentation-retained"
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      original = [zero, retained, zero, one]
      expected = [retained, zero, zero, one]
  withFakeLengthSolver "healthy" $ \executable -> do
    let executionSource = explicitLengthRankingExecutionSource executable
          Nothing Djex.LengthSMTLibInputValuesAfterSatisfiable
        contract = lengthRankingContract 2
    policy <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits executionSource
          Djex.defaultLengthEvaluationLimitSource
    verification <- verificationBatchFromReceipts original
    assessedResult <- expectLengthPostVerificationWithin
      "presentation association"
      $ assessVerifiedLengthCandidatesWithPolicy policy contract verification
    let presentations = presentLengthPostVerificationResult assessedResult
        ranking = case lengthPostVerificationRanking assessedResult of
          Just retainedRanking -> retainedRanking
          Nothing -> error "sealed presentation fixture discarded its ranking"
    map lengthCandidatePresentationText presentations @?=
      map (detailedVerificationVariantText . verifiedCandidate) expected
    assertLengthPresentationAssociations presentations
      [Nothing, Just 0, Just 0, Just 1]
    let assessed = lengthRankingCandidates ranking
        receipts =
          [ receipt
          | candidate <- assessed
          , Counterexample receipt <-
              [rankedLengthCandidateAssessment candidate]
          ]
        notes =
          [ note
          | presentation <- presentations
          , Just note <- [lengthCandidatePresentationNote presentation]
          ]
    length notes @?= 3
    zipWithM_ (\receipt note -> do
        assertBool "counterexample note omitted model qualification"
          $ "replayed finite-list-spine Length counterexample "
              `isInfixOf` note
        assertBool "counterexample note omitted provider-law qualification"
          $ "conditional on 1 assumed provider law used by this candidate"
              `isInfixOf` note
        assertBool "counterexample note exposed a private provider name"
          $ not $ "Demo.zeroList" `isInfixOf` note
        assertBool "counterexample note exposed an internal basis constructor"
          $ not $ "FiniteSpineModelUnderAssumedProviderLaws" `isInfixOf` note
        assertBool "counterexample note exposed its receipt constructor"
          $ not $ "ValidatedLengthCounterexample" `isInfixOf` note
        mapM_ (\overclaim -> assertBool
            "counterexample note made a source-language or solver claim"
            $ not $ overclaim `isInfixOf` note)
          ["Lean", "Z3", "proved", "correct", "incorrect"]
        case Djex.validatedLengthCounterexampleBasis receipt of
          Djex.ProviderIndependentFiniteSpineModel -> pure ()
          Djex.FiniteSpineModelUnderAssumedProviderLaws names ->
            mapM_ (\name -> assertBool
                "counterexample note exposed a private provider name"
                $ not $ renderCanonical name `isInfixOf` note)
              names
      ) receipts notes

    let statusSource = explicitLengthRankingExecutionSource executable
          Nothing Djex.LengthSMTLibStatusOnly
        statusContract = lengthRankingContract 2
    statusPolicy <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits statusSource
          Djex.defaultLengthEvaluationLimitSource
    statusVerification <- verificationBatchFromReceipts [zero, one]
    statusResult <- expectLengthPostVerificationWithin
      "status-only presentation"
      $ assessVerifiedLengthCandidatesWithPolicy statusPolicy statusContract
          statusVerification
    assertBool "status-only ranking emitted a counterexample claim"
      $ all (isNothing . lengthCandidatePresentationNote)
          (presentLengthPostVerificationResult statusResult)

  providerIndependent <- buildProviderIndependentCounterexampleReceipt
    (2 ^ (4095 :: Int))
  let huge = renderLengthCounterexampleNote providerIndependent
  assertBool "provider-independent note lost its semantic basis"
    $ "model-relative; provider-independent" `isInfixOf` huge
  assertBool "large natural reached terminal presentation verbatim"
    $ "<4096-bit natural>" `isInfixOf` huge
  assertBool "counterexample terminal note exceeded its configured bound"
    $ length huge <= maximumLengthCounterexampleNoteCharacters

assertLengthAssessmentSpinePairDispatch :: IO ()
assertLengthAssessmentSpinePairDispatch
  | os == "mingw32" = pure ()
  | otherwise =
      whenDescriptorBoundExecveCheckLaunchPubliclyReachable $ do
      (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
      refused <- syntheticLengthRankingCandidate
        "pair-integration-occurrence-retained"
      withFakeLengthSolver "healthy" $ \executable -> do
        let configurationPath = takeDirectory executable </>
              "pair-assessment-current.json"
            contractPath = takeDirectory executable </>
              "pair-assessment-contract.json"
            pairContract second = jsonLengthSpinePairContract
              ["observed-spine"] "cases-rejected"
              (jsonLengthTruth True)
              (jsonLengthAll
                [ jsonLengthEqual jsonLengthSpinePairResultFirst
                    $ jsonLengthInput 0
                , jsonLengthEqual jsonLengthSpinePairResultSecond
                    $ jsonLengthLiteral second
                ])
              [ jsonLengthProviderLaw "Demo.zeroList" []
                  $ jsonLengthLiteral 0
              ]
            startupDocument = setJsonField
              ["execution", "artifactPolicy"]
              (Json.JStr "input-values-after-satisfiable")
              $ lengthAssessmentConfigurationFileSpinePairFixture
                  executable Nothing [1] 2 (pairContract 1)
            contractDocument second = lengthContractFileFixture
              "binary-product" $ pairContract second
        ByteString.writeFile configurationPath
          $ encodeLengthRankingConfigurationFile startupDocument
        loaded <- loadLengthAssessmentMode PermitUnpinnedExecutable
          $ LengthRankingConfigurationFileSource configurationPath 1000
        mode <- case loaded of
          Left failure -> assertFailure
            ("pair assessment setup failed: " ++ show failure)
              >> error "unreachable"
          Right configured -> pure configured
        lengthAssessmentModeActivationPolicy mode @?=
          Just PermitUnpinnedExecutable
        doesFileExist (executable ++ ".events") >>= (@?= False)

        verification <- verificationBatchFromReceipts
          [inputAndZero, inputAndZero, refused]
        assessed <- expectLengthAssessmentWithin
          $ assessLengthVerificationBatch mode verification
        lengthAssessmentFailure assessed @?= Nothing
        assertBool "pair startup assessment retained a scalar ranking"
          $ isNothing $ lengthAssessmentRanking assessed
        assertBool "pair startup assessment retained a scalar seal"
          $ isNothing $ lengthAssessmentPostVerificationResult assessed
        pairResult <- case
            lengthAssessmentSpinePairPostVerificationResult assessed of
          Nothing -> assertFailure
            "pair startup assessment discarded its product seal"
              >> error "unreachable"
          Just result -> pure result
        sealed <- case lengthSpinePairPostVerificationSealedBatch pairResult of
          Nothing -> assertFailure
            "pair startup assessment bypassed occurrence sealing"
              >> error "unreachable"
          Just value -> pure value
        let expected = [refused, inputAndZero, inputAndZero]
        postVerificationBatchCandidates sealed @?= expected
        lengthAssessmentCandidates assessed @?= expected
        pairRanking <- case lengthAssessmentSpinePairRanking assessed of
          Nothing -> assertFailure
            "pair startup assessment discarded its product ranking"
              >> error "unreachable"
          Just ranking -> pure ranking
        map rankedLengthSpinePairCandidateOriginalIndex
            (lengthSpinePairRankingCandidates pairRanking) @?= [2, 0, 1]
        case map lengthCandidatePresentationNote
            $ presentLengthAssessment assessed of
          [Nothing, Just first, Just second] -> mapM_ (\note -> do
              assertBool "pair presentation omitted its first component"
                $ "first result spine length = 0" `isInfixOf` note
              assertBool "pair presentation omitted its second component"
                $ "second result spine length = 0" `isInfixOf` note
              assertBool "pair presentation exposed a provider name"
                $ not $ "Demo.zeroList" `isInfixOf` note)
            [first, second]
          notes -> assertFailure $ "pair occurrence notes drifted: " ++
            show notes

        permission <- case authorizeExplicitLengthAssessmentRequest
            LengthBehaviorRank mode of
          Left failure -> assertFailure (show failure) >> error "unreachable"
          Right authorized -> pure authorized
        ByteString.writeFile contractPath
          $ encodeLengthRankingConfigurationFile $ contractDocument 0
        request <- expectLengthContractFileRequest contractPath
        selectionLoaded <- loadLengthContractFile request
        selection <- case selectionLoaded of
          Left failure -> assertFailure
            ("pair selection load failed: " ++ show failure)
              >> error "unreachable"
          Right value -> pure value
        -- The request owns the decoded selection; changing its source cannot
        -- affect the later assessment.
        ByteString.writeFile contractPath $ BS.pack "{"
        failingVerification <- verificationBatchFromReceipts [inputAndZero]
        failed <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission selection)
              failingVerification
        lengthAssessmentCandidates failed @?= [inputAndZero]
        assertBool "pair failure exposed a scalar ranking"
          $ isNothing $ lengthAssessmentRanking failed
        assertBool "pair failure exposed a scalar seal"
          $ isNothing $ lengthAssessmentPostVerificationResult failed
        case lengthAssessmentFailure failed of
          Just (LengthAssessmentSpinePairRankingFailed failure) -> do
            lengthSpinePairRankingFailureClass failure @?=
              LengthSpinePairRankingLiveQueryFailed
                Djex.LengthSpinePairSMTLibLiveQueryCounterexampleRejected
            lengthSpinePairRankingFailureOriginalIndex failure @?= Just 0
            lengthSpinePairRankingFailureCleanupIncomplete failure @?= False
          failure -> assertFailure $ "unexpected pair failure: " ++
            show failure
        assertBool "pair failure discarded its product result"
          $ case lengthAssessmentSpinePairPostVerificationResult failed of
              Nothing -> False
              Just _ -> True
        assertBool "atomic pair failure emitted a semantic note"
          $ all (isNothing . lengthCandidatePresentationNote)
              (presentLengthAssessment failed)

        scalar <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission
                $ LeanLengthScalarContractSelection
                $ lengthRankingContract 0)
              failingVerification
        assertBool "scalar request exposed a pair ranking"
          $ isNothing $ lengthAssessmentSpinePairRanking scalar
        assertBool "scalar request exposed a pair seal"
          $ isNothing
          $ lengthAssessmentSpinePairPostVerificationResult scalar
        assertBool "scalar request lost its scalar seal"
          $ case lengthAssessmentPostVerificationResult scalar of
              Nothing -> False
              Just _ -> True

        -- Product selection is lazy below the constructor: the occurrence
        -- adapter rejects maximum-plus-one before demanding its contract.
        let maximumCandidates =
              Djex.defaultLengthSMTLibLiveSessionMaximumQueries
            oversizedCount = fromIntegral maximumCandidates + 1
        oversized <- verificationBatchFromReceipts
          $ replicate oversizedCount duplicatedInput
        rejected <- expectLengthAssessmentWithin
          $ assessLengthVerificationRequest
              (explicitLengthAssessmentRequest permission
                $ LeanLengthSpinePairContractSelection
                $ error "pair maximum-plus-one forced its contract")
              oversized
        case lengthAssessmentFailure rejected of
          Just (LengthAssessmentSpinePairPostVerificationFailed
              (LengthSpinePairPostVerificationInputRejected
                (LengthRankingInputLimitExceeded maximumValue observed))) ->
                  (maximumValue, observed) @?=
                    (maximumCandidates, maximumCandidates + 1)
          failure -> assertFailure $ "unexpected lazy pair rejection: " ++
            show failure

assertLengthAssessmentSpinePairDisabled :: IO ()
assertLengthAssessmentSpinePairDisabled = do
  result <- assessLengthVerificationBatch disabledLengthAssessmentMode
    (error "disabled pair-aware integration forced its verification batch")
  lengthAssessmentFailure result @?= Nothing
  assertBool "disabled pair-aware integration retained a scalar ranking"
    $ isNothing $ lengthAssessmentRanking result
  assertBool "disabled pair-aware integration retained a product ranking"
    $ isNothing $ lengthAssessmentSpinePairRanking result
  assertBool "disabled pair-aware integration retained a scalar result"
    $ isNothing $ lengthAssessmentPostVerificationResult result
  assertBool "disabled pair-aware integration retained a product result"
    $ isNothing $ lengthAssessmentSpinePairPostVerificationResult result
  assertBool "disabled pair-aware integration retained scalar selection"
    $ isNothing $ lengthAssessmentSelectionResult result
  assertBool "disabled pair-aware integration retained product selection"
    $ isNothing $ lengthAssessmentSpinePairSelectionResult result
  parseLengthSynthCommand
      "--length-contract /tmp/pair-current.json -- List Nat -> Prod (List Nat) (List Nat)"
    @?= Right LengthSynthCommand
      { lengthSynthCommandBehaviorMode = LengthBehaviorRank
      , lengthSynthCommandContractPath = Just "/tmp/pair-current.json"
      , lengthSynthCommandGoal = "List Nat -> Prod (List Nat) (List Nat)"
      }
  options <- expectOptions
    [ "--length-ranking-config", "/tmp/pair-current.json"
    , "--length-ranking-config-timeout", "1234"
    , "--length-ranking-allow-unpinned"
    ]
  case lengthAssessmentSetup options of
    Just (PermitUnpinnedExecutable,
        LengthRankingConfigurationFileSource path milliseconds) ->
          (path, milliseconds) @?= ("/tmp/pair-current.json", 1234)
    _ -> assertFailure "pair schemas changed the established CLI grammar"


expectLengthAssessmentWithin
  :: IO result
  -> IO result
expectLengthAssessmentWithin action = do
  bounded <- timeout 8000000 action
  case bounded of
    Nothing -> assertFailure "Length assessment integration exceeded its bound"
      >> error "unreachable"
    Just result -> pure result

assertLengthRankingConfigurationFileRequestAdmission :: IO ()
assertLengthRankingConfigurationFileRequestAdmission =
  withTemporaryDirectory "leant-length-acquisition-admission" $ \root -> do
    lengthRankingConfigurationFileMaximumPathCharacters @?= 4096
    lengthRankingConfigurationFileMaximumTimeoutMilliseconds @?= 60000
    lengthRankingConfigurationFileLoadMaximumBytes @?=
      boundedJsonMaximumTotalBytes lengthRankingConfigurationFileJsonLimits
    let exactPath = root ++ replicate
          (fromIntegral lengthRankingConfigurationFileMaximumPathCharacters
            - length root)
          'a'
        exactSource = LengthRankingConfigurationFileSource exactPath
          lengthRankingConfigurationFileMaximumTimeoutMilliseconds
    case mkLengthRankingConfigurationFileRequest exactSource of
      Left failure -> assertFailure $ "exact request was rejected: "
        ++ show failure
      Right _ -> pure ()

    let cyclicPath = root ++ repeat 'a'
        cyclicSource = LengthRankingConfigurationFileSource cyclicPath
          (error "timeout forced after an oversized path")
    case mkLengthRankingConfigurationFileRequest cyclicSource of
      Left failure -> failure @?=
        LengthRankingConfigurationFilePathCharacterLimitExceeded 4096 4097
      Right _ -> assertFailure "cyclic oversized path was admitted"

    assertAdmissionFailure LengthRankingConfigurationFilePathEmpty
      $ LengthRankingConfigurationFileSource "" 1
    assertAdmissionFailure LengthRankingConfigurationFilePathContainsNul
      $ LengthRankingConfigurationFileSource (root ++ "\0private") 1
    assertAdmissionFailure LengthRankingConfigurationFilePathNotAbsolute
      $ LengthRankingConfigurationFileSource "relative.json" 1
    assertAdmissionFailure LengthRankingConfigurationFileTimeoutNotPositive
      $ LengthRankingConfigurationFileSource root 0
    assertAdmissionFailure
      (LengthRankingConfigurationFileTimeoutLimitExceeded 60000 60001)
      $ LengthRankingConfigurationFileSource root 60001

assertLengthRankingConfigurationFileAcquisition :: IO ()
assertLengthRankingConfigurationFileAcquisition =
  withTemporaryDirectory "leant-length-acquisition-success" $ \root -> do
    let sourcePath = root </> "length-ranking.json"
        executable = root </> "missing-z3"
    ByteString.writeFile sourcePath $ encodeLengthRankingConfigurationFile
      $ lengthRankingConfigurationFileFixture executable Nothing
    request <- expectLengthRankingConfigurationFileRequest sourcePath 1000
    loaded <- loadLengthAssessmentConfigurationFile request
    if os == "mingw32"
      then expectLengthRankingConfigurationFileLoadFailure
        LengthRankingConfigurationFilePlatformUnsupported loaded
      else case loaded of
        Left failure -> assertFailure $ "regular configuration was rejected: "
          ++ show (lengthRankingConfigurationFileLoadErrorClass failure)
        Right disabled -> do
          _ <- expectLengthRankingConfigurationActivation
            PermitUnpinnedExecutable disabled
          pure ()

assertLengthRankingConfigurationFileSourceTypes :: IO ()
assertLengthRankingConfigurationFileSourceTypes =
  withTemporaryDirectory "leant-length-acquisition-types" $ \root -> do
    directoryRequest <- expectLengthRankingConfigurationFileRequest root 1000
    directoryResult <- loadLengthAssessmentConfigurationFile directoryRequest
    if os == "mingw32"
      then expectLengthRankingConfigurationFileLoadFailure
        LengthRankingConfigurationFilePlatformUnsupported directoryResult
      else expectLengthRankingConfigurationFileLoadFailure
        LengthRankingConfigurationFileNotRegular directoryResult

    let target = root </> "target.json"
        linked = root </> "linked.json"
    ByteString.writeFile target $ BS.pack "{}"
    if os == "mingw32"
      then pure ()
      else do
        createFileLink target linked
        linkedRequest <- expectLengthRankingConfigurationFileRequest linked 1000
        linkedResult <- loadLengthAssessmentConfigurationFile linkedRequest
        expectLengthRankingConfigurationFileLoadFailure
          LengthRankingConfigurationFileOpenFailed linkedResult

assertLengthRankingConfigurationFileAcquisitionByteLimit :: IO ()
assertLengthRankingConfigurationFileAcquisitionByteLimit =
  withTemporaryDirectory "leant-length-acquisition-bytes" $ \root -> do
    let exactPath = root </> "exact.json"
        excessivePath = root </> "excessive.json"
        maximumBytes = fromIntegral
          lengthRankingConfigurationFileLoadMaximumBytes
    ByteString.writeFile exactPath $ ByteString.replicate maximumBytes 32
    ByteString.writeFile excessivePath
      $ ByteString.replicate (maximumBytes + 1) 32
    exactRequest <- expectLengthRankingConfigurationFileRequest exactPath 1000
    excessiveRequest <- expectLengthRankingConfigurationFileRequest
      excessivePath 1000
    exactResult <- loadLengthAssessmentConfigurationFile exactRequest
    excessiveResult <- loadLengthAssessmentConfigurationFile excessiveRequest
    if os == "mingw32"
      then do
        expectLengthRankingConfigurationFileLoadFailure
          LengthRankingConfigurationFilePlatformUnsupported exactResult
        expectLengthRankingConfigurationFileLoadFailure
          LengthRankingConfigurationFilePlatformUnsupported excessiveResult
      else do
        case exactResult of
          Left failure -> case
              lengthRankingConfigurationFileLoadErrorClass failure of
            LengthRankingConfigurationFileDecodeRejected _ ->
              lengthRankingConfigurationFileLoadCleanupIncomplete failure @?=
                False
            other -> assertFailure $ "exact byte ceiling failed before decode: "
              ++ show other
          Right _ -> assertFailure "all-whitespace document unexpectedly decoded"
        expectLengthRankingConfigurationFileLoadFailure
          (LengthRankingConfigurationFileByteLimitExceeded 262144 262145)
          excessiveResult

assertLengthRankingConfigurationFileAcquisitionRedaction :: IO ()
assertLengthRankingConfigurationFileAcquisitionRedaction =
  withTemporaryDirectory "leant-length-acquisition-redaction" $ \root -> do
    let privateFragment = "private-acquisition-path-fragment"
        missing = root </> privateFragment
    request <- expectLengthRankingConfigurationFileRequest missing 1000
    loaded <- loadLengthAssessmentConfigurationFile request
    case loaded of
      Right _ -> assertFailure "missing configuration unexpectedly loaded"
      Left failure -> do
        lengthRankingConfigurationFileLoadErrorClass failure @?=
          if os == "mingw32"
            then LengthRankingConfigurationFilePlatformUnsupported
            else LengthRankingConfigurationFileOpenFailed
        lengthRankingConfigurationFileLoadCleanupIncomplete failure @?= False
        assertBool "load failure exposed the private source path"
          $ not $ privateFragment `isInfixOf` show failure

assertAdmissionFailure
  :: LengthRankingConfigurationFileAdmissionError
  -> LengthRankingConfigurationFileSource
  -> IO ()
assertAdmissionFailure expected source =
  case mkLengthRankingConfigurationFileRequest source of
    Left failure -> failure @?= expected
    Right _ -> assertFailure $ "expected request rejection: " ++ show expected

expectLengthRankingConfigurationFileRequest
  :: FilePath
  -> Int
  -> IO LengthRankingConfigurationFileRequest
expectLengthRankingConfigurationFileRequest path timeoutMilliseconds =
  case mkLengthRankingConfigurationFileRequest
      $ LengthRankingConfigurationFileSource path timeoutMilliseconds of
    Left failure -> assertFailure ("request admission failed: " ++ show failure)
      >> error "unreachable"
    Right request -> pure request

expectLengthRankingConfigurationFileLoadFailure
  :: LengthRankingConfigurationFileLoadErrorClass
  -> Either
      LengthRankingConfigurationFileLoadError
      DisabledLengthAssessmentConfiguration
  -> IO ()
expectLengthRankingConfigurationFileLoadFailure expected result = case result of
  Right _ -> assertFailure $ "expected acquisition failure: " ++ show expected
  Left failure -> do
    lengthRankingConfigurationFileLoadErrorClass failure @?= expected
    lengthRankingConfigurationFileLoadCleanupIncomplete failure @?= False

assertLengthRankingConfigurationFileActivation :: IO ()
assertLengthRankingConfigurationFileActivation =
  withTemporaryDirectory "leant-length-file-activation" $ \root -> do
    let executable = root </> "missing-z3"
        scalarDocument = lengthRankingConfigurationFileFixture
          executable Nothing
        pinnedDocument = lengthRankingConfigurationFileFixture executable
          $ Just $ replicate 64 '0'
        pairDocument = lengthAssessmentConfigurationFileSpinePairFixture
          executable Nothing [1] 2 positiveAffinePairContractValue
    lengthRankingConfigurationFileFormat @?=
      Text.pack "leant-live-length-ranking-configuration"
    lengthRankingConfigurationFileJsonLimits @?= BoundedJsonLimits
      { boundedJsonMaximumTotalBytes = 262144
      , boundedJsonMaximumNestingDepth = 133
      , boundedJsonMaximumNodes = 32768
      , boundedJsonMaximumObjectMembers = 32
      , boundedJsonMaximumArrayElements = 257
      , boundedJsonMaximumObjectKeyUtf8Bytes = 64
      , boundedJsonMaximumStringUtf8Bytes = 16384
      , boundedJsonMaximumStringUnicodeScalars = 4096
      , boundedJsonMaximumNumberBytes = 80
      }

    unpinned <- expectLengthAssessmentConfigurationFile scalarDocument
    case activateLengthAssessmentConfiguration
        RequirePinnedExecutable unpinned of
      Left failure -> failure @?=
        LengthRankingConfigurationExecutablePinRequired
      Right _ -> assertFailure
        "an unpinned configuration passed require-pinned activation"
    (_, scalarSelection) <- expectLengthAssessmentConfigurationActivation
      PermitUnpinnedExecutable unpinned
    case scalarSelection of
      LeanLengthScalarContractSelection _ -> pure ()
      LeanLengthSpinePairContractSelection _ -> assertFailure
        "scalar startup activated a product contract"

    pinned <- expectLengthAssessmentConfigurationFile pinnedDocument
    _ <- expectLengthAssessmentConfigurationActivation
      RequirePinnedExecutable pinned
    _ <- expectLengthAssessmentConfigurationActivation
      PermitUnpinnedExecutable pinned

    reordered <- expectLengthAssessmentConfigurationFile
      $ reverseJsonObjectFields pinnedDocument
    _ <- expectLengthAssessmentConfigurationActivation
      RequirePinnedExecutable reordered
    pair <- expectLengthAssessmentConfigurationFile pairDocument
    (_, pairSelection) <- expectLengthAssessmentConfigurationActivation
      PermitUnpinnedExecutable pair
    case pairSelection of
      LeanLengthSpinePairContractSelection _ -> pure ()
      LeanLengthScalarContractSelection _ -> assertFailure
        "product startup activated a scalar contract"
    pure ()

