jsonCurrentLengthContract
  :: Json.JValue
  -> Json.JValue
  -> [Json.JValue]
  -> Json.JValue
jsonCurrentLengthContract precondition postcondition laws =
  addJsonField []
    ("candidateCasePolicy", Json.JStr "cases-rejected")
    $ jsonRoleAwareLengthContract [] precondition postcondition laws

