assertLengthRankingInputBoxValidation :: IO ()
assertLengthRankingInputBoxValidation = do
  (contract, arityCandidates) <- buildLengthSeedBankArityFixture
  (twoInput, threeInput) <- case arityCandidates of
    [_, _, two, three, _] -> pure (two, three)
    _ -> assertFailure "the input-box arity fixture changed cardinality"
      >> error "unreachable"
  let positiveContract = contract
        { leanLengthContractTargetArgumentRoles =
            replicate 3 LengthObservedSpine
        , leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthTruth True
            , lengthContractPostcondition = LengthTruth True
            }
        }
  positiveProblem <- expectRight
    $ prepareCheckedLengthProblem positiveContract threeInput
  let expectedPositiveBasis =
        Djex.FiniteSpineModelUnderAssumedProviderLaws
          $ checkedLengthCandidateUsedProviders
          $ checkedLengthProblemCandidate positiveProblem
  positiveLimits <- explicitLengthInputBoxLimits 3 12
  (positiveRanking, positiveEvents) <-
    runLengthRankingWithFakeTraceWithInputBox
      "query-unsat" Djex.LengthSMTLibStatusOnly
      defaultLengthEvaluationLimits positiveLimits [2, 0, 3]
      positiveContract [threeInput]
  lengthRankingFailure positiveRanking @?= Nothing
  positiveReceipt <- case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates positiveRanking of
    [BoundedPositive receipt] -> pure receipt
    assessments -> assertFailure
      ("unexpected bounded-positive assessment: " ++ show assessments)
        >> error "unreachable"
  Djex.validatedLengthInputBoxInclusiveMaximums positiveReceipt @?=
    [2, 0, 3]
  Djex.validatedLengthInputBoxAssignmentCount positiveReceipt @?= 12
  Djex.validatedLengthInputBoxApplicableAssignmentCount positiveReceipt @?= 12
  Djex.validatedLengthInputBoxBasis positiveReceipt @?= expectedPositiveBasis
  assertFakeLengthQueryEvents [0] [] positiveEvents
  let positiveNote = renderLengthInputBoxValidationNote positiveReceipt
      foldedPositiveNote = map toLower positiveNote
  mapM_ (\fragment -> assertBool
      ("bounded-positive note omitted " ++ show fragment)
      $ fragment `isInfixOf` positiveNote)
    [ "independently checked finite-list-spine Length input box"
    , "bounded/model-relative"
    , "inclusive input maxima = [2, 0, 3]"
    , "checked assignments = 12"
    , "applicable assignments = 12"
    , "conditional on 1 assumed provider law"
    ]
  mapM_ (\provider -> assertBool
      "bounded-positive note exposed a private provider name"
      $ not $ renderCanonical provider `isInfixOf` positiveNote)
    $ checkedLengthCandidateUsedProviders
    $ checkedLengthProblemCandidate positiveProblem
  mapM_ (\overclaim -> assertBool
      ("bounded-positive note made an external or universal claim: "
        ++ overclaim)
      $ not $ overclaim `isInfixOf` foldedPositiveNote)
    ["z3", "unsat", "proof", "proved", "universal", "lean-correct"]
  assertBool "bounded-positive note exceeded the terminal cap"
    $ length positiveNote <= maximumLengthCounterexampleNoteCharacters

  vacuousLimits <- explicitLengthInputBoxLimits 3 1
  let vacuousContract = positiveContract
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthTruth False
            , lengthContractPostcondition = LengthTruth True
            }
        }
  (vacuousRanking, vacuousEvents) <-
    runLengthRankingWithFakeTraceWithInputBox
      "query-unsat" Djex.LengthSMTLibStatusOnly
      defaultLengthEvaluationLimits vacuousLimits [0, 0, 0]
      vacuousContract [threeInput]
  vacuousReceipt <- case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates vacuousRanking of
    [BoundedPositive receipt] -> pure receipt
    assessments -> assertFailure
      ("unexpected vacuous input-box assessment: " ++ show assessments)
        >> error "unreachable"
  Djex.validatedLengthInputBoxAssignmentCount vacuousReceipt @?= 1
  Djex.validatedLengthInputBoxApplicableAssignmentCount vacuousReceipt @?= 0
  assertBool "vacuous positive note hid its empty applicable domain"
    $ "vacuous within this box" `isInfixOf`
        renderLengthInputBoxValidationNote vacuousReceipt
  assertFakeLengthQueryEvents [0] [] vacuousEvents

  let counterexampleContract = contract
        { leanLengthContractTargetArgumentRoles =
            replicate 2 LengthObservedSpine
        }
  counterexampleProblem <- expectRight
    $ prepareCheckedLengthProblem counterexampleContract twoInput
  let expectedCounterexampleBasis =
        Djex.FiniteSpineModelUnderAssumedProviderLaws
          $ checkedLengthCandidateUsedProviders
          $ checkedLengthProblemCandidate counterexampleProblem
  counterexampleLimits <- explicitLengthInputBoxLimits 2 4
  (counterexampleRanking, counterexampleEvents) <-
    runLengthRankingWithFakeTraceWithInputBox
      "query-unsat" Djex.LengthSMTLibStatusOnly
      defaultLengthEvaluationLimits counterexampleLimits [1, 1]
      counterexampleContract [twoInput, twoInput]
  lengthRankingFailure counterexampleRanking @?= Nothing
  map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates counterexampleRanking) @?= [0, 1]
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates counterexampleRanking of
    [Counterexample first, Counterexample second] -> do
      map Djex.validatedLengthCounterexampleInputs [first, second] @?=
        replicate 2 [0, 1]
      map Djex.validatedLengthCounterexampleResult [first, second] @?=
        [1, 1]
      map Djex.validatedLengthCounterexampleBasis [first, second] @?=
        replicate 2 expectedCounterexampleBasis
    assessments -> assertFailure
      $ "unexpected unsat-contradicting assessments: " ++ show assessments
  -- The first independent box traversal contradicts the raw unsat status and
  -- seeds [0,1].  The second occurrence replays that vector through its own
  -- sealed query, so no second solver query or get-value request is needed.
  assertFakeLengthQueryEvents [0] [] counterexampleEvents

assertLengthRankingApplicableDomainComposition :: IO ()
assertLengthRankingApplicableDomainComposition = do
  fixture <- buildLengthRankingLiveFixture
  identity <- buildOneInputLengthRankingCandidate
  retained <- syntheticLengthRankingCandidate
    "applicable-domain-composition-retained"
  applicableLimits <- explicitLengthInputBoxLimits 0 1
  inputBoxLimits <- explicitLengthInputBoxLimits 1 1
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      contract = lengthRankingContract 0
      original = [retained, identity, zero, one]
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let forward = enableLengthRankingNonVacuousApplicableDomainPreference
          $ enableLengthRankingNonVacuousInputBoxPreference
          $ enableLengthRankingApplicableDomainValidation applicableLimits
              Djex.defaultLengthBooleanFiniteUnionLimits
          $ enableLengthRankingInputBoxValidation inputBoxLimits [0]
          $ enableLengthRankingOriginProbe base
        reverseOrder = enableLengthRankingOriginProbe
          $ enableLengthRankingInputBoxValidation inputBoxLimits [0]
          $ enableLengthRankingApplicableDomainValidation applicableLimits
              Djex.defaultLengthBooleanFiniteUnionLimits
          $ enableLengthRankingNonVacuousInputBoxPreference
          $ enableLengthRankingNonVacuousApplicableDomainPreference base
        boxPreferenceOnly = enableLengthRankingNonVacuousInputBoxPreference
          $ enableLengthRankingApplicableDomainValidation applicableLimits
              Djex.defaultLengthBooleanFiniteUnionLimits
          $ enableLengthRankingInputBoxValidation inputBoxLimits [0]
          $ enableLengthRankingOriginProbe base
        run label policy = expectLengthRankingWithin label
          $ rankVerifiedLengthCandidatesWithPolicy policy contract original

    ranked <- run "applicable-domain composed ordering" forward
    reversed <- run "reverse applicable-domain builder ordering" reverseOrder
    assertLengthRankingsEquivalent ranked reversed
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates ranked) @?= [2, 0, 1, 3]
    domainReceipt <- case
        map rankedLengthCandidateAssessment $ lengthRankingCandidates ranked of
      [ ApplicableDomainEstablished domainPositive
        , Unassessed
        , Unassessed
        , Counterexample counterexample
        ] -> do
          Djex.validatedLengthCounterexampleInputs counterexample @?= []
          Djex.validatedLengthCounterexampleResult counterexample @?= 1
          pure domainPositive
      assessments -> assertFailure
        ("unexpected composed applicable-domain assessments: "
          ++ show assessments) >> error "unreachable"
    Djex.validatedLengthApplicableDomainInclusiveMaximumBoxes domainReceipt @?=
      [[]]
    Djex.validatedLengthApplicableDomainAssignmentCount domainReceipt @?= 1
    Djex.validatedLengthApplicableDomainApplicableAssignmentCount
      domainReceipt @?= 1
    zeroProblem <- expectRight $ prepareCheckedLengthProblem contract zero
    Djex.validatedLengthApplicableDomainBasis domainReceipt @?=
      Djex.FiniteSpineModelUnderAssumedProviderLaws
        (checkedLengthCandidateUsedProviders
          $ checkedLengthProblemCandidate zeroProblem)
    -- The explicit empty role vector rejects the unary candidate before either
    -- bounded traversal. Both nullary candidates finish before Z3.
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

    boxFirst <- run "box-only positive ordering" boxPreferenceOnly
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates boxFirst) @?= [0, 1, 2, 3]
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

    -- Every builder is persistent.  Reusing the common base leaves the new
    -- traversal and both ordering authorities disabled, including for a
    -- contract whose nullary domain is complete.
    legacy <- run "immutable applicable-domain base" base
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates legacy) @?= [0, 1, 2, 3]
    map rankedLengthCandidateAssessment
        (lengthRankingCandidates legacy) @?=
      [ Unassessed
      , Unassessed
      , Heuristic Djex.SolverUnsatisfiable
      , Heuristic Djex.SolverUnsatisfiable
      ]
    assertFakeLengthQueryEvents [0, 1] [] =<<
      BS.readFile (executable ++ ".events")

    verification <- verificationBatchFromReceipts original
    associated <- expectLengthPostVerificationWithin
      "applicable-domain occurrence association"
      $ assessVerifiedLengthCandidatesWithPolicy forward contract verification
    assertLengthPostVerificationSealed associated
    associatedRanking <- expectLengthPostVerificationRanking associated
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates associatedRanking) @?= [2, 0, 1, 3]
    associatedDomain <- case
        map rankedLengthCandidateAssessment
          $ lengthRankingCandidates associatedRanking of
      ApplicableDomainEstablished directDomain : _ -> pure directDomain
      assessments -> assertFailure
        ("associated applicable-domain ranking changed: "
          ++ show assessments) >> error "unreachable"
    let domainNote = renderLengthApplicableDomainValidationNote
          associatedDomain
        presentations = presentLengthPostVerificationResult associated
    map lengthCandidatePresentationText presentations @?=
      map (detailedVerificationVariantText . verifiedCandidate)
        (lengthPostVerificationCandidates associated)
    case map lengthCandidatePresentationNote presentations of
      [Just directDomain, Nothing, Nothing, Just counterexampleNote] -> do
        directDomain @?= domainNote
        assertBool "domain counterexample followed the wrong occurrence"
          $ "result spine length = 1" `isInfixOf` counterexampleNote
      notes -> assertFailure
        $ "applicable-domain presentation reassociated notes: " ++ show notes
    mapM_ (\fragment -> assertBool
        ("scalar applicable-domain note omitted " ++ show fragment)
        $ fragment `isInfixOf` domainNote)
      [ "complete finite-spine Length Boolean finite-union atomic-branching"
      , "conditional on 1 assumed provider law"
      , "boxes = 1"
      , "unique = 1"
      , "applicable = 1"
      , "; maxima"
      ]
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

assertLengthRankingApplicableDomainAtomicFailure :: IO ()
assertLengthRankingApplicableDomainAtomicFailure = do
  fixture <- buildLengthRankingLiveFixture
  trailing <- syntheticLengthRankingCandidate
    "applicable-domain-atomic-failure-trailing"
  limits <- explicitLengthInputBoxLimits 0 1
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      original = [zero, one, trailing]
      evaluationSource = Djex.defaultLengthEvaluationLimitSource
        { Djex.lengthEvaluationLimitSourceIntermediateValueBits = 0 }
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ mkLengthRankingPolicy
      $ explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits
          (explicitLengthRankingExecutionSource executable Nothing
            Djex.LengthSMTLibStatusOnly)
          evaluationSource
    ranking <- expectLengthRankingWithin
      "admitted applicable-domain evaluation failure"
      $ rankVerifiedLengthCandidatesWithPolicy
          (enableLengthRankingApplicableDomainValidation limits
            Djex.defaultLengthBooleanFiniteUnionLimits base)
          (lengthRankingContract 0) original
    rankedLengthVerifiedCandidates ranking @?= original
    map rankedLengthCandidateAssessment
        (lengthRankingCandidates ranking) @?= replicate 3 Unassessed
    rankedLengthPreparationRefusals ranking @?=
      [Nothing, Nothing, Just LengthPreparationTypedAuthorityUnavailable]
    failure <- case lengthRankingFailure ranking of
      Nothing -> assertFailure
        "admitted applicable-domain evaluation failure was discarded"
          >> error "unreachable"
      Just retained -> pure retained
    lengthRankingFailureClass failure @?=
      LengthRankingApplicableDomainValidationFailed
        (Djex.LengthApplicableDomainAssignmentEvaluationRejected 0
          $ Djex.LengthEvaluationValueBitLimitExceeded
              Djex.LengthIntermediateValue 0 1)
    lengthRankingFailureOriginalIndex failure @?= Just 1
    lengthRankingFailureCleanupIncomplete failure @?= False
    -- The first nullary candidate established its singleton domain, but the
    -- later admitted traversal failed before either candidate could consume a
    -- live ordinal.  Atomic fallback discards that earlier receipt as well.
    assertFakeLengthQueryEvents [] [] =<<
      BS.readFile (executable ++ ".events")

assertLengthRankingInputBoxSeedIsolation :: IO ()
assertLengthRankingInputBoxSeedIsolation = do
  fixture <- buildLengthRankingLiveFixture
  limits <- explicitLengthInputBoxLimits 0 1
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      contract = lengthRankingContract 0
  (positiveThenCounterexample, firstEvents) <-
    runLengthRankingWithFakeTraceWithInputBox
      "query-unsat" Djex.LengthSMTLibStatusOnly
      defaultLengthEvaluationLimits limits [] contract [zero, one]
  lengthRankingFailure positiveThenCounterexample @?= Nothing
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates positiveThenCounterexample of
    [BoundedPositive positive, Counterexample counterexample] -> do
      Djex.validatedLengthInputBoxInclusiveMaximums positive @?= []
      Djex.validatedLengthInputBoxAssignmentCount positive @?= 1
      Djex.validatedLengthCounterexampleInputs counterexample @?= []
      Djex.validatedLengthCounterexampleResult counterexample @?= 1
    assessments -> assertFailure
      $ "unexpected positive/CE isolation assessments: " ++ show assessments
  -- A bounded positive has no counterexample vector to seed, so the second
  -- candidate must still reach its own live unsat trigger.
  assertFakeLengthQueryEvents [0, 1] [] firstEvents

  (counterexampleAroundPositive, secondEvents) <-
    runLengthRankingWithFakeTraceWithInputBox
      "query-unsat" Djex.LengthSMTLibStatusOnly
      defaultLengthEvaluationLimits limits [] contract [one, zero, one]
  lengthRankingFailure counterexampleAroundPositive @?= Nothing
  map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates counterexampleAroundPositive) @?= [1, 0, 2]
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates counterexampleAroundPositive of
    [ BoundedPositive positive
      , Counterexample first
      , Counterexample second
      ] -> do
        Djex.validatedLengthInputBoxAssignmentCount positive @?= 1
        map Djex.validatedLengthCounterexampleInputs [first, second] @?=
          [[], []]
        map Djex.validatedLengthCounterexampleResult [first, second] @?=
          [1, 1]
    assessments -> assertFailure
      $ "unexpected CE/positive/CE assessments: " ++ show assessments
  -- The positive middle candidate misses the retained [] seed, validates its
  -- own box, and leaves the bank intact for the final counterexample replay.
  assertFakeLengthQueryEvents [0, 1] [] secondEvents

assertLengthRankingNonVacuousPositivePreference :: IO ()
assertLengthRankingNonVacuousPositivePreference = do
  fixture <- buildLengthRankingLiveFixture
  retainedFirst <- syntheticLengthRankingCandidate
    "positive-preference-retained-first"
  retainedSecond <- syntheticLengthRankingCandidate
    "positive-preference-retained-second"
  limits <- explicitLengthInputBoxLimits 0 1
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      original = [retainedFirst, one, zero, retainedSecond, zero, one]
      contract = lengthRankingContract 0
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let bounded = enableLengthRankingInputBoxValidation limits [] base
        preferred = enableLengthRankingNonVacuousInputBoxPreference bounded
        run label policy = do
          ranking <- expectLengthRankingWithin label
            $ rankVerifiedLengthCandidatesWithPolicy
                policy contract original
          events <- BS.readFile $ executable ++ ".events"
          pure (ranking, events)
    (legacy, legacyEvents) <- run "legacy bounded-positive ordering" bounded
    (ranked, rankedEvents) <- run
      "non-vacuous bounded-positive ordering" preferred

    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates legacy) @?= [0, 2, 3, 4, 1, 5]
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates ranked) @?= [2, 4, 0, 3, 1, 5]
    assertPreferredAssessment $ map rankedLengthCandidateAssessment
      $ lengthRankingCandidates ranked
    rankedLengthPreparationRefusals ranked @?=
      [ Nothing, Nothing
      , Just LengthPreparationTypedAuthorityUnavailable
      , Just LengthPreparationTypedAuthorityUnavailable
      , Nothing, Nothing
      ]
    scalarRankingSnapshotByOriginalIndex ranked @?=
      scalarRankingSnapshotByOriginalIndex legacy
    -- The preference is applied only after the serial assessment loop. The
    -- first counterexample seeds [], both positives miss that vector and run
    -- live, and the final duplicate counterexample is still an MRU hit.
    assertFakeLengthQueryEvents [0, 1, 2] [] legacyEvents
    assertFakeLengthQueryEvents [0, 1, 2] [] rankedEvents
 where
  assertPreferredAssessment assessments = case assessments of
    [ BoundedPositive first
      , BoundedPositive second
      , Unassessed, Unassessed
      , Counterexample firstCounterexample
      , Counterexample secondCounterexample
      ] -> do
        map Djex.validatedLengthInputBoxApplicableAssignmentCount
          [first, second] @?= [1, 1]
        map Djex.validatedLengthCounterexampleInputs
          [firstCounterexample, secondCounterexample] @?= [[], []]
    other -> assertFailure
      $ "unexpected positive/neutral/counterexample partition: " ++ show other

assertLengthRankingPositivePreferenceSafety :: IO ()
assertLengthRankingPositivePreferenceSafety = do
  fixture <- buildLengthRankingLiveFixture
  retained <- syntheticLengthRankingCandidate
    "vacuous-positive-preference-retained"
  limits <- explicitLengthInputBoxLimits 0 1
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      vacuousContract = (lengthRankingContract 0)
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthTruth False
            , lengthContractPostcondition = LengthTruth True
            }
        }
      vacuousInput = [zero, retained, one, zero]
  withFakeLengthSolver "query-unsat" $ \executable -> do
    base <- expectRight $ statusOnlyLengthRankingPolicy executable
    let preferred = enableLengthRankingNonVacuousInputBoxPreference
          $ enableLengthRankingInputBoxValidation limits [] base
    vacuous <- expectLengthRankingWithin "vacuous positive ordering"
      $ rankVerifiedLengthCandidatesWithPolicy
          preferred vacuousContract vacuousInput
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates vacuous) @?= [0, 1, 2, 3]
    case map rankedLengthCandidateAssessment
        $ lengthRankingCandidates vacuous of
      [BoundedPositive first, Unassessed,
          BoundedPositive second, BoundedPositive third] ->
        map Djex.validatedLengthInputBoxApplicableAssignmentCount
          [first, second, third] @?= [0, 0, 0]
      assessments -> assertFailure
        $ "vacuous positives left the neutral partition: " ++ show assessments
    assertFakeLengthQueryEvents [0, 1, 2] [] =<<
      BS.readFile (executable ++ ".events")

    verification <- verificationBatchFromReceipts
      [retained, one, zero, zero, one]
    associated <- expectLengthPostVerificationWithin
      "positive preference occurrence association"
      $ assessVerifiedLengthCandidatesWithPolicy preferred
          (lengthRankingContract 0) verification
    assertLengthPostVerificationSealed associated
    ranking <- expectLengthPostVerificationRanking associated
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates ranking) @?= [2, 3, 0, 1, 4]
    let presentations = presentLengthPostVerificationResult associated
    case map lengthCandidatePresentationNote presentations of
      [Just firstPositive, Just secondPositive, Nothing,
          Just firstCounterexample, Just secondCounterexample] -> do
        mapM_ (assertBool "positive note lost its exact occurrence" .
            isInfixOf "applicable assignments = 1")
          [firstPositive, secondPositive]
        mapM_ (assertBool "counterexample note lost its exact occurrence" .
            isInfixOf "result spine length = 1")
          [firstCounterexample, secondCounterexample]
      notes -> assertFailure
        $ "positive preference presentation reassociated notes: " ++ show notes

scalarRankingSnapshotByOriginalIndex
  :: LengthRanking
  -> [(Natural, LengthRankingAssessment, Maybe LengthPreparationRefusalClass)]
scalarRankingSnapshotByOriginalIndex = sortOn (\(index, _, _) -> index)
  . map snapshot
  . lengthRankingCandidates
 where
  snapshot ranked =
    ( rankedLengthCandidateOriginalIndex ranked
    , rankedLengthCandidateAssessment ranked
    , rankedLengthCandidatePreparationRefusal ranked
    )

assertLengthRankingInputBoxAtomicFallback :: IO ()
assertLengthRankingInputBoxAtomicFallback = do
  (contract, scaled, independent) <- buildScaledProviderReplayFixture
  trailing <- syntheticLengthRankingCandidate "input-box-fallback-trailing"
  limits <- explicitLengthInputBoxLimits 1 1
  evaluation <- expectRight $ Djex.mkLengthEvaluationLimits
    Djex.defaultLengthEvaluationLimitSource
      { Djex.lengthEvaluationLimitSourceIntermediateValueBits = 1 }
  let alwaysContract = contract
        { leanLengthContractProviderLaws =
            [ law { leanLengthProviderLawTransfer = LengthLiteral 2 }
            | law <- leanLengthContractProviderLaws contract
            ]
        , leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthTruth True
            , lengthContractPostcondition = LengthEqual
                (LengthVariable LengthResult) (LengthLiteral 0)
            }
        }
      assertNeutral mode expected = do
        (ranking, events) <- runLengthRankingWithFakeTraceWithInputBox
          mode Djex.LengthSMTLibStatusOnly evaluation
          limits [0] alwaysContract [scaled]
        lengthRankingFailure ranking @?= Nothing
        map rankedLengthCandidateAssessment
            (lengthRankingCandidates ranking) @?= [Heuristic expected]
        assertFakeLengthQueryEvents [0] [] events
  -- The deliberately failing transfer remains untouched for sat and unknown;
  -- only raw unsat may trigger the independent validator.
  assertNeutral "healthy" Djex.SolverSatisfiable
  assertNeutral "query-unknown" Djex.SolverUnknown

  let original = [independent, scaled, trailing]
  (ranking, events) <- runLengthRankingWithFakeTraceWithInputBox
    "query-unsat" Djex.LengthSMTLibStatusOnly evaluation
    limits [0] alwaysContract original
  rankedLengthVerifiedCandidates ranking @?= original
  map rankedLengthCandidateAssessment (lengthRankingCandidates ranking) @?=
    replicate 3 Unassessed
  rankedLengthPreparationRefusals ranking @?=
    [Nothing, Nothing, Just LengthPreparationTypedAuthorityUnavailable]
  failure <- case lengthRankingFailure ranking of
    Nothing -> assertFailure "input-box rejection did not fail atomically"
      >> error "unreachable"
    Just retained -> pure retained
  lengthRankingFailureClass failure @?=
    LengthRankingInputBoxValidationFailed
      (Djex.LengthInputBoxAssignmentEvaluationRejected 0
        $ Djex.LengthEvaluationValueBitLimitExceeded
            Djex.LengthIntermediateValue 1 2)
  lengthRankingFailureCleanupIncomplete failure @?= False
  lengthRankingFailureOriginalIndex failure @?= Just 1
  assertFakeLengthQueryEvents [0, 1] [] events

assertLengthPostVerificationAdapter :: IO ()
assertLengthPostVerificationAdapter = do
  fixture <- buildLengthRankingLiveFixture
  retainedFirst <- syntheticLengthRankingCandidate
    "post-verification-retained-first"
  retainedSecond <- syntheticLengthRankingCandidate
    "post-verification-retained-second"
  trailing <- syntheticLengthRankingCandidate
    "post-verification-fallback-trailing"
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      rawDemotion = [zero, retainedFirst, one, retainedSecond]
      rawFallback = [one, zero, trailing]
      maximumCandidates =
        Djex.defaultLengthSMTLibLiveSessionMaximumQueries
      oversizedCount = fromIntegral maximumCandidates + 1
  oversizedVerification <- verificationBatchFromReceipts
    $ replicate oversizedCount zero
  demotionVerification <- verificationBatchFromReceipts rawDemotion
  fallbackVerification <- verificationBatchFromReceipts rawFallback
  let demotionInput = verifiedCandidateReceipts demotionVerification
      demotionExpected = case demotionInput of
        [verifiedZero, verifiedRetainedFirst, verifiedOne,
            verifiedRetainedSecond] ->
          [ verifiedRetainedFirst
          , verifiedRetainedSecond
          , verifiedZero
          , verifiedOne
          ]
        _ -> error "post-verification demotion fixture changed cardinality"
      fallbackInput = verifiedCandidateReceipts fallbackVerification
  withFakeLengthSolver "healthy" $ \executable -> do
    let executionSource = explicitLengthRankingExecutionSource
          executable Nothing Djex.LengthSMTLibInputValuesAfterSatisfiable
        policySource = explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits
          executionSource
          Djex.defaultLengthEvaluationLimitSource
    policy <- expectRight $ mkLengthRankingPolicy policySource

    rejected <- expectLengthPostVerificationWithin "bounded input rejection"
      $ assessVerifiedLengthCandidatesWithPolicy policy
          (error "input rejection forced the Length contract")
          oversizedVerification
    lengthPostVerificationAdapterFailure rejected @?= Just
      (LengthPostVerificationInputRejected
        $ LengthRankingInputLimitExceeded maximumCandidates
            (maximumCandidates + 1))
    assertBool "input rejection retained an impossible ranking report"
      $ isNothing $ lengthPostVerificationRanking rejected
    lengthPostVerificationRankingFailure rejected @?= Nothing
    assertBool "rejected input masqueraded as a sealed candidate batch"
      $ isNothing $ lengthPostVerificationSealedBatch rejected
    lengthPostVerificationCandidates rejected @?=
      verifiedCandidateReceipts oversizedVerification

    let poison :: DetailedVerificationVariant
        poison = error
          "policy post-verification input admission forced a candidate"
    poisonedOversizedVerification <- verifyCandidateGroups oversizedCount
      (const $ pure VariantAccepted)
      $ replicate oversizedCount [poison]
    poisonRejected <- expectLengthPostVerificationWithin
      "policy bounded input rejection with poison"
      $ assessVerifiedLengthCandidatesWithPolicy policy
          (error "input admission forced the Length contract")
          poisonedOversizedVerification
    lengthPostVerificationAdapterFailure poisonRejected @?= Just
      (LengthPostVerificationInputRejected
        $ LengthRankingInputLimitExceeded maximumCandidates
            (maximumCandidates + 1))
    assertBool "policy input rejection retained an impossible ranking"
      $ isNothing $ lengthPostVerificationRanking poisonRejected
    lengthPostVerificationRankingFailure poisonRejected @?= Nothing
    assertBool "policy input rejection masqueraded as a sealed batch"
      $ isNothing $ lengthPostVerificationSealedBatch poisonRejected
    length (lengthPostVerificationCandidates poisonRejected) @?=
      oversizedCount

    demotion <- expectLengthPostVerificationWithin "counterexample demotion"
      $ assessVerifiedLengthCandidatesWithPolicy policy
          (lengthRankingContract 2) demotionVerification
    lengthPostVerificationAdapterFailure demotion @?= Nothing
    lengthPostVerificationCandidates demotion @?= demotionExpected
    assertLengthPostVerificationSealed demotion
    demotionRanking <- expectLengthPostVerificationRanking demotion
    demotionRankingAgain <- expectLengthPostVerificationRanking demotion
    assertLengthRankingsEquivalent demotionRanking demotionRankingAgain
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates demotionRanking) @?=
      [1, 3, 0, 2]
    rankedLengthVerifiedCandidates demotionRanking @?= demotionExpected
    rankedLengthPreparationRefusals demotionRanking @?=
      [ Just LengthPreparationTypedAuthorityUnavailable
      , Just LengthPreparationTypedAuthorityUnavailable
      , Nothing
      , Nothing
      ]
    duplicateVerification <- verificationBatchFromReceipts
      [zero, zero, retainedFirst]
    duplicateRankingResult <- expectLengthPostVerificationWithin
      "equal-occurrence policy demotion"
      $ assessVerifiedLengthCandidatesWithPolicy policy
          (lengthRankingContract 2) duplicateVerification
    duplicateRanking <- expectLengthPostVerificationRanking
      duplicateRankingResult
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates duplicateRanking) @?=
      [2, 0, 1]
    length (lengthPostVerificationCandidates duplicateRankingResult) @?= 3

    fallback <- expectLengthPostVerificationWithin "atomic ranking fallback"
      $ assessVerifiedLengthCandidatesWithPolicy policy
          (lengthRankingContract 0) fallbackVerification
    lengthPostVerificationAdapterFailure fallback @?= Nothing
    lengthPostVerificationCandidates fallback @?= fallbackInput
    assertLengthPostVerificationSealed fallback
    fallbackRanking <- expectLengthPostVerificationRanking fallback
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates fallbackRanking) @?=
      [0, 1, 2]
    rankedLengthVerifiedCandidates fallbackRanking @?= fallbackInput
    rankedLengthPreparationRefusals fallbackRanking @?=
      [Nothing, Nothing, Just LengthPreparationTypedAuthorityUnavailable]
    case lengthRankingFailure fallbackRanking of
      Nothing -> assertFailure
        "post-verification adapter discarded the ranking failure report"
      Just failure -> lengthRankingFailureClass failure @?=
        LengthRankingLiveQueryFailed
          Djex.LengthSMTLibLiveQueryCounterexampleRejected

verificationBatchFromReceipts
  :: [Verified DetailedVerificationVariant]
  -> IO (VerificationBatch DetailedVerificationVariant)
verificationBatchFromReceipts receipts =
  verifyCandidateGroups (length receipts) (const $ pure VariantAccepted)
    [[verifiedCandidate receipt] | receipt <- receipts]

expectLengthPostVerificationWithin
  :: String
  -> IO LengthPostVerificationResult
  -> IO LengthPostVerificationResult
expectLengthPostVerificationWithin label action = do
  bounded <- timeout 8000000 action
  case bounded of
    Nothing -> assertFailure $ "Length post-verification " ++ label
      ++ " exceeded its outer bound"
    Just result -> pure result

expectLengthPostVerificationRanking
  :: LengthPostVerificationResult
  -> IO LengthRanking
expectLengthPostVerificationRanking result = case
    lengthPostVerificationRanking result of
  Nothing -> assertFailure
    "Length post-verification result discarded its ranking report"
  Just ranking -> pure ranking

assertLengthPostVerificationSealed
  :: LengthPostVerificationResult
  -> IO ()
assertLengthPostVerificationSealed result = case
    lengthPostVerificationSealedBatch result of
  Nothing -> assertFailure
    "Length post-verification output bypassed its permutation seal"
  Just batch -> do
    let sealed = postVerificationBatchCandidates batch
    sealed @?= lengthPostVerificationCandidates result
    ranking <- expectLengthPostVerificationRanking result
    lengthPostVerificationRankingFailure result @?=
      lengthRankingFailure ranking
    rankedLengthVerifiedCandidates ranking @?= sealed

assertLengthCounterexampleReceipt
  :: Natural
  -> Djex.ValidatedLengthCounterexample
  -> IO ()
assertLengthCounterexampleReceipt expectedResult receipt = do
  Djex.validatedLengthCounterexampleInputs receipt @?= []
  Djex.validatedLengthCounterexampleResult receipt @?= expectedResult

buildOneInputLengthRankingCandidate
  :: IO (Verified DetailedVerificationVariant)
buildOneInputLengthRankingCandidate =
  buildLengthProjectionRankingCandidate 1

buildLengthProjectionRankingCandidate
  :: Int
  -> IO (Verified DetailedVerificationVariant)
buildLengthProjectionRankingCandidate inputArity = do
  let element = FAtom False "Nat"
      listKey = "List Nat"
      list = FParamRec True "List" listKey [element]
        [ ("List.nil", [])
        , ("List.cons", [element, FAtom False listKey])
        ]
      goal = FArr list list
      zeroProvider = ProviderFrag "Demo.zeroList" list
      oneProvider = ProviderFrag "Demo.oneList" list
  assertBool "the provider-independent fixture is unary"
    $ inputArity == 1
  detailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      False EngineExference 512 Set.empty [zeroProvider, oneProvider] goal
  let expectedSpelling = providerIndependentProjectionSpelling inputArity
  (group, acceptedSpelling) <- case detailed of
    DetailedSynthCandidates groups _ -> case
      [ (retained, spelling)
      | retained <- groups
        , isJust (detailedCandidateGroupSemanticSidecar retained)
        , spelling <- detailedCandidateGroupVariants retained
        , spelling == expectedSpelling
        ] of
      retained : _ -> pure retained
      [] -> assertFailure
        ("Length ranking fixture returned no " ++ show inputArity
          ++ "-input projection " ++ show expectedSpelling ++ ": "
          ++ show
            [ ( detailedCandidateGroupVariants retained
              , detailedCandidateGroupRoute retained
              , isNothing $ detailedCandidateGroupSemanticSidecar retained
              )
            | retained <- groups
            ])
            >> error "unreachable"
    other -> assertFailure
      ("Length projection ranking synthesis failed: " ++ show other)
        >> error "unreachable"
  batch <- verifyCandidateGroups 1
    (\variant -> pure $ if detailedVerificationVariantText variant
        == acceptedSpelling
      then VariantAccepted
      else VariantRejected LeanErrorDiagnostic)
    [detailedCandidateGroupVerificationVariants group]
  case verifiedCandidateReceipts batch of
    [verified] -> pure verified
    receipts -> assertFailure
      ("Length projection verification produced "
        ++ show (length receipts) ++ " receipts") >> error "unreachable"

-- Select a callback-verifiable provider-independent projection without
-- depending on occurrence-local lambda grouping in the erased Djex graph.
-- The checked Length problem assertions below remain the semantic authority.
providerIndependentProjectionSpelling :: Int -> String
providerIndependentProjectionSpelling inputArity = "fun "
  ++ unwords (replicate (inputArity - 1) "_" ++ ["x"])
  ++ " => x"

-- Multi-argument pure projections currently retain only the compatibility
-- expression, not the exact typed graph required by the Length handoff.  The
-- Seed and arity tests therefore use direct providers whose result family
-- differs from their input family. Identity cannot inhabit any of these goals,
-- and every provider is retained in every run authority. Each consumer now
-- supplies the exact target-role vector for the candidate arity it exercises.
buildLengthSeedBankArityFixture
  :: IO
      ( LeanLengthContract
      , [Verified DetailedVerificationVariant]
      )
buildLengthSeedBankArityFixture = do
  let natural = FAtom False "Nat"
      boolean = FAtom False "Bool"
      list key element = FParamRec True "List" key [element]
        [ ("List.nil", [])
        , ("List.cons", [element, FAtom False key])
        ]
      sourceList = list "List Nat" natural
      resultList = list "List Bool" boolean
      arities = [0 .. 4]
      providerName arity = "Demo.project" ++ show arity
      providerType arity =
        foldr FArr resultList $ replicate arity sourceList
      providerLaw arity = LeanLengthProviderLaw
        { leanLengthProviderLawName = providerName arity
        , leanLengthProviderLawArgumentRoles =
            replicate arity LengthSpineArgument
        , leanLengthProviderLawTransfer = if arity == 0
            then LengthLiteral 1
            else LengthVariable $ Djex.LengthProviderArgument
              $ fromIntegral $ arity - 1
        }
      contract = (lengthRankingContract 0)
        { leanLengthContractProviderLaws = map providerLaw arities }
  verified <- mapM
    (buildDirectProviderCandidate arities providerName providerType)
    arities
  pure (contract, verified)
 where
  buildDirectProviderCandidate arities providerName providerType arity = do
    let prioritizedArities = arity : filter (/= arity) arities
        providers =
          [ ProviderFrag (providerName retainedArity)
              (providerType retainedArity)
          | retainedArity <- prioritizedArities
          ]
    detailed <- expectRight $
      synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
        False EngineExference 512 Set.empty providers $ providerType arity
    group <- case detailed of
      DetailedSynthCandidates groups _ -> case
          [ retained
          | retained <- groups
          , detailedCandidateGroupVariants retained == [providerName arity]
          , isJust (detailedCandidateGroupSemanticSidecar retained)
          ] of
        retained : _ -> pure retained
        [] -> assertFailure
          ("seed-bank fixture lacked typed direct provider "
            ++ providerName arity ++ ": " ++ show
              [ ( detailedCandidateGroupVariants retained
                , detailedCandidateGroupRoute retained
                , isNothing
                    $ detailedCandidateGroupSemanticSidecar retained
                )
              | retained <- groups
              ]) >> error "unreachable"
      other -> assertFailure
        ("seed-bank provider synthesis failed at arity " ++ show arity
          ++ ": " ++ show other) >> error "unreachable"
    verifySingleLengthRankingGroup group

buildScaledProviderReplayFixture
  :: IO
      ( LeanLengthContract
      , Verified DetailedVerificationVariant
      , Verified DetailedVerificationVariant
      )
buildScaledProviderReplayFixture = do
  let natural = FAtom False "Nat"
      boolean = FAtom False "Bool"
      list key element = FParamRec True "List" key [element]
        [ ("List.nil", [])
        , ("List.cons", [element, FAtom False key])
        ]
      sourceList = list "List Nat" natural
      resultList = list "List Bool" boolean
      scaledGoal = FArr sourceList resultList
      independentGoal = FArr sourceList sourceList
      scaledProvider = ProviderFrag "Demo.scaleList" scaledGoal
      providers = [scaledProvider]
      contract = (lengthRankingContract 0)
        { leanLengthContractTargetArgumentRoles = [LengthObservedSpine]
        , leanLengthContractProviderLaws =
            [ LeanLengthProviderLaw
                { leanLengthProviderLawName = "Demo.scaleList"
                , leanLengthProviderLawArgumentRoles =
                    [LengthSpineArgument]
                , leanLengthProviderLawTransfer = LengthScale 2
                    $ LengthVariable $ Djex.LengthProviderArgument 0
                }
            ]
        }
  scaledDetailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      False EngineExference 512 Set.empty providers scaledGoal
  scaledGroups <- case scaledDetailed of
    DetailedSynthCandidates retained _ -> pure retained
    other -> assertFailure
      ("scaled-provider replay synthesis failed: " ++ show other)
        >> error "unreachable"
  scaledGroup <- case
      [ group
      | group <- scaledGroups
      , [spelling] <- [detailedCandidateGroupVariants group]
      , "Demo.scaleList" `isInfixOf` spelling
      , isJust (detailedCandidateGroupSemanticSidecar group)
      ] of
    group : _ -> pure group
    [] -> assertFailure
      ("scaled-provider replay fixture lacked its direct provider: "
        ++ show (map detailedCandidateGroupVariants scaledGroups))
        >> error "unreachable"
  independentDetailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      False EngineExference 512 Set.empty providers independentGoal
  independentGroups <- case independentDetailed of
    DetailedSynthCandidates retained _ -> pure retained
    other -> assertFailure
      ("provider-independent replay synthesis failed: " ++ show other)
        >> error "unreachable"
  independentGroup <- case
      [ group
      | group <- independentGroups
      , providerIndependentProjectionSpelling 1 `elem`
          detailedCandidateGroupVariants group
      , isJust (detailedCandidateGroupSemanticSidecar group)
      ] of
    group : _ -> pure group
    [] -> assertFailure
      ("scaled-provider replay fixture lacked its independent identity: "
        ++ show (map detailedCandidateGroupVariants independentGroups))
        >> error "unreachable"
  scaled <- verifySingleLengthRankingGroup scaledGroup
  independent <- verifySingleLengthRankingGroup independentGroup
  pure (contract, scaled, independent)

-- The provider-backed Leant handoff fixtures are correctly zero-input.  This
-- test-only dependency fixture supplies the smallest honest one-input basis:
-- a provider-free typed Exference identity over one declared List spine,
-- sealed and replayed through the same public Length APIs.
buildProviderIndependentCounterexampleReceipt
  :: Natural
  -> IO Djex.ValidatedLengthCounterexample
buildProviderIndependentCounterexampleReceipt input = do
  responseListName <- expectRight $ Djex.mkIdentifier "ResponseList"
  responseNilName <- expectRight $ Djex.mkIdentifier "ResponseNil"
  responseConsName <- expectRight $ Djex.mkIdentifier "ResponseCons"
  responseTargetName <- expectRight $ Djex.mkIdentifier "responseIdentity"
  responseTarget <- expectRight $ Djex.mkDefinitionName responseTargetName
  let parameter = Djex.FlexibleVariable 0 :: Djex.ExferenceTypeVariable
      payload = Djex.TupleType Djex.Boxed [] :: Djex.ExferenceType
      listOf value = Djex.TypeApplication
        (Djex.TypeConstructor responseListName) value
      recursiveList = listOf $ Djex.TypeVariable parameter
      declaration = Djex.DataTypeDeclaration () responseListName
        [Djex.TypeParameter parameter Nothing]
        [ Djex.DataConstructor () responseNilName []
        , Djex.DataConstructor () responseConsName
            [Djex.TypeVariable parameter, recursiveList]
        ]
      goal = Djex.FunctionType (listOf payload) (listOf payload)
      contract = Djex.LengthContractSource
        { Djex.lengthContractPrecondition = Djex.LengthTruth True
        , Djex.lengthContractPostcondition = Djex.LengthEqual
            (Djex.LengthVariable Djex.LengthResult)
            (Djex.LengthLiteral 0)
        }
      responseBytes = map $ fromIntegral . fromEnum
  environment <- expectRight
    (Djex.mkEnvironment [declaration] :: Either
      (Djex.EnvironmentError Djex.ExferenceTypeVariable)
      Djex.ExferenceEnvironment)
  session <- expectRight $ Djex.mkExferenceSession environment
  request <- expectRight $ Djex.mkExferenceRequest Djex.QueryRequest
    { Djex.requestTarget = responseTarget
    , Djex.requestGoal = goal
    , Djex.requestContexts = []
    , Djex.requestOptions = Djex.defaultExferenceOptions
        { Djex.exferenceMaximumSteps = 8
        , Djex.exferenceMultiConstructorPatterns = False
        }
    }
  results <- expectRight $ Djex.runExferenceTypedQuery session request
  let candidates =
        [ retained
        | result <- results
        , retained <- Djex.batchCandidates $ Djex.resultSearch result
        ]
  lengthSession <- expectRight $ Djex.sealLengthSession
    Djex.defaultLengthLimits
    (Djex.exferenceSessionInventory session)
    (Djex.DeclaredListSpine
      responseListName responseNilName responseConsName)
    []
  checkedContract <- expectRight $ Djex.sealLengthContractInContext
    Djex.defaultLengthLimits
    (Djex.checkedLengthSessionContext lengthSession)
    goal contract
  problem <- case
      [ retained
      | candidate <- candidates
      , Right retained <-
          [ Djex.sealLengthTypedCandidateProblem
              Djex.defaultLengthProblemLimits
              lengthSession checkedContract candidate
          ]
      , Djex.checkedLengthCandidateResult
          (Djex.checkedLengthProblemCandidate retained) ==
            Djex.LengthVariable (Djex.LengthInput 0)
      ] of
    retained : _ -> pure retained
    [] -> assertFailure
      "provider-independent fixture returned no checked identity"
        >> error "unreachable"
  query <- expectRight $ Djex.sealLengthSMTLibQuery
    Djex.defaultLengthSMTLibLimits problem
  Djex.parseLengthSMTLibCheckResponse
      Djex.defaultLengthSMTLibResponseLimits
      (responseBytes "sat") @?=
    Right Djex.SolverSatisfiable
  symbol <- case Djex.lengthSMTLibQueryInputSymbols query of
    [retained] -> pure retained
    symbols -> assertFailure
      ("provider-independent fixture retained unexpected inputs: "
        ++ show symbols) >> error "unreachable"
  bindings <- expectRight $ Djex.parseLengthSMTLibInputValueResponse
    Djex.defaultLengthSMTLibResponseLimits query
    $ responseBytes "((" ++ symbol ++ responseBytes (" " ++ show input ++ "))")
  evidence <- case Djex.validateLengthSMTLibCounterexample
      Djex.defaultLengthEvaluationLimits query bindings of
    Left failure -> assertFailure
      ("provider-independent replay failed: " ++ show failure)
        >> error "unreachable"
    Right Nothing -> assertFailure
      "provider-independent violating model produced no evidence"
        >> error "unreachable"
    Right (Just retained) -> pure retained
  receipt <- expectRight $ Djex.replayBehavioralEvidence
    (Djex.checkedLengthProblemBehavioralProblem problem) evidence
  Djex.validatedLengthCounterexampleBasis receipt @?=
    Djex.ProviderIndependentFiniteSpineModel
  pure receipt

assertLengthRankingQueryAssociation
  :: Djex.CheckedLengthProblem Djex.ExferenceLocal Djex.ExferenceLocal
  -> CheckedLengthQuery
  -> IO ()
assertLengthRankingQueryAssociation problem query = do
  assertBool "the exact checked ranking query retained no identity"
    $ not $ null $ Djex.fingerprintCanonicalBytes
      $ Djex.lengthSMTLibQueryFingerprint query
  Djex.behavioralProblemFingerprint
      (Djex.lengthSMTLibQueryBehavioralProblem query) @?=
    Djex.behavioralProblemFingerprint
      (Djex.checkedLengthProblemBehavioralProblem problem)

